/* ---- 用 selfsigned 生成证书（无需 openssl）---- */
const pathMod = require('path');
const fsMod = require('fs');
const CERT_FILE_EARLY = pathMod.join(__dirname, 'files', 'cert.pem');
const KEY_FILE_EARLY = pathMod.join(__dirname, 'files', 'key.pem');
if (!fsMod.existsSync(pathMod.join(__dirname, 'files'))) {
  fsMod.mkdirSync(pathMod.join(__dirname, 'files'), { recursive: true });
}
if (!fsMod.existsSync(CERT_FILE_EARLY) || !fsMod.existsSync(KEY_FILE_EARLY)) {
  try {
    const selfsigned = require('selfsigned');
    const result = selfsigned.generate(
      [{ name: 'commonName', value: 'LAN-Chat' }],
      {
        days: 365,
        keySize: 2048,
        algorithm: 'sha256',
        extensions: [{
          name: 'subjectAltName',
          altNames: [
            { type: 2, value: 'localhost' },
            { type: 7, ip: '127.0.0.1' },
            { type: 7, ip: '0.0.0.0' }
          ]
        }]
      }
    );

    /* selfsigned v2.x 同步返回对象；v3.x+ 返回 Promise。
       这里同时兼容两种：同步写入、异步 then 写入。 */
    if (result && typeof result.then === 'function') {
      result.then(function (pems) {
        try {
          fsMod.writeFileSync(CERT_FILE_EARLY, pems.cert);
          fsMod.writeFileSync(KEY_FILE_EARLY, pems.private);
          console.log('🔐 已用 selfsigned 生成 HTTPS 证书（v3+ 异步）');
        } catch (we) {
          console.error('❌ 写入自签名证书失败:', we.message);
        }
      }).catch(function (e) {
        console.error('❌ selfsigned 生成证书失败:', e.message);
      });
    } else if (result && result.cert && result.private) {
      fsMod.writeFileSync(CERT_FILE_EARLY, result.cert);
      fsMod.writeFileSync(KEY_FILE_EARLY, result.private);
      console.log('🔐 已用 selfsigned 生成 HTTPS 证书（v2 同步）');
    }
  } catch (e) {
    console.error('❌ selfsigned 生成证书失败:', e.message);
  }
}

const express = require('express');
const http = require('http');
const https = require('https');
const { execSync, spawn } = require('child_process');
const { Server } = require('socket.io');
const readline = require('readline');
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const crypto = require('crypto');

const app = express();
/* ★ 适配 cloudflared / nginx 等反向代理：
   开启 trust proxy 后，Express 会信任 X-Forwarded-For /
   X-Forwarded-Proto / X-Forwarded-Host，req.ip 自动拿到
   真实客户端 IP，req.protocol 也能识别到代理前的 https。 */
app.set('trust proxy', true);

/* ============================================================
   ★ 防攻击：HTTP 安全响应头
   ============================================================ */
app.use(function (req, res, next) {
  /* 防止页面被恶意站点通过 iframe 嵌套（防点击劫持） */
  res.setHeader('X-Frame-Options', 'SAMEORIGIN');
  /* 禁止浏览器自动嗅探 MIME 类型（防 XSS 注入） */
  res.setHeader('X-Content-Type-Options', 'nosniff');
  /* 开启基础 XSS 过滤 */
  res.setHeader('X-XSS-Protection', '1; mode=block');
  /* 隐藏底层服务器技术栈 */
  res.removeHeader('X-Powered-By');
  next();
});

const compression = require('compression');
app.use(compression({
  /* 降低阈值到 512B，让更多小 JSON 也被压缩 */
  threshold: 512,
  /* 压缩级别：6 是速度与体积的常用平衡点 */
  level: 6,
  /* 白名单增加字体 */
  filter: function (req, res) {
    var ct = res.getHeader('Content-Type') || '';
    return /text|json|javascript|xml|svg|font/i.test(ct);
  }
}));

/* 全局 IP 封禁中间件：优先级最高，命中即 403，同时拦截 Socket.IO 握手 */
app.use(function (req, res, next) {
  try {
    /* 状态检查接口豁免：让被封的 IP 也能拿到 JSON 结果，
       而不是直接收到 403 HTML —— 前端据此触发刷新 */
    if (req.path === '/api/ip-status') return next();

    /* ★ 走 _getRealIp：反向代理场景自动读取 X-Forwarded-For */
    var _ip = _getRealIp(req);
    if (_ip && _agIsBanned(_ip)) {
      var _until = agState.bannedIps[_ip] || 0;
      var _remainSec = Math.max(0, Math.round((_until - Date.now()) / 1000));
      res.status(403);
      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      res.setHeader('Cache-Control', 'no-store');
      res.setHeader('Retry-After', String(_remainSec));
      var _remainTxt;
      if (_remainSec > 86400) {
        _remainTxt = '约 ' + Math.round(_remainSec / 86400) + ' 天';
      } else if (_remainSec > 3600) {
        _remainTxt = '约 ' + Math.round(_remainSec / 3600) + ' 小时';
      } else if (_remainSec > 60) {
        _remainTxt = '约 ' + Math.round(_remainSec / 60) + ' 分钟';
      } else {
        _remainTxt = _remainSec + ' 秒';
      }
      var _safeIp = String(_ip).replace(/[<>&"]/g, '');
      res.end([
        '<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8">',
        '<meta name="viewport" content="width=device-width,initial-scale=1">',
        '<title>访问被拒绝</title>',
        '<style>',
        '*{box-sizing:border-box;margin:0;padding:0}',
        'body{font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",',
        '"Microsoft YaHei",sans-serif;background:#fbfdfc;color:#1a1a1a;',
        'display:flex;align-items:center;justify-content:center;',
        'min-height:100vh;padding:24px;text-align:center;',
        'background:linear-gradient(160deg,#fef4f4 0%,#fbfdfc 60%);}',
        '.card{background:#fff;border-radius:20px;padding:44px 36px;',
        'max-width:480px;width:100%;',
        'box-shadow:0 20px 60px rgba(198,40,40,.15),0 2px 10px rgba(0,0,0,.05);',
        'border:1px solid rgba(198,40,40,.12);}',
        '.icon{font-size:64px;line-height:1;margin-bottom:16px;}',
        'h1{font-size:24px;color:#c62828;margin-bottom:12px;',
        'letter-spacing:-.3px;font-weight:800;}',
        'p{color:#666;font-size:14.5px;line-height:1.7;}',
        '.ip{margin-top:18px;padding:8px 14px;border-radius:10px;',
        'background:rgba(198,40,40,.06);color:#c62828;',
        'font-family:Consolas,Monaco,monospace;font-size:13px;',
        'word-break:break-all;}',
        '.time{margin-top:14px;color:#c62828;font-weight:600;font-size:15px;}',
        '</style></head><body>',
        '<div class="card">',
        '<div class="icon">🚫</div>',
        '<h1>访问被拒绝</h1>',
        '<p>您的 IP 已被管理员临时封禁，无法访问本服务器。</p>',
        '<div class="ip">' + _safeIp + '</div>',
        '<div class="time">剩余时间：' + _remainTxt + '</div>',
        '<p style="margin-top:18px;font-size:12.5px;opacity:.6;">',
        '如有疑问，请联系服务器管理员',
        '</p></div></body></html>'
      ].join(''));
      return;
    }
  } catch (e) {
    /* 检查出错不阻断请求 */
  }
  next();
});

/* 请求体解析中间件。跳过 /kf/api/* 与 /download/login —— 这两处自行调用 gwReadBody() 解析请求流 */
var _bodyJsonParser = express.json({ limit: '2mb' });
var _bodyUrlParser = express.urlencoded({ extended: true, limit: '2mb' });
app.use(function (req, res, next) {
  /* 手工解析 body 的路径 → 跳过 */
  if (req.path.indexOf('/kf/api/') === 0 ||
    req.path === '/download/login') {
    return next();
  }
  /* 无 body 的请求直接跳过 */
  if (req.method === 'GET' || req.method === 'HEAD' ||
    req.method === 'OPTIONS') {
    return next();
  }
  _bodyJsonParser(req, res, function (err) {
    if (err) {
      console.warn('⚠️ JSON body 解析失败:', err.message);
      return res.status(400).json({ ok: false, error: 'invalid json body' });
    }
    _bodyUrlParser(req, res, next);
  });
});

/* 页面访问日志：仅记录主页面路径，连接时与响应结束时各打印一行 */
var PAGE_NAMES = {
  '/': '主界面',
  '/index': '主界面',
  '/index.html': '主界面',
  '/gw': '官网',
  '/log': '版本日志',
  '/download': '下载中心',
  '/kf': '反馈中心',
  '/root': 'Web 终端'
};

function _clientIp(req) {
  try {
    return String(req.ip || req.connection.remoteAddress || '')
      .replace(/^::ffff:/, '');
  } catch (e) { return ''; }
}

app.use(function (req, res, next) {
  var pageName = PAGE_NAMES[req.path];
  if (!pageName) return next();

  var ip = _clientIp(req);
  var t1 = new Date().toLocaleString('zh-CN', { hour12: false });
  console.log('[' + t1 + '] [连接] ' + pageName + '  ' + ip +
    '  → ' + req.path);

  res.on('finish', function () {
    var t2 = new Date().toLocaleString('zh-CN', { hour12: false });
    console.log('[' + t2 + '] [断开] ' + pageName + '  ' + ip +
      '  ← ' + req.path + ' ' + res.statusCode);
  });

  next();
});

