var INITIAL_BALANCE = 100000;         // 1000.00 元（以「分」为整数存储）
/* 红包金额上限已取消，仅保留最小 0.01 元；
   金额以「分」为整数存储，JS Number 安全整数上限 ≈ 9e15，
   即约 9 万亿元，足够覆盖任何正常使用场景 */
var MAX_REDPACKET_COUNT = 100;
