function saveWallets() { saveJSON(F_WALLETS, wallets); }
function saveRedPackets() { saveJSON(F_REDPACKETS, redPackets); }

function getWallet(userId) {
  if (!wallets[userId]) {
    wallets[userId] = { balance: INITIAL_BALANCE, records: [] };
  }
  var w = wallets[userId];
  if (typeof w.balance !== 'number' || isNaN(w.balance)) w.balance = 0;
  if (w.balance < 0) w.balance = 0;
  if (!Array.isArray(w.records)) w.records = [];
  return w;
}
function addWalletRecord(userId, type, amount, desc, extra, i18n) {
  var w = getWallet(userId);
  w.balance += amount;
  if (w.balance < 0) w.balance = 0;
  var rec = {
    id: 'wr' + Date.now().toString(36) + Math.random().toString(36).substring(2, 6),
    type: type,
    amount: amount,
    desc: desc || '',
    extra: extra || null,
    time: Date.now()
  };
  /* 结构化 i18n：客户端渲染时优先用 i18nKey + i18nParams 本地化，
     没有该字段的历史记录回退到中文 desc。 */
  if (i18n && i18n.key) {
    rec.i18nKey = i18n.key;
    rec.i18nParams = i18n.params || null;
  }
  w.records.unshift(rec);
  if (w.records.length > 200) w.records.length = 200;
  return w;
}
function yuan(cents) {
  var n = Number(cents);
  if (isNaN(n)) n = 0;
  n = Math.round(n);
  var neg = n < 0;
  n = Math.abs(n);
  var intPart = Math.floor(n / 100);
  var decPart = n % 100;
  var intStr = String(intPart).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  var decStr = decPart < 10 ? ('0' + decPart) : String(decPart);
  return (neg ? '-' : '') + intStr + '.' + decStr;
}
function packetClaimedCount(p) { return Object.keys(p.claimed || {}).length; }
function packetClaimedTotal(p) {
  var t = 0;
  var c = p.claimed || {};
  for (var k in c) if (c.hasOwnProperty(k)) t += c[k];
  return t;
}

function broadcastRedpacketStatus(packet) {
  /* 抢完但 claimedDuration 尚未写入（并发边界）→ 在此刻补上，
     保证所有客户端收到的状态是完整的 */
  var _finished = packetClaimedCount(packet) >= packet.count;
  if (_finished && (!packet.claimedDuration ||
    typeof packet.claimedDuration !== 'number' ||
    packet.claimedDuration <= 0)) {
    var _dur = Math.max(1, Math.round((Date.now() - packet.createdAt) / 1000));
    packet.claimedDuration = _dur;
    saveRedPackets();
  }
  var status = {
    packetId: packet.id,
    claimedCount: packetClaimedCount(packet),
    totalCount: packet.count,
    claimedTotal: packetClaimedTotal(packet),
    totalAmount: packet.amount,
    /* ★ v0.23.32 补全：缺失此字段会导致红包详情弹窗
       在实时刷新（renderRpgGrabbers）时丢失幸运王 👑 徽章
       与排名配色 —— 因为 d.type === undefined 时
       isLucky 恒为 false。 */
    type: packet.type,
    finished: _finished,
    expired: Date.now() > packet.expiredAt,
    /* ★ 抢光耗时（秒）：抢完时才有值，用于气泡 / 领取界面显示「用了 X 秒抢光」 */
    claimedDuration: (typeof packet.claimedDuration === 'number' &&
      packet.claimedDuration > 0)
      ? packet.claimedDuration : null,
    grabbers: Object.keys(packet.claimed || {}).map(function (uid) {
      var u = getUserById(uid);
      return {
        userId: uid,
        userName: u ? u.name : uid,
        amount: packet.claimed[uid],
        /* ★ 领取时间戳（兼容旧红包：没有 claimedAt 时回退到红包创建时间） */
        time: (packet.claimedAt && packet.claimedAt[uid]) || packet.createdAt
      };
    })
  };
  if (packet.groupId) {
    var group = getGroupById(packet.groupId);
    if (group) {
      group.members.forEach(function (uid) {
        var u = getUserById(uid);
        if (u && u.online) emitToUser(uid, 'redpacket-status', status);
      });
    }
  } else if (packet.to) {
    var a = getUserById(packet.from);
    var b = getUserById(packet.to);
    if (a && a.online) emitToUser(a.id, 'redpacket-status', status);
    if (b && b.online) emitToUser(b.id, 'redpacket-status', status);
  }
}


