/* ==================== v0.25.6：阅后即焚 ====================
   · enabled       全局开关（命令行 burn on/off）
   · burnTimers    { msgId: timeoutId } —— 已启动的销毁定时器
   · BURN_MAX_MS   单条消息最长存活时间 */
var burnConfig = loadJSON(F_BURN, { enabled: true });
if (typeof burnConfig.enabled !== 'boolean') burnConfig.enabled = true;
var burnTimers = {};
var BURN_MAX_MS = 5 * 60 * 1000;   /* 最长 5 分钟 */

/* ★ v0.26.1：稳定性增强 */
var burnIndex = {};                /* msgId → { sessionKey, scope }，O(1) 查找 */
var burnViewLocks = {};            /* msgId → 上报时间戳，防竞态重复启动 */

/* ============================================================
   ★ v0.26.2：?dev=1 管理员验证 token
   ------------------------------------------------------------
   普通用户访问 ?dev=1 不再直接豁免源码保护，必须先输入
   管理员账号的密码。验证通过后签发一次性 token，有效期 24 小时。
   ============================================================ */
var adminDevTokens = {};           /* token → { userId, name, expires } */
var ADMIN_DEV_TTL = 24 * 3600 * 1000;

function _burnIndexAdd(msgId, sessionKey, scope) {
  if (msgId) burnIndex[msgId] = { sessionKey: sessionKey, scope: scope };
}
function _burnIndexDel(msgId) {
  if (msgId) delete burnIndex[msgId];
}

function saveBurnConfig() { saveJSON(F_BURN, burnConfig); }

/* 启动一条阅后即焚的销毁定时器 */
function scheduleBurn(msgId, sessionKey, delayMs, scope) {
  if (!msgId || !sessionKey) return;
  if (burnTimers[msgId]) clearTimeout(burnTimers[msgId]);
  var d = Math.max(1000, Math.min(BURN_MAX_MS, Number(delayMs) || 30000));
  burnTimers[msgId] = setTimeout(function () {
    delete burnTimers[msgId];
    /* ★ v0.26.0：不再删除，改为标记 burned + 清空敏感字段 */
    var arr = messageHistory[sessionKey];
    if (Array.isArray(arr)) {
      for (var i = 0; i < arr.length; i++) {
        if (arr[i].msgId === msgId) {
          arr[i].burned = true;
          arr[i].content = '';
          arr[i].fileData = null;
          arr[i].fileName = null;
          arr[i].fileSize = 0;
          arr[i].fileType = null;
          arr[i].duration = null;
          arr[i].reply = null;
          break;
        }
      }
      scheduleSaveHistory();
    }
    _burnIndexDel(msgId);
    /* ★ 广播携带服务端时间戳，客户端据此校准时钟 */
    var _srvNow = Date.now();
    if (scope && scope.type === 'group') {
      var g = getGroupById(scope.id);
      if (g) {
        g.members.forEach(function (uid) {
          var u = getUserById(uid);
          if (u && u.online) emitToUser(uid, 'burn-expired', {
            msgId: msgId, serverNow: _srvNow
          });
        });
      }
    } else if (scope && scope.type === 'private') {
      var ids = scope.ids || [];
      for (var j = 0; j < ids.length; j++) {
        var uu = getUserById(ids[j]);
        if (uu && uu.online) emitToUser(uu.id, 'burn-expired', {
          msgId: msgId, serverNow: _srvNow
        });
      }
    }
    log('BURN_EXPIRED', { msgId: msgId });
  }, d);
}

/* 服务启动时扫描历史消息：
   · 已过期的 → 立即删除
   · 已读未到期的 → 恢复定时器
   · 未读的 → 保持等待 */
function restoreBurnTimers() {
  var now = Date.now();
  var expiredN = 0, restoredN = 0;
  for (var key in messageHistory) {
    if (!messageHistory.hasOwnProperty(key)) continue;
    var arr = messageHistory[key];
    if (!Array.isArray(arr)) continue;
    var scope = null;
    if (key.indexOf('group_') === 0) {
      scope = { type: 'group', id: key.substring(6) };
    } else if (key.indexOf('private_') === 0) {
      var rest = key.substring(8);
      var idx = rest.indexOf('_');
      if (idx !== -1) {
        scope = { type: 'private', ids: [rest.substring(0, idx), rest.substring(idx + 1)] };
      }
    }
    if (!scope) continue;
    for (var i = arr.length - 1; i >= 0; i--) {
      var m = arr[i];
      if (!m || !m.burnAfterRead || !m.burnAfterRead.enabled) continue;
      if (m.burnAfterRead.expiresAt && m.burnAfterRead.expiresAt <= now) {
        /* ★ v0.26.0：已过期 → 标记而非删除 */
        m.burned = true;
        m.content = '';
        m.fileData = null;
        m.fileName = null;
        m.fileSize = 0;
        m.fileType = null;
        m.duration = null;
        m.reply = null;
        expiredN++;
      } else if (m.burnAfterRead.viewedAt) {
        _burnIndexAdd(m.msgId, key, scope);
        scheduleBurn(m.msgId, key, m.burnAfterRead.expiresAt - now, scope);
        restoredN++;
      }
    }
  }
  if (expiredN || restoredN) {
    saveHistoryNow();
    console.log('🔥 阅后即焚恢复：清理 ' + expiredN +
      ' 条过期 / 恢复 ' + restoredN + ' 条待销毁定时器');
  }
}

/* ============================================================
   ★ v0.25.0 风控系统（Risk Control）
   ------------------------------------------------------------
   检测维度：
     1. 消息频率       —— 短时间大量消息
     2. 重复消息       —— 相同内容连发
     3. 群发广播       —— 向多个不同目标短时间发消息
     4. 红包滥用       —— 短时间大量发红包 / 领取
     5. 登录失败       —— 连续密码错误
     6. 敏感操作频率   —— 创建群、拉黑等
   处置动作（按严重程度递进）：
     flag     仅记录
     throttle 限流（X 秒内禁止发消息）
     mute     临时禁言（X 秒）
     ban      临时封禁（X 秒）
     kick     立即踢出
   ============================================================ */
var riskConfig = loadJSON(F_RISK_CONFIG, {
  enabled: true,
  rules: {
    msgRate:   { enabled: true,  window: 10000, limit: 20, action: 'throttle', sec: 30 },
    repeatMsg: { enabled: true,  limit: 5,     action: 'mute',     sec: 300 },
    broadcast: { enabled: true,  window: 30000, limit: 10, action: 'flag',     sec: 0 },
    redpacket: { enabled: true,  window: 60000, limit: 5,  action: 'throttle', sec: 60 },
    loginFail: { enabled: true,  window: 60000, limit: 5,  action: 'ban',      sec: 600 },
    opsRate:   { enabled: true,  window: 60000, limit: 15, action: 'flag',     sec: 0 }
  },
  whitelist: [],
  blacklist: []
});
if (!riskConfig || typeof riskConfig !== 'object') {
  riskConfig = { enabled: false, rules: {}, whitelist: [], blacklist: [] };
}
if (!riskConfig.rules || typeof riskConfig.rules !== 'object') riskConfig.rules = {};
if (!Array.isArray(riskConfig.whitelist)) riskConfig.whitelist = [];
if (!Array.isArray(riskConfig.blacklist)) riskConfig.blacklist = [];

/* 内存态风险状态：每个用户一份 */
var riskState = {};

/* 风控事件持久化：最近 1000 条 */
var riskEvents = loadJSON(F_RISK_EVENTS, []);
if (!Array.isArray(riskEvents)) riskEvents = [];
var RISK_EVENTS_MAX = 1000;

function saveRiskConfig() { saveJSON(F_RISK_CONFIG, riskConfig); }
function saveRiskEvents() { saveJSON(F_RISK_EVENTS, riskEvents); }

/* 获取 / 初始化某用户的风险状态 */
function getRiskState(uid) {
  if (!uid) return null;
  if (!riskState[uid]) {
    riskState[uid] = {
      msgTimestamps: [],
      lastMsgContent: '',
      repeatCount: 0,
      lastMsgAt: 0,
      throttleUntil: 0,
      muteUntil: 0,
      banUntil: 0,
      score: 0,
      recentTargets: [],
      loginFailCount: 0,
      lastLoginFailAt: 0,
      opsTimestamps: [],
      redpacketTimestamps: []
    };
  }
  return riskState[uid];
}

/* 记录一条风控事件并广播给所有在线管理员 */
function recordRiskEvent(uid, uname, rule, action, detail, appliedUntil) {
  var entry = {
    id: 'rk' + Date.now().toString(36) +
      Math.random().toString(36).substring(2, 6),
    time: Date.now(),
    userId: uid || '',
    userName: uname || '',
    rule: rule,
    action: action,
    detail: detail || '',
    appliedUntil: appliedUntil || 0
  };
  riskEvents.unshift(entry);
  if (riskEvents.length > RISK_EVENTS_MAX) {
    riskEvents.length = RISK_EVENTS_MAX;
  }
  saveRiskEvents();

  /* 累计风险评分：动作越重，加分越多 */
  var _scoreAdd = { flag: 1, throttle: 3, mute: 5, ban: 10, kick: 10 };
  var _rs = uid ? getRiskState(uid) : null;
  if (_rs) _rs.score += (_scoreAdd[action] || 1);

  /* 通知在线管理员 */
  userMap.forEach(function (u) {
    if (u && u.online && u.isAdmin) {
      emitToUser(u.id, 'risk-alert', entry);
    }
  });
  console.warn('🛡️ [风控] ' + (uname || uid || '?') +
    ' | 规则=' + rule + ' | 动作=' + action +
    (detail ? ' | ' + detail : ''));
  return entry;
}

/* 判断该用户是否被豁免（白名单 / 管理员） */
function isRiskExempt(uid, uname) {
  if (!uid) return true;
  var live = getUserById(uid);
  if (live && live.isAdmin) return true;
  if (uname && riskConfig.whitelist.indexOf(uname) !== -1) return true;
  if (uid && riskConfig.whitelist.indexOf(uid) !== -1) return true;
  return false;
}

/* 判断该用户是否当前被限流 / 禁言 / 封禁 */
function checkRiskBlock(uid) {
  var rs = getRiskState(uid);
  if (!rs) return null;
  var now = Date.now();
  if (rs.banUntil > now) {
    return { kind: 'ban', until: rs.banUntil, remain: rs.banUntil - now };
  }
  if (rs.muteUntil > now) {
    return { kind: 'mute', until: rs.muteUntil, remain: rs.muteUntil - now };
  }
  if (rs.throttleUntil > now) {
    return { kind: 'throttle', until: rs.throttleUntil, remain: rs.throttleUntil - now };
  }
  return null;
}

/* 应用处置动作 */
function applyRiskAction(uid, uname, action, sec, rule, detail) {
  var rs = getRiskState(uid);
  if (!rs) return;
  var now = Date.now();
  var ms = Math.max(0, (parseInt(sec, 10) || 0) * 1000);
  var until = 0;

  if (action === 'throttle' && ms > 0) {
    rs.throttleUntil = Math.max(rs.throttleUntil, now + ms);
    until = rs.throttleUntil;
  } else if (action === 'mute' && ms > 0) {
    rs.muteUntil = Math.max(rs.muteUntil, now + ms);
    until = rs.muteUntil;
    /* 同步应用到用户对象的 muted 字段（兼容现有 UI） */
    var live = getUserById(uid);
    if (live) live.muted = true;
  } else if (action === 'ban' && ms > 0) {
    rs.banUntil = Math.max(rs.banUntil, now + ms);
    until = rs.banUntil;
    /* 立即断开该用户的所有连接 */
    var _banSocks = [];
    try {
      io.sockets.sockets.forEach(function (sk) {
        if (sk && sk.data && sk.data.userId === uid) _banSocks.push(sk);
      });
    } catch (e) {}
    for (var _i = 0; _i < _banSocks.length; _i++) {
      (function (sk) {
        try {
          sk.emit('risk-banned', {
            rule: rule, reason: detail || '',
            until: until, remainSec: Math.round(ms / 1000)
          });
        } catch (e) {}
        setTimeout(function () {
          try { sk.disconnect(true); } catch (e) {}
        }, 400);
      })(_banSocks[_i]);
    }
  } else if (action === 'kick') {
    var _kickSocks = [];
    try {
      io.sockets.sockets.forEach(function (sk) {
        if (sk && sk.data && sk.data.userId === uid) _kickSocks.push(sk);
      });
    } catch (e) {}
    for (var _j = 0; _j < _kickSocks.length; _j++) {
      (function (sk) {
        try {
          sk.emit('risk-banned', {
            rule: rule, reason: detail || '',
            until: 0, remainSec: 0, kicked: true
          });
        } catch (e) {}
        setTimeout(function () {
          try { sk.disconnect(true); } catch (e) {}
        }, 400);
      })(_kickSocks[_j]);
    }
  }
  recordRiskEvent(uid, uname, rule, action, detail, until);
}

/* 风控检查：在消息发送前调用
   返回 null 表示放行，返回 { kind, remain } 表示被拦截 */
function checkMsgRate(user, isGroup) {
  if (!riskConfig.enabled) return null;
  if (!user || !user.id) return null;
  if (isRiskExempt(user.id, user.name)) return null;

  /* 当前是否被处置 */
  var block = checkRiskBlock(user.id);
  if (block) return block;

  var rs = getRiskState(user.id);
  var now = Date.now();
  var rules = riskConfig.rules;

  /* --- 规则 1：消息频率 --- */
  var r1 = rules.msgRate;
  if (r1 && r1.enabled) {
    var window1 = Math.max(1000, parseInt(r1.window, 10) || 10000);
    var limit1 = Math.max(2, parseInt(r1.limit, 10) || 20);
    /* 保留窗口内的消息时间戳 */
    var cutoff = now - window1;
    while (rs.msgTimestamps.length && rs.msgTimestamps[0] < cutoff) {
      rs.msgTimestamps.shift();
    }
    rs.msgTimestamps.push(now);
    if (rs.msgTimestamps.length > limit1) {
      var _act1 = String(r1.action || 'throttle');
      var _sec1 = Math.max(1, parseInt(r1.sec, 10) || 30);
      applyRiskAction(user.id, user.name, _act1, _sec1, 'msgRate',
        (window1 / 1000) + '秒内发送' + rs.msgTimestamps.length + '条（上限' + limit1 + '）');
      /* 清空时间戳，避免累积触发 */
      rs.msgTimestamps = [];
      var _b1 = checkRiskBlock(user.id);
      if (_b1) return _b1;
    }
  }

  /* --- 规则 2：重复消息 --- */
  var r2 = rules.repeatMsg;
  if (r2 && r2.enabled) {
    var limit2 = Math.max(2, parseInt(r2.limit, 10) || 5);
    var content = typeof user._lastContent === 'string' ? user._lastContent : '';
    if (content && content === rs.lastMsgContent) {
      rs.repeatCount++;
    } else {
      rs.repeatCount = 1;
      rs.lastMsgContent = content;
    }
    if (rs.repeatCount >= limit2) {
      var _act2 = String(r2.action || 'mute');
      var _sec2 = Math.max(1, parseInt(r2.sec, 10) || 300);
      applyRiskAction(user.id, user.name, _act2, _sec2, 'repeatMsg',
        '连续发送相同内容 ' + rs.repeatCount + ' 次');
      rs.repeatCount = 0;
      rs.lastMsgContent = '';
      var _b2 = checkRiskBlock(user.id);
      if (_b2) return _b2;
    }
  }

  /* --- 规则 3：群发广播 --- */
  var r3 = rules.broadcast;
  if (r3 && r3.enabled) {
    var window3 = Math.max(1000, parseInt(r3.window, 10) || 30000);
    var limit3 = Math.max(2, parseInt(r3.limit, 10) || 10);
    var cutoff3 = now - window3;
    while (rs.recentTargets.length && rs.recentTargets[0].t < cutoff3) {
      rs.recentTargets.shift();
    }
    var target = isGroup ? ('g:' + user._targetGroup) : ('u:' + user._targetUser);
    if (target) {
      var exists = false;
      for (var _ti = 0; _ti < rs.recentTargets.length; _ti++) {
        if (rs.recentTargets[_ti].k === target) { exists = true; break; }
      }
      if (!exists) {
        rs.recentTargets.push({ t: now, k: target });
      }
    }
    if (rs.recentTargets.length > limit3) {
      var _act3 = String(r3.action || 'flag');
      var _sec3 = Math.max(0, parseInt(r3.sec, 10) || 0);
      applyRiskAction(user.id, user.name, _act3, _sec3, 'broadcast',
        (window3 / 1000) + '秒内向 ' + rs.recentTargets.length + ' 个不同目标发消息');
      rs.recentTargets = [];
      var _b3 = checkRiskBlock(user.id);
      if (_b3) return _b3;
    }
  }

  return null;
}

/* 风控检查：敏感操作频率（创建群、拉黑等）
   通常用于 handleCommand / 部分 socket 事件 */
function checkOpsRate(user, opName) {
  if (!riskConfig.enabled) return;
  if (!user || !user.id) return;
  if (isRiskExempt(user.id, user.name)) return;

  var rs = getRiskState(user.id);
  var now = Date.now();
  var r6 = riskConfig.rules.opsRate;
  if (!r6 || !r6.enabled) return;

  var window6 = Math.max(1000, parseInt(r6.window, 10) || 60000);
  var limit6 = Math.max(2, parseInt(r6.limit, 10) || 15);
  var cutoff6 = now - window6;
  while (rs.opsTimestamps.length && rs.opsTimestamps[0] < cutoff6) {
    rs.opsTimestamps.shift();
  }
  rs.opsTimestamps.push(now);
  if (rs.opsTimestamps.length > limit6) {
    var _act6 = String(r6.action || 'flag');
    var _sec6 = Math.max(0, parseInt(r6.sec, 10) || 0);
    applyRiskAction(user.id, user.name, _act6, _sec6, 'opsRate',
      (window6 / 1000) + '秒内执行 ' + rs.opsTimestamps.length +
      ' 次敏感操作（' + opName + '）');
    rs.opsTimestamps = [];
  }
}

/* 风控检查：登录失败
   在 login-error '密码错误' 分支调用 */
function checkLoginFail(name) {
  if (!riskConfig.enabled) return;
  var r5 = riskConfig.rules.loginFail;
  if (!r5 || !r5.enabled) return;

  var rec = persistentUsers[name];
  if (!rec) return;
  if (isRiskExempt(rec.id, name)) return;

  var rs = getRiskState(rec.id);
  var now = Date.now();
  var window5 = Math.max(1000, parseInt(r5.window, 10) || 60000);
  var limit5 = Math.max(2, parseInt(r5.limit, 10) || 5);

  if (!rs.lastLoginFailAt || now - rs.lastLoginFailAt > window5) {
    rs.loginFailCount = 0;
  }
  rs.loginFailCount++;
  rs.lastLoginFailAt = now;

  if (rs.loginFailCount >= limit5) {
    var _act5 = String(r5.action || 'ban');
    var _sec5 = Math.max(30, parseInt(r5.sec, 10) || 600);
    applyRiskAction(rec.id, name, _act5, _sec5, 'loginFail',
      window5 / 1000 + '秒内密码错误 ' + rs.loginFailCount + ' 次');
    rs.loginFailCount = 0;
    /* 若用户在线（换设备登录场景），立即踢出 */
    var live = getUserById(rec.id);
    if (live && live.online) {
      emitToUser(rec.id, 'risk-banned', {
        rule: 'loginFail',
        reason: '频繁密码错误',
        until: rs.banUntil, remainSec: _sec5
      });
    }
  }
}

/* 风控检查：红包发送频率 */
function checkRedpacketRate(user) {
  if (!riskConfig.enabled) return null;
  if (!user || !user.id) return null;
  if (isRiskExempt(user.id, user.name)) return null;

  var block = checkRiskBlock(user.id);
  if (block) return block;

  var rs = getRiskState(user.id);
  var now = Date.now();
  var r4 = riskConfig.rules.redpacket;
  if (!r4 || !r4.enabled) return null;

  var window4 = Math.max(1000, parseInt(r4.window, 10) || 60000);
  var limit4 = Math.max(2, parseInt(r4.limit, 10) || 5);
  var cutoff4 = now - window4;
  while (rs.redpacketTimestamps.length && rs.redpacketTimestamps[0] < cutoff4) {
    rs.redpacketTimestamps.shift();
  }
  rs.redpacketTimestamps.push(now);
  if (rs.redpacketTimestamps.length > limit4) {
    var _act4 = String(r4.action || 'throttle');
    var _sec4 = Math.max(1, parseInt(r4.sec, 10) || 60);
    applyRiskAction(user.id, user.name, _act4, _sec4, 'redpacket',
      (window4 / 1000) + '秒内发送 ' + rs.redpacketTimestamps.length + ' 个红包');
    rs.redpacketTimestamps = [];
    return checkRiskBlock(user.id);
  }
  return null;
}

function saveModeration() { saveJSON(F_MODERATION, moderation); }

/* 大小写不敏感：英文单词全部小写，中文原样 */
function _normalizeWord(w) { return String(w || '').trim(); }

/* 返回命中的敏感词数组（空数组表示未命中） */
function checkModeration(text) {
  if (!moderation.enabled || !moderation.words.length) return [];
  if (typeof text !== 'string' || !text) return [];
  var lower = text.toLowerCase();
  var hits = [];
  for (var i = 0; i < moderation.words.length; i++) {
    var w = moderation.words[i];
    if (!w) continue;
    if (lower.indexOf(String(w).toLowerCase()) !== -1) hits.push(w);
  }
  return hits;
}

/* 记录到审核队列 + 通知在线管理员 */
function pushModerationQueue(msg, hits) {
  var entry = {
    id: 'md' + Date.now().toString(36) +
      Math.random().toString(36).substring(2, 6),
    time: Date.now(),
    fromId: msg.from,
    fromName: msg.fromName || msg.from,
    to: msg.to || msg.groupId || '',
    scope: msg.groupId ? 'group' : 'private',
    content: String(msg.content || '').slice(0, 500),
    hits: hits.slice(0, 10),
    msgId: msg.msgId || ''
  };
  moderationQueue.unshift(entry);
  if (moderationQueue.length > MODERATION_QUEUE_MAX) {
    moderationQueue.length = MODERATION_QUEUE_MAX;
  }
  /* 推送告警给所有在线管理员 */
  userMap.forEach(function (u) {
    if (u && u.online && u.isAdmin) {
      emitToUser(u.id, 'moderation-alert', entry);
    }
  });
  console.warn('🛡️ [审核] ' + entry.fromName + ' → ' +
    (entry.scope === 'group' ? '群 ' + entry.to : '用户 ' + entry.to) +
    ' 命中敏感词 [' + hits.join(',') + ']');
}

var MAX_MUSIC_SIZE = 80 * 1024 * 1024;   /* 单曲上限 80MB */
var MAX_MUSIC_COUNT = 200;               /* 曲库上限 200 首 */

function saveMusicList() { saveJSON(F_MUSIC, musicList); }

function musicToClient(m) {
  return {
    id: m.id,
    name: m.name,
    artist: m.artist || '',
    album: m.album || '',
    url: '/music/' + encodeURIComponent(m.fileName),
    fileSize: m.fileSize,
    mimeType: m.mimeType,
    uploader: m.uploader,
    uploaderName: m.uploaderName,
    uploadTime: m.uploadTime,
    duration: m.duration || 0,
    likes: (m.likes || []).slice(),
    plays: m.plays || 0
  };
}
function findMusicIndex(id) {
  for (var i = 0; i < musicList.length; i++) {
    if (musicList[i].id === id) return i;
  }
  return -1;
}

/* ==================== 用户反馈数据层 ====================
   feedbackList：数组，每项形如
   { id, userId, userName, content, contact, status,
     adminNote, createdAt, updatedAt, history[] }
   —— 反馈编号格式：WL-000001（服务端自增，保留 6 位补零）
   —— status 取值：unconfirmed / confirmed / bydesign / fixed */
var F_FEEDBACK = path.join(DATA_DIR, 'feedback.json');
var feedbackList = loadJSON(F_FEEDBACK, []);
if (!Array.isArray(feedbackList)) feedbackList = [];

/* 反馈编号计数器：启动时从现有数据推导最大序号 */
var feedbackCounter = 0;
(function initFeedbackCounter() {
  for (var _fi = 0; _fi < feedbackList.length; _fi++) {
    var _fm = /^WL-(\d+)$/.exec(String(feedbackList[_fi].id || ''));
    if (_fm) {
      var _fn = parseInt(_fm[1], 10);
      if (_fn > feedbackCounter) feedbackCounter = _fn;
    }
  }
})();

function saveFeedback() { saveJSON(F_FEEDBACK, feedbackList); }

function genFeedbackId() {
  feedbackCounter++;
  var s = String(feedbackCounter);
  while (s.length < 6) s = '0' + s;
  return 'WL-' + s;
}

/* 反馈状态定义（服务端与客户端共用同一套键名） */
/* ============================================================
   ★ v0.24.53：状态与类型体系 —— 对齐 Mojang Bug Tracker
   ------------------------------------------------------------
   状态（8 种，颜色与 bugs.mojang.com 一致）：
     open / in_progress / resolved / fixed / cannot_reproduce /
     duplicate / invalid / wont_fix
   类型（4 种）：
     bug / feature / suggestion / question
   优先级沿用原有 4 档，配色对齐 bug tracker。
   兼容旧数据：老 unconfirmed/confirmed/bydesign 状态由
   normalizeStatus() 自动映射到新状态。
   ============================================================ */

var FEEDBACK_STATUS = {
  open:             { zh: '待处理',   en: 'Open',               color: '#d32f2f', icon: '🔴' },
  in_progress:      { zh: '处理中',   en: 'In Progress',        color: '#f57c00', icon: '🟠' },
  resolved:         { zh: '已解决',   en: 'Resolved',           color: '#388e3c', icon: '🟢' },
  fixed:            { zh: '已修复',   en: 'Fixed',              color: '#2e7d32', icon: '✅' },
  cannot_reproduce: { zh: '无法复现', en: 'Cannot Reproduce',   color: '#757575', icon: '⚪' },
  duplicate:        { zh: '重复',     en: 'Duplicate',          color: '#9e9e9e', icon: '🔁' },
  invalid:          { zh: '无效',     en: 'Invalid',            color: '#616161', icon: '⛔' },
  wont_fix:         { zh: '不予处理', en: "Won't Fix",          color: '#5d4037', icon: '🚫' }
};
function normalizeStatus(s) {
  if (FEEDBACK_STATUS[s]) return s;
  var _m = { unconfirmed: 'open', confirmed: 'in_progress', bydesign: 'wont_fix' };
  return _m[s] || 'open';
}
var FEEDBACK_CATEGORY = {
  bug:        { zh: '🐞 缺陷',   en: '🐞 Bug' },
  feature:    { zh: '💡 特性',   en: '💡 Feature' },
  suggestion: { zh: '✏️ 建议',   en: '✏️ Suggestion' },
  question:   { zh: '❓ 提问',   en: '❓ Question' }
};
function normalizeCategory(c) {
  if (FEEDBACK_CATEGORY[c]) return c;
  var _m = { ux: 'suggestion', perf: 'bug', other: 'question' };
  return _m[c] || 'question';
}
var FEEDBACK_PRIORITY = {
  low:    { zh: '低',   en: 'Low',    color: '#9e9e9e', weight: 1 },
  normal: { zh: '普通', en: 'Normal', color: '#1976d2', weight: 2 },
  high:   { zh: '高',   en: 'High',   color: '#f57c00', weight: 3 },
  urgent: { zh: '紧急', en: 'Urgent', color: '#d32f2f', weight: 4 }
};

/* ==================== 红包系统消息 ====================
   格式: "领取者"收了"发送者"的红包，领取了 X 元
   - 群聊：写入群历史，广播给所有群成员
   - 私聊：写入私聊历史，分别发给双方（peerId 指向对方，便于客户端定位会话） */
function buildRedpacketSystemMessage(packet, grabber, amountCents, claimedDuration) {
  var baseContent = '"' + grabber.name + '"收了"' + packet.fromName +
    '"的红包，领取了 ' + yuan(amountCents) + ' 元';
  /* 若本条消息是红包被抢完的那一条 → 追加「红包抢完了，在发出红包的 X 秒内」 */
  if (claimedDuration != null) {
    baseContent += '\n红包抢完了，在发出红包的 ' + claimedDuration + ' 秒内';
  }
  return {
    from: 'SYSTEM',
    fromName: '系统',
    content: baseContent,
    time: new Date().toLocaleString('zh-CN', { hour12: false }),
    msgId: generateId(),
    type: 'text',
    recalled: false,
    recalledBy: null,
    readUsers: [],
    fromLevel: 0,
    fromVip: false,
    fromAdmin: false,
    isRedpacketSys: true,
    /* 结构化字段，让客户端按当前语言本地化 */
    rpSysGrabber: grabber.name,
    rpSysFromName: packet.fromName,
    rpSysAmount: amountCents,
    /* ★ 红包 ID：客户端点击蓝色【红包】标签时跳转的目标 */
    rpSysPacketId: packet.id || null,
    /* ★ 是否为「抢完那一刻」的系统消息，以及抢光耗时 */
    rpSysFinished: claimedDuration != null,
    rpSysClaimedDuration: claimedDuration == null ? null : claimedDuration
  };
}

function broadcastRedpacketSystemMessage(packet, grabber, amountCents, claimedDuration) {
  try {
    var base = buildRedpacketSystemMessage(packet, grabber, amountCents, claimedDuration);

    if (packet.groupId) {
      var group = getGroupById(packet.groupId);
      if (!group) return;
      var gMsg = {};
      for (var gk in base) if (base.hasOwnProperty(gk)) gMsg[gk] = base[gk];
      gMsg.groupId = packet.groupId;
      var gkey = getHistoryKey('group', packet.groupId);
      saveMessage('group', gkey, gMsg);
      group.members.forEach(function (uid) {
        var u = getUserById(uid);
        if (u && u.online) emitToUser(uid, 'group-message', gMsg);
      });
      return;
    }

    if (packet.to) {
      var fromU = getUserById(packet.from);
      var toU = getUserById(packet.to);
      var pkey = getHistoryKey('private', packet.from, packet.to);
      saveMessage('private', pkey, base);

      /* 红包发送者视角：会话键 = 接收者的 id */
      if (fromU && fromU.online) {
        var msgFrom = {};
        for (var k1 in base) if (base.hasOwnProperty(k1)) msgFrom[k1] = base[k1];
        msgFrom.to = packet.to;
        msgFrom.peerId = packet.to;
        emitToUser(fromU.id, 'private-message', msgFrom);
      }
      /* 红包接收者视角：会话键 = 发送者的 id */
      if (toU && toU.online && toU.id !== packet.from) {
        var msgTo = {};
        for (var k2 in base) if (base.hasOwnProperty(k2)) msgTo[k2] = base[k2];
        msgTo.to = packet.from;
        msgTo.peerId = packet.from;
        emitToUser(toU.id, 'private-message', msgTo);
      }
    }
  } catch (e) {
    console.error('broadcastRedpacketSystemMessage error:', e);
  }
}

/* ============================================================
   群通话系统消息
   ------------------------------------------------------------
   · action = 'start' → 「xxx 发起了群语音/视频通话」
   · action = 'end'   → 「xxx 结束了群语音/视频通话，通话时长 X 分 Y 秒」
   只存结构化字段（gcSys*），客户端按当前语言重建文案；
   这样切换语言时历史记录也能跟着变，与红包系统消息一致。
   ============================================================ */
function broadcastGroupCallSystemMessage(groupId, user, action, callType, durationSec) {
  try {
    if (!groupId || !user) return;
    var group = getGroupById(groupId);
    if (!group) return;

    var _kindTxt = (callType === 'video') ? '群视频通话' : '群语音通话';
    var _dur = Math.max(0, Math.round(Number(durationSec) || 0));
    var content;
    if (action === 'start') {
      content = '"' + user.name + '"发起了' + _kindTxt;
    } else {
      var _durTxt = '';
      if (_dur >= 1) {
        var _m = Math.floor(_dur / 60);
        var _s = _dur % 60;
        _durTxt = (_m > 0)
          ? ('，通话时长 ' + _m + ' 分 ' + _s + ' 秒')
          : ('，通话时长 ' + _s + ' 秒');
      }
      content = '"' + user.name + '"结束了' + _kindTxt + _durTxt;
    }

    var msg = {
      /* ★ 关键修复：必须携带 groupId，客户端 group-message 处理器
         靠它定位会话；缺少时 gid === undefined，消息会被直接丢弃，
         表现为「群里看不到发起了通话 / 结束了通话」。 */
      groupId: groupId,
      from: 'SYSTEM',
      fromName: '系统',
      content: content,
      time: new Date().toLocaleString('zh-CN', { hour12: false }),
      msgId: generateId(),
      type: 'text',
      recalled: false,
      recalledBy: null,
      readUsers: [],
      fromLevel: 0,
      fromVip: false,
      fromAdmin: false,
      /* ---- 结构化字段，供客户端按语言重建 ---- */
      isGroupCallSys: true,
      gcSysAction: action,
      gcSysName: user.name,
      gcSysUserId: user.id,
      gcSysCallType: (callType === 'video') ? 'video' : 'voice',
      gcSysDuration: _dur
    };

    var gkey = getHistoryKey('group', groupId);
    saveMessage('group', gkey, msg);
    /* 广播给所有在线成员 → 客户端 addMessage() 会即时 renderMessages() */
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) emitToUser(uid, 'group-message', msg);
    });
  } catch (e) {
    console.error('broadcastGroupCallSystemMessage error:', e.message);
  }
}

/* ============================================================
   「微信支付」流水通知
   ------------------------------------------------------------
   在转账 / 红包 / 管理员调整余额时，向该用户的「微信支付」
   会话写入一条来自 wx_pay 的通知消息，客户端刷新即可看到。
   ============================================================ */
function pushWxPayNotice(userId, content, opts) {
  try {
    if (!userId) return;
    var user = getUserById(userId);
    if (!user) return;
    var key = getHistoryKey('private', userId, 'wx_pay');
    var msg = {
      from: 'wx_pay',
      fromName: '微信支付',
      to: userId,
      content: content,
      time: new Date().toLocaleString('zh-CN', { hour12: false }),
      msgId: generateId(),
      type: 'text',
      recalled: false, recalledBy: null,
      fromLevel: 100, fromVip: true, fromAdmin: false,
      fromVerified: '微信支付 官方账号',
      isWxPayNotice: true,
      noticeType: (opts && opts.type) || 'info',
      noticeIcon: (opts && opts.icon) || '💳'
    };
    saveMessage('private', key, msg);
    if (user.online) {
      emitToUser(user.id, 'private-message', msg);
    }
  } catch (e) {
    console.error('pushWxPayNotice error:', e.message);
  }
}

/* ============================================================
   系统账号消息上限：每个会话最多保留 5 条
   —— 每次登录都会追加一条欢迎 / 介绍消息，
      长期运行会无限累积，这里按标记字段做上限裁剪
   ============================================================ */
function trimSystemMessages(sessionKey, markerField, maxKeep) {
  try {
    if (!sessionKey) return;
    maxKeep = maxKeep || 5;
    var arr = messageHistory[sessionKey];
    if (!Array.isArray(arr) || arr.length <= maxKeep) return;

    /* 先把所有「系统消息」和「其它消息」分开统计 */
    var sysCount = 0;
    for (var i = 0; i < arr.length; i++) {
      if (arr[i] && arr[i][markerField]) sysCount++;
    }
    if (sysCount <= maxKeep) return;

    /* 从后往前保留最近 maxKeep 条系统消息，其余系统消息丢弃 */
    var kept = [];
    var remained = 0;
    for (var j = arr.length - 1; j >= 0; j--) {
      var m = arr[j];
      if (m && m[markerField]) {
        if (remained < maxKeep) {
          kept.unshift(m);
          remained++;
        }
        /* 超出的系统消息直接跳过（丢弃） */
      } else {
        kept.unshift(m);
      }
    }
    messageHistory[sessionKey] = kept;
  } catch (e) {
    console.error('trimSystemMessages error:', e.message);
  }
}

/* ============================================================
   红包金额算法（拼手气）—— 微信算法 × 完全随机 · 混合
   ------------------------------------------------------------
   ▍微信算法（两倍均值法）
       每次上限 = 2 × 剩余均值，在 [1, 上限] 均匀采样。
       [1, 2·avg] 的数学期望 = avg，因此先抢后抢的期望所得相等，
       天然保证公平 —— 这就是微信官方采用的算法。

   ▍完全随机
       上限 = min(3 × 剩余均值, 硬上限)，在 [1, 上限] 均匀采样。
       上限拉到 3 倍均值，区间更宽、方差更大，
       会出现明显低于均值的小额和接近 3 倍均值的大额。

   ▍混合
       每次采样的上限，以概率 (wWechat, wRandom) 掷骰子选择：
         - 已领比例 [0%,   30%)  → 微信 45% / 随机 55%  (前段戏剧性)
         - 已领比例 [30%,  70%)  → 微信 65% / 随机 35%  (均衡)
         - 已领比例 [70%, 100%)  → 微信 85% / 随机 15%  (后段保公平)

       这样：
         · 前面几份波动大 → 有人抢到"大红包"，有人只抢到几分
         · 中间几份趋于稳定 → 落回微信的公平区间
         · 后面几份几乎全走微信 → 尾包不会比均值瘦太多

   ▍硬约束（两种分支共用）
       · 上限 ≤ left - (leftCount - 1)  →  余下每人至少能拿 1 分
       · 最后一份 = left               →  剩余全部给最后一人

   金额以「分」为单位做整数运算，避免浮点误差。
   ============================================================ */
function pickRedpacketAmount(packet) {
  var left = packet.amount - packetClaimedTotal(packet);
  var leftCount = packet.count - packetClaimedCount(packet);
  if (leftCount <= 0 || left <= 0) return 0;

  /* ---- 最后一份：剩余全部给他 ---- */
  if (leftCount === 1) return left;

  /* ---- 普通红包：等额分配（保持原语义） ---- */
  if (packet.type === 'normal') {
    var per = Math.floor(left / leftCount);
    if (per < 1) per = 1;
    if (per > left - (leftCount - 1)) per = left - (leftCount - 1);
    if (per < 1) per = 1;
    return per;
  }

  /* ---- 拼手气：微信 × 完全随机 · 混合 ---- */
  var avg = left / leftCount;                 /* 当前剩余均值（分） */
  var hardCap = left - (leftCount - 1);       /* 硬上限：留足后面每人 1 分 */
  if (hardCap < 1) hardCap = 1;

  /* 进度：已领份数 / (总份数 - 1)，最后一份除外
     —— 用 (count - 1) 做分母，使 0 ~ 1 之间均匀分布 */
  var claimed = packetClaimedCount(packet);
  var progress = packet.count > 1 ? claimed / (packet.count - 1) : 1;

  /* 混合权重（阶段渐进：前随机、后微信） */
  var wWechat, wRandom;
  if (progress < 0.3) {
    wWechat = 0.45; wRandom = 0.55;
  } else if (progress < 0.7) {
    wWechat = 0.65; wRandom = 0.35;
  } else {
    wWechat = 0.85; wRandom = 0.15;
  }
  var totalW = wWechat + wRandom;              /* 归一化兜底 */

  /* 微信分支上限：2 × 均值（经典二倍均值法） */
  var upperWechat = Math.floor(2 * avg);

  /* 完全随机分支上限：min(3 × 均值, 硬上限)
     用 3 倍均值而不是硬上限，避免前几份一次把余额吃光 */
  var upperRandom = Math.floor(3 * avg);
  if (upperRandom > hardCap) upperRandom = hardCap;

  /* 掷骰子选分支 */
  var r = Math.random() * totalW;
  var upper = (r < wWechat) ? upperWechat : upperRandom;

  /* 硬约束（微信分支的 2×avg 在某些极端情况下可能 > hardCap） */
  if (upper > hardCap) upper = hardCap;
  if (upper < 1) upper = 1;

  /* 均匀采样 [1, upper] */
  var amt = Math.floor(Math.random() * upper) + 1;

  /* 双保险 */
  if (amt < 1) amt = 1;
  if (amt > upper) amt = upper;
  if (amt > hardCap) amt = hardCap;

  return amt;
}

/* ==================== 全局内存映射 ====================
   userMap / groupMap 是服务端核心数据容器。
   之前漏掉声明 → getUserById / getGroupById / loadGroups /
   saveGroups / broadcastGroupList 等都会抛 TypeError，
   群聊消息、用户列表、已读回执全部失效。
   groupReadMap：群消息已读回执 { groupId: { msgId: Set(userId) } }
   MAX_HISTORY ：每个会话最多保留的历史消息条数 */
var userMap = new Map();
var groupMap = new Map();
var groupReadMap = {};
/* 单会话消息上限：3000 条（服务端内存保留，磁盘全部保留） */
var MAX_HISTORY = 3000;
/* 每次下发给客户端的消息条数。用户滚动到顶部时按需加载。 */
var HISTORY_PAGE_SIZE = 50;


var MAX_LEVEL = 1000;

/* EXP_TABLE[lv] = 从 1 级升到 lv 级所需的累计经验
   ★ v0.28.0：等级上限扩展到 1000 级。
     · 2 ~ 39 级：保持原值（兼容旧数据）
     · 40 ~ 1000 级：每 10 级为一组，每级增量 +100
       （40-49 组每级 +90；50-59 组每级 +190；…；1000 级单独 +9690） */
var EXP_TABLE = (function () {
  var t = new Array(MAX_LEVEL + 1);
  t[0] = 0;
  t[1] = 0;
  var lv2to39 = [
    15, 30, 45, 90, 110, 130, 150, 200, 260, 300,
    370, 420, 490, 560, 630, 700, 780, 800, 840, 870,
    960, 1100, 1200, 1300, 1400, 1600, 1800, 1880, 1990,
    2100, 2210, 2330, 2340, 2440, 2550, 2640, 2760, 2850
  ];
  for (var i = 0; i < lv2to39.length; i++) t[i + 2] = lv2to39[i];
  var last = 2850;
  var inc = 90;
  for (var lv = 40; lv <= MAX_LEVEL; lv++) {
    last += inc;
    t[lv] = last;
    /* 每满 10 级 → 下一组每级增量 +100 */
    if ((lv - 39) % 10 === 0 && lv < MAX_LEVEL) inc += 100;
  }
  return t;
})();

function calcLevelFromExp(exp) {
  var e = Math.max(0, Math.floor(Number(exp) || 0));
  for (var lv = MAX_LEVEL; lv >= 1; lv--) {
    if (e >= EXP_TABLE[lv]) return lv;
  }
  return 1;
}

function expForLevel(lv) {
  lv = Math.max(1, Math.min(MAX_LEVEL, Math.floor(Number(lv)) || 1));
  return EXP_TABLE[lv] || 0;
}

/* 本地日期 YYYY-MM-DD */
function todayStr() {
  var d = new Date();
  return d.getFullYear() + '-' +
    (d.getMonth() + 1 < 10 ? '0' : '') + (d.getMonth() + 1) + '-' +
    (d.getDate() < 10 ? '0' : '') + d.getDate();
}

var _saveUsersTimer = null;
function scheduleSaveUsers() {
  if (_saveUsersTimer) return;
  _saveUsersTimer = setTimeout(function () {
    _saveUsersTimer = null;
    saveUsers();
  }, 1000);
}

/* 给用户增加经验；返回 { userId, name, exp, level, oldLevel, leveledUp, gained } */
function addExpToUser(userId, amount) {
  var amt = Math.floor(Number(amount) || 0);
  if (!userId || amt === 0) return null;

  var user = userMap.get(userId);
  if (user) {
    if (typeof user.exp !== 'number' || isNaN(user.exp)) {
      user.exp = expForLevel(user.level || 1);
    }
    var oldLevel = user.level || 1;
    user.exp = Math.max(0, user.exp + amt);
    var newLevel = calcLevelFromExp(user.exp);
    user.level = newLevel;
    if (persistentUsers[user.name]) {
      persistentUsers[user.name].exp = user.exp;
      persistentUsers[user.name].level = newLevel;
    }
    scheduleSaveUsers();
    return {
      userId: user.id, name: user.name, exp: user.exp,
      level: newLevel, oldLevel: oldLevel,
      leveledUp: newLevel > oldLevel, gained: amt
    };
  }

  for (var k in persistentUsers) {
    if (!persistentUsers.hasOwnProperty(k)) continue;
    var rec = persistentUsers[k];
    if (rec && rec.id === userId) {
      if (typeof rec.exp !== 'number' || isNaN(rec.exp)) {
        rec.exp = expForLevel(rec.level || 1);
      }
      var oldLv = rec.level || 1;
      rec.exp = Math.max(0, rec.exp + amt);
      rec.level = calcLevelFromExp(rec.exp);
      scheduleSaveUsers();
      return {
        userId: userId, name: rec.name, exp: rec.exp,
        level: rec.level, oldLevel: oldLv,
        leveledUp: rec.level > oldLv, gained: amt
      };
    }
  }
  return null;
}

/* 统一下发经验变化的辅助函数 */
function pushExpResult(socket, expRes, reason) {
  if (!expRes) return;
  socket.emit('exp-gained', {
    amount: expRes.gained,
    reason: reason || 'unknown',
    exp: expRes.exp,
    level: expRes.level,
    oldLevel: expRes.oldLevel,
    leveledUp: expRes.leveledUp
  });
  if (expRes.leveledUp) {
    io.emit('user-updated', {
      id: expRes.userId, name: expRes.name,
      level: expRes.level, exp: expRes.exp
    });
  }
}

