// 说明：本 IIFE 已在文件上方执行过一次，此处不再重复。
// （重复执行会浪费启动时间，也可能因两次写入持久化文件
//   造成 disk I/O 抖动。）

/* ==================== 群通话状态（内存，不持久化） ====================
   groupCalls[groupId] = {
     groupId, hostId, type: 'voice'|'video',
     startedAt, participants: Set(uid)
   }
   通话过程中任何成员通过 P2P mesh 连接所有其他参与者；本结构仅用于
   告诉客户端「谁参与了通话」，以及新加入者需要跟谁建 P2P。 */
var groupCalls = {};
var MAX_GROUP_CALL_PARTICIPANTS = 6;

/* ============================================================
   ★ 一次性数据修复：清理 `private_<id>_system` 会话中的红包系统消息
   ------------------------------------------------------------
   历史版本允许向 system 发红包，红包系统消息（from='system'）
   被写进了与欢迎消息相同的会话 key 中。这些残留消息会让客户端
   在 history-bulk 里错把系统账号显示成"系统"。
   此处按 msgId 前缀/结构特征剔除，避免污染。
   ============================================================ */
(function cleanupSystemSessionResidue() {
  try {
    var _cleaned = 0;
    for (var _key in messageHistory) {
      if (!messageHistory.hasOwnProperty(_key)) continue;
      if (_key.indexOf('private_') !== 0) continue;
      /* 只处理对端是 system 的会话 */
      var _rest = _key.substring(8);
      var _idx = _rest.indexOf('_');
      if (_idx === -1) continue;
      var _a = _rest.substring(0, _idx);
      var _b = _rest.substring(_idx + 1);
      if (_a !== 'system' && _b !== 'system') continue;
      var _arr = messageHistory[_key];
      if (!Array.isArray(_arr)) continue;
      /* 剔除红包系统消息 / 通话记录 / 群通话系统消息：
         这些消息的 from 都是 'system' 且不是欢迎消息 */
      var _filtered = _arr.filter(function (m) {
        if (!m || m.from !== 'system') return true;
        /* 保留欢迎消息 */
        if (m.isWelcome) return true;
        /* 其余系统消息（红包 / 通话 / 群通话）一律剔除 */
        return false;
      });
      if (_filtered.length !== _arr.length) {
        _cleaned += _arr.length - _filtered.length;
        messageHistory[_key] = _filtered;
      }
    }
    if (_cleaned > 0) {
      saveJSON(F_HISTORY, messageHistory);
      console.log('🧹 已清理 ' + _cleaned + ' 条系统会话残留消息');
    }
  } catch (e) {
    console.error('⚠️ 系统会话清理失败（已跳过）:', e.message);
  }
})();

(function loadGroups() {
  var arr = loadJSON(F_GROUPS, []);
  if (!Array.isArray(arr)) return;
  
  for (var i = 0; i < arr.length; i++) {
    var g = arr[i];
    if (!g || !g.id) continue;
    
    try {
      /* 兼容旧数据：防止因意外导致 members 变成对象 */
      var _members = g.members;
      if (!Array.isArray(_members)) {
        if (_members && typeof _members === 'object') {
          _members = Object.keys(_members);
        } else {
          _members = [];
        }
      }

      var memberSet = new Set(_members);
      
      /* 过滤掉不应该当群主的系统账号 */
      ['SYSTEM', 'system', 'wx_team', 'wx_pay'].forEach(function(sysId) {
        memberSet.delete(sysId);
      });

      /* 确保群主一定在群成员列表里 */
      if (g.owner && !memberSet.has(g.owner)) {
        memberSet.add(g.owner);
      }

      groupMap.set(g.id, {
        id: g.id, name: g.name, owner: g.owner,
        members: memberSet,
        titles: g.titles || {},
        announcement: g.announcement || '',
        announcements: (function() {
          var arr = g.announcements || [];
          if (!arr.length && g.announcement && g.announcement.trim()) {
            arr.push({
              id: 'ann_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6),
              text: g.announcement.trim(),
              time: g.announcementTime || Date.now(),
              author: g.announcementAuthor || '群主',
              pinned: true
            });
          }
          return arr;
        })(),
        muted: g.muted || {},
        allMuted: !!g.allMuted,
        files: g.files || [],
        albums: g.albums || [],
        votes: g.votes || [],
        /* 已解散状态（重启后恢复） */
        disbanded: !!g.disbanded,
        disbandedAt: g.disbandedAt || 0,
        disbandedBy: g.disbandedBy || '',
        disbandedByName: g.disbandedByName || ''
      });
    } catch (e) {
      console.error('⚠️ 群组加载失败:', g.id, e.message);
    }
  }
  
  console.log('📦 已加载群组:', groupMap.size, '个');
})();

