<div class="call-modal" id="callModal" style="display:none;">
  <!-- 视频通话背景层 -->
  <div class="call-video-wrap" id="callVideoWrap">
    <video class="call-video-remote" id="callRemoteVideo" autoplay playsinline></video>
    <video class="call-video-local mirror" id="callLocalVideo" autoplay playsinline muted></video>
    <div class="call-video-info" id="callVideoInfo">
      <span class="call-video-name" id="callVideoName">—</span>
      <span class="call-video-timer" id="callVideoTimer"></span>
    </div>
  </div>
  <!-- 语音通话 / 呼叫中背景层 -->
  <div class="call-stage" id="callStage">
    <!-- ★ 连接质量指示器：常驻右上角，仅在通话中显示 -->
    <div class="call-quality" id="callQuality" title="连接质量">
      <span class="cq-bars">
        <i class="cq-bar"></i><i class="cq-bar"></i><i class="cq-bar"></i>
      </span>
      <span class="cq-text" id="callQualityText">—</span>
    </div>
    <div class="call-avatar-wrap">
      <div class="call-avatar-ring"></div>
      <div class="call-avatar-ring"></div>
      <div class="call-avatar-ring"></div>
      <!-- ★ 音量环：对方说话时播放发光动画 -->
      <div class="call-volume-ring" id="callVolumeRing"></div>
      <div class="call-avatar" id="callAvatar">?</div>
      <!-- ★ 静音徽章：对方静音时显示在头像右下角 -->
      <div class="call-mute-badge" id="callMuteBadge" title="对方已静音">🔇</div>
    </div>
    <div class="call-name" id="callName">—</div>
    <div class="call-status" id="callStatus"></div>
  </div>
  <!-- 控制按钮 -->
  <div class="call-actions" id="callActions">
    <button class="call-btn reject" id="callRejectBtn" style="display:none;">
      <span>📵</span>
      <span class="call-btn-label" id="callRejectLabel">拒接</span>
    </button>
    <button class="call-btn accept" id="callAcceptBtn" style="display:none;">
      <span>📞</span>
      <span class="call-btn-label" id="callAcceptLabel">接听</span>
    </button>
    <button class="call-btn hangup" id="callHangupBtn" style="display:none;">
      <span>📵</span>
      <span class="call-btn-label" id="callHangupLabel">挂断</span>
    </button>
    <button class="call-btn" id="callMuteBtn" style="display:none;">
      <span id="callMuteIcon">🎙️</span>
      <span class="call-btn-label" id="callMuteLabel">静音</span>
    </button>
    <button class="call-btn" id="callVideoToggleBtn" style="display:none;">
      <span id="callVideoToggleIcon">📹</span>
      <span class="call-btn-label" id="callVideoToggleLabel">关闭视频</span>
    </button>
    <button class="call-btn" id="callSwitchCameraBtn" style="display:none;">
      <span>🔄</span>
      <span class="call-btn-label" id="callSwitchLabel">切换</span>
    </button>
  </div>
</div>

