/* ==================== 更新日志：按需加载 ====================
   CHANGELOG_DATA 已迁移到服务端（GET /api/changelog）。
   客户端仅在用户打开「更新日志」弹窗时才请求，
   未打开则完全不传输 —— 节省约 60KB 初始 HTML 体积。

   下面是客户端侧的本地化函数与按需加载器，与之前的逻辑一致。 */

/* ============================================================
   ★ v0.26.1：更新日志文本读取
   ------------------------------------------------------------
   源数据已全部为纯中文字符串，此处仅做非中文语言的短路处理。
   ============================================================ */
function clText(v) {
  /* 非中文语言 → 统一返回提示文本 */
  if (state.lang !== 'zh') {
    return t('changelogNonChinese');
  }
  if (v == null) return '';
  /* 兼容性：万一有残留对象，取第一个字符串值 */
  if (typeof v === 'object') {
    for (var k in v) if (v.hasOwnProperty(k)) return String(v[k]);
    return '';
  }
  return String(v);
}

/* ---- 按需获取更新日志数据（首次打开弹窗时请求，之后命中缓存） ---- */
var _changelogDataCache = null;
var _changelogFetching = null;
function fetchChangelogData() {
  /* ★ v0.31.3：只读模式下 /api/changelog 已被 403 拦截，
     直接返回空数组，避免客户端弹出"加载失败"错误提示。 */
  if (window.__readonlyMode === true || state.readonlyMode === true) {
    _changelogDataCache = [];
    return Promise.resolve([]);
  }
  if (_changelogDataCache) return Promise.resolve(_changelogDataCache);
  if (_changelogFetching) return _changelogFetching;

  /* ★ 三层回退：
       1. fetch /api/changelog
       2. 失败 → 读取服务端内嵌到 HTML 的 window.__CHANGELOG_DATA__
       3. 都失败 → 返回空数组（弹窗显示"暂无更新记录"，不会"加载失败"） */
  _changelogFetching = fetch('/api/changelog', {
    method: 'GET',
    headers: { 'Accept': 'application/json' }
  }).then(function (r) {
    console.log('📋 [changelog] HTTP', r.status, r.headers.get('content-type'));
    if (!r.ok) throw new Error('HTTP ' + r.status);
    return r.json();
  }).then(function (data) {
    if (!Array.isArray(data)) throw new Error('not an array');
    console.log('📋 [changelog] 加载成功，共', data.length, '个版本');
    _changelogDataCache = data;
    _changelogFetching = null;
    return _changelogDataCache;
  }).catch(function (err) {
    console.warn('⚠️ [changelog] fetch 失败:', err.message, '→ 尝试内嵌数据');
    _changelogFetching = null;

    /* 回退：服务端在 buildHtml 里注入的内嵌数据 */
    try {
      if (Array.isArray(window.__CHANGELOG_DATA__) &&
          window.__CHANGELOG_DATA__.length) {
        console.log('📋 [changelog] 使用内嵌数据，共',
          window.__CHANGELOG_DATA__.length, '个版本');
        _changelogDataCache = window.__CHANGELOG_DATA__;
        return _changelogDataCache;
      }
    } catch (e) {}

    /* 最终兜底：空数组（弹窗显示"暂无更新记录"，而不是"加载失败"） */
    _changelogDataCache = [];
    return _changelogDataCache;
  });
  return _changelogFetching;
}

/* 客户端缓存上限：红包 / 语音波形 / 翻译 / 表情回应，超出后 FIFO 淘汰 */
var _CLIENT_CACHE_LIMIT = {
  redPacket: 200,     /* 红包状态缓存 */
  voiceWave: 300,     /* 语音波形缓存 */
  translate: 100,     /* 翻译结果缓存 */
  reactions: 300      /* 表情回应快照（滑动窗口） */
};

/* 客户端缓存淘汰：保留最近 N 条（FIFO） */
function _clientCacheTrim(obj, limit) {
  if (!obj || typeof obj !== 'object') return;
  var keys = Object.keys(obj);
  if (keys.length <= limit) return;
  var dropN = keys.length - limit;
  for (var i = 0; i < dropN; i++) {
    delete obj[keys[i]];
  }
}

