/* 客户端单会话消息上限：切换会话时裁回最近 N 条 */
var CLIENT_MAX_HISTORY = 500;

/* 按需加载分页大小（与服务端一致） */
var CLIENT_HISTORY_PAGE = 50;

/* 客户端消息数组裁剪 */
function _trimClientHistory(arr) {
  if (!Array.isArray(arr)) return arr;
  if (arr.length <= CLIENT_MAX_HISTORY) return arr;
  arr.splice(0, arr.length - CLIENT_MAX_HISTORY);
  return arr;
}

/* PC 侧栏宽度：0 = 未自定义（走响应式） */
try {
  var _psw = parseInt(localStorage.getItem('pc_sidebar_width') || '0', 10);
  state.pcSidebarWidth = (isNaN(_psw) || _psw < 180 || _psw > 400) ? 0 : _psw;
} catch (e) { state.pcSidebarWidth = 0; }
try {
  var _pgw = parseInt(localStorage.getItem('pc_gsp_width') || '0', 10);
  state.pcGspWidth = (isNaN(_pgw) || _pgw < 240 || _pgw > 520) ? 0 : _pgw;
} catch (e) { state.pcGspWidth = 0; }

function applyPcPanelWidths() {
  var root = document.documentElement;
  if (!root) return;

  /* ---- 联系人栏 ---- */
  if (state.pcSidebarWidth > 0) {
    root.style.setProperty('--pc-sidebar-width', state.pcSidebarWidth + 'px');
    root.classList.add('has-custom-sidebar-width');
  } else {
    root.style.removeProperty('--pc-sidebar-width');
    root.classList.remove('has-custom-sidebar-width');
  }

  /* ---- 群聊侧栏 ---- */
  if (state.pcGspWidth > 0) {
    root.style.setProperty('--pc-gsp-width', state.pcGspWidth + 'px');
    root.classList.add('has-custom-gsp-width');
  } else {
    root.style.removeProperty('--pc-gsp-width');
    root.classList.remove('has-custom-gsp-width');
  }

  /* ---- 同步设置面板里的滑块显示值 ---- */
  var s1 = document.getElementById('setPcSidebarWidth');
  var v1 = document.getElementById('setPcSidebarWidthVal');
  if (s1 && v1) {
    if (state.pcSidebarWidth > 0) {
      s1.value = String(state.pcSidebarWidth);
      v1.textContent = state.pcSidebarWidth + 'px';
      v1.style.color = 'var(--accent)';
    } else {
      s1.value = '240';
      v1.textContent = '默认';
      v1.style.color = 'var(--text-secondary)';
    }
  }
  var s2 = document.getElementById('setPcGspWidth');
  var v2 = document.getElementById('setPcGspWidthVal');
  if (s2 && v2) {
    if (state.pcGspWidth > 0) {
      s2.value = String(state.pcGspWidth);
      v2.textContent = state.pcGspWidth + 'px';
      v2.style.color = 'var(--accent)';
    } else {
      s2.value = '280';
      v2.textContent = '默认';
      v2.style.color = 'var(--text-secondary)';
    }
  }

  /* ---- 移动端直接忽略：设置里保留滑块，但不实际生效 ---- */
  if (window.innerWidth <= 768) {
    /* 移动端不应用宽度类，避免破坏全屏抽屉布局 */
    if (state.pcSidebarWidth > 0) {
      /* 已经设过变量，但 CSS 规则只在 html.is-pc 下生效 —— 安全 */
    }
  }
}

/* 页面加载时立即应用一次（此时 html 上可能还没 is-pc 类，
   后续 initLayoutModeClass 会补上，配合 is-pc 类规则才生效） */
applyPcPanelWidths();

