function saveChatBgMap() {
  try { localStorage.setItem('chat_bg_map', JSON.stringify(state.chatBgMap)); } catch (e) {}
}

function applyChatBackground() {
  var list = dom.messageList;
  if (!list) return;
  var key = '';
  if (state.currentTarget && state.currentType) {
    key = (state.currentType === 'private' ? 'private_' : 'group_') + state.currentTarget;
  }
  var bg = key ? state.chatBgMap[key] : '';
  if (bg) {
    list.style.backgroundImage = 'url("' + String(bg).replace(/"/g, '%22') + '")';
    list.style.backgroundSize = 'cover';
    list.style.backgroundPosition = 'center';
    list.style.backgroundRepeat = 'no-repeat';
    list.classList.add('has-custom-bg');
  } else {
    list.style.backgroundImage = '';
    list.style.backgroundSize = '';
    list.style.backgroundPosition = '';
    list.style.backgroundRepeat = '';
    list.classList.remove('has-custom-bg');
  }
}

/* ★ v0.27.0：弹出设置聊天背景对话框 */
function promptChatBg(id, type) {
  var key = (type === 'private' ? 'private_' : 'group_') + id;
  var cur = state.chatBgMap[key] || '';
  var _name = '';
  if (type === 'private') {
    _name = (state.users[id] && state.users[id].name) || id;
  } else {
    _name = (state.groups[id] && state.groups[id].name) || id;
  }
  showModal(
    '🖼️ 设置聊天背景 · ' + _name,
    '<div style="font-size:13px;color:#666;line-height:1.7;margin-bottom:12px;">' +
    '选择一个本地图片作为该会话的背景。<br>' +
    '留空点保存 = 清除当前会话背景。</div>' +
    '<input type="file" id="chatBgFile" accept="image/*" ' +
    'style="width:100%;padding:8px 12px;border:1px solid #ddd;' +
    'border-radius:10px;background:#fff;font-size:13px;">' +
    '<div id="chatBgPreview" style="margin-top:12px;text-align:center;' +
    'min-height:80px;border-radius:10px;background:#f5f5f5;padding:8px;' +
    'font-size:12px;color:#999;line-height:80px;">' +
    (cur ? '当前已设置背景' : '未选择图片') + '</div>',
    function () {
      /* 保存按钮 */
      var fileEl = document.getElementById('chatBgFile');
      var f = fileEl && fileEl.files && fileEl.files[0];
      if (!f) {
        /* 没有选新图 → 询问是否清除 */
        if (cur) {
          if (confirm('未选择新图片，是否清除当前会话的背景？')) {
            delete state.chatBgMap[key];
            saveChatBgMap();
            if (state.currentTarget === id && state.currentType === type) {
              applyChatBackground();
            }
            showToast('已清除会话背景');
          }
        } else {
          showToast('未选择图片');
        }
        return;
      }
      if (!/^image\//.test(f.type)) { showToast('请选择图片'); return; }
      if (f.size > 3 * 1024 * 1024) { showToast('图片太大（≤ 3MB）'); return; }
      var rd = new FileReader();
      rd.onload = function (ev) {
        var data = ev.target.result;
        if (data.length > 1.6e6) {
          showToast('图片处理后仍然过大，请换一张更小的');
          return;
        }
        state.chatBgMap[key] = data;
        saveChatBgMap();
        if (state.currentTarget === id && state.currentType === type) {
          applyChatBackground();
        }
        showToast('✅ 会话背景已设置');
      };
      rd.readAsDataURL(f);
    },
    { width: '420px', confirmText: '保存' }
  );
}
