function $id(id) { return document.getElementById(id); }

/* 自绘 select：保留原 select 元素（隐藏）以兼容既有事件监听 */
function enhanceSelect(selectEl) {
  if (!selectEl || selectEl._customized) return;
  selectEl._customized = true;

  /* ---- 外层容器 ---- */
  var wrapper = document.createElement('div');
  wrapper.className = 'custom-select';
  if (selectEl.classList.contains('custom-select-block')) {
    wrapper.classList.add('custom-select-block');
  }
  selectEl.parentNode.insertBefore(wrapper, selectEl);
  wrapper.appendChild(selectEl);
  selectEl.classList.add('custom-select-native');

  /* ---- 触发器 ---- */
  var trigger = document.createElement('button');
  trigger.type = 'button';
  trigger.className = 'custom-select-trigger';
  trigger.setAttribute('aria-haspopup', 'listbox');

  var label = document.createElement('span');
  label.className = 'custom-select-label';

  var arrow = document.createElement('span');
  arrow.className = 'custom-select-arrow';
  arrow.textContent = '▼';

  trigger.appendChild(label);
  trigger.appendChild(arrow);
  wrapper.appendChild(trigger);

  /* ---- 菜单 ---- */
  var menu = document.createElement('div');
  menu.className = 'custom-select-menu';
  menu.setAttribute('role', 'listbox');
  wrapper.appendChild(menu);

  /* ---- 渲染选项 ---- */
  function renderOptions() {
    menu.innerHTML = '';
    var _groups = {};
    for (var i = 0; i < selectEl.options.length; i++) {
      (function (opt, idx) {
        var item = document.createElement('div');
        item.className = 'custom-select-option';
        item.setAttribute('role', 'option');
        item.dataset.value = String(opt.value);
        item.dataset.idx = String(idx);
        item.textContent = opt.textContent;
        if (opt.disabled) item.classList.add('disabled');
        if (idx === selectEl.selectedIndex) item.classList.add('selected');
        item.addEventListener('click', function (e) {
          e.stopPropagation();
          if (opt.disabled) return;
          selectEl.selectedIndex = idx;
          try {
            selectEl.dispatchEvent(new Event('change', { bubbles: true }));
          } catch (er) {
            var ev = document.createEvent('HTMLEvents');
            ev.initEvent('change', true, false);
            selectEl.dispatchEvent(ev);
          }
          syncLabel();
          closeMenu();
          try { trigger.focus(); } catch (er2) {}
        });
        menu.appendChild(item);
      })(selectEl.options[i], i);
    }
  }

  /* ---- 同步显示值 ---- */
  function syncLabel() {
    var opt = selectEl.options[selectEl.selectedIndex];
    label.textContent = opt ? opt.textContent : '—';
    var items = menu.querySelectorAll('.custom-select-option');
    for (var i = 0; i < items.length; i++) {
      items[i].classList.toggle('selected',
        items[i].dataset.value === String(selectEl.value));
    }
    wrapper.classList.toggle('disabled', !!selectEl.disabled);
    trigger.disabled = !!selectEl.disabled;
  }

  /* ---- 打开 / 关闭 ---- */
  function closeOtherMenus() {
    var others = document.querySelectorAll('.custom-select.open');
    for (var i = 0; i < others.length; i++) {
      if (others[i] !== wrapper) others[i].classList.remove('open');
    }
  }

  function openMenu() {
    closeOtherMenus();
    /* 视口底部 → 朝上展开 */
    var r = trigger.getBoundingClientRect();
    var vh = window.innerHeight || document.documentElement.clientHeight || 0;
    var spaceBelow = vh - r.bottom;
    if (spaceBelow < 240 && r.top > spaceBelow) {
      wrapper.classList.add('drop-up');
    } else {
      wrapper.classList.remove('drop-up');
    }
    wrapper.classList.add('open');
    var sel = menu.querySelector('.custom-select-option.selected');
    if (sel) {
      try { sel.scrollIntoView({ block: 'nearest' }); } catch (e) {}
    }
  }

  function closeMenu() {
    wrapper.classList.remove('open');
  }

  function toggleMenu() {
    if (wrapper.classList.contains('open')) closeMenu();
    else openMenu();
  }

  /* ---- 事件 ---- */
  trigger.addEventListener('click', function (e) {
    e.stopPropagation();
    if (selectEl.disabled) return;
    toggleMenu();
  });

  trigger.addEventListener('keydown', function (e) {
    var k = e.key;
    if (k === 'ArrowDown' || k === 'ArrowUp') {
      e.preventDefault();
      if (!wrapper.classList.contains('open')) { openMenu(); return; }
      var items = menu.querySelectorAll('.custom-select-option:not(.disabled)');
      var cur = -1;
      for (var i = 0; i < items.length; i++) {
        if (items[i].classList.contains('selected')) { cur = i; break; }
      }
      var delta = (k === 'ArrowDown') ? 1 : -1;
      var next = cur + delta;
      if (next < 0) next = items.length - 1;
      if (next >= items.length) next = 0;
      if (items[next]) items[next].click();
    } else if (k === 'Enter' || k === ' ') {
      e.preventDefault();
      if (wrapper.classList.contains('open')) {
        var sel = menu.querySelector('.custom-select-option.selected');
        if (sel) sel.click();
        else closeMenu();
      } else {
        openMenu();
      }
    } else if (k === 'Escape') {
      if (wrapper.classList.contains('open')) {
        e.preventDefault();
        closeMenu();
      }
    } else if (k === 'Tab') {
      closeMenu();
    }
  });

  document.addEventListener('click', function (e) {
    if (!wrapper.contains(e.target)) closeMenu();
  });

  /* ---- 程序修改 select 时同步（例如语言切换重填 option）---- */
  try {
    var observer = new MutationObserver(function () {
      renderOptions();
      syncLabel();
    });
    observer.observe(selectEl, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['disabled', 'selected']
    });
  } catch (e) {}

  selectEl.addEventListener('change', syncLabel);

  /* ---- 首次渲染 ---- */
  renderOptions();
  syncLabel();
}

/* 批量转换 */
function enhanceAllSelects(root) {
  try {
    var scope = root || document;
    var selects = scope.querySelectorAll('select:not(.custom-select-native)');
    for (var i = 0; i < selects.length; i++) enhanceSelect(selects[i]);
  } catch (e) {
    console.warn('[custom-select] 转换失败:', e && e.message);
  }
}

/* 自绘时间选择器：input[type=time] → 小时+分钟两个 select，原 input 保留为 "HH:MM" */
function enhanceTimeInput(input, opts) {
  if (!input || input._customized) return;
  input._customized = true;
  opts = opts || {};
  var minStep = opts.minuteStep || 5;

  var wrap = document.createElement('span');
  wrap.className = 'tp-wrap';

  function buildSel(count, step, pad2) {
    var s = document.createElement('select');
    for (var i = 0; i < count; i += step) {
      var o = document.createElement('option');
      o.value = String(i);
      o.textContent = pad2 ? ((i < 10 ? '0' : '') + i) : String(i);
      s.appendChild(o);
    }
    return s;
  }

  var hourSel = buildSel(24, 1, true);
  var minSel  = buildSel(60, minStep, true);

  /* 解析当前值 */
  var raw = String(input.value || '').trim();
  var parts = raw ? raw.split(':') : ['00', '00'];
  var hh = parseInt(parts[0], 10);
  var mm = parseInt(parts[1], 10);
  if (isNaN(hh) || hh < 0 || hh > 23) hh = 0;
  if (isNaN(mm) || mm < 0 || mm > 59) mm = 0;
  mm = Math.round(mm / minStep) * minStep;
  if (mm >= 60) mm = 60 - minStep;
  hourSel.value = String(hh);
  minSel.value = String(mm);

  function sync() {
    var h = parseInt(hourSel.value, 10) || 0;
    var m = parseInt(minSel.value, 10) || 0;
    input.value = (h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m;
    try {
      input.dispatchEvent(new Event('change', { bubbles: true }));
    } catch (e) {
      var ev = document.createEvent('HTMLEvents');
      ev.initEvent('change', true, false);
      input.dispatchEvent(ev);
    }
  }
  hourSel.addEventListener('change', sync);
  minSel.addEventListener('change', sync);

  var sep = document.createElement('span');
  sep.className = 'tp-sep';
  sep.textContent = ':';

  wrap.appendChild(hourSel);
  wrap.appendChild(sep);
  wrap.appendChild(minSel);

  input.style.display = 'none';
  input.parentNode.insertBefore(wrap, input);

  if (typeof enhanceSelect === 'function') {
    enhanceSelect(hourSel);
    enhanceSelect(minSel);
  }
}

/* 自绘日期选择器：input[type=date] → 年+月+日三个 select，原 input 保留为 "YYYY-MM-DD" */
function enhanceDateInput(input, opts) {
  if (!input || input._customized) return;
  input._customized = true;
  opts = opts || {};
  var now = new Date();
  var minYear = opts.minYear || 1920;
  var maxYear = opts.maxYear || now.getFullYear();

  var wrap = document.createElement('span');
  wrap.className = 'dp-wrap';

  function buildSel(values, labels) {
    var s = document.createElement('select');
    for (var i = 0; i < values.length; i++) {
      var o = document.createElement('option');
      o.value = String(values[i]);
      o.textContent = labels ? labels[i] : String(values[i]);
      s.appendChild(o);
    }
    return s;
  }

  var years = [];
  for (var y = maxYear; y >= minYear; y--) years.push(y);
  var months = [];
  for (var m = 1; m <= 12; m++) months.push(m);
  var yearSel = buildSel(years, null);
  var monthSel = buildSel(months, null);

  yearSel.className = 'dp-year';

  var daySel = document.createElement('select');

  function rebuildDays() {
    var y2 = parseInt(yearSel.value, 10) || maxYear;
    var m2 = parseInt(monthSel.value, 10) || 1;
    var daysInMonth = new Date(y2, m2, 0).getDate();
    var cur = parseInt(daySel.value, 10) || 1;
    daySel.innerHTML = '';
    for (var d = 1; d <= daysInMonth; d++) {
      var o = document.createElement('option');
      o.value = String(d);
      o.textContent = (d < 10 ? '0' : '') + d;
      daySel.appendChild(o);
    }
    if (cur > daysInMonth) cur = daysInMonth;
    daySel.value = String(cur);
    if (daySel._customized) {
      /* 同步自绘组件 */
      try {
        daySel.dispatchEvent(new Event('change', { bubbles: true }));
      } catch (e) {}
    }
  }

  /* 解析当前值 */
  var raw = String(input.value || '').trim();
  var m3 = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m3) {
    var yy = parseInt(m3[1], 10);
    var mm2 = parseInt(m3[2], 10);
    var dd = parseInt(m3[3], 10);
    if (yy >= minYear && yy <= maxYear) yearSel.value = String(yy);
    if (mm2 >= 1 && mm2 <= 12) monthSel.value = String(mm2);
    rebuildDays();
    if (dd >= 1 && dd <= 31) daySel.value = String(dd);
  } else {
    /* 空值：默认当前日期 */
    yearSel.value = String(maxYear);
    monthSel.value = String(now.getMonth() + 1);
    rebuildDays();
    daySel.value = String(now.getDate());
  }

  yearSel.addEventListener('change', function () { rebuildDays(); sync(); });
  monthSel.addEventListener('change', function () { rebuildDays(); sync(); });
  daySel.addEventListener('change', sync);

  function sync() {
    var y3 = parseInt(yearSel.value, 10);
    var m4 = parseInt(monthSel.value, 10);
    var d3 = parseInt(daySel.value, 10);
    if (isNaN(y3) || isNaN(m4) || isNaN(d3)) return;
    input.value = y3 + '-' +
      (m4 < 10 ? '0' : '') + m4 + '-' +
      (d3 < 10 ? '0' : '') + d3;
    try {
      input.dispatchEvent(new Event('change', { bubbles: true }));
    } catch (e) {
      var ev = document.createEvent('HTMLEvents');
      ev.initEvent('change', true, false);
      input.dispatchEvent(ev);
    }
  }

  /* 分隔符 */
  function mkSep(txt) {
    var s = document.createElement('span');
    s.className = 'tp-sep';
    s.textContent = txt;
    return s;
  }
  wrap.appendChild(yearSel);
  wrap.appendChild(mkSep('-'));
  wrap.appendChild(monthSel);
  wrap.appendChild(mkSep('-'));
  wrap.appendChild(daySel);

  input.style.display = 'none';
  input.parentNode.insertBefore(wrap, input);

  if (typeof enhanceSelect === 'function') {
    enhanceSelect(yearSel);
    enhanceSelect(monthSel);
    enhanceSelect(daySel);
  }

  /* 每年 / 月变化时，日列表需要重建 → 监听自绘 change */
  yearSel.addEventListener('change', function () {
    var _tmp = daySel._customized;
    daySel._customized = false;
    rebuildDays();
  });
  monthSel.addEventListener('change', function () {
    daySel._customized = false;
    rebuildDays();
  });
}

/* 批量转换所有 time / date 输入 */
function enhanceAllTimeDateInputs(root) {
  try {
    var scope = root || document;
    /* time */
    var times = scope.querySelectorAll('input[type=time]:not([data-tp-done])');
    for (var i = 0; i < times.length; i++) {
      times[i].setAttribute('data-tp-done', '1');
      enhanceTimeInput(times[i]);
    }
    /* date */
    var dates = scope.querySelectorAll('input[type=date]:not([data-dp-done])');
    for (var j = 0; j < dates.length; j++) {
      dates[j].setAttribute('data-dp-done', '1');
      enhanceDateInput(dates[j]);
    }
  } catch (e) {
    console.warn('[time-date] 转换失败:', e && e.message);
  }
}

/* 页面加载后自动转换；动态添加的 select 也可手动调用 */
function _enhanceAll() {
  enhanceAllSelects();
  enhanceAllTimeDateInputs();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', function () {
    _enhanceAll();
    try {
      var mo = new MutationObserver(function () { _enhanceAll(); });
      mo.observe(document.body, { childList: true, subtree: true });
    } catch (e) {}
  });
} else {
  _enhanceAll();
}

// System account identifiers.
/* ★ v0.24.5：兼容大小写 —— 历史数据里 SYSTEM 账号的 id 可能是
   'SYSTEM'、'system' 甚至 'System'（早期版本迁移微信团队时
   曾把 id 误写成小写 'system'）。此前只做大写精确匹配，
   导致 id 为小写 'system' 的账号在管理员面板 / 消息头像 /
   名片等所有需要「官方蓝」的地方都落回普通用户的「金色」。
   改为：先精确匹配 → 再大小写不敏感兜底。 */
var SYSTEM_USER_IDS = ['wx_team', 'wx_pay', 'SYSTEM'];
function isSystemUserId(id) {
  if (id == null) return false;
  var s = String(id);
  /* 1) 精确匹配已知系统 id */
  for (var i = 0; i < SYSTEM_USER_IDS.length; i++) {
    if (s === SYSTEM_USER_IDS[i]) return true;
  }
  /* 2) 大小写不敏感兜底：'system' / 'System' / 'SYSTEM' 一律视为系统账号 */
  if (s.toLowerCase() === 'system') return true;
  /* 3) 微信团队 / 微信支付的大小写兜底（防止未来出现 'WX_TEAM'） */
  var low = s.toLowerCase();
  if (low === 'wx_team' || low === 'wx_pay') return true;
  return false;
}

/* 客户端 SHA256：不用 Web Crypto（仅 HTTPS 可用），输出与服务端 hashSecret() 一致 */
function _sha256Hex(ascii) {
  /* SHA-256 常量 */
  var K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];
  /* 计算辅助：循环右移 */
  function rotr(x, n) { return (x >>> n) | (x << (32 - n)); }

  /* UTF-8 编码：所有输入按字节处理 */
  var utf8 = unescape(encodeURIComponent(String(ascii)));
  var len = utf8.length;

  /* 填充：0x80 + 若干 0x00 + 8 字节大端长度 */
  var totalLen = ((len + 8) >> 6) + 1;
  var words = new Array(totalLen * 16);
  for (var i = 0; i < words.length; i++) words[i] = 0;
  for (var j = 0; j < len; j++) {
    words[j >> 2] |= utf8.charCodeAt(j) << (24 - (j % 4) * 8);
  }
  words[len >> 2] |= 0x80 << (24 - (len % 4) * 8);
  words[totalLen * 16 - 1] = len * 8;

  /* 初始哈希值 */
  var H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
           0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];

  var W = new Array(64);
  for (var blk = 0; blk < totalLen; blk++) {
    for (var t = 0; t < 16; t++) W[t] = words[blk * 16 + t];
    for (var t2 = 16; t2 < 64; t2++) {
      var s0 = rotr(W[t2-15],7) ^ rotr(W[t2-15],18) ^ (W[t2-15] >>> 3);
      var s1 = rotr(W[t2-2],17) ^ rotr(W[t2-2],19) ^ (W[t2-2] >>> 10);
      W[t2] = (W[t2-16] + s0 + W[t2-7] + s1) | 0;
    }
    var a = H[0], b = H[1], c = H[2], d = H[3];
    var e = H[4], f = H[5], g = H[6], h = H[7];
    for (var r = 0; r < 64; r++) {
      var S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
      var ch = (e & f) ^ ((~e) & g);
      var temp1 = (h + S1 + ch + K[r] + W[r]) | 0;
      var S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
      var maj = (a & b) ^ (a & c) ^ (b & c);
      var temp2 = (S0 + maj) | 0;
      h = g; g = f; f = e;
      e = (d + temp1) | 0;
      d = c; c = b; b = a;
      a = (temp1 + temp2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0;
    H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0;
    H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }

  /* 输出：8 个 32 位字 → 64 位十六进制 */
  var out = '';
  for (var x = 0; x < 8; x++) {
    var hex = (H[x] >>> 0).toString(16);
    while (hex.length < 8) hex = '0' + hex;
    out += hex;
  }
  return out;
}

/* 客户端哈希：与服务端 hashSecret() 输出完全一致 */
function clientHashSecret(text) {
  return _sha256Hex('lanchat::secret::' + String(text == null ? '' : text));
}

/* 传输层加密状态：HTTPS=TLS，HTTP=未加密（密码已预哈希，内容明文） */
function getTransportSecurity() {
  try {
    if (location.protocol === 'https:') return 'tls';
    if (location.hostname === 'localhost' ||
        location.hostname === '127.0.0.1' ||
        location.hostname === '[::1]') return 'local';
    return 'none';
  } catch (e) { return 'none'; }
}

function updateSecurityBadge() {
  var el = $id('loginSecurityBadge');
  if (!el) return;
  var s = getTransportSecurity();
  if (s === 'tls') {
    el.className = 'login-security-badge secure';
    el.innerHTML = '🔒 传输已加密（TLS / WSS）';
    el.title = '当前使用 HTTPS，所有数据经 TLS 加密传输';
  } else if (s === 'local') {
    el.className = 'login-security-badge secure';
    el.innerHTML = '🔒 本机访问（localhost）';
    el.title = '浏览器将 localhost 视为安全上下文';
  } else {
    el.className = 'login-security-badge warn';
    el.innerHTML = '⚠️ 未加密传输（HTTP）—— 密码已本地哈希，建议启用 HTTPS';
    el.title = '当前使用 HTTP，除密码外的其它数据（消息内容等）未加密。' +
               '请在服务器端执行 gencert 生成证书后重启以启用 HTTPS。';
  }
}

/* 设备令牌：localStorage 优先，cookie 兜底（Safari ITP 会清 localStorage） */

/* ============================================================
   ★ v0.27.7：HTML 流式传输自动检测
   ------------------------------------------------------------
   现代浏览器在收到 X-Streaming: 1 响应头时，会一边接收
   一边解析 HTML，感知加载时间显著缩短。

   检测策略：
     1. 首次访问 —— 用普通方式加载（保证兼容性）
     2. 加载完成后异步探测 /?stream=1 是否被支持（HEAD 请求）
     3. 支持则记录到 localStorage，下次访问自动加 ?stream=1
     4. 不支持则永久禁用
   ============================================================ */
(function _initStreamingProbe() {
  try {
    /* 已经进入过流式模式 → 不做任何事 */
    if (/[?&]stream=1\b/.test(location.search)) {
      try { sessionStorage.setItem('__stream_ok__', '1'); } catch (e) {}
      return;
    }

    var _probed = '';
    try { _probed = localStorage.getItem('__stream_support__') || ''; } catch (e) {}

    /* 已探测过支持 → 立即跳转到流式 URL（不刷新历史） */
    if (_probed === '1' && !sessionStorage.getItem('__stream_redirected__')) {
      try { sessionStorage.setItem('__stream_redirected__', '1'); } catch (e) {}
      var _url = location.pathname +
        (location.search ? location.search + '&' : '?') + 'stream=1' +
        (location.hash || '');
      try { location.replace(_url); } catch (e) {}
      return;
    }

    /* 未探测 → 页面空闲后后台探测一次 */
    var _probe = function () {
      try {
        fetch(location.pathname + '?stream=1&probe=1', {
          method: 'HEAD',
          cache: 'no-store',
          credentials: 'same-origin'
        }).then(function (r) {
          var ok = r.headers.get('X-Streaming') === '1';
          try {
            localStorage.setItem('__stream_support__', ok ? '1' : '0');
          } catch (e) {}
          if (ok && !sessionStorage.getItem('__stream_redirected__')) {
            try { sessionStorage.setItem('__stream_redirected__', '1'); } catch (e) {}
            var _u = location.pathname +
              (location.search ? location.search + '&' : '?') + 'stream=1' +
              (location.hash || '');
            try { location.replace(_u); } catch (e) {}
          }
        }).catch(function () {
          try { localStorage.setItem('__stream_support__', '0'); } catch (e) {}
        });
      } catch (e) {}
    };
    if (document.readyState === 'complete') {
      setTimeout(_probe, 1200);
    } else {
      window.addEventListener('load', function () { setTimeout(_probe, 1200); });
    }
  } catch (e) {}
})();

/* ---- 环境探测：localStorage 是否可写 ---- */
var _lsUsable = (function () {
  try {
    var k = '__lanchat_probe__';
    window.localStorage.setItem(k, '1');
    window.localStorage.removeItem(k);
    return true;
  } catch (e) {
    return false;
  }
})();

/* ---- cookie 轻量读写（仅用于存放小体积令牌映射） ---- */
function _cookieSet(name, value, days) {
  try {
    var exp = '';
    if (days) {
      var d = new Date();
      d.setTime(d.getTime() + days * 86400000);
      exp = '; expires=' + d.toUTCString();
    }
    /* SameSite=Lax 兼顾 CSRF 防护与常规导航；
       不加 Secure，以兼容纯 HTTP 局域网环境。 */
    document.cookie = name + '=' + encodeURIComponent(value) +
      exp + '; path=/; SameSite=Lax';
  } catch (e) {}
}
function _cookieGet(name) {
  try {
    var m = document.cookie.match(new RegExp(
      '(?:^|;\\s*)' + name.replace(/[.*+?^$()|[\]\\]/g, '\\$&') + '=([^;]*)'));
    return m ? decodeURIComponent(m[1]) : '';
  } catch (e) { return ''; }
}
function _cookieDel(name) {
  try {
    document.cookie = name + '=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/;';
  } catch (e) {}
}

/* ---- safeStorage：localStorage 优先，cookie 兜底 ---- */
var safeStorage = {
  get: function (key) {
    if (_lsUsable) {
      try {
        var v = window.localStorage.getItem(key);
        if (v !== null && v !== '') return v;
      } catch (e) {}
    }
    var cv = _cookieGet(key);
    return cv || null;
  },
  set: function (key, value) {
    /* ★ v0.27.23：大体积数据（> 2MB）直接跳过 localStorage，防止配额溢出崩溃 */
    var isBig = (typeof value === 'string' && value.length > 2 * 1024 * 1024);
    if (_lsUsable && !isBig) {
      try {
        window.localStorage.setItem(key, value);
      } catch (e) {
        /* QuotaExceededError / SecurityError：尝试清理最老的非核心缓存腾空间 */
        console.warn('[safeStorage] 写入失败（配额满？）:', key, e.message);
        try {
          var _evictKeys = ['translated_cache', 'voice_wave_cache', 'search_history'];
          for (var _i = 0; _i < _evictKeys.length; _i++) {
            window.localStorage.removeItem(_evictKeys[_i]);
          }
          window.localStorage.setItem(key, value);
        } catch (e2) {
          console.warn('[safeStorage] 清理后仍失败，放弃写入:', e2.message);
        }
      }
    } else if (isBig) {
      console.warn('[safeStorage] 数据过大（> 2MB），跳过 localStorage:', key);
    }
    /* 值体积 < 3800 字节才写入 cookie */
    if (typeof value === 'string' && value.length > 0 && value.length < 3800) {
      _cookieSet(key, value, 365);
    }
  },
  remove: function (key) {
    if (_lsUsable) {
      try { window.localStorage.removeItem(key); } catch (e) {}
    }
    _cookieDel(key);
  }
};

/* 设备信息采集：上报 deviceId / name / os / browser / platform / screen / deviceType */
function getOrCreateDeviceId() {
  try {
    var did = safeStorage.get('lanchat_device_id');
    if (did && /^[a-zA-Z0-9_-]{8,80}$/.test(did)) return did;
    var newId = 'd_' + Date.now().toString(36) + '_' +
                Math.random().toString(36).substring(2, 10) +
                Math.random().toString(36).substring(2, 6);
    safeStorage.set('lanchat_device_id', newId);
    return newId;
  } catch (e) {
    return 'd_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 12);
  }
}

function collectDeviceInfo() {
  var ua = navigator.userAgent || '';

  /* ---- 系统识别 ---- */
  var os = '';
  if (/Windows NT 10\.0/.test(ua)) os = 'Windows 10/11';
  else if (/Windows NT 6\.3/.test(ua)) os = 'Windows 8.1';
  else if (/Windows NT 6\.2/.test(ua)) os = 'Windows 8';
  else if (/Windows NT 6\.1/.test(ua)) os = 'Windows 7';
  else if (/Windows/.test(ua)) os = 'Windows';
  else if (/Mac OS X|Macintosh/.test(ua)) os = 'macOS';
  else if (/Android/.test(ua)) {
    var am = ua.match(/Android\s*([\d.]+)/);
    os = am ? ('Android ' + am[1]) : 'Android';
  }
  else if (/iPhone|iPad|iPod/.test(ua)) {
    var im = ua.match(/OS\s+([\d_]+)/);
    os = im ? ('iOS ' + im[1].replace(/_/g, '.')) : 'iOS';
  }
  else if (/Linux/.test(ua)) os = 'Linux';
  else if (/CrOS/.test(ua)) os = 'ChromeOS';
  else os = '未知系统';

  /* ---- 浏览器识别 ---- */
  var browser = '';
  if (/Edg\//.test(ua)) {
    var em = ua.match(/Edg\/([\d.]+)/);
    browser = 'Edge' + (em ? ' ' + em[1].split('.')[0] : '');
  } else if (/OPR\/|Opera/.test(ua)) {
    browser = 'Opera';
  } else if (/MicroMessenger/.test(ua)) {
    browser = '微信内置浏览器';
  } else if (/Chrome\//.test(ua) && !/Edg\//.test(ua)) {
    var cm = ua.match(/Chrome\/([\d.]+)/);
    browser = 'Chrome' + (cm ? ' ' + cm[1].split('.')[0] : '');
  } else if (/Firefox\//.test(ua)) {
    var fm = ua.match(/Firefox\/([\d.]+)/);
    browser = 'Firefox' + (fm ? ' ' + fm[1].split('.')[0] : '');
  } else if (/Safari\//.test(ua) && !/Chrome\//.test(ua)) {
    var sm = ua.match(/Version\/([\d.]+)/);
    browser = 'Safari' + (sm ? ' ' + sm[1].split('.')[0] : '');
  } else if (/MSIE|Trident/.test(ua)) {
    browser = 'IE';
  } else {
    browser = (ua.slice(0, 24) || '未知浏览器');
  }

  /* ---- 设备类型 ---- */
  var isTablet = /iPad|Tablet/i.test(ua) ||
                 (/Android/i.test(ua) && !/Mobile/i.test(ua));
  var isMobile = !isTablet && /Android|iPhone|iPod|Mobile|Windows Phone/i.test(ua);
  var deviceType = isTablet ? 'tablet' : (isMobile ? 'mobile' : 'desktop');

  /* ---- 屏幕分辨率 ---- */
  var screenSize = '';
  try {
    if (typeof screen !== 'undefined' && screen.width && screen.height) {
      screenSize = screen.width + '×' + screen.height;
    }
  } catch (e) {}

  return {
    deviceId:   getOrCreateDeviceId(),
    name:       browser + ' on ' + os,
    os:         os,
    browser:    browser,
    platform:   navigator.platform || '',
    screen:     screenSize,
    deviceType: deviceType
  };
}

function getDeviceTokens() {
  try {
    var raw = safeStorage.get('lanchat_device_tokens');
    return raw ? (JSON.parse(raw) || {}) : {};
  } catch (e) { return {}; }
}
function getDeviceToken(name) {
  if (!name) return '';
  var m = getDeviceTokens();
  return m[name] || '';
}
function saveDeviceToken(name, token) {
  if (!name || !token) return;
  var m = getDeviceTokens();
  m[name] = token;
  safeStorage.set('lanchat_device_tokens', JSON.stringify(m));
}
function clearDeviceToken(name) {
  if (!name) return;
  var m = getDeviceTokens();
  if (m[name]) {
    delete m[name];
    safeStorage.set('lanchat_device_tokens', JSON.stringify(m));
  }
}

