/* ---- 补充表：原 S2T_SRC / S2T_DST 遗漏的高频常用字 ----
   原表主要覆盖生僻 CJK 汉字，遗漏了日常 UI 高频字
   （态、见、观、觉、览、云、书、画、声、乐、术、药…）。
   以「追加表 + 覆盖合并」的方式补齐，避免直接改动超长主表。
   两张表的字符顺序必须严格一一对应。 */
var S2T_EXTRA_SRC = '态严亚肃军农宪尔标树检见观觉览云于与艺术药乐声绘画书笔纸归紧闲闹习处织价级触层级';
var S2T_EXTRA_DST = '態嚴亞肅軍農憲爾標樹檢見觀覺覽雲於與藝術藥樂聲繪畫書筆紙歸緊閒鬧習處織價級觸層級';

var S2T_TABLE = (function () {
  /* 长度自检：若不一致 → 说明粘贴时漏字/多字，打印到控制台提醒 */
  if (S2T_SRC.length !== S2T_DST.length) {
    console.error('⚠️ S2T_SRC / S2T_DST 长度不一致:',
      S2T_SRC.length, 'vs', S2T_DST.length);
  }
  if (S2T_EXTRA_SRC.length !== S2T_EXTRA_DST.length) {
    console.error('⚠️ S2T_EXTRA_SRC / S2T_EXTRA_DST 长度不一致:',
      S2T_EXTRA_SRC.length, 'vs', S2T_EXTRA_DST.length);
  }
  var m = Object.create(null);
  var n = Math.min(S2T_SRC.length, S2T_DST.length);
  for (var i = 0; i < n; i++) {
    m[S2T_SRC[i]] = S2T_DST[i];
  }
  /* 补充表覆盖主表：补充表是人工核对的常用字，优先级更高 */
  var en = Math.min(S2T_EXTRA_SRC.length, S2T_EXTRA_DST.length);
  for (var j = 0; j < en; j++) {
    m[S2T_EXTRA_SRC[j]] = S2T_EXTRA_DST[j];
  }
  return m;
})();

function s2t(str) {
  if (str == null) return '';
  var s = String(str);
  var out = '';
  for (var i = 0; i < s.length; i++) {
    var c = s.charAt(i);
    out += (S2T_TABLE[c] || c);
  }
  return out;
}

function t(key) {
  /* 1) 当前语言包 */
  var pack = I18N[state.lang];
  if (pack && pack[key] != null) return pack[key];
  /* 2) 简体中文的翻译 */
  var base = I18N.zh[key] != null ? I18N.zh[key] : key;
  /* 3) 繁体：对简体结果做 s2t 转换 */
  if (state.lang === 'zh-TW') return s2t(base);
  /* 4) 文言文 / 其他：直接返回简体 */
  return base;
}

function updateSettingRowLabels() {
  /* ---- 设置面板：下拉选项文字 / 按钮文字 ---- */
  var mapSelect = [
    { id: 'setSendKey', keys: ['sendKeyEnter', 'sendKeyCtrl'] },
    { id: 'setVoiceMaxDuration', keys: ['voiceDuration30', 'voiceDuration60', 'voiceDuration120', 'voiceDuration300'] },
    { id: 'setSoundType', keys: ['setSoundBeep', 'setSoundDrop', 'setSoundBell', 'setSoundNone'] },
    /* 在线状态下拉：四个 option 的文本随语言刷新 */
    { id: 'setPresence', keys: [
      'presenceOnline', 'presenceAway', 'presenceBusy', 'presenceDnd',
      'presenceListening', 'presenceGaming', 'presenceWorking',
      'presenceStudying', 'presenceEating', 'presenceSleeping'
    ] }
  ];
  for (var si = 0; si < mapSelect.length; si++) {
    var sel = document.getElementById(mapSelect[si].id);
    if (!sel) continue;
    for (var oi = 0; oi < mapSelect[si].keys.length && oi < sel.options.length; oi++) {
      sel.options[oi].text = t(mapSelect[si].keys[oi]);
    }
  }
  /* 导出 / 快捷键按钮 */
  var expTxt = document.getElementById('exportTxtBtn');
  if (expTxt) expTxt.textContent = t('setExportTxt');
  var expJson = document.getElementById('exportJsonBtn');
  if (expJson) expJson.textContent = t('setExportJson');
  var openSc = document.getElementById('openShortcutsBtn');
  if (openSc) openSc.textContent = t('setOpenShortcuts');
  var closeSet = document.getElementById('closeSettingsModal');
  if (closeSet) closeSet.textContent = t('closeBtn');
  var closeStar = document.getElementById('closeStarredModal');
  if (closeStar) closeStar.textContent = t('closeBtn');
  var clearStar = document.getElementById('clearStarredBtn');
  if (clearStar) clearStar.textContent = t('btnClearStarred');
  var closeShort = document.getElementById('closeShortcutsModal');
  if (closeShort) closeShort.textContent = t('closeBtn');

  /* ---- 设置面板行标签 ---- */
  var map = {
    setTimeMode: 'setTimeMode', setFontSize: 'setFontSize',
    setLineHeight: 'setLineHeight', setBubbleWidth: 'setBubbleWidth',
    setNotify: 'setNotify', setSound: 'setSound',
    setAutoScroll: 'setAutoScroll', setTitleFlash: 'setTitleFlash',
    setShowAvatar: 'setShowAvatar', setMergeMessages: 'setMergeMessages',
    setFlatStyle: 'setFlatStyle', setHour12: 'setHour12',
    setSendKey: 'setSendKey', setSoundType: 'setSoundType',
    setVoiceMaxDuration: 'setVoiceMaxDuration', setVoiceSpeed: 'setVoiceSpeed',
    setVoiceAutoSend: 'setVoiceAutoSend', setLanguage: 'setLanguage',
    setPresence: 'presenceLabel',   /* 「我的状态」行标签 */
    setThemeMode: 'setThemeMode',
  };
  for (var id in map) {
    if (!map.hasOwnProperty(id)) continue;
    var el = document.getElementById(id);
    if (!el) continue;
    var row = el.closest ? el.closest('.setting-row') : null;
    if (!row) continue;
    var span = row.querySelector('span');
    if (!span) continue;
    var hint = span.querySelector('small');
    if (hint) {
      span.childNodes[0].nodeValue = t(map[id]) + ' ';
      var hintKey = map[id] + 'Hint';
      var hintText = t(hintKey);
      if (hintText && hintText !== hintKey) hint.textContent = hintText;
    } else {
      span.textContent = t(map[id]);
    }
  }
}

function applyLang() {
  var _htmlLang = 'zh-CN';
  if (state.lang === 'en') _htmlLang = 'en';
  else if (state.lang === 'zh-TW') _htmlLang = 'zh-Hant';
  else if (state.lang === 'zh-wenyan') _htmlLang = 'lzh';
  document.documentElement.lang = _htmlLang;
  try {
    /* 页面标题 */
    var _pageTitle = t('appTitle');
    state._origTitle = _pageTitle;
    if (!state._titleTimer) {
      document.title = _pageTitle;
    }
    var title = document.querySelector('.app-title');
    if (title) title.textContent = t('appTitle');
    var lt = document.querySelector('#loginOverlay h2');
    if (lt) lt.textContent = t('loginTitle');
    var lp = document.querySelector('#loginOverlay p');
    if (lp) lp.textContent = t('loginHint');
    if (dom.loginInput) dom.loginInput.placeholder = t('loginPlaceholder');
    if (dom.loginBtn && !dom.loginBtn.disabled) dom.loginBtn.textContent = t('loginBtn');
    if (dom.createGroupBtn) dom.createGroupBtn.textContent = t('createGroup');
    if (dom.refreshContactsBtn) dom.refreshContactsBtn.textContent = t('refreshContacts');
    var secs = document.querySelectorAll('.sidebar .section-title');
    if (secs.length >= 2) {
      secs[0].textContent = t('sectionPrivate');
      secs[1].textContent = t('sectionGroup');
    }
    if (dom.contactSearchInput) dom.contactSearchInput.placeholder = t('contactSearchPh');
    if (dom.msgInput) dom.msgInput.placeholder = t('msgPlaceholder');
    if (dom.sendBtn) dom.sendBtn.textContent = t('sendBtn');
    var grb = document.getElementById('globalRefreshBtn');
    if (grb) {
      grb.textContent = t('globalRefreshBtn');
      grb.title = t('globalRefreshTitle');
    }
    updateSettingRowLabels();
    /* ---- 主题色 / 免打扰行标签（无 id 输入控件，手动刷新） ---- */
    (function refreshExtraSettingLabels() {
      var sw = dom.colorSwatches;
      if (sw && sw.parentNode) {
        var row = sw.parentNode;
        var lbl = null;
        for (var ci = 0; ci < row.children.length; ci++) {
          if (row.children[ci].tagName === 'SPAN') { lbl = row.children[ci]; break; }
        }
        if (lbl) lbl.textContent = t('setAccentColor');
      }
      if (dom.setQuietEnabled) {
        var row1 = dom.setQuietEnabled.closest ? dom.setQuietEnabled.closest('.setting-row') : null;
        if (row1) { var s1 = row1.querySelector('span'); if (s1) s1.textContent = t('setQuietEnabled'); }
      }
      if (dom.setQuietStart) {
        var row2 = dom.setQuietStart.closest ? dom.setQuietStart.closest('.setting-row') : null;
        if (row2) { var s2 = row2.querySelector('span'); if (s2) s2.textContent = t('setQuietRange'); }
      }
    })();
    /* ---- 文件上传按钮文字刷新 ---- */
    (function refreshFileUploadLabels() {
      var fileLbl = $id('qqFileUploadLabel');
      if (fileLbl) fileLbl.textContent = t('fileChoose');
      var albumLbl = $id('qqAlbumUploadLabel');
      if (albumLbl) albumLbl.textContent = t('fileChooseImage');
      /* 文件名行也刷新（如果没有选中文件显示"未选择文件"，有文件则保留） */
      var fn = $id('qqFileUploadName');
      if (fn && !fn.classList.contains('has-file')) fn.textContent = t('fileNoFile');
      var an = $id('qqAlbumUploadName');
      if (an && !an.classList.contains('has-file')) an.textContent = t('fileNoFile');
    })();
    /* ---- 设置面板：下拉选项文字 ---- */
    (function applySelectOptionLabels() {
      var sels = [
        { id: 'setTimeMode', keys: ['setTimeBoth', 'setTimeClock', 'setTimeRel'] },
        { id: 'setThemeMode', keys: ['themeModeLight', 'themeModeDark', 'themeModeAuto'] },
        { id: 'setSendKey', keys: ['sendKeyEnter', 'sendKeyCtrl'] },
        { id: 'setSoundType', keys: ['setSoundBeep', 'setSoundDrop', 'setSoundBell', 'setSoundNone'] },
        { id: 'setVoiceMaxDuration', keys: ['voiceDuration30', 'voiceDuration60', 'voiceDuration120', 'voiceDuration300'] },
        { id: 'setVoiceSpeed', keys: null },
        { id: 'setLanguage', keys: null }
      ];
      for (var si = 0; si < sels.length; si++) {
        var sel = document.getElementById(sels[si].id);
        if (!sel || !sels[si].keys) continue;
        for (var oi = 0; oi < sels[si].keys.length && oi < sel.options.length; oi++) {
          sel.options[oi].text = t(sels[si].keys[oi]);
        }
      }
      var expTxt = document.getElementById('exportTxtBtn');
      if (expTxt) expTxt.textContent = t('setExportTxt');
      var expJson = document.getElementById('exportJsonBtn');
      if (expJson) expJson.textContent = t('setExportJson');
      var openSc = document.getElementById('openShortcutsBtn');
      if (openSc) openSc.textContent = t('setOpenShortcuts');
      var closeSet = document.getElementById('closeSettingsModal');
      if (closeSet) closeSet.textContent = t('btnClose');
      var closeStar = document.getElementById('closeStarredModal');
      if (closeStar) closeStar.textContent = t('btnClose');
      var clearStar = document.getElementById('clearStarredBtn');
      if (clearStar) clearStar.textContent = t('btnClearStarred');
      var closeShort = document.getElementById('closeShortcutsModal');
      if (closeShort) closeShort.textContent = t('btnClose');
      var closeMember = document.getElementById('closeMemberList');
      if (closeMember) closeMember.textContent = t('btnClose');
      var cancelGrp = document.getElementById('cancelCreateGroup');
      if (cancelGrp) cancelGrp.textContent = t('btnCancel');
      var confirmGrp = document.getElementById('confirmCreateGroup');
      if (confirmGrp) confirmGrp.textContent = t('btnConfirm');
      var cancelMng = document.getElementById('cancelGroupManage');
      if (cancelMng) cancelMng.textContent = t('btnClose');
      var closeQQF = document.getElementById('closeQQFileModal');
      if (closeQQF) closeQQF.textContent = t('btnClose');
      var closeQQA = document.getElementById('closeQQAlbumModal');
      if (closeQQA) closeQQA.textContent = t('btnClose');
      var closeQQV = document.getElementById('closeQQVoteModal');
      if (closeQQV) closeQQV.textContent = t('btnClose');
      var closeAdmin = document.getElementById('closeAdminModal');
      if (closeAdmin) closeAdmin.textContent = t('btnClose');
      var closeFwd = document.getElementById('closeForwardModal');
      if (closeFwd) closeFwd.textContent = t('btnCancel');
      /* ---- 设置面板扩展词条（Apple 风格已移除） ---- */
    })();
    var h3s = document.querySelectorAll('.modal-box h3');
    for (var j = 0; j < h3s.length; j++) {
      var txt = h3s[j].textContent || '';
      if (txt.indexOf('设置') !== -1 || txt.indexOf('Settings') !== -1) {
        h3s[j].textContent = t('settingsTitle');
      }
    }
    /* 菜单项文本映射：新增 react（表情回应），保持与其他项一致的刷新路径 */
    var actions = { edit: 'msgEdit', recall: 'msgRecall', delete: 'msgDelete', reply: 'msgReply',
                    forward: 'msgForward', react: 'msgReact', pin: 'msgPin',
                    speak: 'msgSpeak', copy: 'msgCopy' };
    var msgMenuItems = dom.msgMenu.querySelectorAll('.menu-item');
    for (var m = 0; m < msgMenuItems.length; m++) {
      var act = msgMenuItems[m].getAttribute('data-action');
      if (act && actions[act]) msgMenuItems[m].textContent = t(actions[act]);
    }
    var tmSel = document.getElementById('setTimeMode');
    if (tmSel && tmSel.options.length >= 3) {
      tmSel.options[0].text = t('setTimeBoth');
      tmSel.options[1].text = t('setTimeClock');
      tmSel.options[2].text = t('setTimeRel');
    }
    var thSel = document.getElementById('setThemeMode');
    if (thSel && thSel.options.length >= 3) {
      thSel.options[0].text = t('themeModeLight');
      thSel.options[1].text = t('themeModeDark');
      thSel.options[2].text = t('themeModeAuto');
    }
    /* 通用 data-i18n 属性遍历 */
    var nodes = document.querySelectorAll('[data-i18n]');
    for (var i = 0; i < nodes.length; i++) {
      var k = nodes[i].getAttribute('data-i18n');
      if (k) nodes[i].textContent = t(k);
    }
    var phNodes = document.querySelectorAll('[data-i18n-ph]');
    for (var j = 0; j < phNodes.length; j++) {
      var k2 = phNodes[j].getAttribute('data-i18n-ph');
      if (k2) phNodes[j].placeholder = t(k2);
    }
    var tNodes = document.querySelectorAll('[data-i18n-title]');
    for (var m = 0; m < tNodes.length; m++) {
      var k3 = tNodes[m].getAttribute('data-i18n-title');
      if (k3) tNodes[m].title = t(k3);
    }
    /* ★ data-i18n-html：整体替换 innerHTML，
       适用于带 <b> / <kbd> / <code> 等标签的富文本（关于面板等） */
    var htmlNodes = document.querySelectorAll('[data-i18n-html]');
    for (var hi = 0; hi < htmlNodes.length; hi++) {
      var hk = htmlNodes[hi].getAttribute('data-i18n-html');
      if (!hk) continue;
      var hval = t(hk);
      if (hval && hval !== hk) {
        htmlNodes[hi].innerHTML = hval;
      }
    }
    /* ★ aria-label 本地化：屏幕阅读器可读 */
    var ariaNodes = document.querySelectorAll('[data-i18n-aria-label]');
    for (var an = 0; an < ariaNodes.length; an++) {
      var ak = ariaNodes[an].getAttribute('data-i18n-aria-label');
      if (ak) ariaNodes[an].setAttribute('aria-label', t(ak));
    }
    /* 头部昵称：按登录状态分别处理，避免被 data-i18n 覆盖 */
    if (dom.headerNickname) {
      if (state.isLoggedIn) {
        updateHeaderNickname();
      } else {
        dom.headerNickname.textContent = t('headerNotLogged');
      }
    }
    /* ★ 顶栏签到按钮本地化 */
    updateSigninBtnState();
    /* ★ v0.24.45：刷新「我」页面的动态文案（主题 / 通知 / 全屏 / 签到等） */
    if (typeof updateMobileMePage === 'function') {
      try { updateMobileMePage(); } catch (e) {}
    }
    /* 空间 tab 文字 */
    try {
      if (dom.spaceModal) {
        var _feedTab = dom.spaceModal.querySelector('.space-tab[data-tab="feed"]');
        if (_feedTab) _feedTab.textContent = t('spaceTabFeed');
        var _mineTab = dom.spaceModal.querySelector('.space-tab[data-tab="mine"]');
        if (_mineTab) _mineTab.textContent = t('spaceTabMine');
      }
    } catch (eTabs) {}
    /* ============================================================
       已打开的钱包 / 红包 / 空间面板：切换语言时立即刷新
       （合并之前重复的两段代码，保证只渲染一次）
       ============================================================ */
    try {
      /* ---- 钱包面板 ---- */
      if (dom.walletRecordsList &&
          dom.walletModal && dom.walletModal.classList.contains('open')) {
        renderWalletRecords();
        renderWalletTransferTargets();
      }

      /* ---- 发红包弹窗标题 ---- */
      if (dom.redpacketModal && dom.redpacketModal.classList.contains('open') &&
          state.currentTarget) {
        var _rpTargetName = '';
        if (state.currentType === 'group') {
          var _rpG = state.groups[state.currentTarget];
          _rpTargetName = _rpG ? _rpG.name : '';
        } else {
          var _rpU = state.users[state.currentTarget];
          _rpTargetName = _rpU ? _rpU.name : '';
        }
        dom.redpacketToLabel.textContent = t('rpTitlePrefix') + _rpTargetName;
      }

      /* ---- 领红包弹窗：刷新「用了 X 秒抢光」等信息行 ---- */
      if (dom.redpacketGrabModal && dom.redpacketGrabModal.classList.contains('open') &&
          state.redPacketCurrent) {
        var _rpCached = state.redPacketCache[state.redPacketCurrent];
        var _rpInfo = _rpCached && _rpCached.info;
        if (_rpInfo) renderRpgDetail(_rpInfo);
        else if (_rpCached && _rpCached.status) renderRpgGrabbers(_rpCached.status);
      }

      /* ---- 空间面板 ---- */
      if (dom.spaceModal && dom.spaceModal.classList.contains('open')) {
        renderSpaceHeader();
        renderSpaceStats();
        renderMomentList();
      }
    } catch (eWallet) {}

    /* ---- 当前会话里的红包系统消息按语言重建 ---- */
    if (state.currentTarget) {
      try { renderMessages(); } catch (eMsg) {}
    }
    /* ★ 关于面板的官网地址与内联链接：随语言切换一起刷新 */
    try {
      if (typeof window.__refreshAboutOfficial === 'function') {
        window.__refreshAboutOfficial();
      }
    } catch (eAbout) {
      /* 绝不让关于面板的刷新失败影响整个 applyLang */
      console.warn('[applyLang] about official refresh failed:', eAbout && eAbout.message);
    }

    /* ★ 全屏断线遮罩：若正在显示，刷新其文案 */
    try {
      var _rOv = $id('reconnectOverlay');
      if (_rOv && _rOv.classList.contains('show')) {
        var _ttl = $id('reconnectOverlayTitle');
        if (_ttl) _ttl.textContent = t('reconnectOverlayTitle');
        var _dsc = $id('reconnectOverlayDesc');
        if (_dsc) _dsc.textContent = t('reconnectOverlayDesc');
        var _btn = $id('reconnectOverlayRetry');
        if (_btn) _btn.textContent = t('connRetry');
      }
    } catch (eOv) {}

    /* 在线人数：按当前语言重建 */
    if (dom.onlineCount) {
      var _onlineN = 0;
      for (var _k in state.users) {
        if (state.users.hasOwnProperty(_k) && state.users[_k].online && _k !== state.myId) _onlineN++;
      }
      dom.onlineCount.textContent = '🟢 ' + _onlineN + t('onlineSuffix');
    }
    /* 更新动态拼接的标题 */
    if (dom.replyHint && dom.replyHint.style.display !== 'none') {
      /* 已有文案时保持不动 */
    }
    if (state.currentTarget) {
      renderMessages();
      renderPinnedBanner();
    } else {
      renderPlaceholder();
    }
    renderContacts();
    /* ★ 心情选择器 / 名片：切语言时立即用新语言重绘 */
    try {
      if (dom.profileEditModal && dom.profileEditModal.classList.contains('open')) {
        renderMoodPicker();
        updateZodiacHint();
        /* ★ 语言切换 → 重建省市下拉的占位符文字 */
        if (typeof buildProvinceOptions === 'function') {
          buildProvinceOptions();
          rebuildCityOptions(
            dom.editProvince ? dom.editProvince.value : '',
            dom.editCity ? dom.editCity.value : ''
          );
        }
      }
      if (dom.profileModal && dom.profileModal.classList.contains('open') &&
          state.currentProfileUserId) {
        renderProfileCard(state.currentProfileUserId);
      }
    } catch (eMood) {}
    /* ---- 已打开的弹窗重新渲染（切换语言时刷新动态内容）---- */
    try {
      if (dom.adminModal && dom.adminModal.classList.contains('open')) renderAdminPanel();
      if (dom.starredModal && dom.starredModal.classList.contains('open')) renderStarred();
      if (dom.qqFileModal && dom.qqFileModal.classList.contains('open')) renderQQFiles();
      if (dom.qqAlbumModal && dom.qqAlbumModal.classList.contains('open')) renderQQAlbum();
      if (dom.qqVoteModal && dom.qqVoteModal.classList.contains('open')) renderQQVotes();
      if (dom.memberListModal && dom.memberListModal.classList.contains('open') &&
          state.currentTarget && state.currentType === 'group') {
        dom.memberBtn.click();
      }
      /* ★ 更新日志：语言切换后立即按新语言重绘 */
      if (dom.changelogModal && dom.changelogModal.classList.contains('open') &&
          typeof window.__openChangelog === 'function') {
        window.__openChangelog();
      }
    } catch (e2) { console.error('rerender modals error:', e2); }
  } catch (e) { console.error('applyLang error:', e); }
}

