/* 顶栏铅笔按钮：仅群聊且当前用户是群主时显示 */
function updateChatTitleEditBtn() {
  var btn = $id('chatTitleEditBtn');
  if (!btn) return;
  var show = false;
  if (state.currentType === 'group' && state.currentTarget) {
    var g = state.groups[state.currentTarget];
    if (g && g.owner === state.myId) show = true;
  }
  btn.style.display = show ? 'inline-flex' : 'none';
}

(function initChatTitleEdit() {
  var btn = $id('chatTitleEditBtn');
  if (!btn) return;
  btn.addEventListener('click', function (e) {
    e.stopPropagation();
    if (state.currentType !== 'group' || !state.currentTarget) return;
    var g = state.groups[state.currentTarget];
    if (!g) return;
    if (g.owner !== state.myId) {
      showToast(t('renameGroupOnlyOwner'));
      return;
    }
    var _oldGroupName = g.name;
    var _groupId = state.currentTarget;
    showPrompt(t('renameGroupPrompt'), _oldGroupName, {
      icon: '✏️',
      maxLength: 20,
      confirmText: t('btnSave')
    }).then(function (newName) {
      if (newName == null) return;
      newName = String(newName).trim();
      if (!newName) {
        showToast(t('renameGroupEmpty'));
        return;
      }
      if (newName === _oldGroupName) return;
      if (newName.length > 20) newName = newName.slice(0, 20);
      state.socket.emit('rename-group', {
        groupId: _groupId,
        newName: newName
      });
    });
  });
})();

/* 全部用户弹窗：分在线/离线两组，按 管理员→认证→等级→昵称 排序 */
function renderOnlineUsers() {
  var modal = $id('onlineUsersModal');
  if (!modal) return;
  var scroll = $id('ouScroll');
  var summary = $id('ouSummary');
  if (!scroll) return;

  var _en = state.lang === 'en';
  var online = [];
  var offline = [];
  var k;

  for (k in state.users) {
    if (!state.users.hasOwnProperty(k)) continue;
    var u = state.users[k];
    if (!u || !u.id) continue;
    if (u.online) online.push(u);
    else offline.push(u);
  }

  /* 排序：管理员 → 认证 → 等级降序 → 昵称 */
  function cmpUser(a, b) {
    if (!!a.isAdmin !== !!b.isAdmin) return a.isAdmin ? -1 : 1;
    if (!!a.verified !== !!b.verified) return a.verified ? -1 : 1;
    var la = a.level || 0;
    var lb = b.level || 0;
    if (la !== lb) return lb - la;
    return String(a.name || a.id).localeCompare(String(b.name || b.id), 'zh');
  }
  online.sort(cmpUser);
  offline.sort(cmpUser);

  /* ---- 顶部摘要 ---- */
  if (summary) {
    var total = online.length + offline.length;
    summary.innerHTML =
      '<span>' + (_en ? 'Total' : '总用户') +
        '：<b>' + total + '</b></span>' +
      '<span>' + (_en ? 'Online' : '在线') +
        '：<b class="ou-count-online">' + online.length + '</b></span>' +
      '<span>' + (_en ? 'Offline' : '离线') +
        '：<b class="ou-count-offline">' + offline.length + '</b></span>';
  }

  /* ---- 单行渲染 ---- */
  function rowHtml(u) {
    var name = u.name && u.name !== u.id ? u.name : ('用户 ' + String(u.id).slice(-4));
    var initial = (name || '?').charAt(0).toUpperCase();
    var avatar = (u.profile && u.profile.avatar) || '';
    var isSys = isSystemUserId(u.id);
    /* ★ v0.24.66：兼容两种命名 ——
       上方 rowHtml 使用 isSys，而别处可能引用 _isSysUser，
       两者指向同一个值，避免 "ReferenceError: _isSysUser is not defined"。 */
    var _isSysUser = isSys;
    var isSelf = (u.id === state.myId);

    var avInner = avatar
      ? '<img src="' + avatar + '" alt="">'
      : escapeHtml(initial);
    var avBg = avatar ? 'transparent' : stringColor(u.id);

    /* 认证标签（★ v0.24.66：同时过滤系统账号专属文本，防止错配外泄） */
    var _sysTextsAll = [
      '系统通知 官方账号',
      '微信团队 官方账号',
      '微信支付 官方账号',
      '微信团队 官方',
      '微信支付 官方'
    ];
    var _verifiedDisplay = u.verified || '';
    if (_verifiedDisplay && !isSys &&
        _sysTextsAll.indexOf(String(_verifiedDisplay)) !== -1) {
      _verifiedDisplay = '';
    }
    var verifyHtml = _verifiedDisplay
      ? '<span class="verify-tag' + (isSys ? ' system' : '') +
        '" style="font-size:10px;padding:0 6px;line-height:14px;">' +
        '<span class="verify-check" style="min-width:11px;height:11px;font-size:8px;">✓</span>' +
        escapeHtml(_verifiedDisplay) + '</span>'
      : '';
    /* 等级 */
    var lvHtml = (u.level > 0)
      ? '<span class="lv-badge' + (u.vip ? ' vip' : '') +
        '" style="font-size:10px;line-height:14px;">' +
        (u.vip ? '👑' : '') + 'LV' + u.level + '</span>'
      : '';
    /* 管理员 */
    var adminHtml = u.isAdmin
      ? '<span style="font-size:10px;background:#1e90ff;color:#fff;' +
        'padding:0 6px;border-radius:8px;line-height:14px;font-weight:600;">' +
        escapeHtml(t('tagAdminShort')) + '</span>'
      : '';

    /* 头像角标：封禁优先，其次在线状态点 */
    var dotHtml = '';
    if (u.banned) {
      dotHtml = '<span class="ou-avatar-banned-badge" title="' +
        escapeHtml(t('profileBanned')) + '">🚫</span>';
    } else if (u.online) {
      var presence = u.presence || 'online';
      /* 仅「在线」以外的状态用彩色点强调；在线用绿色点 */
      dotHtml = '<span class="ou-dot-mini ' + presence + '"></span>';
    }

    /* 副标题：状态 + 官方 */
    var sub;
    if (!u.online) {
      sub = _en ? 'Offline' : '离线';
    } else {
      var presence2 = u.presence || 'online';
      sub = (presence2 === 'online')
        ? (_en ? 'Online' : '在线')
        : t(PRESENCE_SHORT_KEY[presence2] || 'presenceOnlineShort');
    }
    if (isSys) sub += ' · ' + (_en ? 'Official' : '官方');
    if (isSelf) sub += ' · ' + (_en ? 'Me' : '我');

    var cls = 'ou-user';
    if (!u.online) cls += ' ou-offline';
    if (isSelf) cls += ' ou-self';
    if (u.banned) cls += ' ou-banned';

    /* 搜索键：昵称 + ID + 认证文本 */
    var _searchKey = String(name + ' ' + u.id + ' ' + (_verifiedDisplay || '')).toLowerCase();

    return '<div class="' + cls + '" data-uid="' + escapeHtml(u.id) +
      '" data-search="' + escapeHtml(_searchKey) + '" tabindex="0">' +
      '<div class="ou-avatar" style="background:' + avBg + ';">' +
        avInner + dotHtml +
      '</div>' +
      '<div class="ou-info">' +
        '<div class="ou-name">' +
          escapeHtml(name) + verifyHtml + lvHtml + adminHtml +
        '</div>' +
        '<div class="ou-sub">' + escapeHtml(sub) + '</div>' +
      '</div>' +
    '</div>';
  }

  /* ---- 拼接 HTML ---- */
  var html = '';

  if (online.length) {
    html += '<div class="ou-group-title">' +
      '<span class="ou-dot online"></span>' +
      (_en ? 'ONLINE' : '在线') +
      '<span class="ou-group-count">· ' + online.length + '</span>' +
    '</div>';
    for (var i = 0; i < online.length; i++) html += rowHtml(online[i]);
  }
  if (offline.length) {
    html += '<div class="ou-group-title">' +
      '<span class="ou-dot offline"></span>' +
      (_en ? 'OFFLINE' : '离线') +
      '<span class="ou-group-count">· ' + offline.length + '</span>' +
    '</div>';
    for (var j = 0; j < offline.length; j++) html += rowHtml(offline[j]);
  }
  if (!html) {
    html = '<div class="ou-empty">' +
      (_en ? 'No users' : '暂无用户') + '</div>';
  }

  scroll.innerHTML = html;

  /* ---- 行点击 → 打开名片 ---- */
  var rows = scroll.querySelectorAll('.ou-user');
  for (var r = 0; r < rows.length; r++) {
    (function (el) {
      var openIt = function () {
        var uid = el.dataset.uid;
        if (!uid || !state.users[uid]) return;
        closeModalWithFade(modal);
        /* 让关闭动画先播完，再打开名片 */
        setTimeout(function () { openProfile(uid); }, 220);
      };
      el.addEventListener('click', openIt);
      el.addEventListener('keydown', function (ev) {
        if (ev.key === 'Enter' || ev.key === ' ') {
          ev.preventDefault();
          openIt();
        }
      });
    })(rows[r]);
  }
}

function openOnlineUsersModal() {
  if (!state.isLoggedIn) {
    showToast(t('toastLoginFirst'));
    return;
  }
  var modal = $id('onlineUsersModal');
  if (!modal) return;
  var _s = $id('ouSearchInput');
  if (_s) _s.value = '';
  renderOnlineUsers();
  modal.classList.add('open');
  setTimeout(function () {
    if (_s) { try { _s.focus(); } catch (e) {} }
  }, 80);
}

(function initOnlineUsersUI() {
  var modal = $id('onlineUsersModal');
  if (!modal) return;

  /* 顶栏按钮 */
  if (dom.onlineCount) {
    dom.onlineCount.addEventListener('click', function (e) {
      e.stopPropagation();
      openOnlineUsersModal();
    });
  }

  /* 关闭按钮 */
  var closeBtn = $id('closeOnlineUsersModal');
  if (closeBtn) {
    closeBtn.addEventListener('click', function () {
      closeModalWithFade(modal);
    });
  }
  /* 点遮罩关闭 */
  modal.addEventListener('click', function (e) {
    if (typeof isEventOnOverlayBackground === 'function'
        ? isEventOnOverlayBackground(e, modal)
        : e.target === modal) {
      closeModalWithFade(modal);
    }
  });

  /* 搜索框实时过滤 */
  var searchInput = $id('ouSearchInput');
  if (searchInput) {
    searchInput.addEventListener('input', function () {
      var q = String(searchInput.value || '').trim().toLowerCase();
      var scroll = $id('ouScroll');
      if (!scroll) return;
      var rows = scroll.querySelectorAll('.ou-user');
      var visibleCount = 0;
      for (var i = 0; i < rows.length; i++) {
        var key = String(rows[i].getAttribute('data-search') || '').toLowerCase();
        var hit = (!q || key.indexOf(q) !== -1);
        rows[i].style.display = hit ? '' : 'none';
        if (hit) visibleCount++;
      }
      /* 分组标题：组内无可见项时隐藏 */
      var titles = scroll.querySelectorAll('.ou-group-title');
      for (var t = 0; t < titles.length; t++) {
        var titleEl = titles[t];
        var sib = titleEl.nextElementSibling;
        var groupVisible = 0;
        while (sib && !sib.classList.contains('ou-group-title')) {
          if (sib.classList.contains('ou-user') &&
              sib.style.display !== 'none') groupVisible++;
          sib = sib.nextElementSibling;
        }
        titleEl.style.display = groupVisible ? '' : 'none';
      }
      /* 空态提示 */
      var empty = scroll.querySelector('.ou-empty');
      if (!rows.length) return;
      if (visibleCount === 0) {
        if (!empty) {
          empty = document.createElement('div');
          empty.className = 'ou-empty';
          empty.textContent = '没有匹配的用户';
          scroll.appendChild(empty);
        } else {
          empty.style.display = '';
        }
      } else if (empty) {
        empty.style.display = 'none';
      }
    });
  }
})();

/* 顶栏签到按钮：未签到→执行签到，已签到→打开日历（不 disabled） */
function updateSigninBtnState() {
  if (!dom.signinBtn) return;
  var _signed = (state.myLastSignin === todayStr());
  var _en = state.lang === 'en';

  if (_signed) {
    var _streak = calcSigninStreak(state.mySigninHistory || []);
    /* 天数 ≥ 2 才显示连击，避免「连续 1 天」的别扭文案 */
    if (_streak >= 2) {
      dom.signinBtn.innerHTML = '✅ ' + (_en
        ? ('Signed · ' + _streak + 'd')
        : ('已签到 · ' + _streak + '天'));
    } else {
      dom.signinBtn.innerHTML = '✅ ' + (_en ? 'Signed in' : '已签到');
    }
    dom.signinBtn.classList.add('done');
    dom.signinBtn.disabled = false;
    dom.signinBtn.title = _en
      ? 'Already signed in today · Click to view calendar'
      : '今日已签到 · 点击查看日历';
  } else {
    dom.signinBtn.innerHTML = '📅 ' + (_en ? 'Sign in +10' : '签到 +10');
    dom.signinBtn.classList.remove('done');
    dom.signinBtn.disabled = false;
    dom.signinBtn.title = _en ? 'Daily sign-in +10 EXP' : '每日签到 +10 经验';
  }
}

/* 升级动画 */
function showLevelUpAnimation(oldLv, newLv) {
  var div = document.createElement('div');
  div.className = 'level-up-anim';
  var _en = state.lang === 'en';
  div.innerHTML =
    '<div class="level-up-icon">🎉</div>' +
    '<div class="level-up-title">' + (_en ? 'LEVEL UP!' : '升 级 啦') + '</div>' +
    '<div class="level-up-detail">LV' + oldLv + ' → LV' + newLv + '</div>';
  document.body.appendChild(div);
  setTimeout(function () { div.classList.add('show'); }, 16);
  setTimeout(function () {
    div.classList.remove('show');
    setTimeout(function () {
      if (div.parentNode) div.parentNode.removeChild(div);
    }, 400);
  }, 2600);
}

/* ============================================================
   ★ v0.30.0：只读模式（仅查看模式）客户端辅助
   ============================================================ */
function _installClientReadOnlyGuard() {
  if (!state.socket || state.socket.__roWrapped) return;
  state.socket.__roWrapped = true;
  var origEmit = state.socket.emit.bind(state.socket);
  /* 与服务端保持一致的白名单 */
  var RO_ALLOW = {
    'login': 1,
    'ui-guard-violation': 1,
    'protect-devtools-open': 1,
    'verify-admin-dev': 1,
    'check-admin-dev': 1,
    'request-feedback-token': 1,
    'get-groups': 1,
    'get-history': 1,
    'history-load-more': 1,
    'get-my-history': 1,
    'profile-get': 1,
    'wallet-get': 1,
    'devices-get': 1,
    'scheduled-list': 1,
    'auto-reply-list': 1,
    'keyword-rules-get': 1,
    'shortcuts-get': 1,
    'time-theme-get': 1,
    'contact-tags-get': 1,
    'remarks-get': 1,
    'get-blocks': 1,
    'moment-get': 1,
    'moment-get-visitors': 1,
    'group-activity-get': 1,
    'announcement-history-get': 1,
    'announcement-reads-get': 1,
    'music-list': 1,
    'redpacket-info': 1,
    'net-ping': 1,
    'private-read': 1,
    'group-read': 1,
    'terminal-auth': 1,
    'terminal-request-code': 1,
    'terminal-exec': 1
  };
  state.socket.emit = function (eventName) {
    if ((state.readOnly || state.readonlyMode) && eventName && !RO_ALLOW[eventName]) {
      try {
        if (typeof showToast === 'function') {
          showToast('🔒 ' + (t('readonlyBlockedToast') || '仅查看模式已开启，此操作不可用'));
        }
      } catch (e) {}
      return state.socket;
    }
    return origEmit.apply(state.socket, arguments);
  };
  console.log('🔒 [只读守卫] 客户端事件拦截器已安装');
}

function applyReadOnlyUI() {
  var ro = !!state.readOnly;
  try {
    document.body.classList.toggle('readonly-mode', ro);
    var banner = document.getElementById('readOnlyBanner');
    if (banner) banner.style.display = ro ? 'flex' : 'none';

    if (ro) {
      if (dom.msgInput && !dom.msgInput.disabled) {
        dom.msgInput.disabled = true;
        dom.msgInput.setAttribute('data-ro-saved', '1');
        dom.msgInput.placeholder = (t('readonlyInputPh') || '🔒 仅查看模式 · 无法发送消息');
        try { dom.msgInput.style.height = '40px'; } catch (e) {}
      }
      if (dom.sendBtn) dom.sendBtn.disabled = true;
    } else {
      if (dom.msgInput && dom.msgInput.getAttribute('data-ro-saved')) {
        dom.msgInput.disabled = false;
        dom.msgInput.removeAttribute('data-ro-saved');
        /* 恢复 placeholder，需要判断当前会话是否是系统账号 */
        var _sys = (state.currentType === 'private' && isSystemUserId(state.currentTarget));
        if (_sys) {
          if (state.currentTarget === 'wx_pay') {
            dom.msgInput.placeholder = '微信支付为服务号，不支持发送消息';
          } else if (state.currentTarget === 'SYSTEM') {
            dom.msgInput.placeholder = '系统通知为服务号，不支持发送消息';
          } else {
            dom.msgInput.placeholder = '微信团队为服务号，不支持发送消息';
          }
        } else {
          dom.msgInput.placeholder = t('msgPlaceholder');
        }
      }
      if (dom.sendBtn && state.currentTarget) dom.sendBtn.disabled = false;
    }
  } catch (e) {
    console.warn('[readonly] applyReadOnlyUI 出错:', e && e.message);
  }
}

