var _recentToastTexts = {};   /* 防抖：{ text: timestamp } */

function showToast(msg) {
  if (state.lang === 'en' && typeof msg === 'string' && /[\u4e00-\u9fa5]/.test(msg)) {
    console.warn('[i18n MISS]', msg);
  }
  var c = dom.toastContainer;
  if (!c) return;

  var text = String(msg == null ? '' : msg);

  /* ---- 防抖：同一文本 1 秒内不重复弹出 ---- */
  var now = Date.now();
  if (_recentToastTexts[text] && now - _recentToastTexts[text] < 1000) {
    return;
  }
  _recentToastTexts[text] = now;
  /* 定期清理过期的防抖记录 */
  if (!_recentToastTexts._cleanTimer) {
    _recentToastTexts._cleanTimer = setInterval(function () {
      var t = Date.now();
      var changed = false;
      for (var k in _recentToastTexts) {
        if (k === '_cleanTimer') continue;
        if (t - _recentToastTexts[k] > 5000) {
          delete _recentToastTexts[k];
          changed = true;
        }
      }
      if (!changed) {
        clearInterval(_recentToastTexts._cleanTimer);
        delete _recentToastTexts._cleanTimer;
      }
    }, 5000);
  }
  /* 记录数超过 200 时立即裁剪一次，防止高峰期间堆积 */
  (function () {
    var cnt = 0;
    for (var k in _recentToastTexts) {
      if (k === '_cleanTimer') continue;
      cnt++;
    }
    if (cnt > 200) {
      var t2 = Date.now();
      var cutoff = t2 - 5000;
      for (var k2 in _recentToastTexts) {
        if (k2 === '_cleanTimer') continue;
        if (_recentToastTexts[k2] < cutoff) delete _recentToastTexts[k2];
      }
    }
  })();

  /* ---- 超长文本截断到 200 字 ---- */
  if (text.length > 200) {
    text = text.slice(0, 199) + '…';
  }

  /* ---- 创建提示条目 ---- */
  var item = document.createElement('div');
  item.className = 'toast-item';

  /* 文本容器 */
  var body = document.createElement('span');
  body.className = 'toast-body';
  body.textContent = text;
  item.appendChild(body);

  /* 关闭按钮 */
  var closeBtn = document.createElement('button');
  closeBtn.type = 'button';
  closeBtn.className = 'toast-close';
  closeBtn.setAttribute('aria-label', '关闭提示');
  closeBtn.title = '关闭';
  closeBtn.textContent = '✕';
  item.appendChild(closeBtn);

  /* ★ v0.24.64：先加 has-toast 类让容器切回 display:flex，
     再 append 子元素 —— 这样 requestAnimationFrame 里
     的 CSS transition 才能正常触发。 */
  c.classList.add('has-toast');
  c.appendChild(item);

  /* ---- 淡入 ---- */
  requestAnimationFrame(function () {
    requestAnimationFrame(function () {
      item.classList.add('show');
    });
  });

  /* ---- 位置更新 ---- */
  _updateToastBottom();

  /* ---- 自动关闭 ---- */
  var _closed = false;
  var _autoTimer = setTimeout(function () { _closeToast(); }, 3000);

  function _closeToast() {
    if (_closed) return;
    _closed = true;
    clearTimeout(_autoTimer);
    item.classList.remove('show');
    setTimeout(function () {
      if (item.parentNode) item.parentNode.removeChild(item);
      /* ★ v0.24.64：移除子元素后若容器为空 → 移除 has-toast，
         容器重新回到 display:none 状态，彻底退出布局。 */
      if (c.children.length === 0) {
        c.classList.remove('has-toast');
        c.style.bottom = '';
      } else {
        _updateToastBottom();
      }
    }, 340);
  }

  /* ---- 手动关闭 ---- */
  closeBtn.addEventListener('click', function (e) {
    e.stopPropagation();
    _closeToast();
  });

  /* ---- 点击整条也关闭（方便长文本场景） ---- */
  item.addEventListener('click', function (e) {
    /* 但不要拦截关闭按钮的点击 */
    if (e.target === closeBtn) return;
    _closeToast();
  });
}

/* 提示容器 bottom = 20 + TabBar（移动端）+ popup-stack 高度 */
function _updateToastBottom() {
  var toast = document.getElementById('toastContainer');
  if (!toast) return;

  /* ★ v0.24.64：容器为空时无需计算位置 ——
     它已经 display:none，跳过所有计算。 */
  if (!toast.classList.contains('has-toast') ||
      toast.children.length === 0) {
    return;
  }

  var base = 20;

  /* ---- 移动端：避开 TabBar ---- */
  if (window.innerWidth <= 768) {
    var tabbar = document.getElementById('mobileTabBar');
    if (tabbar) {
      var s = window.getComputedStyle(tabbar);
      if (s.display !== 'none' && s.visibility !== 'hidden' &&
          tabbar.offsetHeight > 0) {
        base += tabbar.offsetHeight;
        /* 加上安全区 */
        base += 12;
      }
    }
  }

  /* ---- 避开右下角消息弹窗堆栈 ---- */
  var popup = document.getElementById('popupStack');
  if (popup && popup.parentNode) {
    var ph = popup.offsetHeight;
    if (ph > 0) base += ph + 8;
  }

  toast.style.bottom = base + 'px';
}

/* 供外部模块调用（popup 变化时刷新） */
window.__updateToastBottom = _updateToastBottom;

/* 点击遮罩关闭：旧浏览器 e.target 常失效，需辅以坐标判定 */
function isEventOnOverlayBackground(e, ov) {
  if (!ov) return false;
  /* 条件 1：事件目标就是遮罩本身 */
  if (e.target === ov) return true;
  /* 条件 2：坐标判定（兼容旧浏览器的事件对象）*/
  var cx = null, cy = null;
  if (typeof e.clientX === 'number' && typeof e.clientY === 'number') {
    cx = e.clientX; cy = e.clientY;
  } else if (e.touches && e.touches.length) {
    cx = e.touches[0].clientX; cy = e.touches[0].clientY;
  } else if (e.changedTouches && e.changedTouches.length) {
    cx = e.changedTouches[0].clientX; cy = e.changedTouches[0].clientY;
  }
  if (cx == null || cy == null) return false;
  /* 找到遮罩里第一个可见的「卡片」子元素 */
  var card = null;
  var children = ov.children;
  for (var i = 0; i < children.length; i++) {
    var c = children[i];
    if (!c || c.nodeType !== 1) continue;
    if (c.offsetWidth === 0 && c.offsetHeight === 0) continue;
    card = c;
    break;
  }
  if (!card) return true;
  var r = card.getBoundingClientRect();
  if (!r) return true;
  return !(cx >= r.left && cx <= r.right && cy >= r.top && cy <= r.bottom);
}
window.isEventOnOverlayBackground = isEventOnOverlayBackground;

/* 稳定的弹窗关闭：清 closing 残留 + 双通道 finish，避免「关不掉」与「误关」 */
function closeModalWithFade(modal) {
  if (!modal) return;

  /* ---- 清掉上一次关闭的残留 ---- */
  if (modal._closeTimer) {
    clearTimeout(modal._closeTimer);
    modal._closeTimer = null;
  }
  modal.classList.remove('closing');

  /* 本来就没开 → 什么都不做 */
  if (!modal.classList.contains('open')) return;

  /* ---- 播放淡出动画 ---- */
  modal.classList.add('closing');

  var done = false;
  var finish = function () {
    if (done) return;
    done = true;
    if (modal._closeTimer) {
      clearTimeout(modal._closeTimer);
      modal._closeTimer = null;
    }
    /* 若动画期间元素被重新打开，closing 会被打开逻辑移除 → 不处理 */
    if (!modal.classList.contains('closing')) return;
    modal.classList.remove('closing');
    modal.classList.remove('open');
  };

  try {
    modal.addEventListener('animationend', finish, { once: true });
  } catch (e) {
    modal.addEventListener('animationend', finish, false);
  }
  modal._closeTimer = setTimeout(finish, 300);
}

/* ============================================================
   ★ 与 closeModalWithFade 配套的「安全打开」
   ------------------------------------------------------------
   所有 modal.classList.add('open') 建议改用 openModalSafely()，
   这样在极短时间「关 → 开」时，不会被上一次的关闭计时器误关。
   ============================================================ */
function openModalSafely(modal) {
  if (!modal) return;
  if (modal._closeTimer) {
    clearTimeout(modal._closeTimer);
    modal._closeTimer = null;
  }
  modal.classList.remove('closing');
  modal.classList.add('open');
}

/* 通用对话框：showConfirm / showPrompt 返回 Promise，替代原生 confirm/prompt */
var _appDialog = {
  el: null, inputEl: null, confirmBtn: null, cancelBtn: null,
  messageEl: null, titleEl: null, iconEl: null,
  resolve: null, type: 'confirm',
  /* ★ 允许 prompt 提交空字符串（v0.23.31）
     默认 false（空输入会拒绝关闭）；
     业务层传 allowEmpty:true 时，空字符串也是合法值，
     用于「留空即删除」这类场景。 */
  allowEmpty: false
};

function _appDialogInit() {
  var d = _appDialog;
  d.el = document.getElementById('appDialogModal');
  if (!d.el) return false;
  d.inputEl    = document.getElementById('appDialogInput');
  d.confirmBtn = document.getElementById('appDialogConfirmBtn');
  d.cancelBtn  = document.getElementById('appDialogCancelBtn');
  d.messageEl  = document.getElementById('appDialogMessage');
  d.titleEl    = document.getElementById('appDialogTitle');
  d.iconEl     = document.getElementById('appDialogIcon');

  function finish(value) {
    /* ★ 关键修复：不再以 d.resolve 是否为 null 决定是否关闭。
       只要调用了 finish（取消 / 确定 / 遮罩 / Esc），就一定关闭弹窗，
       避免"resolve 已兑现但弹窗没关"导致按钮点不动、弹窗关不掉。 */
    var r = d.resolve;
    d.resolve = null;

    /* ---- 先关闭弹窗（视觉上立即消失） ---- */
    if (typeof closeModalWithFade === 'function') {
      closeModalWithFade(d.el);
    } else {
      d.el.classList.remove('open');
      d.el.classList.remove('closing');
    }

    /* ★ 解锁 */
    try { document.body.classList.remove('app-dialog-active'); } catch (e) {}

    /* ---- 有 Promise 才兑现 ---- */
    if (typeof r === 'function') {
      try { r(value); } catch (e) {}
    }
  }

  d.confirmBtn.addEventListener('click', function () {
    if (d.type === 'prompt') {
      var val = (d.inputEl.value || '').trim();
      /* ★ 空输入处理：
         · allowEmpty === true  → 空字符串也是合法值，直接提交
         · 否则                 → 拒绝关闭，把焦点还给输入框 */
      if (!val && !d.allowEmpty) {
        try { d.inputEl.focus(); } catch (e) {}
        return;
      }
      finish(val);
    } else {
      finish(true);
    }
  });
  d.cancelBtn.addEventListener('click', function () {
    /* ★ 取消前先清掉可能残留的 closing，
       避免 closeModalWithFade 因为 closing 存在而提前 return */
    d.el.classList.remove('closing');
    finish(d.type === 'prompt' ? null : false);
  });
  d.inputEl.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault(); e.stopPropagation();
      d.confirmBtn.click();
    } else if (e.key === 'Escape') {
      e.preventDefault(); e.stopPropagation();
      d.cancelBtn.click();
    }
  });
  /* 点击遮罩关闭 = 取消 */
  d.el.addEventListener('click', function (e) {
    var onBg = (typeof isEventOnOverlayBackground === 'function')
      ? isEventOnOverlayBackground(e, d.el)
      : (e.target === d.el);
    if (onBg) finish(d.type === 'prompt' ? null : false);
  });
  return true;
}

function showDialog(opts) {
  opts = opts || {};
  if (!_appDialog.el) _appDialogInit();
  var d = _appDialog;
  /* 组件缺失 → 保底返回，避免调用方卡死 */
  if (!d.el) return Promise.resolve(opts.type === 'prompt' ? null : false);

  /* 已有对话框未关闭 → 先兑现旧的 Promise，避免泄漏 */
  if (d.resolve) {
    var old = d.resolve;
    d.resolve = null;
    old(opts.type === 'prompt' ? null : false);
  }

  d.type = opts.type || 'confirm';
  /* ★ 记录 allowEmpty 开关（每次打开都重置，避免残留上一次的值） */
  d.allowEmpty = (opts.allowEmpty === true);

  /* ---- 图标 ---- */
  var icon = opts.icon;
  if (icon === undefined) {
    icon = d.type === 'prompt' ? '✏️' : (opts.danger ? '⚠️' : '❓');
  }
  if (icon) {
    d.iconEl.textContent = icon;
    d.iconEl.style.display = '';
  } else {
    d.iconEl.style.display = 'none';
  }

  /* ---- 标题（默认取 i18n；传 null / '' 可隐藏） ---- */
  var title = opts.title;
  if (title === undefined) {
    title = d.type === 'prompt' ? t('dialogPromptTitle') : t('dialogConfirmTitle');
  }
  if (title) {
    d.titleEl.textContent = title;
    d.titleEl.style.display = '';
  } else {
    d.titleEl.style.display = 'none';
  }

  /* ---- 正文 ---- */
  d.messageEl.textContent = opts.message || '';
  if (!opts.message) d.messageEl.style.display = 'none';
  else d.messageEl.style.display = '';

  /* ---- 输入框（仅 prompt 显示） ---- */
  if (d.type === 'prompt') {
    d.inputEl.style.display = '';
    d.inputEl.value = opts.defaultValue != null ? String(opts.defaultValue) : '';
    d.inputEl.placeholder = opts.placeholder || '';
    d.inputEl.maxLength = Math.max(1, parseInt(opts.maxLength, 10) || 200);
    /* ★ v0.26.2：支持密码框 */
    d.inputEl.type = (opts.inputType === 'password') ? 'password' : 'text';
    d.inputEl.setAttribute('autocomplete',
      opts.inputType === 'password' ? 'current-password' : 'off');
  } else {
    d.inputEl.style.display = 'none';
    d.inputEl.value = '';
  }

  /* ---- 按钮文案与配色 ---- */
  d.cancelBtn.textContent  = opts.cancelText  || t('btnCancel');
  d.confirmBtn.textContent = opts.confirmText || t('btnConfirm');
  d.confirmBtn.classList.toggle('danger', !!opts.danger);

  /* ============================================================
     ★ v0.30.0：动态提升对话框层级
     ------------------------------------------------------------
     问题：showDialog 的 #appDialogModal 在 CSS 中固定为
     z-index: 100010，而 showModal() 创建的弹层（如「群公告」）
     默认是 100020 → 在群公告里点「删除」时，弹出的确认框会被
     群公告弹窗压在下面，用户看不到确认按钮，点不到。

     方案：每次打开对话框前，扫描当前所有打开的弹层，
     取其最高 z-index + 10 作为对话框层级，保证永远在最顶层。
     这样对任意嵌套深度都成立，比硬编码一个大数字更稳健。
     ============================================================ */
  (function _raiseDialogZ() {
    var maxZ = 100010;
    try {
      var all = document.querySelectorAll(
        '.modal-overlay.open, .image-modal.open, ' +
        '.browser-modal.open, .call-modal.open, .group-call-modal.open, ' +
        '.space-modal.open, .reaction-picker.open, .cmd-palette-overlay.open, ' +
        '.header-more-menu.open, .chat-more-menu.open, .input-more-menu.open'
      );
      for (var i = 0; i < all.length; i++) {
        var el = all[i];
        if (!el || el === d.el) continue;
        var z = parseInt(window.getComputedStyle(el).zIndex, 10);
        if (!isNaN(z) && z > maxZ) maxZ = z;
      }
    } catch (e) {}
    /* 关闭后自动还原，避免下次没有弹窗时层级过高导致误盖其他元素 */
    d.el.style.zIndex = String(maxZ + 10);
    d.el.setAttribute('data-raised-z', '1');
  })();

  /* ---- 显示 ---- */
  /* ★ 关键修复：先清掉可能残留的 closing，
     避免新对话框挂上 .closing 后按钮点不动 / 被误关 */
  openModalSafely(d.el);
  /* ★ 加锁：对话框显示期间禁止底层滚动与误触 */
  try { document.body.classList.add('app-dialog-active'); } catch (e) {}
  setTimeout(function () {
    try {
      if (d.type === 'prompt') { d.inputEl.focus(); d.inputEl.select(); }
      else { d.confirmBtn.focus(); }
    } catch (e) {}
  }, 80);

  return new Promise(function (resolve) { d.resolve = resolve; });
}

function showConfirm(message, opts) {
  opts = opts || {};
  opts.type = 'confirm';
  opts.message = message;
  return showDialog(opts);
}

function showPrompt(message, defaultValue, opts) {
  opts = opts || {};
  opts.type = 'prompt';
  opts.message = message;
  opts.defaultValue = defaultValue;
  return showDialog(opts);
}

window.showConfirm = showConfirm;
window.showPrompt  = showPrompt;

/* ============================================================
   ★ 通用「只读 / 展示型」弹窗（供网络详情、群动态、设备列表等使用）
   ------------------------------------------------------------
   参数：
     title       弹窗标题（字符串，可为空）
     html        正文 HTML 字符串
     onConfirm   可选，点「确定」时调用的回调；传 null 则不显示确定按钮
     opts        可选：
       width       弹窗宽度（默认 '480px'）
       confirmText 确定按钮文案
       cancelText  取消/关闭按钮文案
       zIndex      层级（默认 100020）
   返回：遮罩元素（可直接移除）
   ============================================================ */
function showModal(title, html, onConfirm, opts) {
  opts = opts || {};
  var width = opts.width || '480px';

  /* ---- 遮罩 ---- */
  var overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.style.zIndex = String(opts.zIndex || 100020);

  /* ---- 内容卡 ---- */
  var box = document.createElement('div');
  box.className = 'modal-box';
  box.style.width = width;
  box.style.maxWidth = '95vw';
  box.style.maxHeight = '88vh';
  box.style.overflowY = 'auto';

  var h = document.createElement('h3');
  h.textContent = title || '';
  if (!title) h.style.display = 'none';
  box.appendChild(h);

  var body = document.createElement('div');
  body.innerHTML = html || '';
  box.appendChild(body);

  /* ---- 按钮区 ---- */
  var actions = document.createElement('div');
  actions.className = 'modal-actions';

  if (typeof onConfirm === 'function') {
    var btnConfirm = document.createElement('button');
    btnConfirm.className = 'btn-confirm';
    btnConfirm.textContent = opts.confirmText || t('btnConfirm') || '确定';
    btnConfirm.addEventListener('click', function () {
      try { onConfirm(); } catch (e) { console.warn('showModal onConfirm:', e); }
      closeSelf();
    });
    actions.appendChild(btnConfirm);
  }

  var btnClose = document.createElement('button');
  btnClose.className = 'btn-cancel';
  btnClose.textContent = opts.cancelText || t('btnClose') || '关闭';
  btnClose.addEventListener('click', closeSelf);
  actions.appendChild(btnClose);

  box.appendChild(actions);
  overlay.appendChild(box);
  document.body.appendChild(overlay);

  /* ---- 淡入 ---- */
  setTimeout(function () { overlay.classList.add('open'); }, 16);

  /* ---- 关闭并清理 DOM ---- */
  function closeSelf() {
    if (typeof closeModalWithFade === 'function') {
      closeModalWithFade(overlay);
    } else {
      overlay.classList.remove('open');
    }
    setTimeout(function () {
      if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
    }, 400);
  }

  /* ---- 点遮罩关闭 ---- */
  overlay.addEventListener('click', function (e) {
    var onBg = (typeof isEventOnOverlayBackground === 'function')
      ? isEventOnOverlayBackground(e, overlay)
      : (e.target === overlay);
    if (onBg) closeSelf();
  });

  /* ---- Esc 关闭 ---- */
  overlay.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') { e.preventDefault(); closeSelf(); }
  });

  return overlay;
}
window.showModal = showModal;

/* 服务器重启检测：bootId 变化时弹刷新横幅；纯内存，手动刷新不误报 */

/* ============================================================
   ★ v0.27.17：多设备在线横幅
   ------------------------------------------------------------
   显示「💻 电脑正在登录」/「📱 手机正在登录」，
   点「详情」打开完整设备信息弹窗。
   ============================================================ */
var _concurrentBannerTimer = null;
var _concurrentDevInfo = null;

function _deviceIcon(type) {
  if (type === 'mobile') return '📱';
  if (type === 'tablet') return '📲';
  return '💻';
}
function _deviceLabel(type) {
  if (type === 'mobile') return '手机';
  if (type === 'tablet') return '平板';
  return '电脑';
}

function _fmtConcurrentTime(ts) {
  if (!ts) return '—';
  try {
    return new Date(ts).toLocaleString('zh-CN', { hour12: false });
  } catch (e) { return '—'; }
}

function showConcurrentBanner(info) {
  var banner = document.getElementById('concurrentBanner');
  if (!banner || !info) return;

  _concurrentDevInfo = info;

  var iconEl = document.getElementById('concurrentBannerIcon');
  var textEl = document.getElementById('concurrentBannerText');
  var tLabel = _deviceLabel(info.type);
  var tIcon = _deviceIcon(info.type);
  if (iconEl) iconEl.textContent = tIcon;
  if (textEl) {
    textEl.textContent = tLabel + '正在登录' +
      (info.name ? '（' + info.name + '）' : '');
  }

  banner.classList.add('show');

  /* 12 秒后自动收起；用户点「详情」或「关闭」会重置计时器 */
  if (_concurrentBannerTimer) clearTimeout(_concurrentBannerTimer);
  _concurrentBannerTimer = setTimeout(function () {
    banner.classList.remove('show');
  }, 12000);
}

function showConcurrentDetail() {
  var d = _concurrentDevInfo;
  if (!d) return;
  var tLabel = _deviceLabel(d.type);
  var tIcon = _deviceIcon(d.type);
  var rows = [
    ['设备类型', tIcon + ' ' + tLabel],
    ['设备名称', d.name || '—'],
    ['操作系统', d.os || '—'],
    ['浏览器', d.browser || '—'],
    ['平台', d.platform || '—'],
    ['屏幕', d.screen || '—'],
    ['IP 地址', d.ip || '—'],
    ['登录时间', _fmtConcurrentTime(d.loginAt)]
  ];
  var html = '<div style="padding:4px 0;">';
  for (var i = 0; i < rows.length; i++) {
    html += '<div style="display:flex;gap:10px;padding:8px 0;' +
      'border-bottom:1px solid var(--border-modal);font-size:14px;">' +
      '<span style="color:var(--text-muted);min-width:80px;flex-shrink:0;">' +
        escapeHtml(rows[i][0]) + '</span>' +
      '<span style="color:var(--text-primary);word-break:break-all;flex:1;">' +
        escapeHtml(rows[i][1]) + '</span>' +
    '</div>';
  }
  html += '<div style="margin-top:14px;padding:10px 12px;' +
    'background:rgba(91,110,245,.08);border-radius:10px;' +
    'font-size:13px;color:var(--text-secondary);line-height:1.7;">' +
    '💡 ' + escapeHtml(tLabel) +
    '与本设备同时在线。若是本人操作无需处理；' +
    '若非本人，请立即修改密码。</div>';
  html += '</div>';
  showModal(
    tIcon + ' ' + tLabel + '正在登录',
    html,
    null,
    { width: '440px', confirmText: t('btnConfirm'), cancelText: t('btnClose') }
  );
}

(function initConcurrentBanner() {
  var banner = document.getElementById('concurrentBanner');
  if (!banner) return;

  var detailBtn = document.getElementById('concurrentBannerDetail');
  var closeBtn = document.getElementById('concurrentBannerClose');

  if (detailBtn) {
    detailBtn.addEventListener('click', function () {
      showConcurrentDetail();
      /* 保持横幅显示，用户可关闭 */
      if (_concurrentBannerTimer) clearTimeout(_concurrentBannerTimer);
      _concurrentBannerTimer = setTimeout(function () {
        banner.classList.remove('show');
      }, 12000);
    });
  }
  if (closeBtn) {
    closeBtn.addEventListener('click', function () {
      banner.classList.remove('show');
      if (_concurrentBannerTimer) {
        clearTimeout(_concurrentBannerTimer);
        _concurrentBannerTimer = null;
      }
    });
  }
})();

/* v0.19.3：横幅关闭后 10 秒自动重新显示，避免用户误关后一直看不到 */
var _updateBannerReShowTimer = null;

function showUpdateBanner() {
  var el = $id('updateBanner');
  if (!el) return;
  /* 显示时清掉待重显计时器，避免重复 */
  if (_updateBannerReShowTimer) {
    clearTimeout(_updateBannerReShowTimer);
    _updateBannerReShowTimer = null;
  }
  el.classList.add('show');
}

function hideUpdateBanner() {
  var el = $id('updateBanner');
  if (!el) return;
  el.classList.remove('show');
  /* 只对"服务器已重启"的横幅做重显；主动调用 hide 也一样 */
  if (_updateBannerReShowTimer) {
    clearTimeout(_updateBannerReShowTimer);
  }
  _updateBannerReShowTimer = setTimeout(function () {
    _updateBannerReShowTimer = null;
    showUpdateBanner();
  }, 10000);
}

/* 处理 login-success 携带的 bootId。
   返回 true 表示「服务端重启过」→ 调用方应展示横幅。 */
function handleServerBootId(newBootId) {
  if (!newBootId) return false;
  if (state.serverBootId == null) {
    /* 页面加载后的第一次登录 → 只记录，不提示 */
    state.serverBootId = newBootId;
    return false;
  }
  if (state.serverBootId !== newBootId) {
    /* bootId 变化 → 服务端重启过 → 提示刷新 */
    state.serverBootId = newBootId;
    return true;
  }
  return false;
}

(function initUpdateBanner() {
  var banner = $id('updateBanner');
  if (!banner) return;
  var btnRefresh = $id('updateBannerBtn');
  var btnClose = $id('updateBannerClose');

  if (btnRefresh) {
    btnRefresh.addEventListener('click', function () {
      /* 保留昵称以便自动恢复 */
      try {
        if (state.myName) safeStorage.set('lastNickname', state.myName);
      } catch (e) {}
      /* 主动刷新 → 不需要 10 秒重显 */
      if (_updateBannerReShowTimer) {
        clearTimeout(_updateBannerReShowTimer);
        _updateBannerReShowTimer = null;
      }
      /* 现代浏览器会忽略 reload 的参数；直接调用 reload() 即可。
         为兼容极老浏览器（IE9 之前），仍用 try / catch 兜底。 */
      try {
        location.reload();
      } catch (e) {
        try { location.href = location.href; } catch (e2) {}
      }
    });
  }
  if (btnClose) {
    btnClose.addEventListener('click', hideUpdateBanner);
  }

  /* 供外部调用 */
  window.__showUpdateBanner = showUpdateBanner;
  window.__hideUpdateBanner = hideUpdateBanner;
})();

/* ★ v0.30.0：只读模式横幅"了解详情"按钮 */
(function initReadOnlyBannerUI() {
  var helpBtn = document.getElementById('readOnlyHelpBtn');
  if (helpBtn) {
    helpBtn.addEventListener('click', function (e) {
      e.stopPropagation();
      try { openReadOnlyHelp(); } catch (err) {}
    });
  }
})();

/* ============================================================
   ★ 只读横幅「暂时关闭 + 延迟重弹」
   ------------------------------------------------------------
   · 点 ✕ → 横幅隐藏
   · READONLY_BANNER_REAPPEAR_MS 毫秒后自动重弹
     （前提：期间仍处于只读模式；若已退出只读则不再弹）
   · 默认 10000（10 秒）；想要 1 秒 → 改成 1000
   ============================================================ */
var READONLY_BANNER_REAPPEAR_MS = 10000;

(function initReadOnlyBannerClose() {
  var banner = document.getElementById('readOnlyBanner');
  var closeBtn = document.getElementById('readOnlyBannerClose');
  if (!banner || !closeBtn) return;

  /* 当前是否仍处于只读模式（state 字段 + body 类，任一命中即算） */
  function _stillReadonly() {
    try {
      if (state && (state.readonlyMode || state.readOnly)) return true;
    } catch (e) {}
    try {
      if (document.body &&
          document.body.classList.contains('readonly-mode')) return true;
    } catch (e) {}
    return false;
  }

  /* 点 ✕：隐藏 + 排期重弹 */
  closeBtn.addEventListener('click', function (e) {
    e.stopPropagation();
    banner.classList.add('banner-hidden');

    if (window.__readonlyBannerReappearTimer) {
      clearTimeout(window.__readonlyBannerReappearTimer);
      window.__readonlyBannerReappearTimer = null;
    }

    window.__readonlyBannerReappearTimer = setTimeout(function () {
      window.__readonlyBannerReappearTimer = null;
      if (!_stillReadonly()) return;    /* 已退出只读 → 不弹 */
      banner.classList.remove('banner-hidden');
      /* 重播一次进场动画 */
      try {
        banner.style.animation = 'none';
        void banner.offsetWidth;
        banner.style.animation = '';
      } catch (er) {}
    }, READONLY_BANNER_REAPPEAR_MS);
  });

  /* 只读模式退出时，清除隐藏态与定时器，保证下次开启时横幅正常出现 */
  function _onReadonlyOff() {
    if (_stillReadonly()) return;
    if (banner.classList.contains('banner-hidden')) {
      banner.classList.remove('banner-hidden');
    }
    if (window.__readonlyBannerReappearTimer) {
      clearTimeout(window.__readonlyBannerReappearTimer);
      window.__readonlyBannerReappearTimer = null;
    }
  }

  /* body.class 变化时触发（readonly-mode 被加/移除） */
  try {
    new MutationObserver(_onReadonlyOff).observe(document.body, {
      attributes: true,
      attributeFilter: ['class']
    });
  } catch (e) {}
})();

/* 连接状态提示：断线后追加显示全屏遮罩 */
var _reconnectOverlayTimer = null;
var _reconnectOverlayShown = false;

function _hideReconnectOverlay() {
  if (_reconnectOverlayTimer) {
    clearTimeout(_reconnectOverlayTimer);
    _reconnectOverlayTimer = null;
  }
  _reconnectOverlayShown = false;
  var ov = $id('reconnectOverlay');
  if (ov) ov.classList.remove('show');
  /* ★ 恢复整页交互 */
  try { document.body.classList.remove('reconnect-active'); } catch (e) {}
}

function _showReconnectOverlay() {
  var ov = $id('reconnectOverlay');
  if (!ov) return;
  /* 文案按当前语言刷新 */
  var ttl = $id('reconnectOverlayTitle');
  if (ttl) ttl.textContent = t('reconnectOverlayTitle');
  var dsc = $id('reconnectOverlayDesc');
  if (dsc) dsc.textContent = t('reconnectOverlayDesc');
  var btn = $id('reconnectOverlayRetry');
  if (btn) btn.textContent = t('connRetry');
  ov.classList.add('show');
  _reconnectOverlayShown = true;
  /* ★ 除重试按钮外，禁用整页所有交互（CSS + 事件双重保险）*/
  try { document.body.classList.add('reconnect-active'); } catch (e) {}
  /* 焦点自动落到重试按钮，方便键盘用户直接回车重试；
     同时避免焦点仍在输入框导致 Enter 触发其它行为 */
  try { if (btn && btn.focus) btn.focus(); } catch (e) {}
}

function _scheduleReconnectOverlay() {
  /* 已经显示 or 已经排期 → 不重复排 */
  if (_reconnectOverlayShown || _reconnectOverlayTimer) return;
  /* ★ 从 state 读取延时：-1 表示不显示 */
  var _delay = state.reconnectOverlayDelay;
  if (typeof _delay !== 'number' || isNaN(_delay)) _delay = 5000;
  if (_delay === -1 || _delay === 0) return;
  _reconnectOverlayTimer = setTimeout(function () {
    _reconnectOverlayTimer = null;
    _showReconnectOverlay();
  }, _delay);
}

function showConnectionStatus(mode, text) {
  var el = dom.connectionStatus;
  if (!el) return;
  el.classList.remove('connecting');
  if (mode === 'hidden') {
    el.classList.remove('show');
    /* ★ 连接恢复 → 全屏遮罩也立即隐藏 */
    _hideReconnectOverlay();
    /* 恢复输入（仅在已选会话且有 socket 时） */
    if (dom.msgInput && dom.sendBtn && state.currentTarget &&
        state.socket && state.socket.connected) {
      dom.msgInput.disabled = false;
      dom.sendBtn.disabled = false;
    }
    /* 连接恢复 → 重新拉一次当前会话的红包状态 */
    if (state.isLoggedIn && state.socket && state.socket.connected) {
      try {
        state.redPacketPending = {};
        if (state.currentTarget) {
          var _arr = (state.currentType === 'private')
            ? (state.messages[state.currentTarget] || [])
            : ((state.groups[state.currentTarget] &&
                state.groups[state.currentTarget].messages) || []);
          for (var _k = 0; _k < _arr.length; _k++) {
            if (_arr[_k].type === 'redpacket' && _arr[_k].packetId &&
                _arr[_k].packetId.indexOf('local_') !== 0) {
              state.socket.emit('redpacket-info', { packetId: _arr[_k].packetId });
            }
          }
        }
        if (state.redPacketCurrent &&
            dom.redpacketGrabModal &&
            dom.redpacketGrabModal.classList.contains('open')) {
          state.socket.emit('redpacket-info', { packetId: state.redPacketCurrent });
        }
      } catch (e) {}
    }
    return;
  }
  if (mode === 'connecting') el.classList.add('connecting');
  el.classList.add('show');
  var textEl = el.querySelector('.conn-text');
  if (textEl && text) textEl.textContent = text;
  var retryBtn = el.querySelector('.conn-retry');
  if (retryBtn) {
    retryBtn.style.display = (mode === 'connecting') ? 'none' : '';
    retryBtn.textContent = t('connRetry');
  }
  /* 断线期间禁止输入 */
  if (dom.msgInput && dom.sendBtn) {
    dom.msgInput.disabled = true;
    dom.sendBtn.disabled = true;
  }
  /* ★ 断线持续 5 秒后 → 追加显示全屏遮罩 */
  _scheduleReconnectOverlay();
}
window.showConnectionStatus = showConnectionStatus;
window.__showReconnectOverlay = _showReconnectOverlay;
window.__hideReconnectOverlay = _hideReconnectOverlay;
function msgPreviewText(msg, maxLen) {
  if (!msg) return '';
  maxLen = maxLen || 60;
  if (msg.recalled) return t('tagRecalled');
  if (msg.isPat) return '拍了拍'; // 增加拍一拍预览
  if (msg.type === 'voice') return t('tagVoice');
  if (msg.type === 'sticker') return t('tagSticker');
  if (msg.type === 'redpacket') {
    return '[红包] ' + (msg.packetGreeting || '恭喜发财，大吉大利');
  }
  if (msg.type === 'file') {
    var ft = msg.fileType || '';
    if (ft.indexOf('image/') === 0) return t('tagImage');
    if (ft.indexOf('video/') === 0) return t('tagVideo');
    if (ft.indexOf('audio/') === 0) return t('tagVoice');
    return t('tagFile') + ' ' + (msg.fileName || '');
  }
  /* ============================================================
     ★ v0.24.32：超长文本截断 + 省略号
     ------------------------------------------------------------
     此前是 .slice(0, maxLen) 硬截断，末尾无省略号，用户看不出
     还有后续内容。现在：超过 maxLen → 截到 maxLen-1 位 + '…'，
     总长恰好等于 maxLen。
     所有调用点（侧边栏预览 / 右下角弹窗 / 置顶横幅 / 转发预览 /
     收藏预览）都自动受益。
     ============================================================ */
  var _text = String(msg.content || '');
  if (_text.length > maxLen) {
    return _text.slice(0, Math.max(1, maxLen - 1)) + '…';
  }
  return _text;
}
function previewOf(data) { return msgPreviewText(data, 60); }
/* ---------- 每会话草稿 ---------- */
function currentChatKey() {
  if (!state.currentTarget || !state.currentType) return '';
  return (state.currentType === 'private' ? 'private_' : 'group_') + state.currentTarget;
}
function saveDraftNow() {
  var k = currentChatKey();
  if (!k || !dom.msgInput) return;
  var v = dom.msgInput.value;
  if (v && v.trim()) state.drafts[k] = v;
  else delete state.drafts[k];
  try { localStorage.setItem('chat_drafts', JSON.stringify(state.drafts)); } catch (e) {}
}
function saveDraftDebounced() {
  if (state._draftTimer) clearTimeout(state._draftTimer);
  state._draftTimer = setTimeout(function () {
    state._draftTimer = null;
    saveDraftNow();
  }, 350);
}
function loadDraftForCurrent() {
  var k = currentChatKey();
  if (!dom.msgInput) return;
  dom.msgInput.value = (k && state.drafts[k]) ? state.drafts[k] : '';
  /* ★ textarea 恢复草稿后自动增高 */
  try {
    if (dom.msgInput.tagName === 'TEXTAREA') {
      dom.msgInput.style.height = 'auto';
      var h = Math.min(Math.max(dom.msgInput.scrollHeight, 40), 120);
      dom.msgInput.style.height = h + 'px';
    }
  } catch (e) {}
}
function clearDraftForCurrent() {
  var k = currentChatKey();
  if (!k) return;
  delete state.drafts[k];
  try { localStorage.setItem('chat_drafts', JSON.stringify(state.drafts)); } catch (e) {}
}

function loadSetting(key, def) {
  try {
    var v = localStorage.getItem('set_' + key);
    return v === null ? def : JSON.parse(v);
  } catch (e) { return def; }
}
function saveSetting(key, val) {
  try { localStorage.setItem('set_' + key, JSON.stringify(val)); } catch (e) {}
}
function debounce(fn, ms) {
  var tm = null;
  return function () {
    var self = this, args = arguments;
    clearTimeout(tm);
    tm = setTimeout(function () { fn.apply(self, args); }, ms);
  };
}

/* ==================== 时钟 ==================== */
function updateClock() {
  var now = new Date();
  var p = function (n) { return (n < 10 ? '0' : '') + n; };
  dom.clockDisplay.textContent = p(now.getHours()) + ':' + p(now.getMinutes()) + ':' + p(now.getSeconds());
}
setInterval(updateClock, 1000); updateClock();

/* 主题 */
function setTheme(tm, silent) {
  var root = document.documentElement;
  if (tm === 'dark') {
    root.setAttribute('data-theme', 'dark');
    dom.themeToggle.textContent = '☀️';
  } else {
    root.removeAttribute('data-theme');
    dom.themeToggle.textContent = '🌙';
  }
  state.theme = tm;
  /* 明暗模式下气泡颜色的 shift 方向不同，需要重新计算 */
  if (typeof applyAccentColor === 'function') {
    try { applyAccentColor(state.themeColor || '#07c160'); } catch (e) {}
  }
  if (!silent) {
    try { localStorage.setItem('theme', tm); } catch (e) {}
    /* 用户手动切换时，主题模式重置为显式 light/dark */
    state.themeMode = tm;
    try { localStorage.setItem('themeMode', tm); } catch (e) {}
    if (dom.setThemeMode) dom.setThemeMode.value = tm;
  }
}
dom.themeToggle.addEventListener('click', function () {
  /* 从 auto 模式切过来时按当前实际显示取反 */
  var next = state.theme === 'light' ? 'dark' : 'light';
  state.themeMode = next;
  setTheme(next);
});

/* 系统主题跟随 */
(function initThemeMedia() {
  try {
    var mq = window.matchMedia('(prefers-color-scheme: dark)');
    var listener = function (e) {
      if (state.themeMode === 'auto') setTheme(e.matches ? 'dark' : 'light', true);
    };
    if (mq.addEventListener) mq.addEventListener('change', listener);
    else if (mq.addListener) mq.addListener(listener);
  } catch (e) {}
})();
dom.timeModeToggle.addEventListener('click', function () {
  var order = ['both', 'clock', 'rel'];
  var names = { both: t('setTimeBoth'), clock: t('setTimeClock'), rel: t('setTimeRel') };
  var i = order.indexOf(state.timeMode);
  if (i === -1) i = 0;
  state.timeMode = order[(i + 1) % order.length];
  try { localStorage.setItem('timeMode', state.timeMode); } catch (e) {}
  showToast(t('toastTimeMode') + ' · ' + names[state.timeMode]);
  if (state.currentTarget) renderMessages();
});
var savedThemeMode = 'light';
try { savedThemeMode = localStorage.getItem('themeMode') || localStorage.getItem('theme') || 'light'; } catch (e) {}
state.themeMode = savedThemeMode;
if (savedThemeMode === 'auto') {
  try {
    var _m = window.matchMedia('(prefers-color-scheme: dark)');
    setTheme(_m.matches ? 'dark' : 'light', true);
  } catch (e) { setTheme('light', true); }
} else {
  setTheme(savedThemeMode === 'dark' ? 'dark' : 'light', true);
}

/* ==================== 横竖屏 ==================== */
var isLandscape = false;
dom.orientationToggle.addEventListener('click', function () {
  isLandscape = !isLandscape;
  var app = document.getElementById('app');
  if (isLandscape) {
    app.classList.add('landscape');
    dom.orientationToggle.textContent = '🖥️';
    if (dom.sidebar.classList.contains('open')) toggleSidebar(false);
  } else {
    app.classList.remove('landscape');
    dom.orientationToggle.textContent = '📱';
  }
});


/* ==================== 全屏切换 ==================== */
(function initFullscreen() {
  if (!dom.fullscreenToggle) return;
  dom.fullscreenToggle.addEventListener('click', function () {
    try {
      if (!document.fullscreenElement && !document.webkitFullscreenElement) {
        var el = document.documentElement;
        var req = el.requestFullscreen || el.webkitRequestFullscreen || el.msRequestFullscreen;
        if (req) req.call(el).then(function () {
          showToast(t('toastFullscreenOn'));
        }).catch(function () {});
      } else {
        var ex = document.exitFullscreen || document.webkitExitFullscreen || document.msExitFullscreen;
        if (ex) ex.call(document).then(function () {
          showToast(t('toastFullscreenOff'));
        }).catch(function () {});
      }
    } catch (e) {}
  });
})();


/* 「更多」菜单（PC 与移动端双端统一收纳策略） */
(function initMoreMenus() {
  var headerMoreBtn  = $id('headerMoreBtn');
  var headerMoreMenu = $id('headerMoreMenu');
  var chatMoreBtn    = $id('chatMoreBtn');
  var chatMoreMenu   = $id('chatMoreMenu');
  if (!headerMoreMenu && !chatMoreMenu) return;

  /* 桌面端还原顺序（保证与原始布局完全一致） */
  var HEADER_ORDER = ['headerNickname', 'onlineCount', 'adminBtn', 'walletBtn', 'signinBtn', 'spaceBtn', 'musicBtn', 'aboutBtn',
    'timeModeToggle', 'themeToggle', 'orientationToggle', 'fullscreenToggle', 'logoutBtn'];
  /* 移动端要收纳的头部按钮
     （walletBtn / signinBtn 已含在内 → 移动端可通过「⋯」进入钱包 / 签到） */
  /* aboutBtn 已从「更多」菜单移除：关于入口只在登录界面与设置里 */
  var HEADER_MOVE  = ['onlineCount', 'adminBtn', 'walletBtn', 'signinBtn',
    'timeModeToggle', 'themeToggle', 'orientationToggle', 'fullscreenToggle', 'logoutBtn'];
  /* 收纳策略：PC 特供 5 个按钮 → PC 收顶栏 ⋯，移动端收聊天头 ⋯ */

  /* PC 端顶栏收纳：12 个（含 5 个 PC 特供） */
  var HEADER_MOVE_PC = ['onlineCount', 'adminBtn',
                        'walletBtn', 'signinBtn', 'spaceBtn',
                        'musicBtn', 'feedbackBtn',
                        'timeModeToggle', 'themeToggle', 'orientationToggle',
                        'fullscreenToggle', 'logoutBtn'];

  /* 移动端顶栏收纳：7 个（不含 PC 特供，因为 PC 特供会走聊天头部 ⋯） */
  var HEADER_MOVE_MOBILE = ['onlineCount', 'adminBtn',
                            'timeModeToggle', 'themeToggle', 'orientationToggle',
                            'fullscreenToggle', 'logoutBtn'];

  /* 移动端聊天头部额外收纳：PC 特供 5 个 */
  var CHAT_MOVE_MOBILE_EXTRA = ['walletBtn', 'signinBtn', 'spaceBtn',
                                'musicBtn', 'feedbackBtn'];
  /* 桌面端聊天头部还原顺序 */
  var CHAT_ORDER = ['replyHint', 'closeChatBtn', 'memberBtn', 'qqTools',
    'scrollToggle', 'refreshBtn', 'searchToggleBtn', 'starredBtn',
    'settingsBtn', 'clearChatBtn', 'biliBtn'];
  /* ★ 聊天头部按钮收纳策略：双端统一收纳。
     PC 与移动端都把 7 个次要按钮收进 ⋯ 菜单
     （关闭会话 ✕ 保留在头部，随时可退）。
     保持两端行为一致，交互心智模型统一。 */
  var CHAT_MOVE  = ['qqTools', 'scrollToggle', 'refreshBtn', 'searchToggleBtn',
    'starredBtn', 'settingsBtn', 'clearChatBtn', 'biliBtn'];

  var headerMoved = false, chatMoved = false;

  function nodes(ids) {
    var out = [];
    for (var i = 0; i < ids.length; i++) {
      var el = document.getElementById(ids[i]);
      if (el) out.push(el);
    }
    return out;
  }

  function rebuild(parent, order, tail) {
    if (!parent) return;
    var list = nodes(order);
    for (var i = 0; i < list.length; i++) parent.appendChild(list[i]);
    if (tail) parent.appendChild(tail);
  }

  function sync() {
    try {
      window.__uiGuardSuppressUntil = Date.now() + 2500;
    } catch (e) {}

    /* ★ 收纳判定：
       · 移动端：聊天头部 + 顶栏 都收纳（原有策略）
       · PC 端：仅顶栏收纳 5 个"PC 特供"按钮；
                聊天头部不收纳（PC 屏宽，按钮全部平铺） */
    var w = window.innerWidth || 0;
    var isPC = getIsPC();

    var headerInfo  = document.querySelector('.header .user-info');
    var headerLeft  = document.querySelector('.header .left');
    var chatActions = document.querySelector('.chat-header .header-actions');
    var grb = document.getElementById('globalRefreshBtn');

    /* ---- 头部 / 聊天头部 ----
       ★ 模式区分收纳：
         · PC 端  → 顶栏 ⋯ 收纳 12 个；聊天头部 ⋯ 收纳 7 个
         · 移动端 → 顶栏 ⋯ 收纳 7 个；聊天头部 ⋯ 收纳 7 + 5 个
       （移动端顶栏隐藏，PC 特供的 5 个按钮只能从聊天头部 ⋯ 访问）
       仅在模式切换时重排一次，避免频繁搬动 DOM。 */
    var _targetMode = isPC ? 'pc' : 'mobile';
    if (headerMoreMenu && headerInfo && chatMoreMenu && chatActions &&
        window._collapseMode !== _targetMode) {

      /* ---- 1. 全部还原到原位 ---- */
      rebuild(chatActions, CHAT_ORDER, chatMoreBtn);
      chatActions.appendChild(chatMoreMenu);
      if (headerLeft && grb) headerLeft.appendChild(grb);
      rebuild(headerInfo, HEADER_ORDER, headerMoreBtn);
      headerInfo.appendChild(headerMoreMenu);
      headerMoved = false;
      chatMoved = false;

      /* ---- 2. 顶栏收纳 ---- */
      if (grb) headerMoreMenu.appendChild(grb);
      var _hmList = isPC ? HEADER_MOVE_PC : HEADER_MOVE_MOBILE;
      var hm = nodes(_hmList);
      for (var i = 0; i < hm.length; i++) headerMoreMenu.appendChild(hm[i]);
      headerMoved = true;

      /* ---- 3. 聊天头部收纳 ---- */
      /* PC 端：7 个基础按钮 */
      /* 移动端：7 个基础按钮 + 5 个 PC 特供 */
      var _cmList = isPC
        ? CHAT_MOVE
        : CHAT_MOVE.concat(CHAT_MOVE_MOBILE_EXTRA);
      var cm = nodes(_cmList);
      for (var j = 0; j < cm.length; j++) chatMoreMenu.appendChild(cm[j]);
      chatMoved = true;

      window._collapseMode = _targetMode;
    }
  }

  function closeAll(except) {
    if (headerMoreMenu && headerMoreMenu !== except) {
      headerMoreMenu.classList.remove('open');
      if (headerMoreBtn) headerMoreBtn.classList.remove('open');
    }
    if (chatMoreMenu && chatMoreMenu !== except) {
      chatMoreMenu.classList.remove('open');
      if (chatMoreBtn) chatMoreBtn.classList.remove('open');
    }
  }
  window.__closeMoreMenus = closeAll;

  if (headerMoreBtn && headerMoreMenu) {
    headerMoreBtn.addEventListener('click', function (e) {
      e.stopPropagation();
      closeAll(headerMoreMenu);
      var open = headerMoreMenu.classList.toggle('open');
      headerMoreBtn.classList.toggle('open', open);
    });
  }
  if (chatMoreBtn && chatMoreMenu) {
    chatMoreBtn.addEventListener('click', function (e) {
      e.stopPropagation();
      closeAll(chatMoreMenu);
      var open = chatMoreMenu.classList.toggle('open');
      chatMoreBtn.classList.toggle('open', open);
    });
  }
  /* 点菜单内部不关闭 */
  if (headerMoreMenu) headerMoreMenu.addEventListener('click', function (e) { e.stopPropagation(); });
  if (chatMoreMenu) chatMoreMenu.addEventListener('click', function (e) { e.stopPropagation(); });
  document.addEventListener('click', function () { closeAll(null); });

  /* 点击菜单里的按钮后自动收起 */
  /* ---- 看视频按钮（放在更多菜单中） ---- */
  (function bindBiliBtn() {
    var btn = document.getElementById('biliBtn');
    if (!btn) return;
    btn.addEventListener('click', function (e) {
      e.stopPropagation();
      if (typeof window.__openBiliPanel === 'function') {
        window.__openBiliPanel();
      }
    });
  })();

  function bindAutoClose(menu, btn) {
    if (!menu || !btn) return;
    menu.addEventListener('click', function (e) {
      var t = e.target;
      while (t && t !== menu) {
        if (t.tagName === 'BUTTON') {
          setTimeout(function () {
            menu.classList.remove('open');
            btn.classList.remove('open');
          }, 120);
          return;
        }
        t = t.parentNode;
      }
    });
  }
  bindAutoClose(headerMoreMenu, headerMoreBtn);
  bindAutoClose(chatMoreMenu, chatMoreBtn);

  var _rt = null;
  window.addEventListener('resize', function () {
    if (_rt) clearTimeout(_rt);
    _rt = setTimeout(function () { _rt = null; sync(); }, 150);
  });

  sync();
})();

/* PC 顶栏收纳：8 个不常用按钮收进 ⋯，状态持久化 */
(function initHeaderCollapse() {
  var btn = $id('headerCollapseBtn');
  var menu = $id('headerMoreMenu');
  if (!btn || !menu) return;

  /* 收纳按钮列表 */
  var COLLAPSE_MOVE = [
    'walletBtn', 'signinBtn', 'spaceBtn', 'musicBtn', 'feedbackBtn',
    'timeModeToggle', 'orientationToggle', 'fullscreenToggle'
  ];
  var KEY = 'header_collapsed';
  var isCollapsed = false;
  try { isCollapsed = localStorage.getItem(KEY) === '1'; } catch (e) {}

  function apply() {
    var info = document.querySelector('.header .user-info');
    if (!info) return;
    var anchor = $id('headerMoreBtn');
    if (!anchor) return;

    /* 收纳前后需授权 + 重拍快照，避免 UI Guard 误判为"移动元素" */
    try { window.__uiGuardSuppressUntil = Date.now() + 1500; } catch (e0) {}

    if (isCollapsed) {
      /* 移入菜单 */
      for (var i = 0; i < COLLAPSE_MOVE.length; i++) {
        var el = $id(COLLAPSE_MOVE[i]);
        if (el && el.parentNode !== menu) menu.appendChild(el);
      }
      btn.classList.add('active');
      btn.textContent = '»';
      btn.title = '展开顶栏';
    } else {
      /* 恢复原位：插到收纳按钮之前 */
      for (var j = 0; j < COLLAPSE_MOVE.length; j++) {
        var el2 = $id(COLLAPSE_MOVE[j]);
        if (el2 && info.contains(anchor)) {
          info.insertBefore(el2, btn);
        }
      }
      btn.classList.remove('active');
      btn.textContent = '«';
      btn.title = '收纳顶栏';
    }

    /* ★ 重拍父节点快照 —— 新父节点成为基准 */
    try {
      if (typeof uiGuardSnapshotParents === 'function') {
        uiGuardSnapshotParents();
      }
    } catch (e1) {}

    /* ★ 延长授权窗口，覆盖 MutationObserver 的 300ms 延迟确认 */
    try { window.__uiGuardSuppressUntil = Date.now() + 1200; } catch (e2) {}
  }

  btn.addEventListener('click', function (e) {
    e.stopPropagation();
    isCollapsed = !isCollapsed;
    try { localStorage.setItem(KEY, isCollapsed ? '1' : '0'); } catch (er) {}
    apply();
    showToast(isCollapsed ? '顶栏已收纳' : '顶栏已展开');
  });

  /* 供 initMoreMenus 在 resize 后调用 */
  window.__applyHeaderCollapse = apply;

  /* 首次应用 */
  apply();
})();

/* 侧边栏 */
function toggleSidebar(show) {
  if (typeof show === 'boolean') {
    if (show) dom.sidebar.classList.add('open');
    else dom.sidebar.classList.remove('open');
  } else {
    dom.sidebar.classList.toggle('open');
  }
  var opened = dom.sidebar.classList.contains('open');
  if (opened) dom.sidebarOverlay.classList.add('active');
  else dom.sidebarOverlay.classList.remove('active');
  /* 移动端：交由 mobileSetPage 状态机统一管理 */
  if (window.innerWidth <= 768) {
    document.body.style.overflow = opened ? 'hidden' : '';
    /* 若打开侧边栏 → 切到会话列表页；若关闭侧边栏且当前是会话列表页 → 保持不变 */
    if (opened && typeof mobileSetPage === 'function') {
      /* 只在当前不在聊天详情页时切到 chat 页 */
      if (!document.body.classList.contains('mobile-chat-detail')) {
        mobileSetPage('chat');
      }
    }
    /* 兼容旧 CSS：保留 mobile-sidebar-open 类 */
    document.body.classList.toggle('mobile-sidebar-open', opened);
  } else {
    document.body.style.overflow = '';
    document.body.classList.remove('mobile-sidebar-open');
  }
}
