function renderQQVotes() {
  var g = state.groups[state.currentTarget];
  if (!g) return;
  var list = dom.qqVoteList;
  list.innerHTML = '';
  var votes = g.votes || [];
  if (!votes.length) {
    list.innerHTML = '<div style="color:var(--text-muted);text-align:center;">' +
      escapeHtml(t('noVotes')) + '</div>';
    return;
  }
  for (var i = 0; i < votes.length; i++) {
    var v = votes[i];
    var item = document.createElement('div');
    item.className = 'qq-vote-item';
    var creator = state.users[v.creator] ? state.users[v.creator].name : v.creator;
    var total = 0;
    for (var o in v.results) if (v.results.hasOwnProperty(o)) total += v.results[o];
    var html = '<div class="vote-question" style="width:100%;"><strong>' + escapeHtml(v.question) + '</strong>' +
      escapeHtml(t('qqVoteCreatorPre')) + escapeHtml(creator) + escapeHtml(t('qqVoteCreatorSuf')) + '</div>';
    html += '<div style="font-size:13px;width:100%;">';
    for (var j = 0; j < v.options.length; j++) {
      var opt = v.options[j];
      var cnt = v.results[opt] || 0;
      var pct = total > 0 ? (cnt / total * 100).toFixed(1) : '0.0';
      html += '<div>' + escapeHtml(opt) + ': ' + cnt + escapeHtml(t('votesUnit')) + ' (' + pct + '%)' +
        '<span class="vote-bar" style="width:' + Math.max(parseFloat(pct), 2) + '%;"></span></div>';
    }
    var hasVoted = v.voters && v.voters.indexOf(state.myId) !== -1;
    if (!hasVoted && v.active !== false) {
      html += '<div style="margin-top:4px;"><select class="vote-select" data-vid="' + v.voteId + '" style="padding:2px 8px;border-radius:12px;border:1px solid var(--border-input);">';
      for (var kk = 0; kk < v.options.length; kk++) {
        html += '<option value="' + escapeHtml(v.options[kk]) + '">' + escapeHtml(v.options[kk]) + '</option>';
      }
      html += '</select><button class="vote-submit" data-vid="' + v.voteId + '" style="background:var(--bg-btn-primary);color:#fff;border:none;padding:2px 12px;border-radius:12px;cursor:pointer;margin-left:4px;">' +
        escapeHtml(t('btnVote')) + '</button></div>';
    } else if (hasVoted) {
      html += '<div style="color:var(--text-muted);font-size:12px;">' +
        escapeHtml(t('qqVoteDone')) + '</div>';
    }
    html += '</div>';
    item.innerHTML = html;
    list.appendChild(item);
  }
  var submitBtns = list.querySelectorAll('.vote-submit');
  for (var s = 0; s < submitBtns.length; s++) {
    (function (btn) {
      btn.addEventListener('click', function () {
        var vid = btn.dataset.vid;
        var sel = list.querySelector('.vote-select[data-vid="' + vid + '"]');
        if (!sel) return;
        state.socket.emit('qq-vote-submit', {
          groupId: state.currentTarget, voteId: vid, option: sel.value
        });
      });
    })(submitBtns[s]);
  }
}

/* ==================== 主题色 ==================== */
function shiftColor(hex, percent) {
  var h = String(hex || '#07c160').replace('#', '');
  if (h.length === 3) h = h.split('').map(function (c) { return c + c; }).join('');
  var r = parseInt(h.substring(0, 2), 16);
  var g = parseInt(h.substring(2, 4), 16);
  var b = parseInt(h.substring(4, 6), 16);
  var amt = Math.round(2.55 * percent);
  r = Math.max(0, Math.min(255, r + amt));
  g = Math.max(0, Math.min(255, g + amt));
  b = Math.max(0, Math.min(255, b + amt));
  return '#' + [r, g, b].map(function (v) {
    var s = v.toString(16);
    return s.length === 1 ? '0' + s : s;
  }).join('');
}

function hexToRgbTuple(hex) {
  var h = String(hex || '#07c160').replace('#', '');
  if (h.length === 3) h = h.split('').map(function (c) { return c + c; }).join('');
  if (h.length !== 6) h = '07c160';
  var r = parseInt(h.substring(0, 2), 16);
  var g = parseInt(h.substring(2, 4), 16);
  var b = parseInt(h.substring(4, 6), 16);
  if (isNaN(r) || isNaN(g) || isNaN(b)) { r = 7; g = 193; b = 96; }
  return r + ',' + g + ',' + b;
}

function applyAccentColor(color) {
  if (!color) color = '#07c160';
  var root = document.documentElement;
  /* ---- 主题色核心变量：全站（含液态玻璃 / 空间 / 名片 / 语音）通用 ---- */
  root.style.setProperty('--accent', color);
  root.style.setProperty('--accent-hover', shiftColor(color, -12));
  root.style.setProperty('--accent-rgb', hexToRgbTuple(color));
  /* ---- 兼容旧的按钮变量 ---- */
  root.style.setProperty('--bg-btn-primary', color);
  root.style.setProperty('--bg-btn-primary-hover', shiftColor(color, -12));
  /* 自己的消息气泡颜色跟随主题色（明暗分别调整） */
  if (state.theme === 'dark') {
    root.style.setProperty('--bg-msg-self', shiftColor(color, -38));
  } else {
    root.style.setProperty('--bg-msg-self', shiftColor(color, 38));
  }
}

function syncAccentSwatches(color) {
  if (!dom.colorSwatches) return;
  var all = dom.colorSwatches.querySelectorAll('.color-swatch');
  for (var i = 0; i < all.length; i++) {
    /* color 为 null 时清除所有高亮（用于自定义取色场景） */
    all[i].classList.toggle('active', color != null && all[i].dataset.color === color);
  }
}

if (dom.colorSwatches) {
  dom.colorSwatches.addEventListener('click', function (e) {
    var sw = e.target.closest ? e.target.closest('.color-swatch') : null;
    if (!sw) return;

    /* ★ 自定义色块：打开原生取色器 */
    if (sw.id === 'colorSwatchCustom' || sw.classList.contains('color-swatch-custom')) {
      var temp = document.createElement('input');
      temp.type = 'color';
      temp.value = state.themeColor || '#07c160';
      temp.style.cssText = 'position:fixed;left:-9999px;top:-9999px;';
      document.body.appendChild(temp);
      temp.addEventListener('input', function () {
        state.themeColor = temp.value;
        applyAccentColor(temp.value);
        try { localStorage.setItem('themeColor', temp.value); } catch (er) {}
      });
      temp.addEventListener('change', function () {
        syncAccentSwatches(null);   /* 取消所有预设的高亮 */
        sw.classList.add('active');  /* 只保留自定义块的 active */
        try { localStorage.setItem('themeColor', temp.value); } catch (er) {}
        setTimeout(function () {
          if (temp.parentNode) temp.parentNode.removeChild(temp);
        }, 400);
      });
      try { temp.click(); } catch (er) {}
      return;
    }

    var color = sw.dataset.color;
    state.themeColor = color;
    try { localStorage.setItem('themeColor', color); } catch (e) {}
    applyAccentColor(color);
    syncAccentSwatches(color);
    showToast(t('toastAccentApplied'));
  });
}

/* ==================== 夜间免打扰时段 ==================== */
function isQuietNow() {
  if (!state.quietEnabled) return false;
  var now = new Date();
  var cur = now.getHours() * 60 + now.getMinutes();
  var s = state.quietStart, e = state.quietEnd;
  if (s === e) return false;
  if (s < e) return cur >= s && cur < e;
  return cur >= s || cur < e;
}

/* ==================== 声音提醒 ==================== */
var _audioCtx = null;
function ensureAudioCtx() {
  if (_audioCtx) return _audioCtx;
  try {
    var AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    _audioCtx = new AC();
  } catch (e) { _audioCtx = null; }
  return _audioCtx;
}
function playBeep(urgent) {
  if (!state.soundEnabled) return;
  if (state.soundType === 'none') return;
  var ctx = ensureAudioCtx();
  if (!ctx) return;
  try {
    if (ctx.state === 'suspended') ctx.resume();
    var t0 = ctx.currentTime;
    /* ★ v0.30.0：按用户设定的音量缩放（0~1 乘数） */
    var _volMul = (typeof state.soundVolume === 'number')
      ? Math.max(0, Math.min(1, state.soundVolume / 100))
      : 0.8;
    /* 0 音量视同静音 */
    if (_volMul <= 0) return;
    /* @提及 / 关键词强提醒：连续两声，比普通消息更醒目 */
    if (urgent) {
      var uo1 = ctx.createOscillator(), ug1 = ctx.createGain();
      uo1.connect(ug1); ug1.connect(ctx.destination);
      uo1.type = 'sine';
      uo1.frequency.setValueAtTime(1046, t0);
      ug1.gain.setValueAtTime(0.0001, t0);
      ug1.gain.exponentialRampToValueAtTime(0.14 * _volMul, t0 + 0.01);
      ug1.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.18);
      uo1.start(t0); uo1.stop(t0 + 0.22);

      var uo2 = ctx.createOscillator(), ug2 = ctx.createGain();
      uo2.connect(ug2); ug2.connect(ctx.destination);
      uo2.type = 'sine';
      uo2.frequency.setValueAtTime(1397, t0 + 0.20);
      ug2.gain.setValueAtTime(0.0001, t0 + 0.20);
      ug2.gain.exponentialRampToValueAtTime(0.14 * _volMul, t0 + 0.21);
      ug2.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.40);
      uo2.start(t0 + 0.20); uo2.stop(t0 + 0.44);
      return;
    }
    var type = state.soundType || 'beep';
    var osc = ctx.createOscillator();
    var gain = ctx.createGain();
    gain.connect(ctx.destination);
    osc.connect(gain);
    if (type === 'drop') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(1200, t0);
      osc.frequency.exponentialRampToValueAtTime(600, t0 + 0.15);
      gain.gain.setValueAtTime(0.0001, t0);
      gain.gain.exponentialRampToValueAtTime(0.13 * _volMul, t0 + 0.01);
      gain.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.20);
      osc.start(t0); osc.stop(t0 + 0.22);
    } else if (type === 'bell') {
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(1046, t0);
      osc.frequency.setValueAtTime(1568, t0 + 0.10);
      osc.frequency.setValueAtTime(2093, t0 + 0.20);
      gain.gain.setValueAtTime(0.0001, t0);
      gain.gain.exponentialRampToValueAtTime(0.09 * _volMul, t0 + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.45);
      osc.start(t0); osc.stop(t0 + 0.5);
    } else {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(880, t0);
      osc.frequency.setValueAtTime(1180, t0 + 0.09);
      gain.gain.setValueAtTime(0.0001, t0);
      gain.gain.exponentialRampToValueAtTime(0.12 * _volMul, t0 + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.28);
      osc.start(t0); osc.stop(t0 + 0.32);
    }
  } catch (e) {}
}
document.addEventListener('pointerdown', function once() {
  document.removeEventListener('pointerdown', once);
  ensureAudioCtx();
}, false);

/* ==================== 桌面通知 ==================== */
function requestNotifyPermission() {
  if (!('Notification' in window)) { showToast(t('toastNotifyUnsupported')); return; }
  if (Notification.permission === 'granted') return;
  if (Notification.permission === 'denied') {
    showToast(t('toastNotifyDenied'));
    return;
  }
  try { Notification.requestPermission(); } catch (e) {}
}
/* 桌面通知：支持按会话合并、点击跳转、富文本 */
function notifyDesktop(title, body, opts) {
  if (!state.notifyEnabled) return;
  if (!('Notification' in window) || Notification.permission !== 'granted') return;
  if (!document.hidden && document.hasFocus()) return;
  opts = opts || {};
  try {
    var n = new Notification(title, {
      body: body,
      /* 同会话多条用同一 tag → 系统只保留一条并累计 */
      tag: opts.tag || 'lan-chat',
      /* 系统通知自带角标（部分浏览器支持） */
      badge: opts.badge || undefined,
      silent: true
    });
    n.onclick = function () {
      try { window.focus(); } catch (e) {}
      try { n.close(); } catch (e) {}
      /* ★ 点击系统通知直接跳转到会话 */
      if (opts.targetId && opts.targetType) {
        if (opts.targetType === 'private' && state.users[opts.targetId]) {
          selectContact(opts.targetId, 'private');
        } else if (opts.targetType === 'group' && state.groups[opts.targetId]) {
          selectContact(opts.targetId, 'group');
        }
      }
    };
    setTimeout(function () { try { n.close(); } catch (e) {} }, 8000);
  } catch (e) {}
}

/* ==================== 标签页未读数 ==================== */
function updateTitleUnread() {
  if (_titleFlashTimer) return; /* 闪烁时不动 */
  var total = 0;
  for (var k in state.unread) {
    if (state.unread.hasOwnProperty(k)) {
      if (k === 'wx_pay') continue;
      total += state.unread[k] || 0;
    }
  }
  var mentions = 0;
  for (var m in state.mentions) {
    if (state.mentions.hasOwnProperty(m) && state.mentions[m]) mentions++;
  }
  var base = state._origTitle || t('appTitle');
  if (mentions > 0) {
    /* ★ @提及：显示「(总未读) [N 个会话@你] 标题」 */
    var _en = state.lang === 'en';
    var _mTxt = _en
      ? ('[@' + (mentions > 1 ? 'x' + mentions : '') + '] ')
      : ('[有人@你' + (mentions > 1 ? '·' + mentions : '') + '] ');
    document.title = '(' + total + ') ' + _mTxt + base;
  } else if (total > 0) {
    document.title = '(' + total + ') ' + base;
  } else {
    document.title = base;
  }
}

/* ==================== 标题闪烁 ====================
   说明：本函数在文件下方还有一份更完整的实现（使用 _titleFlashTimer），
   本处保留占位注释，实际逻辑以下方定义为准。 */
window.addEventListener('focus', stopFlashTitle);
document.addEventListener('visibilitychange', function () {
  if (!document.hidden) {
    stopFlashTitle();
  } else {
    /* ★ 页面隐藏（切到后台）时，主动释放语音波形、翻译等非核心大对象缓存 */
    if (typeof _clientCacheTrim === 'function') {
      _clientCacheTrim(state.voiceWaveCache, 50);
      _clientCacheTrim(_translateCache, 20);
    }
  }
});
/* 消息通知总入口：音乐 / 桌面通知 / 标题闪烁，按免打扰策略分级处理 */
function alertNewMessage(title, body, chatKey, opts) {
  opts = opts || {};
  var urgent = !!opts.isMention || !!opts.isKeyword;
  /* ★ v0.27.20：免打扰时仍提醒 @ */
  var mentionPass = !!opts.isMention && state.dndAllowMention === true;

  /* ---- 全局免打扰 ---- */
  if (state.doNotDisturb) {
    if (opts.isKeyword || mentionPass) playBeep(true);
    else flashTitle();
    return;
  }
  var away = document.hidden || !document.hasFocus();
  if (!away) return;

  /* ---- 单会话静音 ---- */
  if (chatKey && state.mutedChats[chatKey]) {
    if (opts.isKeyword || mentionPass) playBeep(true);
    else flashTitle();
    return;
  }

  /* ---- 夜间免打扰 ---- */
  if (isQuietNow()) {
    if (opts.isKeyword || mentionPass) playBeep(true);
    else flashTitle();
    return;
  }

  playBeep(urgent);
  /* ★ 隐私模式：隐藏消息内容 */
  var _nb = state.notifyPrivacy
    ? (state.lang === 'en' ? 'You have a new message' : '你收到一条新消息')
    : body;
  notifyDesktop(title, _nb, {
    tag: chatKey || 'lan-chat',
    targetId: opts.targetId || '',
    targetType: opts.targetType || ''
  });
  flashTitle();
}
window.alertNewMessage = alertNewMessage;
window.previewOf = previewOf;

/* ==================== 消息搜索 ==================== */
function clearSearch() {
  var hits = dom.messageList.querySelectorAll('.search-hit');
  for (var i = 0; i < hits.length; i++) hits[i].classList.remove('search-hit');
  var act = dom.messageList.querySelectorAll('.search-hit-active');
  for (var j = 0; j < act.length; j++) act[j].classList.remove('search-hit-active');
  state.searchResults = [];
  state.searchIndex = -1;
  if (dom.searchCount) dom.searchCount.textContent = '0/0';
}
function runSearch() {
  var q = dom.searchInput.value.trim();
  clearSearch();
  if (!q) return;
  _searchHistoryPush(q);
  _searchHistoryHide();
  var msgs = dom.messageList.querySelectorAll('.msg');
  for (var i = 0; i < msgs.length; i++) {
    var el = msgs[i];
    // ★ v0.29.0：深拷贝节点并移除不需要匹配的部分（已读、发送者、时间、头像等）
    var clone = el.cloneNode(true);
    var exclude = clone.querySelectorAll('.read-info, .sender, .time, .reactions-row, .reply-block, .msg-avatar, .burned');
    for (var j = 0; j < exclude.length; j++) {
      if (exclude[j].parentNode) exclude[j].parentNode.removeChild(exclude[j]);
    }
    if ((clone.textContent || '').indexOf(q) !== -1) {
      el.classList.add('search-hit');
      state.searchResults.push(el);
    }
  }
  if (state.searchResults.length) {
    state.searchIndex = 0;
    focusSearchHit();
  } else {
    dom.searchCount.textContent = '0/0';
  }
}
function focusSearchHit() {
  var arr = state.searchResults;
  for (var i = 0; i < arr.length; i++) arr[i].classList.remove('search-hit-active');
  if (!arr.length || state.searchIndex < 0) {
    dom.searchCount.textContent = '0/0';
    return;
  }
  var el = arr[state.searchIndex];
  el.classList.add('search-hit-active');
  try { el.scrollIntoView({ behavior: 'smooth', block: 'center' }); }
  catch (e) {
    var top = el.offsetTop - dom.messageList.clientHeight / 2;
    dom.messageList.scrollTop = Math.max(0, top);
  }
  dom.searchCount.textContent = (state.searchIndex + 1) + '/' + arr.length;
}
function stepSearch(delta) {
  if (!state.searchResults.length) return;
  var n = state.searchResults.length;
  state.searchIndex = (state.searchIndex + delta + n) % n;
  focusSearchHit();
}
function openSearch(show) {
  if (typeof show === 'boolean') dom.searchBar.classList.toggle('open', show);
  else dom.searchBar.classList.toggle('open');
  if (dom.searchBar.classList.contains('open')) {
    dom.searchInput.focus();
    dom.searchInput.select();
    _searchHistoryRender();
  } else {
    clearSearch();
    dom.searchInput.value = '';
    _searchHistoryHide();
  }
}

/* ============================================================
   ★ v0.27.6：消息搜索历史
   ------------------------------------------------------------
   · 最近 10 条搜索词，存于 localStorage
   · 搜索框获得焦点时下拉显示，点击即填入
   · 单条可删除；空历史不显示
   ============================================================ */
var SEARCH_HISTORY_KEY = 'search_history';
var SEARCH_HISTORY_MAX = 10;

function _searchHistoryGet() {
  try {
    var raw = localStorage.getItem(SEARCH_HISTORY_KEY);
    var arr = raw ? JSON.parse(raw) : [];
    return Array.isArray(arr) ? arr : [];
  } catch (e) { return []; }
}

function _searchHistorySave(arr) {
  try {
    localStorage.setItem(SEARCH_HISTORY_KEY,
      JSON.stringify(arr.slice(0, SEARCH_HISTORY_MAX)));
  } catch (e) {}
}

function _searchHistoryPush(q) {
  q = String(q || '').trim();
  if (!q || q.length < 1) return;
  var arr = _searchHistoryGet();
  arr = arr.filter(function (x) { return x !== q; });
  arr.unshift(q);
  _searchHistorySave(arr);
}

function _searchHistoryClear() {
  try { localStorage.removeItem(SEARCH_HISTORY_KEY); } catch (e) {}
  _searchHistoryHide();
}

function _searchHistoryRender() {
  var arr = _searchHistoryGet();
  var box = document.getElementById('__searchHistoryBox');
  if (!arr.length) {
    if (box) box.style.display = 'none';
    return;
  }
  if (!box) {
    box = document.createElement('div');
    box.id = '__searchHistoryBox';
    box.style.cssText = [
      'position:absolute;top:100%;left:0;right:0;z-index:9999;',
      'background:var(--bg-modal);',
      'border:1px solid var(--border-modal);',
      'border-radius:12px;',
      'margin-top:6px;padding:6px 0;',
      'box-shadow:0 8px 28px rgba(0,0,0,.18);',
      'max-height:260px;overflow-y:auto;'
    ].join('');
    /* 挂在搜索栏下方 —— 搜索栏本身就是定位祖先 */
    var bar = dom.searchBar;
    if (bar) {
      var pos = window.getComputedStyle(bar).position;
      if (pos === 'static') bar.style.position = 'relative';
      bar.appendChild(box);
    } else {
      return;
    }
  }
  box.innerHTML = '';

  /* 标题行 */
  var head = document.createElement('div');
  head.style.cssText = 'padding:4px 14px 6px;font-size:11.5px;' +
    'color:var(--text-muted);font-weight:600;letter-spacing:.4px;' +
    'display:flex;align-items:center;justify-content:space-between;';
  head.innerHTML = '<span>' +
    (state.lang === 'en' ? 'RECENT SEARCHES' : '最近搜索') +
    '</span>';
  var clearBtn = document.createElement('button');
  clearBtn.type = 'button';
  clearBtn.textContent = state.lang === 'en' ? 'Clear' : '清空';
  clearBtn.style.cssText =
    'background:none;border:none;color:var(--text-muted);' +
    'cursor:pointer;font-size:11.5px;padding:2px 6px;' +
    'border-radius:6px;font-family:inherit;';
  clearBtn.addEventListener('mousedown', function (e) {
    e.preventDefault();
    e.stopPropagation();
    _searchHistoryClear();
  });
  head.appendChild(clearBtn);
  box.appendChild(head);

  /* 每一条 */
  for (var i = 0; i < arr.length; i++) {
    (function (kw) {
      var row = document.createElement('div');
      row.style.cssText = 'padding:8px 14px;font-size:13.5px;' +
        'cursor:pointer;display:flex;align-items:center;gap:10px;' +
        'color:var(--text-primary);transition:background .12s;';
      row.innerHTML =
        '<span style="opacity:.5;font-size:12px;">🕒</span>' +
        '<span style="flex:1;min-width:0;overflow:hidden;' +
        'text-overflow:ellipsis;white-space:nowrap;">' +
        escapeHtml(kw) + '</span>' +
        '<span class="sh-del" style="opacity:.4;font-size:14px;' +
        'padding:0 4px;border-radius:4px;">✕</span>';
      row.addEventListener('mousedown', function (e) {
        e.preventDefault();
        var del = e.target && e.target.classList &&
          e.target.classList.contains('sh-del');
        if (del) {
          e.stopPropagation();
          var cur = _searchHistoryGet().filter(function (x) {
            return x !== kw;
          });
          _searchHistorySave(cur);
          _searchHistoryRender();
          return;
        }
        dom.searchInput.value = kw;
        _searchHistoryHide();
        runSearch();
      });
      row.addEventListener('mouseenter', function () {
        row.style.background = 'rgba(var(--accent-rgb),.1)';
      });
      row.addEventListener('mouseleave', function () {
        row.style.background = '';
      });
      box.appendChild(row);
    })(arr[i]);
  }
  box.style.display = '';
}

function _searchHistoryHide() {
  var box = document.getElementById('__searchHistoryBox');
  if (box) box.style.display = 'none';
}

/* 在搜索框失焦 / 关闭搜索 / 执行搜索后，延迟隐藏（允许点击） */
document.addEventListener('mousedown', function (e) {
  var box = document.getElementById('__searchHistoryBox');
  if (!box || box.style.display === 'none') return;
  if (box.contains(e.target)) return;
  if (dom.searchBar && dom.searchBar.contains(e.target)) return;
  _searchHistoryHide();
}, true);
dom.searchToggleBtn.addEventListener('click', function () { openSearch(); });
dom.searchCloseBtn.addEventListener('click', function () { openSearch(false); });
dom.searchPrevBtn.addEventListener('click', function () { stepSearch(-1); });
dom.searchNextBtn.addEventListener('click', function () { stepSearch(1); });
/* ★ v0.27.0：一键把搜索命中的消息全部加入收藏 */
(function initSearchStarBtn() {
  var btn = document.getElementById('searchStarBtn');
  if (!btn) return;
  btn.addEventListener('click', function () {
    var arr = state.searchResults || [];
    if (!arr.length) { showToast('当前没有命中消息'); return; }
    var added = 0;
    for (var i = 0; i < arr.length; i++) {
      var mid = arr[i].getAttribute('data-msgid');
      if (!mid) continue;
      if (!state.starredMsgs[mid]) {
        state.starredMsgs[mid] = { msgId: mid, savedAt: Date.now() };
        added++;
      }
    }
    if (added) {
      saveStarred();
      showToast('⭐ 已加入收藏 ' + added + ' 条');
    } else {
      showToast('命中的消息已全部在收藏中');
    }
  });
})();
dom.searchInput.addEventListener('input', debounce(runSearch, 220));
dom.searchInput.addEventListener('focus', function () {
  /* ★ v0.27.6：搜索框获得焦点时显示历史（仅当输入为空） */
  if (!dom.searchInput.value.trim()) _searchHistoryRender();
});
dom.searchInput.addEventListener('keydown', function (e) {
  if (e.key === 'Enter') {
    e.preventDefault();
    _searchHistoryPush(dom.searchInput.value.trim());
    _searchHistoryHide();
    stepSearch(e.shiftKey ? -1 : 1);
  } else if (e.key === 'Escape') {
    e.preventDefault();
    _searchHistoryHide();
    openSearch(false);
  } else if (e.key === 'ArrowDown') {
    /* ★ v0.27.6：方向键快速选中历史首条 */
    var box = document.getElementById('__searchHistoryBox');
    if (box && box.style.display !== 'none') {
      var first = box.querySelector('div[style*="cursor:pointer"],div[style*="cursor: pointer"]');
      /* 兜底：找非标题行 */
      var rows = box.querySelectorAll('div');
      for (var _ri = 0; _ri < rows.length; _ri++) {
        if (rows[_ri].style.cursor === 'pointer') { first = rows[_ri]; break; }
      }
      if (first) {
        e.preventDefault();
        first.dispatchEvent(new Event('mousedown'));
      }
    }
  }
});
document.addEventListener('keydown', function (e) {
  if ((e.ctrlKey || e.metaKey) && (e.key === 'f' || e.key === 'F')) {
    if (!state.currentTarget) return;
    e.preventDefault();
    openSearch(true);
  }
});

