/* ============================================================
   复用层 1：统一存储封装
   ============================================================ */
var LS = {
  get: function (k, dft) {
    try {
      var v = localStorage.getItem('lc_' + k);
      return v ? JSON.parse(v) : dft;
    } catch (e) { return dft; }
  },
  set: function (k, v) {
    try { localStorage.setItem('lc_' + k, JSON.stringify(v)); } catch (e) {}
  },
  del: function (k) {
    try { localStorage.removeItem('lc_' + k); } catch (e) {}
  }
};

/* ============================================================
   复用层 2：统一 touch 手势库
   ------------------------------------------------------------
   服务：① 下拉刷新  ② 滑动操作
   用法：
     bindSwipe(el, {
       onPullDown: function (dist, release) {...},
       onSwipeLeft: function () {...},
       onSwipeRight: function () {...},
       swipeThreshold: 48, pullThreshold: 60,
       enablePull: false, enableSwipe: true
     });
   ============================================================ */
function bindSwipe(el, opt) {
  if (!el) return;
  opt = opt || {};
  var startX = 0, startY = 0;
  var curX = 0, curY = 0;
  var axis = null;           /* 'x' | 'y' | null */
  var active = false;
  var SWIPE_T = opt.swipeThreshold || 48;
  var PULL_T  = opt.pullThreshold  || 60;

  el.addEventListener('touchstart', function (e) {
    if (e.touches.length !== 1) return;
    startX = e.touches[0].clientX;
    startY = e.touches[0].clientY;
    curX = startX; curY = startY;
    axis = null;
    active = true;
  }, { passive: true });

  el.addEventListener('touchmove', function (e) {
    if (!active || e.touches.length !== 1) return;
    curX = e.touches[0].clientX;
    curY = e.touches[0].clientY;
    var dx = curX - startX;
    var dy = curY - startY;
    if (!axis) {
      if (Math.abs(dx) > Math.abs(dy) && Math.abs(dx) > 8) axis = 'x';
      else if (Math.abs(dy) > Math.abs(dx) && Math.abs(dy) > 8) axis = 'y';
      else return;
    }
    if (axis === 'x' && opt.enableSwipe && opt.onSwipeMove) {
      opt.onSwipeMove(dx);
    }
    if (axis === 'y' && opt.enablePull && opt.onPullDown) {
      /* 只在滚动到顶部时触发下拉 */
      if (el.scrollTop <= 0 && dy > 0) {
        opt.onPullDown(dy, false);
      }
    }
  }, { passive: true });

  el.addEventListener('touchend', function (e) {
    if (!active) return;
    active = false;
    var dx = curX - startX;
    var dy = curY - startY;
    if (axis === 'x' && opt.enableSwipe) {
      if (dx < -SWIPE_T && opt.onSwipeLeft) opt.onSwipeLeft();
      else if (dx > SWIPE_T && opt.onSwipeRight) opt.onSwipeRight();
      if (opt.onSwipeMove) opt.onSwipeMove(0);
    }
    if (axis === 'y' && opt.enablePull && opt.onPullDown) {
      opt.onPullDown(dy, true);
    }
  }, { passive: true });

  el.addEventListener('touchcancel', function () {
    active = false;
    axis = null;
    if (opt.onSwipeMove) opt.onSwipeMove(0);
    if (opt.enablePull && opt.onPullDown) opt.onPullDown(0, true);
  }, { passive: true });
}

/* ============================================================
   复用层 3：Canvas 绘制工具（消息导出为图片）
   ============================================================ */
function drawChatToCanvas(msgs, opts) {
  opts = opts || {};
  var MAX_W = 560;
  var PAD = 16;
  var AVATAR = 40;
  var LINE_H = 22;
  var FONT_SIZE = 14;
  var FONT = FONT_SIZE + 'px -apple-system,"PingFang SC","Microsoft YaHei",sans-serif';
  var chatName = opts.chatName || '聊天记录';

  /* ---- 预处理：把每条消息转为 "文字行" ---- */
  var lines = [];
  lines.push({ type: 'title', text: chatName });
  lines.push({ type: 'sub', text: new Date().toLocaleString('zh-CN', { hour12: false }) });
  lines.push({ type: 'gap', h: 12 });

  var canvas = document.createElement('canvas');
  var ctx = canvas.getContext('2d');
  ctx.font = FONT;

  function wrapText(text, maxW) {
    var out = [];
    var t = String(text || '');
    /* 先按 \n 分段，再按宽度折行 */
    var paras = t.split('\n');
    for (var pi = 0; pi < paras.length; pi++) {
      var cur = '';
      var chars = paras[pi];
      for (var ci = 0; ci < chars.length; ci++) {
        var ch = chars.charAt(ci);
        var test = cur + ch;
        if (ctx.measureText(test).width > maxW) {
          out.push(cur);
          cur = ch;
        } else {
          cur = test;
        }
      }
      out.push(cur);
    }
    return out;
  }

  for (var i = 0; i < msgs.length; i++) {
    var m = msgs[i];
    if (!m || m.recalled) continue;
    var isSelf = (m.from === opts.myId);
    var bubbleMax = MAX_W - PAD * 2 - AVATAR - 16;
    var bodyText = '';
    if (m.type === 'text') bodyText = String(m.content || '');
    else if (m.type === 'file') {
      var ft = m.fileType || '';
      bodyText = (ft.indexOf('image/') === 0) ? '[图片]'
        : (ft.indexOf('video/') === 0) ? '[视频]'
        : (ft.indexOf('audio/') === 0) ? '[语音]'
        : '[文件] ' + (m.fileName || '');
    }
    else if (m.type === 'voice') bodyText = '[语音 ' + (m.duration || '?') + '秒]';
    else if (m.type === 'sticker') bodyText = '[表情]';
    else if (m.type === 'redpacket') bodyText = '[红包] ' + (m.packetGreeting || '');
    else bodyText = '[消息]';

    var wrapped = wrapText(bodyText, bubbleMax - 24);
    var bubbleW = 0;
    for (var w = 0; w < wrapped.length; w++) {
      bubbleW = Math.max(bubbleW, ctx.measureText(wrapped[w]).width);
    }
    bubbleW = Math.min(bubbleMax, bubbleW + 24);
    var bubbleH = wrapped.length * LINE_H + 20;

    var name = m.fromName || m.from || '';
    lines.push({
      type: 'msg',
      isSelf: isSelf,
      name: name,
      time: (m.time || '').slice(-8, -3) || '',
      avatar: m.fromAvatar || '',
      initial: (name || '?').charAt(0).toUpperCase(),
      wrapped: wrapped,
      bubbleW: bubbleW,
      bubbleH: bubbleH
    });
    lines.push({ type: 'gap', h: 10 });
  }

  /* ---- 计算总高度 ---- */
  var totalH = 0;
  for (var li = 0; li < lines.length; li++) {
    var l = lines[li];
    if (l.type === 'title') totalH += 36;
    else if (l.type === 'sub') totalH += 20;
    else if (l.type === 'gap') totalH += l.h;
    else if (l.type === 'msg') totalH += Math.max(AVATAR, l.bubbleH) + 26;
  }
  totalH += PAD * 2 + 40;
  var totalW = MAX_W;

  /* ---- 高清屏 2x 绘制 ---- */
  var DPR = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = totalW * DPR;
  canvas.height = totalH * DPR;
  ctx.scale(DPR, DPR);
  ctx.font = FONT;

  /* ---- 背景 ---- */
  ctx.fillStyle = '#ededed';
  ctx.fillRect(0, 0, totalW, totalH);

  /* ---- 顶部标题卡 ---- */
  var y = PAD;
  ctx.fillStyle = '#fff';
  ctx.fillRect(0, 0, totalW, 44);
  ctx.fillStyle = '#191919';
  ctx.font = 'bold 15px -apple-system,"PingFang SC","Microsoft YaHei",sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(chatName, totalW / 2, 22);
  ctx.font = FONT;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'alphabetic';
  y = 60;

  /* ---- 绘制每条消息 ---- */
  for (var di = 0; di < lines.length; di++) {
    var d = lines[di];
    if (d.type === 'gap') { y += d.h; continue; }
    if (d.type === 'title' || d.type === 'sub') continue;

    var rowH = Math.max(AVATAR, d.bubbleH);
    var avX = d.isSelf ? (totalW - PAD - AVATAR) : PAD;
    var bubX = d.isSelf
      ? (avX - 8 - d.bubbleW)
      : (avX + AVATAR + 8);

    /* 头像 */
    ctx.beginPath();
    ctx.arc(avX + AVATAR / 2, y + 20, AVATAR / 2, 0, Math.PI * 2);
    ctx.fillStyle = d.isSelf ? '#07c160' : '#576b95';
    ctx.fill();
    ctx.fillStyle = '#fff';
    ctx.font = 'bold 16px -apple-system,"PingFang SC","Microsoft YaHei",sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(d.initial, avX + AVATAR / 2, y + 21);

    /* 发送者名 + 时间（非自己） */
    if (!d.isSelf) {
      ctx.font = '11px -apple-system,"PingFang SC","Microsoft YaHei",sans-serif';
      ctx.fillStyle = '#888';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'alphabetic';
      ctx.fillText(d.name + '  ' + d.time, bubX + 4, y + 12);
    }

    /* 气泡 */
    var bubY = y + 18;
    ctx.beginPath();
    var r = 8;
    var bx = bubX, by = bubY, bw = d.bubbleW, bh = d.bubbleH;
    ctx.moveTo(bx + r, by);
    ctx.lineTo(bx + bw - r, by);
    ctx.quadraticCurveTo(bx + bw, by, bx + bw, by + r);
    ctx.lineTo(bx + bw, by + bh - r);
    ctx.quadraticCurveTo(bx + bw, by + bh, bx + bw - r, by + bh);
    ctx.lineTo(bx + r, by + bh);
    ctx.quadraticCurveTo(bx, by + bh, bx, by + bh - r);
    ctx.lineTo(bx, by + r);
    ctx.quadraticCurveTo(bx, by, bx + r, by);
    ctx.closePath();
    ctx.fillStyle = d.isSelf ? '#95ec69' : '#fff';
    ctx.fill();

    /* 文字 */
    ctx.font = FONT;
    ctx.fillStyle = '#191919';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    for (var tw = 0; tw < d.wrapped.length; tw++) {
      ctx.fillText(d.wrapped[tw], bx + 12, by + 10 + tw * LINE_H);
    }

    /* 自己的时间（右下） */
    if (d.isSelf) {
      ctx.font = '11px -apple-system,"PingFang SC","Microsoft YaHei",sans-serif';
      ctx.fillStyle = '#888';
      ctx.textAlign = 'right';
      ctx.textBaseline = 'alphabetic';
      ctx.fillText(d.time, bubX - 8, y + 12);
    }

    /* 恢复默认 */
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.font = FONT;

    y += rowH + 26;
  }

  /* ---- 底部水印 ---- */
  ctx.font = '11px -apple-system,"PingFang SC","Microsoft YaHei",sans-serif';
  ctx.fillStyle = 'rgba(0,0,0,.32)';
  ctx.textAlign = 'center';
  ctx.fillText('微信 · 局域网', totalW / 2, totalH - 16);

  return canvas;
}

/* ============================================================
   ① 移动端下拉刷新
   ------------------------------------------------------------
   ★ 同 initSwipeContacts：移除一次性 matchMedia 判定，
     改为事件触发时读取 html.is-mobile。 */
(function initPullRefresh() {
  var list = dom.messageList;
  var ind = document.getElementById('pullIndicator');
  if (!list || !ind) return;

  var indIcon = ind.querySelector('.pull-icon');
  var indText = ind.querySelector('.pull-text');
  var _pullDist = 0;
  var _refreshing = false;

  bindSwipe(list, {
    enablePull: true,
    pullThreshold: 60,
    onPullDown: function (dist, release) {
      /* ★ 只对移动端生效 */
      if (!document.documentElement.classList.contains('is-mobile')) return;
      if (_refreshing) return;
      _pullDist = dist;
      if (release) {
        if (dist >= 60 && state.currentTarget) {
          _refreshing = true;
          ind.classList.add('ready', 'refreshing');
          indText.textContent = '刷新中…';
          indIcon.textContent = '↻';
          ind.style.transform = 'translateY(0)';
          /* 触发刷新 */
          if (state.socket && state.socket.connected) {
            state.socket.emit('history-load-more', {
              targetId: state.currentTarget,
              type: state.currentType,
              beforeMsgId: '',
              limit: CLIENT_HISTORY_PAGE
            });
          }
          setTimeout(function () {
            _refreshing = false;
            ind.classList.remove('show', 'ready', 'refreshing');
            indText.textContent = '下拉刷新';
            indIcon.textContent = '↓';
            ind.style.transform = '';
          }, 900);
        } else {
          /* 距离不够，弹回 */
          ind.classList.remove('ready');
          ind.style.transform = 'translateY(-60px)';
          setTimeout(function () { ind.classList.remove('show'); }, 200);
        }
      } else {
        /* 拖动中 */
        var clamped = Math.min(dist, 90);
        ind.classList.add('show');
        ind.style.transform = 'translateY(' + (clamped - 60) + 'px)';
        if (dist >= 60) {
          ind.classList.add('ready');
          indText.textContent = '松开刷新';
        } else {
          ind.classList.remove('ready');
          indText.textContent = '下拉刷新';
        }
      }
    }
  });
})();

