/* ============================================================
   ④ 移动端「拍摄」按钮
   ============================================================ */
(function initCaptureBtn() {
  var btn = document.getElementById('captureBtn');
  if (!btn) return;
  btn.addEventListener('click', function () {
    if (!state.currentTarget) { showToast(t('toastPickContact')); return; }
    var fi = document.createElement('input');
    fi.type = 'file';
    fi.accept = 'image/*';
    fi.capture = 'environment';
    fi.style.display = 'none';
    document.body.appendChild(fi);
    fi.addEventListener('change', function () {
      var f = fi.files[0];
      if (!f) { document.body.removeChild(fi); return; }
      if (f.size > state.maxFileSize) {
        showToast(t('qqFileTooLargePrefix') +
          (state.maxFileSize / 1048576).toFixed(0) +
          t('qqFileTooLargeSuffix'));
        document.body.removeChild(fi);
        return;
      }
      var rd = new FileReader();
      rd.onload = function (ev) {
        compressImage(ev.target.result, 1280, 0.75).then(function (c) {
          sendFileMessage('photo_' + Date.now() + '.jpg',
            Math.round(c.length * 0.75), 'image/jpeg', c);
        });
      };
      rd.readAsDataURL(f);
      document.body.removeChild(fi);
    });
    fi.click();
  });
})();

/* ============================================================
   ⑤ 手表端快捷短语面板
   ============================================================ */
(function initWatchPhrases() {
  if (!document.documentElement.classList.contains('is-watch')) return;
  var box = document.getElementById('watchPhrases');
  if (!box) return;

  function render() {
    box.innerHTML = '';
    var defaults = ['好', '稍等', '在忙', '收到', '谢谢'];
    var list = (state.quickReplies && state.quickReplies.length)
      ? state.quickReplies.slice(0, 5) : defaults;
    for (var i = 0; i < list.length; i++) {
      (function (txt) {
        var b = document.createElement('button');
        b.type = 'button';
        b.className = 'watch-phrase';
        b.textContent = txt;
        b.addEventListener('click', function () {
          if (!state.currentTarget) { showToast(t('toastPickContact')); return; }
          dom.msgInput.value = txt;
          sendMessage();
        });
        box.appendChild(b);
      })(list[i]);
    }
  }
  render();
  /* 快捷回复更新时刷新 */
  var _origSave = window.saveQuickReplies;
  if (typeof _origSave === 'function') {
    window.saveQuickReplies = function () {
      _origSave.apply(this, arguments);
      render();
    };
  }
})();

/* ============================================================
   ⑧ 收藏夹分类
   ============================================================ */
var STARRED_TAGS = [
  { key: 'important', label: '重要', color: '#fa5151' },
  { key: 'later',     label: '稍后看', color: '#f5a623' },
  { key: 'reference', label: '参考',  color: '#1976d2' },
  { key: 'other',     label: '其他',  color: '#888' }
];
var _starredFilter = 'all';

function _getStarredTag(entry) {
  if (!entry || !entry.tag) return null;
  for (var i = 0; i < STARRED_TAGS.length; i++) {
    if (STARRED_TAGS[i].key === entry.tag) return STARRED_TAGS[i];
  }
  return null;
}

/* 重写收藏夹渲染：加分类筛选 + 标签 */
(function initStarredCategories() {
  /* 在 renderStarred 之前插入筛选栏 */
  var _origRenderStarred = window.renderStarred;

  window.renderStarred = function () {
    var box = dom.starredList;
    if (!box) return;
    var items = collectStarredMessages();

    /* 筛选 */
    if (_starredFilter !== 'all') {
      items = items.filter(function (it) {
        return state.starredMsgs[it.msg.msgId] &&
          state.starredMsgs[it.msg.msgId].tag === _starredFilter;
      });
    }

    /* 筛选栏 */
    var barHtml = '<div class="starred-filter-bar">';
    var allCount = collectStarredMessages().length;
    barHtml += '<button type="button" class="starred-filter-chip' +
      (_starredFilter === 'all' ? ' active' : '') +
      '" data-sf="all">全部 (' + allCount + ')</button>';
    for (var si = 0; si < STARRED_TAGS.length; si++) {
      var st = STARRED_TAGS[si];
      var cnt = 0;
      var all = collectStarredMessages();
      for (var ai = 0; ai < all.length; ai++) {
        var rec = state.starredMsgs[all[ai].msg.msgId];
        if (rec && rec.tag === st.key) cnt++;
      }
      barHtml += '<button type="button" class="starred-filter-chip' +
        (_starredFilter === st.key ? ' active' : '') +
        '" data-sf="' + st.key + '">' + st.label + ' (' + cnt + ')</button>';
    }
    barHtml += '</div>';

    if (!items.length) {
      box.innerHTML = barHtml + '<div class="starred-empty">' +
        (state.lang === 'en' ? 'No messages' : '暂无收藏') + '</div>';
      _bindStarredFilterBar();
      return;
    }

    var html = barHtml;
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      var m = it.msg;
      var who = m.from === state.myId ? state.myName :
        (state.users[m.from] ? state.users[m.from].name : m.from);
      var scope = it.scope === 'private' ? t('scopePrivate') :
        (t('scopeGroupPrefix') +
          (state.groups[it.targetId] ? state.groups[it.targetId].name : it.targetId));
      var preview = msgPreviewText(m, 120);
      if (preview.length >= 120) preview += '…';

      var rec = state.starredMsgs[m.msgId] || {};
      var tag = _getStarredTag(rec);
      var tagHtml = tag
        ? '<span class="starred-tag-chip" style="background:' +
          tag.color + '">' + tag.label + '</span>'
        : '';

      html += '<div class="starred-item" data-msgid="' + escapeHtml(m.msgId) +
        '" data-scope="' + it.scope + '" data-target="' + escapeHtml(it.targetId) + '">' +
        '<div class="meta">' + tagHtml + escapeHtml(scope) + ' · ' +
        escapeHtml(who) + ' · ' +
        escapeHtml(formatFullTime(parseMsgTime(m))) + '</div>' +
        '<div class="preview">' + escapeHtml(preview) + '</div>' +
        '</div>';
    }
    box.innerHTML = html;
    _bindStarredFilterBar();

    /* 点击项 */
    var els = box.querySelectorAll('.starred-item');
    for (var j = 0; j < els.length; j++) {
      (function (el) {
        el.addEventListener('click', function () {
          var scope = el.dataset.scope;
          var tid = el.dataset.target;
          var mid = el.dataset.msgid;
          dom.starredModal.classList.remove('open');
          if (scope === 'private' && state.users[tid]) selectContact(tid, 'private');
          else if (scope === 'group' && state.groups[tid]) selectContact(tid, 'group');
          setTimeout(function () { jumpToMessage(mid); }, 300);
        });
        /* 右键：设置 / 清除分类 */
        el.addEventListener('contextmenu', function (e) {
          e.preventDefault();
          e.stopPropagation();
          var mid = el.dataset.msgid;
          var rec = state.starredMsgs[mid] || {};
          showMsgMenuTagPicker(mid, rec.tag);
        });
      })(els[j]);
    }
  };

  function _bindStarredFilterBar() {
    var chips = dom.starredList.querySelectorAll('.starred-filter-chip');
    for (var i = 0; i < chips.length; i++) {
      (function (c) {
        c.addEventListener('click', function () {
          _starredFilter = c.getAttribute('data-sf') || 'all';
          window.renderStarred();
        });
      })(chips[i]);
    }
  }
})();

/* 标签选择弹窗 */
function showMsgMenuTagPicker(msgId, curTag) {
  var html = '<div class="tag-picker-hint">' +
    (state.lang === 'en' ? 'Pick a category for this starred message' :
      '为这条收藏消息选择分类') + '</div>' +
    '<div class="tag-picker-list">';
  html += '<label class="tag-pick-row' +
    (!curTag ? ' checked' : '') + '">' +
    '<input type="radio" name="starTag" value=""' +
    (!curTag ? ' checked' : '') + '>' +
    '<span class="tag-pick-name">' +
    (state.lang === 'en' ? 'None' : '无分类') + '</span></label>';
  for (var i = 0; i < STARRED_TAGS.length; i++) {
    var tg = STARRED_TAGS[i];
    html += '<label class="tag-pick-row' +
      (curTag === tg.key ? ' checked' : '') + '">' +
      '<input type="radio" name="starTag" value="' + tg.key + '"' +
      (curTag === tg.key ? ' checked' : '') + '>' +
      '<span class="tag-pick-dot" style="background:' + tg.color + '"></span>' +
      '<span class="tag-pick-name">' + tg.label + '</span></label>';
  }
  html += '</div>';
  showModal(state.lang === 'en' ? 'Category' : '收藏分类', html, function () {
    var sel = document.querySelector('input[name="starTag"]:checked');
    var val = sel ? sel.value : '';
    if (!state.starredMsgs[msgId]) {
      state.starredMsgs[msgId] = { msgId: msgId, savedAt: Date.now() };
    }
    if (val) state.starredMsgs[msgId].tag = val;
    else delete state.starredMsgs[msgId].tag;
    saveStarred();
    window.renderStarred();
  }, { width: '380px', confirmText: t('btnSave') });
}

/* ============================================================
   ⑨ 全局搜索（跨会话搜消息）
   ============================================================ */
(function initGlobalSearch() {
  /* 挂载面板 DOM */
  var panel = document.createElement('div');
  panel.className = 'global-search-panel';
  panel.id = 'globalSearchPanel';
  panel.innerHTML =
    '<div class="global-search-box">' +
      '<div class="global-search-input-wrap">' +
        '<span style="font-size:16px;opacity:.55;">🔎</span>' +
        '<input type="text" class="global-search-input" ' +
          'id="globalSearchInput" ' +
          'placeholder="' + (state.lang === 'en'
            ? 'Search all chats…' : '在所有会话中搜索…') + '" ' +
          'autocomplete="off" spellcheck="false">' +
        '<span class="global-search-count" id="globalSearchCount">—</span>' +
      '</div>' +
      '<div class="global-search-list" id="globalSearchList"></div>' +
    '</div>';
  document.body.appendChild(panel);

  var inp = document.getElementById('globalSearchInput');
  var listEl = document.getElementById('globalSearchList');
  var countEl = document.getElementById('globalSearchCount');
  var _timer = null;

  function open() {
    panel.classList.add('open');
    setTimeout(function () { inp.focus(); inp.select(); }, 60);
  }
  function close() {
    panel.classList.remove('open');
  }

  function doSearch() {
    var q = String(inp.value || '').trim();
    if (!q) {
      listEl.innerHTML = '';
      countEl.textContent = '—';
      return;
    }
    if (!state.socket || !state.socket.connected) {
      listEl.innerHTML = '<div style="text-align:center;padding:30px;' +
        'color:var(--text-muted);font-size:13px;">' +
        (state.lang === 'en' ? 'Not connected' : '未连接') + '</div>';
      return;
    }
    state.socket.emit('global-search', { q: q, limit: 60 });
  }

  inp.addEventListener('input', function () {
    if (_timer) clearTimeout(_timer);
    _timer = setTimeout(doSearch, 320);
  });
  inp.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') { e.preventDefault(); close(); }
    if (e.key === 'Enter') {
      e.preventDefault();
      if (_timer) clearTimeout(_timer);
      doSearch();
    }
  });
  panel.addEventListener('click', function (e) {
    if (e.target === panel) close();
  });

  /* 快捷键：Ctrl+Shift+F */
  document.addEventListener('keydown', function (e) {
    if ((e.ctrlKey || e.metaKey) && e.shiftKey &&
        (e.key === 'f' || e.key === 'F')) {
      e.preventDefault();
      if (panel.classList.contains('open')) close();
      else open();
    }
  });

  /* 服务端回包 */
  if (state.socket) {
    state.socket.on('global-search-result', function (d) {
      if (!d) return;
      var arr = d.results || [];
      countEl.textContent = arr.length + (state.lang === 'en' ? ' found' : ' 条');
      if (!arr.length) {
        listEl.innerHTML = '<div style="text-align:center;padding:30px;' +
          'color:var(--text-muted);font-size:13px;">' +
          (state.lang === 'en' ? 'No results' : '没有找到结果') + '</div>';
        return;
      }
      var html = '';
      for (var i = 0; i < arr.length; i++) {
        var r = arr[i];
        var hlText = escapeHtml(r.preview);
        try {
          var re = new RegExp('(' +
            String(d.q).replace(/[\\^$.*+?()[\]{}|]/g, '\\$&') + ')', 'gi');
          hlText = hlText.replace(re, '<mark>$1</mark>');
        } catch (e) {}
        html += '<div class="global-search-item" ' +
          'data-tid="' + escapeHtml(r.targetId) + '" ' +
          'data-ttype="' + escapeHtml(r.type) + '" ' +
          'data-mid="' + escapeHtml(r.msgId) + '">' +
          '<div class="gsi-head">' +
            '<span class="gsi-chat">' + escapeHtml(r.chatName) + '</span>' +
            '<span>·</span>' +
            '<span>' + escapeHtml(r.fromName || '') + '</span>' +
            '<span>·</span>' +
            '<span>' + escapeHtml(r.time || '') + '</span>' +
          '</div>' +
          '<div class="gsi-text">' + hlText + '</div>' +
          '</div>';
      }
      listEl.innerHTML = html;
      var items = listEl.querySelectorAll('.global-search-item');
      for (var j = 0; j < items.length; j++) {
        (function (el) {
          el.addEventListener('click', function () {
            var tid = el.getAttribute('data-tid');
            var ttype = el.getAttribute('data-ttype');
            var mid = el.getAttribute('data-mid');
            close();
            if (ttype === 'private' && state.users[tid]) {
              selectContact(tid, 'private');
            } else if (ttype === 'group' && state.groups[tid]) {
              selectContact(tid, 'group');
            }
            setTimeout(function () { jumpToMessage(mid); }, 350);
          });
        })(items[j]);
      }
    });
  }

  window.__openGlobalSearch = open;
})();

/* ============================================================
   ⑩ 消息导出为图片
   ============================================================ */
(function initExportImage() {
  /* 通过给消息菜单追加项的通用工具实现（复用层） */
  function _addMenuItem(label, icon, handler) {
    var menu = dom.msgMenu;
    if (!menu) return;
    var item = document.createElement('div');
    item.className = 'menu-item';
    item.dataset.action = '_export_img';
    item.textContent = icon + ' ' + label;
    item.addEventListener('click', function (e) {
      e.stopPropagation();
      menu.style.display = 'none';
      handler(menu.dataset.msgid);
    });
    menu.appendChild(item);
  }

  _addMenuItem(state.lang === 'en' ? 'Export as image' : '导出为图片',
    '🖼️', function (msgId) {
      var msg = findMessageById(msgId);
      if (!msg) return;
      /* 导出当前会话最后 30 条（含选中的这条） */
      var key = currentChatKey();
      if (!key) return;
      var arr;
      if (state.currentType === 'private') {
        arr = state.messages[state.currentTarget] || [];
      } else {
        var g = state.groups[state.currentTarget];
        arr = (g && g.messages) || [];
      }
      /* 定位到选中消息附近 */
      var idx = -1;
      for (var i = 0; i < arr.length; i++) {
        if (arr[i].msgId === msgId) { idx = i; break; }
      }
      if (idx === -1) idx = arr.length - 1;
      var start = Math.max(0, idx - 15);
      var end = Math.min(arr.length, start + 30);
      var slice = arr.slice(start, end);
      var chatName = state.currentType === 'private'
        ? ((state.users[state.currentTarget] &&
            state.users[state.currentTarget].name) || '会话')
        : ((state.groups[state.currentTarget] &&
            state.groups[state.currentTarget].name) || '群聊');
      _showExportPreview(slice, chatName);
    });
})();

function _showExportPreview(msgs, chatName) {
  var canvas = drawChatToCanvas(msgs, {
    myId: state.myId,
    chatName: chatName
  });
  var dataUrl = canvas.toDataURL('image/png');

  var ov = document.createElement('div');
  ov.className = 'export-preview-overlay open';
  ov.id = '__exportPreviewOv';
  ov.innerHTML =
    '<div class="export-preview-wrap">' +
      '<img class="export-preview-img" src="' + dataUrl + '" alt="preview">' +
      '<div class="export-preview-actions">' +
        '<button type="button" class="app-dialog-btn cancel" ' +
          'id="__expClose">' +
          (state.lang === 'en' ? 'Close' : '关闭') + '</button>' +
        '<button type="button" class="app-dialog-btn confirm" ' +
          'id="__expSave">' +
          (state.lang === 'en' ? 'Save' : '保存图片') + '</button>' +
      '</div>' +
    '</div>';
  document.body.appendChild(ov);

  document.getElementById('__expClose').addEventListener('click', function () {
    if (ov.parentNode) ov.parentNode.removeChild(ov);
  });
  document.getElementById('__expSave').addEventListener('click', function () {
    downloadData(dataUrl, 'chat_' + Date.now() + '.png');
  });
  ov.addEventListener('click', function (e) {
    if (e.target === ov && ov.parentNode) ov.parentNode.removeChild(ov);
  });
}

/* ============================================================
   ⑪ 敏感词自动学习（挂载到审核面板）
   ============================================================ */
(function initModerationLearn() {
  /* 监听 moderation-alert 事件，把 payload 存起来 */
  state._lastModAlert = null;
  /* 由于 socket.on('moderation-alert') 已在 setupSocketEvents 中绑定，
     我们通过事件钩子捕获 —— 简单做法：在 showMessagePopup 处扩展 */
  /* 简化：监听 socket 上的同名事件（允许多个 handler） */
  /* 此处不重复绑定，走"面板显示时提供按钮"的路线 */

  /* 在 popup 渲染后，如果 payload 有 hits 字段，自动加"加入黑名单"按钮 */
  window.__modLearn = function (hits) {
    if (!Array.isArray(hits) || !hits.length) return;
    for (var i = 0; i < hits.length; i++) {
      var w = String(hits[i]).trim();
      if (!w) continue;
      if (state.socket && state.socket.connected) {
        state.socket.emit('moderation-learn', { word: w });
      }
    }
    showToast(state.lang === 'en' ? 'Added to filter' : '已加入过滤词');
  };
})();

