document.addEventListener('contextmenu', function (e) {
  var el = e.target && e.target.closest ? e.target.closest('.contact-item') : null;
  if (el) {
    e.preventDefault();
    var id = el.dataset.id;
    var type = el.dataset.type;
    if (id && type) showContactMenu(e.clientX, e.clientY, id, type);
    return;
  }
  /* ★ 禁用浏览器自带的右键菜单，避免与自定义菜单重叠 / 冲突。
     输入框 / 文本域 / 可编辑区域保留原生菜单，方便复制粘贴。 */
  var t = e.target;
  var tag = (t && t.tagName) ? t.tagName.toLowerCase() : '';
  if (tag === 'input' || tag === 'textarea' || (t && t.isContentEditable)) return;
  e.preventDefault();
});

