/* ==================== 双击上下半区滚动 ==================== */
(function () {
  var list = document.getElementById('messageList');
  if (!list) return;
  list.addEventListener('dblclick', function (e) {
    /* ★ 新增：双击顶部空白处，直接平滑回到最顶部 */
    var rect = list.getBoundingClientRect();
    if (e.clientY - rect.top < 50) {
      try {
        list.scrollTo({ top: 0, behavior: 'smooth' });
      } catch (err) {
        list.scrollTop = 0;
      }
      return;
    }

    var tt = e.target;
    while (tt && tt !== list) {
      var tag = tt.tagName;
      if (tag === 'IMG' || tag === 'VIDEO' || tag === 'AUDIO' ||
          tag === 'BUTTON' || tag === 'A' || tag === 'INPUT' ||
          tag === 'SELECT' || tag === 'TEXTAREA') {
        return;
      }
      if (tt.classList && tt.classList.contains('msg')) return;
      if (tt.classList && (
          tt.classList.contains('scroll-control-btn') ||
          tt.classList.contains('scroll-bottom-btn') ||
          tt.classList.contains('reply-block') ||
          tt.classList.contains('download-btn') ||
          tt.classList.contains('file-info'))) {
        return;
      }
      tt = tt.parentNode;
    }
    var rect = list.getBoundingClientRect();
    var y = e.clientY - rect.top;
    var half = rect.height / 2;
    var amount = Math.max(list.clientHeight * 0.85, 200);
    if (y < half) {
      list.scrollTop = Math.max(0, list.scrollTop - amount);
    } else {
      list.scrollTop = Math.min(list.scrollHeight - list.clientHeight, list.scrollTop + amount);
    }
  });
})();

/* ==================== 点击遮罩关闭弹窗（兼容版） ====================
   统一使用 isEventOnOverlayBackground()：
   - 主判定：e.target === 遮罩本身
   - 兜底判定：点击坐标落在卡片矩形之外
   并额外绑定 touchstart / touchend，兼容老 Android / iOS Safari
   有时 click 事件不冒泡到 fixed 层的问题。 */
(function bindOverlayClose() {
  var overlays = document.querySelectorAll('.modal-overlay');

  /* ============================================================
     ★ v0.24.13：防点击穿透
     ------------------------------------------------------------
     移动端点击遮罩空白区关闭弹窗时，浏览器会在 touchend 之后
     再派发一次「幽灵 click」。若遮罩下方正好有按钮，这个 click
     会被那个按钮捕获 → 表现为「点击空白却打开了别的功能」。

     解决方案：关闭遮罩后设置一个 500ms 的全局锁，
     此期间所有 click / touchend / touchstart 事件在捕获阶段被拦截。
     ============================================================ */
  function _lockClickThrough() {
    window.__overlayCloseLockUntil = Date.now() + 500;
  }
  if (!window.__overlayCloseLockBound) {
    window.__overlayCloseLockBound = true;
    var _captureBlock = function (e) {
      if (window.__overlayCloseLockUntil &&
          Date.now() < window.__overlayCloseLockUntil) {
        try { e.stopPropagation(); } catch (er) {}
        try { e.preventDefault(); } catch (er) {}
      }
    };
    document.addEventListener('click', _captureBlock, true);
    document.addEventListener('touchend', _captureBlock, true);
    document.addEventListener('touchstart', _captureBlock, true);
    /* 兜底：锁超时后自动清除 */
    setInterval(function () {
      if (window.__overlayCloseLockUntil &&
          Date.now() >= window.__overlayCloseLockUntil) {
        window.__overlayCloseLockUntil = 0;
      }
    }, 1000);
  }

  function closeOverlay(ov) {
    /* 先锁穿透，再关闭 */
    _lockClickThrough();
    /* ★ 使用带淡出的关闭函数 → 所有弹窗点遮罩关闭都有退场动画 */
    if (typeof closeModalWithFade === 'function') {
      closeModalWithFade(ov);
    } else {
      ov.classList.remove('open');
    }
    if (typeof window.__closeMoreMenus === 'function') window.__closeMoreMenus(null);
  }

  for (var i = 0; i < overlays.length; i++) {
    (function (ov) {
      ov.addEventListener('click', function (e) {
        if (!isEventOnOverlayBackground(e, ov)) return;
        closeOverlay(ov);
      });
    })(overlays[i]);
  }

  var supportsTouch = ('ontouchstart' in window) || (navigator.maxTouchPoints > 0);
  if (supportsTouch) {
    for (var j = 0; j < overlays.length; j++) {
      (function (ov) {
        var _startedOnBg = false;
        ov.addEventListener('touchstart', function (e) {
          _startedOnBg = isEventOnOverlayBackground(e, ov);
        }, false);
        ov.addEventListener('touchend', function (e) {
          if (!_startedOnBg) return;
          if (!isEventOnOverlayBackground(e, ov)) return;
          closeOverlay(ov);
        }, false);
      })(overlays[j]);
    }
  }
})();

/* ==================== 图片拖拽粘贴上传 ==================== */
document.addEventListener('paste', function (e) {
  if (!state.currentTarget) return;
  var items = e.clipboardData && e.clipboardData.items;
  if (!items) return;
  for (var i = 0; i < items.length; i++) {
    if (items[i].type && items[i].type.indexOf('image/') === 0) {
      var blob = items[i].getAsFile();
      if (!blob) continue;
      if (blob.size > state.maxFileSize) {
        showToast(t('qqFileTooLargePrefix') +
          (state.maxFileSize / 1048576).toFixed(0) + t('qqFileTooLargeSuffix'));
        return;
      }
      var rd = new FileReader();
      rd.onload = function (ev) {
        compressImage(ev.target.result, 1280, 0.75).then(function (c) {
          sendFileMessage('pasted_' + Date.now() + '.png',
            Math.round(c.length * 0.75), 'image/jpeg', c);
        });
      };
      rd.readAsDataURL(blob);
      e.preventDefault();
      break;
    }
  }
});

/* 语音 / 视频通话（ICE 默认 STUN，登录后由服务端覆盖） */
/* ============================================================
   通话常量（v0.33.0 重构）
   ============================================================ */
var CALL_ICE_SERVERS = [
  { urls: 'stun:stun.l.google.com:19302' },
  { urls: 'stun:stun1.l.google.com:19302' },
  { urls: 'stun:stun.services.mozilla.com' },
  { urls: 'stun:stun.cloudflare.com:3478' }
];
/* 呼叫超时：35 秒 */
var CALL_TIMEOUT_MS = 35000;
/* 通话中"对方静音"提示阈值：连续 800ms 音量为 0 视为静音 */
var CALL_SILENT_MUTE_MS = 800;
/* 连接质量采样间隔 */
var CALL_QUALITY_INTERVAL = 2000;
/* ICE 重启最小间隔 */
var CALL_ICE_RESTART_MIN_MS = 30000;

/* 检测浏览器是否支持 WebRTC + getUserMedia */
function callSupported() {
  return !!(window.RTCPeerConnection && navigator.mediaDevices &&
            typeof navigator.mediaDevices.getUserMedia === 'function');
}

/* 检测是否处于安全上下文（HTTPS / localhost / 127.0.0.1）
   —— 非安全上下文中 navigator.mediaDevices 为 undefined */
function callIsSecureContext() {
  try {
    if (window.isSecureContext === true) return true;
    if (location.protocol === 'https:') return true;
    if (location.hostname === 'localhost' ||
        location.hostname === '127.0.0.1' ||
        location.hostname === '[::1]') return true;
    return false;
  } catch (e) { return false; }
}

/* 给用户清晰的环境错误提示 */
function callCheckEnvironment() {
  if (!callSupported()) {
    showToast(t('callUnsupported') || '当前浏览器不支持通话');
    return false;
  }
  if (!callIsSecureContext()) {
    showToast('⚠️ 通话需要 HTTPS 或 localhost 访问。\n' +
      '局域网中请使用 https:// 打开，或联系管理员执行 gencert 生成证书。');
    return false;
  }
  return true;
}

function callResetUI() {
  try { dom.callModal.classList.remove('open', 'mode-video'); } catch (e) {}
  try { dom.callModal.style.display = 'none'; } catch (e) {}
  try { dom.callRejectBtn.style.display = 'none'; } catch (e) {}
  try { dom.callAcceptBtn.style.display = 'none'; } catch (e) {}
  try { dom.callHangupBtn.style.display = 'none'; } catch (e) {}
  try { dom.callMuteBtn.style.display = 'none'; } catch (e) {}
  try { dom.callVideoToggleBtn.style.display = 'none'; } catch (e) {}
  try { dom.callSwitchCameraBtn.style.display = 'none'; } catch (e) {}
  try { dom.callAvatar.innerHTML = '?'; } catch (e) {}
  try { dom.callAvatar.classList.remove('verified', 'system'); } catch (e) {}
  try { dom.callName.textContent = '—'; } catch (e) {}
  try { dom.callStatus.textContent = ''; } catch (e) {}
  try { dom.callStatus.classList.remove('timer'); } catch (e) {}
  try { dom.callVideoName.textContent = '—'; } catch (e) {}
  try { dom.callVideoTimer.textContent = ''; } catch (e) {}

  /* 清理所有叠加层，避免残留状态影响下一次 */
  try { if (dom.callMuteBadge) dom.callMuteBadge.classList.remove('show'); } catch (e) {}
  try {
    if (dom.callQuality) {
      dom.callQuality.classList.remove('show', 'good', 'fair', 'poor', 'bad');
    }
  } catch (e) {}
  try {
    if (dom.callVolumeRing) {
      dom.callVolumeRing.classList.remove('active', 'self');
    }
  } catch (e) {}
  try {
    dom.callRemoteVideo.srcObject = null;
    dom.callLocalVideo.srcObject = null;
  } catch (e) {}
  /* 移除任何残留的 call-ended-badge */
  try {
    var badges = dom.callModal.querySelectorAll('.call-ended-badge');
    for (var i = 0; i < badges.length; i++) {
      if (badges[i].parentNode) badges[i].parentNode.removeChild(badges[i]);
    }
  } catch (e) {}
}

function stopCallTone() {
  var c = state.call;
  if (c.ringtoneTimer) {
    clearInterval(c.ringtoneTimer);
    c.ringtoneTimer = null;
  }
  if (c.audioCtx) {
    try {
      /* 某些浏览器 close() 返回 Promise，须 catch 避免 unhandledrejection */
      var p = c.audioCtx.close();
      if (p && p.catch) p.catch(function () {});
    } catch (e) {}
    c.audioCtx = null;
  }
}

function playCallTone(kind) {
  /* kind: 'ring' 呼出响铃 | 'ringing' 来电 | 'end' 结束 */
  try {
    stopCallTone();
    var AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    var ctx = new AC();
    state.call.audioCtx = ctx;
    var makeBeep = function (freq, dur, delay) {
      var osc = ctx.createOscillator();
      var g = ctx.createGain();
      osc.connect(g); g.connect(ctx.destination);
      osc.frequency.value = freq;
      osc.type = 'sine';
      var t0 = ctx.currentTime + (delay || 0);
      g.gain.setValueAtTime(0.0001, t0);
      g.gain.exponentialRampToValueAtTime(0.08, t0 + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
      osc.start(t0);
      osc.stop(t0 + dur + 0.05);
    };
    if (kind === 'end') { makeBeep(520, 0.18, 0); makeBeep(380, 0.24, 0.18); return; }
    var isRing = (kind === 'ring');
    var tick = function () {
      if (isRing) { makeBeep(660, 0.4, 0); makeBeep(660, 0.4, 0.5); }
      else { makeBeep(880, 0.3, 0); makeBeep(660, 0.3, 0.4); }
    };
    tick();
    state.call.ringtoneTimer = setInterval(tick, 2000);
  } catch (e) {}
}

function startCallTimer() {
  var c = state.call;
  if (c.timerId) { clearInterval(c.timerId); c.timerId = null; }
  c.startTime = Date.now();
  c.connectedAt = Date.now();
  var render = function () {
    if (!state.call.active || state.call !== c) {
      if (c.timerId) { clearInterval(c.timerId); c.timerId = null; }
      return;
    }
    var sec = Math.floor((Date.now() - c.startTime) / 1000);
    var mm = Math.floor(sec / 60), ss = sec % 60;
    var txt = pad2(mm) + ':' + pad2(ss);
    try {
      dom.callStatus.textContent = txt;
      dom.callStatus.classList.add('timer');
      dom.callVideoTimer.textContent = txt;
    } catch (e) {}
  };
  render();
  c.timerId = setInterval(render, 1000);
}

function stopCallTimer() {
  if (state.call.timerId) {
    clearInterval(state.call.timerId);
    state.call.timerId = null;
  }
}

function showCallAvatar(u, verified) {
  var initial = (u || '?').charAt(0).toUpperCase();
  var av = '';
  if (state.call.peerAvatar) av = state.call.peerAvatar;
  try {
    if (av) {
      dom.callAvatar.innerHTML = '<img src="' + escapeHtml(av) + '" alt="">';
    } else {
      dom.callAvatar.textContent = initial;
    }
    dom.callAvatar.classList.toggle('verified', !!verified);
    dom.callAvatar.classList.toggle('system', isSystemUserId(state.call.peerId));
  } catch (e) {}
}

/* ---------- 发起通话（v0.33.0 重构） ---------- */
function startCall(callType) {
  if (!callCheckEnvironment()) return;
  if (!state.currentTarget || state.currentType !== 'private') {
    showToast(t('callOnlyPrivate')); return;
  }

  /* ★ 主叫前先检查残留状态：
     · 真·通话中（active / ringing / connecting / calling）→ 提示忙
     · 状态异常（active=true 但 status 为 null）→ 强制清理后继续 */
  if (state.call.active) {
    var _st = state.call.status;
    if (_st === 'active' || _st === 'ringing' ||
        _st === 'connecting' || _st === 'calling') {
      showToast(t('callSelfBusy'));
      return;
    }
    console.warn('[Call] startCall 前检测到残留状态（status=' + _st + '），强制清理');
    try { callFinish(null, true, null); } catch (e) {}
  }

  var peerId = state.currentTarget;
  var peer = state.users[peerId];
  if (!peer) { showToast(t('toastUserOffline')); return; }
  if (!peer.online) { showToast(t('callOffline') || '对方不在线'); return; }
  if (!state.socket || !state.socket.connected) {
    showConnectionStatus('error', t('connServerLost'));
    return;
  }

  var c = state.call;
  c.active = true;
  c.type = (callType === 'video') ? 'video' : 'voice';
  c.peerId = peerId;
  c.peerName = peer.name || peerId;
  c.peerAvatar = (peer.profile && peer.profile.avatar) || '';
  c.peerVerified = peer.verified || '';
  c.direction = 'outgoing';
  c.status = 'calling';
  c.isMuted = false;
  c.videoEnabled = (c.type === 'video');
  c.facingMode = 'user';
  c.pendingCandidates = [];
  c.pc = null;
  c.localStream = null;
  c.remoteStream = null;
  c.connectedAt = 0;
  c.startTime = 0;
  c._isCaller = true;
  c._makingOffer = false;
  c._ignoreOffer = false;
  c._hangupped = false;
  c._mediaStreamStopped = false;
  c._permDenied = false;

  callResetUI();
  dom.callModal.style.display = 'flex';
  dom.callModal.classList.toggle('mode-video', false);
  dom.callModal.classList.add('open');
  showCallAvatar(c.peerName, c.peerVerified);
  dom.callName.textContent = c.peerName;
  dom.callStatus.textContent = t('callCalling');
  dom.callHangupBtn.style.display = 'flex';
  dom.callHangupLabel.textContent = t('callHangup');
  playCallTone('ring');

  /* 提前获取本地媒体，接听后能立即听到声音 */
  getUserMediaStream(c.type).then(function (stream) {
    if (!state.call.active || state.call !== c) {
      try { stream.getTracks().forEach(function (tk) { tk.stop(); }); } catch (e) {}
      return;
    }
    c.localStream = stream;
    try { dom.callLocalVideo.srcObject = stream; } catch (e) {}
    try { dom.callLocalVideo.classList.toggle('mirror', c.facingMode === 'user'); } catch (e) {}
    /* 提前建 PC（不发起 offer，等 call-accepted 后再发起） */
    try { ensurePeerConnection(); } catch (e) {
      console.error('[Call] startCall 建 PC 失败:', e);
    }
  }).catch(function (err) {
    if (!state.call.active || state.call !== c) return;
    if (err && err.name === 'NotAllowedError') c._permDenied = true;
    if (state.socket && state.socket.connected) {
      state.socket.emit('call-end', { to: peerId });
    }
    callFinish(callType === 'video' ? t('callCameraDenied') : t('callMicDenied'),
               true, 'canceled');
  });

  /* 通知对端 */
  state.socket.emit('call-request', { to: peerId, callType: c.type });

  /* 呼叫超时 */
  c.timeoutId = setTimeout(function () {
    if (!state.call.active || state.call.status !== 'calling') return;
    if (state.socket && state.socket.connected) {
      try { state.socket.emit('call-end', { to: peerId }); } catch (e) {}
    }
    callFinish(t('callTimeout'), true, 'missed');
  }, CALL_TIMEOUT_MS);
}

function getUserMediaStream(callType) {
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    return Promise.reject(new Error('getUserMedia unavailable'));
  }
  var constraints = {
    audio: {
      echoCancellation: true,
      noiseSuppression: true,
      autoGainControl: true,
      sampleRate: 48000,
      channelCount: 1
    },
    video: (callType === 'video') ? {
      width: { ideal: 1280, max: 1920 },
      height: { ideal: 720, max: 1080 },
      frameRate: { ideal: 24, max: 30 },
      facingMode: state.call.facingMode || 'user'
    } : false
  };
  return navigator.mediaDevices.getUserMedia(constraints).catch(function (err) {
    var _en = state.lang === 'en';
    if (err && err.name === 'NotAllowedError') {
      showToast(callType === 'video'
        ? (t('callCameraDenied') || '摄像头权限被拒绝')
        : (t('callMicDenied') || '麦克风权限被拒绝'));
    } else if (err && err.name === 'NotFoundError' || err.name === 'OverconstrainedError') {
      showToast(callType === 'video'
        ? (_en ? 'No camera / microphone found' : '未检测到摄像头 / 麦克风')
        : (_en ? 'No microphone found' : '未检测到麦克风'));
    } else if (err && err.name === 'NotReadableError') {
      showToast(_en ? 'Camera / microphone is busy' : '摄像头 / 麦克风被其它程序占用');
    } else {
      showToast(t('callFailed'));
    }
    throw err;
  });
}

/* ---------- 来电处理（v0.33.0 重构） ---------- */
function handleIncomingCall(data) {
  if (!data || !data.from) return;
  var c = state.call;

  if (c.active) {
    /* ★ 真·通话中（或正在建立连接）→ 忙线 */
    if (c.status === 'active' || c.status === 'connecting') {
      console.warn('[Call] 来电忽略（忙线）：当前 ' + c.status +
        '，对端 ' + data.from);
      if (state.socket && state.socket.connected) {
        state.socket.emit('call-reject', { to: data.from, reason: 'busy' });
      }
      return;
    }

    /* ★ 正在 ringing：同一 caller 重复通知 → 幂等忽略；不同 caller → 忙线 */
    if (c.status === 'ringing') {
      if (c.peerId === data.from) {
        console.log('[Call] 来电幂等忽略：重复的 call-incoming');
        return;
      }
      console.warn('[Call] 来电忽略（忙线）：当前 ringing，对端 ' + data.from);
      if (state.socket && state.socket.connected) {
        state.socket.emit('call-reject', { to: data.from, reason: 'busy' });
      }
      return;
    }

    /* ★ 正在 calling（本端是主叫，正在拨号中）→ 忙线 */
    if (c.status === 'calling') {
      console.warn('[Call] 来电忽略（本端正在呼叫）');
      if (state.socket && state.socket.connected) {
        state.socket.emit('call-reject', { to: data.from, reason: 'busy' });
      }
      return;
    }

    /* ★ 其余情况：active=true 但 status 异常（null/undefined）→ 视为残留 */
    console.warn('[Call] 检测到残留通话状态（status=' + c.status +
      '，peerId=' + c.peerId + '），强制清理后接收新来电');
    try { callFinish(null, true, null); } catch (e) {}
    /* 下面继续走正常接收流程 */
  }

  // ============ 正常接收新来电 ============
  c.active = true;
  c.type = (data.callType === 'video') ? 'video' : 'voice';
  c.peerId = data.from;
  c.peerName = data.fromName || data.from;
  c.peerAvatar = data.fromAvatar || '';
  c.peerVerified = data.fromVerified || '';
  c.direction = 'incoming';
  c.status = 'ringing';
  c.isMuted = false;
  c.videoEnabled = (c.type === 'video');
  c.facingMode = 'user';
  c.pendingCandidates = [];
  c.pc = null;
  c.localStream = null;
  c.remoteStream = null;
  c.connectedAt = 0;
  c.startTime = 0;
  c._isCaller = false;
  c._makingOffer = false;
  c._ignoreOffer = false;
  c._hangupped = false;
  c._mediaStreamStopped = false;
  c._permDenied = false;

  callResetUI();
  dom.callModal.style.display = 'flex';
  dom.callModal.classList.toggle('mode-video', false);
  dom.callModal.classList.add('open');
  showCallAvatar(c.peerName, c.peerVerified);
  dom.callName.textContent = c.peerName;
  dom.callStatus.textContent = (c.type === 'video' ? '📹 ' : '📞 ') + t('callRinging');
  dom.callRejectBtn.style.display = 'flex';
  dom.callRejectLabel.textContent = t('callReject');
  dom.callAcceptBtn.style.display = 'flex';
  dom.callAcceptLabel.textContent = t('callAccept');
  playCallTone('ringing');

  c.timeoutId = setTimeout(function () {
    if (!state.call.active || state.call.status !== 'ringing') return;
    if (state.socket && state.socket.connected) {
      state.socket.emit('call-reject', { to: c.peerId, reason: 'timeout' });
    }
    callFinish(t('callTimeout'), true, 'missed');
  }, CALL_TIMEOUT_MS);
}

/* ---------- 接受通话（v0.33.0 重构） ----------
   ★ 关键：被叫方不主动 createOffer，只 ensurePC(false) + 通知服务端 */
function acceptCall() {
  if (!callCheckEnvironment()) {
    rejectCall('failed');
    return;
  }
  var c = state.call;
  if (!c.active || c.status !== 'ringing') return;
  if (c.timeoutId) { clearTimeout(c.timeoutId); c.timeoutId = null; }
  stopCallTone();

  c.status = 'connecting';
  dom.callStatus.textContent = t('callConnecting');
  dom.callRejectBtn.style.display = 'none';
  dom.callAcceptBtn.style.display = 'none';
  dom.callHangupBtn.style.display = 'flex';
  dom.callHangupLabel.textContent = t('callHangup');

  getUserMediaStream(c.type).then(function (stream) {
    if (!state.call.active || state.call !== c) {
      try { stream.getTracks().forEach(function (tk) { tk.stop(); }); } catch (e) {}
      return;
    }
    c.localStream = stream;
    try { dom.callLocalVideo.srcObject = stream; } catch (e) {}
    try { dom.callLocalVideo.classList.toggle('mirror', c.facingMode === 'user'); } catch (e) {}
    setupVolumeDetection(stream, true);

    /* ★ 被叫方：只创建 PC，等待主叫 offer（被叫永不 createOffer） */
    try { ensurePeerConnection(); } catch (e) {
      console.error('[Call] acceptCall 建 PC 失败:', e);
    }

    /* 通知主叫方"已接听" —— 注意：必须在 ensurePeerConnection 之后，
       确保被叫方 PC 已就绪；即使主叫 offer 迅速到达也能立即处理 */
    if (state.socket && state.socket.connected) {
      state.socket.emit('call-accept', { to: c.peerId });
    }
  }).catch(function (err) {
    if (err && err.name === 'NotAllowedError') c._permDenied = true;
    if (state.socket && state.socket.connected) {
      state.socket.emit('call-reject', { to: c.peerId, reason: 'failed' });
    }
    callFinish(t('callFailed'), true, 'rejected');
  });
}

/* ---------- 拒绝通话 ---------- */
function rejectCall(reason) {
  var c = state.call;
  if (!c.active) return;
  c._hangupped = true;
  if (c.timeoutId) { clearTimeout(c.timeoutId); c.timeoutId = null; }
  if (state.socket && state.socket.connected && c.peerId) {
    state.socket.emit('call-reject', { to: c.peerId, reason: reason || 'rejected' });
  }
  callFinish(t('callRejected'), true, 'rejected');
}

/* 通话记录：callFinish 内写入，callKind / callResult / callDuration 由双方按视角渲染 */
/* 通话记录：仅主叫方写；结构化字段，文案由双方各自渲染 */
function saveCallRecord(kind, durationSec, result) {
  try {
    var peerId = state.call.lastPeerId;
    if (!peerId) return;

    var _kind = (kind === 'video') ? 'video' : 'voice';
    var _result = result || 'ended';
    var _dur = Math.max(0, Math.round(Number(durationSec) || 0));

    /* 正常接通但时长过短（< 1 秒）→ 不写记录，避免噪音 */
    if (_result === 'ended' && _dur < 1) return;

    if (!state.messages[peerId]) state.messages[peerId] = [];

    var msgId = 'call_' + Date.now().toString(36) +
      Math.random().toString(36).substring(2, 6);
    var msg = {
      from: state.myId,
      to: peerId,
      content: '',                    /* 中文兜底由渲染端按语言生成 */
      time: getFullTime(),
      msgId: msgId,
      type: 'text',
      recalled: false,
      recalledBy: null,
      status: 'sent',
      readUsers: [],
      /* ---- 通话记录结构化字段 ---- */
      isCallRecord: true,
      callKind: _kind,
      callResult: _result,
      callDuration: _dur,
      callInitiator: state.myId,
      fromLevel: state.myLevel,
      fromVip: state.myVip,
      fromAdmin: state.isAdmin,
      fromVerified: state.myVerified || ''
    };
    addMessage(peerId, msg, 'private');
    /* 通过 private-message 转发给对方（服务端会持久化并投递给对方） */
    if (state.socket && state.socket.connected) {
      state.socket.emit('private-message', {
        to: peerId,
        content: '',
        msgId: msgId,
        type: 'text',
        isCallRecord: true,
        callKind: _kind,
        callResult: _result,
        callDuration: _dur,
        callInitiator: state.myId
      });
    }
  } catch (e) {
    console.warn('saveCallRecord 失败:', e.message);
  }
}

/* ---------- 挂断 ---------- */
function hangupCall() {
  var c = state.call;
  if (!c.active) return;
  c._hangupped = true;
  if (c.timeoutId) { clearTimeout(c.timeoutId); c.timeoutId = null; }
  if (state.socket && state.socket.connected && c.peerId) {
    state.socket.emit('call-end', { to: c.peerId });
  }
  var _res = c.connectedAt ? 'ended' : 'canceled';
  callFinish(t('callEnded'), true, _res);
}

/* 通话结束入口（v0.33.0 重构）
   result = 'ended' | 'canceled' | 'rejected' | 'missed' | 'busy' */
function callFinish(statusText, silent, result) {
  var c = state.call;
  if (!c.active) { try { callResetUI(); } catch (e) {} return; }

  /* 定格结束信息，供写历史使用 */
  c.lastPeerId = c.peerId || '';
  c.lastKind = c.type || 'voice';
  c.lastResult = result || 'ended';
  var _duration = c.connectedAt
    ? Math.round((Date.now() - c.connectedAt) / 1000)
    : 0;
  var _isOutgoing = (c.direction === 'outgoing');

  /* ---- 资源清理 ---- */
  try { if (c.timeoutId) { clearTimeout(c.timeoutId); c.timeoutId = null; } } catch (e) {}
  try { stopCallTimer(); } catch (e) {}
  try { stopCallTone(); } catch (e) {}
  try { teardownVolumeDetection(); } catch (e) {}
  try { teardownQualityMonitor(); } catch (e) {}
  try { if (dom.callMuteBadge) dom.callMuteBadge.classList.remove('show'); } catch (e) {}
  if (!silent) { try { playCallTone('end'); } catch (e) {} }

  /* 解绑事件后 close，避免 close 触发 onconnectionstatechange 递归 */
  try {
    if (c.pc) {
      try { c.pc.onicecandidate = null; } catch (e) {}
      try { c.pc.ontrack = null; } catch (e) {}
      try { c.pc.onconnectionstatechange = null; } catch (e) {}
      try { c.pc.oniceconnectionstatechange = null; } catch (e) {}
      try { c.pc.onnegotiationneeded = null; } catch (e) {}
      c.pc.close();
    }
  } catch (e) {}
  c.pc = null;

  /* 停止本地轨道 */
  try {
    if (c.localStream) {
      c.localStream.getTracks().forEach(function (tk) {
        try { tk.stop(); } catch (e) {}
      });
    }
  } catch (e) {}
  c.localStream = null;
  c.remoteStream = null;
  c.pendingCandidates = [];
  try { dom.callRemoteVideo.srcObject = null; } catch (e) {}
  try { dom.callLocalVideo.srcObject = null; } catch (e) {}

  /* 显示"通话结束"提示 */
  if (statusText) {
    try {
      var endBadge = document.createElement('div');
      endBadge.className = 'call-ended-badge';
      endBadge.textContent = statusText;
      dom.callModal.appendChild(endBadge);
      setTimeout(function () {
        if (endBadge.parentNode) endBadge.parentNode.removeChild(endBadge);
        try { callResetUI(); } catch (e) {}
      }, 800);
    } catch (e) { try { callResetUI(); } catch (e2) {} }
  } else {
    try { callResetUI(); } catch (e) {}
  }

  /* 写通话记录（仅主叫方） */
  try {
    if (_isOutgoing && c.lastPeerId) {
      saveCallRecord(c.lastKind, _duration, c.lastResult);
    }
  } catch (e) {
    console.warn('通话记录写入失败:', e.message);
  }

  /* 重置状态 */
  c.active = false;
  c.type = null;
  c.peerId = null;
  c.peerName = '';
  c.peerAvatar = '';
  c.peerVerified = '';
  c.direction = null;
  c.status = null;
  c.isMuted = false;
  c.videoEnabled = true;
  c.peerMuted = false;
  c.peerVideoEnabled = true;
  c.peerSpeaking = false;
  c.localSpeaking = false;
  c.lastQualityClass = '';
  c.lastIceRestartAt = 0;
  c.connectedAt = 0;
  c.startTime = 0;
  c._isCaller = false;
  c._makingOffer = false;
  c._ignoreOffer = false;
  c._hangupped = false;
  c._mediaStreamStopped = false;
  c._permDenied = false;
  c._pendingOffer = null;
  c._lastMuteAt = 0;
  c._silentSince = 0;
  c._callQualityText = '';
}

/* ============================================================
   ensurePeerConnection（v0.33.1 重构）
   ------------------------------------------------------------
   ★ 关键变化：本函数不再主动发起 offer，只负责：
       1. 幂等创建 RTCPeerConnection（已存在则复用）
       2. 添加本地 tracks
       3. 绑定 ICE / track / connectionState 事件
       4. 冲刷缓存的 ICE candidates
       5. 处理缓存的 pending offer（被叫在 acceptCall 期间收到的）
   发起 offer 统一走 makeCallOffer()，由调用方显式控制时序。
   ============================================================ */
function ensurePeerConnection() {
  var c = state.call;
  if (!c.active) return null;

  /* ---- 已存在：处理可能的 pendingOffer，然后直接返回 ---- */
  if (c.pc) {
    if (c._pendingOffer && c.peerId) {
      var _sdp0 = c._pendingOffer;
      c._pendingOffer = null;
      console.log('[Call] ensurePeerConnection：处理已缓存的 pendingOffer');
      try {
        handleCallSignal({
          from: c.peerId,
          signal: { type: 'offer', sdp: _sdp0 }
        });
      } catch (e) {
        console.warn('[Call] 处理 pendingOffer 失败:', e);
      }
    }
    return c.pc;
  }

  /* ---- 前置条件检查 ---- */
  if (!c.localStream) {
    console.warn('[Call] ensurePeerConnection：localStream 未就绪，等待');
    return null;
  }
  if (!window.RTCPeerConnection) {
    showToast(t('callUnsupported') || '当前浏览器不支持 WebRTC');
    return null;
  }

  /* ---- 创建 PC ---- */
  var pc;
  try {
    pc = new RTCPeerConnection({
      iceServers: CALL_ICE_SERVERS,
      iceTransportPolicy: 'all',
      bundlePolicy: 'max-bundle',
      rtcpMuxPolicy: 'require',
      iceCandidatePoolSize: 2
    });
  } catch (e) {
    console.error('[Call] 创建 PC 失败:', e);
    callFinish(t('callFailed'), true, 'rejected');
    return null;
  }
  c.pc = pc;
  c._makingOffer = false;
  c._ignoreOffer = false;

  /* ---- 添加本地 tracks ---- */
  try {
    c.localStream.getTracks().forEach(function (track) {
      try { pc.addTrack(track, c.localStream); } catch (e) {
        console.warn('[Call] addTrack failed:', track.kind, e);
      }
    });
  } catch (e) {}

  /* ---- 绑定事件 ---- */
  pc.onicecandidate = function (e) {
    if (!c.active || state.call !== c) return;
    if (e.candidate) {
      if (state.socket && state.socket.connected && c.peerId) {
        state.socket.emit('call-signal', {
          to: c.peerId,
          signal: { type: 'ice', candidate: e.candidate }
        });
      }
    }
  };

  pc.ontrack = function (e) {
    try {
      var _stream = (e.streams && e.streams[0]) ? e.streams[0] : null;
      if (!_stream) {
        if (!c.remoteStream) c.remoteStream = new MediaStream();
        try { c.remoteStream.addTrack(e.track); } catch (err) {}
        _stream = c.remoteStream;
      } else {
        c.remoteStream = _stream;
      }
      try { dom.callRemoteVideo.srcObject = _stream; } catch (err) {}
      if (!c.remoteAnalyser) setupVolumeDetection(_stream, false);

      if (c.type === 'video' &&
          _stream.getVideoTracks().length > 0 &&
          c.peerVideoEnabled) {
        dom.callModal.classList.add('mode-video');
        dom.callVideoName.textContent = c.peerName;
        dom.callVideoToggleBtn.style.display = 'flex';
        dom.callSwitchCameraBtn.style.display = 'flex';
      }
    } catch (err) {
      console.error('[Call] ontrack 处理失败:', err);
    }
  };

  pc.onconnectionstatechange = function () {
    var st = pc.connectionState;
    console.log('[Call] connectionState:', st);

    if (st === 'connected') {
      if (c.status !== 'active') {
        c.status = 'active';
        try {
          dom.callStatus.classList.add('timer');
          startCallTimer();
          dom.callMuteBtn.style.display = 'flex';
          if (c.type === 'video') {
            dom.callVideoToggleBtn.style.display = 'flex';
            dom.callSwitchCameraBtn.style.display = 'flex';
          }
          updateCallControlLabels();
        } catch (e) {}
        setupQualityMonitor();
        syncCallMediaState();
      }
    } else if (st === 'failed') {
      if (c.active) {
        tryRestartIce('connection-failed');
        setTimeout(function () {
          if (state.call.active && state.call.pc &&
              state.call.pc.connectionState === 'failed') {
            callFinish(t('callEnded'), true, 'ended');
          }
        }, 8000);
      }
    } else if (st === 'closed') {
      if (c.active) callFinish(t('callEnded'), true, 'ended');
    } else if (st === 'disconnected') {
      tryRestartIce('connection-disconnected');
      setTimeout(function () {
        if (state.call.active && state.call.pc &&
            state.call.pc.connectionState === 'disconnected') {
          callFinish(t('callEnded'), true, 'ended');
        }
      }, 5000);
    }
  };

  pc.oniceconnectionstatechange = function () {
    console.log('[Call] iceConnectionState:', pc.iceConnectionState);
  };

  pc.onnegotiationneeded = function () {
    console.log('[Call] negotiationneeded');
    /* 由 makeCallOffer 显式发起，此处不做自动 offer 避免 glare */
  };

  /* ---- 冲刷已缓存的 ICE ---- */
  flushPendingCandidates();

  /* ---- 处理缓存的 pending offer（被叫在 acceptCall getUserMedia 期间收到的） ---- */
  if (c._pendingOffer && c.peerId) {
    var _sdp = c._pendingOffer;
    c._pendingOffer = null;
    console.log('[Call] ensurePeerConnection：处理缓存的 pendingOffer');
    try {
      handleCallSignal({
        from: c.peerId,
        signal: { type: 'offer', sdp: _sdp }
      });
    } catch (e) {
      console.warn('[Call] 处理 pendingOffer 失败:', e);
    }
  }

  return pc;
}

/* 发起一次 offer（首次协商 / 重新协商 / ICE 重启共用） */
function makeCallOffer(isIceRestart) {
  var c = state.call;
  var pc = c.pc;
  if (!c.active || !pc) {
    console.warn('[Call] makeCallOffer 跳过：active=' + c.active + ' pc=' + !!pc);
    return;
  }
  if (c._makingOffer) {
    console.warn('[Call] makeCallOffer 跳过：正在 createOffer（glare 防重入）');
    return;
  }
  c._makingOffer = true;
  console.log('[Call] makeCallOffer 发起（isIceRestart=' + !!isIceRestart + '）');

  var opts = {
    offerToReceiveAudio: true,
    offerToReceiveVideo: (c.type === 'video' || c.videoEnabled)
  };
  if (isIceRestart) opts.iceRestart = true;

  pc.createOffer(opts).then(function (offer) {
    if (!c.active || state.call !== c) throw new Error('call-ended');
    return pc.setLocalDescription(offer);
  }).then(function () {
    if (!c.active || state.call !== c) return;
    if (state.socket && state.socket.connected && c.peerId) {
      state.socket.emit('call-signal', {
        to: c.peerId,
        signal: { type: 'offer', sdp: pc.localDescription }
      });
    }
    c._makingOffer = false;
  }).catch(function (err) {
    console.error('[Call] createOffer failed:', err);
    c._makingOffer = false;
    if (c.active && state.call === c && !c._hangupped) {
      callFinish(t('callFailed'), true, 'rejected');
    }
  });
}

/* 统一信令处理（glare 保护 + rollback） */
function handleCallSignal(data) {
  var c = state.call;
  if (!c.active || state.call !== c) return;
  if (!data || !data.signal || !data.from) return;

  /* ★ 关键：只接受当前对端的信令，丢弃旧通话的迟到信令 */
  if (c.peerId && data.from !== c.peerId) {
    console.warn('[Call] 丢弃非当前对端的信令：from=' + data.from +
      ' 期望=' + c.peerId + ' type=' + data.signal.type);
    return;
  }

  var sig = data.signal;
  var fromId = data.from;

  /* ---- ICE candidate：可以早于 PC 到达，先缓存 ---- */
  if (sig.type === 'ice') {
    if (!c.pc) {
      c.pendingCandidates.push(sig.candidate);
      return;
    }
    try {
      c.pc.addIceCandidate(new RTCIceCandidate(sig.candidate))
        .catch(function (err) {
          if (err && err.name !== 'InvalidStateError') {
            console.warn('[Call] addIceCandidate failed:', err);
          }
        });
    } catch (e) {}
    return;
  }

  /* ---- offer ---- */
  if (sig.type === 'offer') {
    var pc = c.pc;
    if (!pc) {
      /* ★ v0.33.1：被叫方在 acceptCall 的 getUserMedia 期间收到的 offer
         → 缓存到 c._pendingOffer，等 ensurePeerConnection 完成后自动处理 */
      console.warn('[Call] 收到 offer 但 PC 未创建，缓存等待');
      c._pendingOffer = sig.sdp;
      return;
    }
    /* glare 保护：本端正在 createOffer 时忽略对方 offer */
    if (c._makingOffer) {
      c._ignoreOffer = true;
      console.warn('[Call] glare：本地正在 createOffer，忽略对方 offer');
      return;
    }

    var _setRemote = function () {
      return pc.setRemoteDescription(new RTCSessionDescription(sig.sdp));
    };
    var _before = Promise.resolve();
    if (pc.signalingState === 'have-local-offer') {
      /* 本地有未完成的 offer → rollback 后再 setRemote */
      _before = pc.setLocalDescription({ type: 'rollback' }).catch(function () {});
    }
    _before.then(_setRemote)
      .then(function () {
        flushPendingCandidates();
        return pc.createAnswer();
      })
      .then(function (answer) {
        return pc.setLocalDescription(answer);
      })
      .then(function () {
        if (state.socket && state.socket.connected && c.active) {
          state.socket.emit('call-signal', {
            to: fromId,
            signal: { type: 'answer', sdp: pc.localDescription }
          });
        }
      })
      .catch(function (err) {
        console.error('[Call] handleOffer failed:', err);
        if (c.active) callFinish(t('callFailed'), true, 'rejected');
      });
    return;
  }

  /* ---- answer ---- */
  if (sig.type === 'answer') {
    if (!c.pc) return;
    c.pc.setRemoteDescription(new RTCSessionDescription(sig.sdp))
      .then(function () {
        flushPendingCandidates();
      })
      .catch(function (err) {
        console.error('[Call] handleAnswer failed:', err);
      });
    return;
  }
}

function flushPendingCandidates() {
  var c = state.call;
  if (!c.pc) return;
  var list = c.pendingCandidates.slice();
  c.pendingCandidates = [];
  for (var i = 0; i < list.length; i++) {
    try {
      c.pc.addIceCandidate(new RTCIceCandidate(list[i]))
        .catch(function () {});
    } catch (e) {}
  }
}

/* ICE 重启（节流：30 秒内最多一次） */
function tryRestartIce(reason) {
  var c = state.call;
  if (!c.active || !c.pc) return;
  if (c.status !== 'active') return;
  var now = Date.now();
  if (now - (c.lastIceRestartAt || 0) < CALL_ICE_RESTART_MIN_MS) return;
  c.lastIceRestartAt = now;
  console.log('[Call] ICE restart:', reason);
  makeCallOffer(true);
}

/* 把本地媒体状态同步给对方 */
function syncCallMediaState() {
  var c = state.call;
  if (!c.active || !c.peerId) return;
  if (!state.socket || !state.socket.connected) return;
  state.socket.emit('call-media-state', {
    to: c.peerId,
    muted: !!c.isMuted,
    videoEnabled: !!c.videoEnabled,
    speaking: !!c.localSpeaking
  });
}

function toggleCallMute() {
  var c = state.call;
  if (!c.localStream) return;
  c.isMuted = !c.isMuted;
  c.localStream.getAudioTracks().forEach(function (tk) {
    try { tk.enabled = !c.isMuted; } catch (e) {}
  });
  try {
    dom.callMuteBtn.classList.toggle('muted', c.isMuted);
    dom.callMuteIcon.textContent = c.isMuted ? '🔇' : '🎙️';
    dom.callMuteLabel.textContent = c.isMuted ? t('callUnmute') : t('callMute');
  } catch (e) {}
  syncCallMediaState();
}

/* 视频开关（支持语音→视频升级 / 视频→语音降级） */
function toggleCallVideo() {
  var c = state.call;
  if (!c.localStream) return;
  if (!c.pc) return;

  var _wantEnable = !c.videoEnabled;
  var videoTracks = c.localStream.getVideoTracks();

  function _updateUI() {
    try {
      dom.callVideoToggleBtn.classList.toggle('video-off', !c.videoEnabled);
      dom.callVideoToggleIcon.textContent = c.videoEnabled ? '📹' : '🚫';
      dom.callVideoToggleLabel.textContent = c.videoEnabled
        ? t('callVideoOff') : t('callVideoOn');
      dom.callLocalVideo.classList.toggle('hidden', !c.videoEnabled);
    } catch (e) {}
    syncCallMediaState();
  }

  if (videoTracks.length > 0) {
    /* 已有视频轨：仅切 enabled，无需重协商 */
    c.videoEnabled = _wantEnable;
    videoTracks.forEach(function (tk) {
      try { tk.enabled = c.videoEnabled; } catch (e) {}
    });
    _updateUI();
    return;
  }

  if (!_wantEnable) {
    /* 已是无视频状态 → 直接切 UI */
    c.videoEnabled = false;
    _updateUI();
    return;
  }

  /* 语音 → 视频：获取视频轨 → replaceTrack / addTrack → 重协商 */
  navigator.mediaDevices.getUserMedia({
    video: { facingMode: c.facingMode || 'user' },
    audio: false
  }).then(function (newStream) {
    if (!state.call.active || state.call !== c) {
      try { newStream.getTracks().forEach(function (tk) { tk.stop(); }); } catch (e) {}
      return;
    }
    var newTrack = newStream.getVideoTracks()[0];
    if (!newTrack) { showToast(t('callCameraDenied')); return; }

    try { c.localStream.addTrack(newTrack); } catch (e) {}
    c.videoEnabled = true;

    var sender = c.pc.getSenders().filter(function (s) {
      return s.track && s.track.kind === 'video';
    })[0];
    if (sender) {
      sender.replaceTrack(newTrack).then(function () {
        makeCallOffer(false);
      }).catch(function (err) {
        console.warn('[Call] replaceTrack failed:', err);
      });
    } else {
      try { c.pc.addTrack(newTrack, c.localStream); } catch (e) {}
      makeCallOffer(false);
    }
    try { dom.callLocalVideo.srcObject = c.localStream; } catch (e) {}
    _updateUI();
  }).catch(function (err) {
    console.warn('[Call] add video track failed:', err);
    c.videoEnabled = false;
    _updateUI();
    showToast(t('callCameraDenied'));
  });
}

/* 切换前后摄像头（replaceTrack，无需重协商） */
function switchCallCamera() {
  var c = state.call;
  if (c.type !== 'video' || !c.localStream) return;
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) return;

  var _prev = c.facingMode;
  c.facingMode = (_prev === 'user') ? 'environment' : 'user';

  navigator.mediaDevices.getUserMedia({
    video: { facingMode: c.facingMode },
    audio: false
  }).then(function (newStream) {
    if (!state.call.active || state.call !== c) {
      try { newStream.getTracks().forEach(function (tk) { tk.stop(); }); } catch (e) {}
      return;
    }
    var newTrack = newStream.getVideoTracks()[0];
    if (!newTrack) { c.facingMode = _prev; return; }

    /* 停旧轨 */
    c.localStream.getVideoTracks().forEach(function (tk) {
      try { c.localStream.removeTrack(tk); } catch (e) {}
      try { tk.stop(); } catch (e) {}
    });
    try { c.localStream.addTrack(newTrack); } catch (e) {}

    var sender = c.pc && c.pc.getSenders &&
      c.pc.getSenders().filter(function (s) {
        return s.track && s.track.kind === 'video';
      })[0];
    if (sender) {
      sender.replaceTrack(newTrack).catch(function (err) {
        console.warn('[Call] switchCamera replaceTrack failed:', err);
      });
    } else if (c.pc) {
      try { c.pc.addTrack(newTrack, c.localStream); } catch (e) {}
      makeCallOffer(false);
    }
    try {
      dom.callLocalVideo.srcObject = c.localStream;
      dom.callLocalVideo.classList.toggle('mirror', c.facingMode === 'user');
    } catch (e) {}
  }).catch(function (err) {
    console.warn('[Call] switch camera failed:', err);
    c.facingMode = _prev;
    showToast(t('callCameraDenied'));
  });
}

function updateCallControlLabels() {
  try {
    dom.callMuteIcon.textContent = state.call.isMuted ? '🔇' : '🎙️';
    dom.callMuteLabel.textContent = state.call.isMuted ? t('callUnmute') : t('callMute');
    dom.callVideoToggleIcon.textContent = state.call.videoEnabled ? '📹' : '🚫';
    dom.callVideoToggleLabel.textContent = state.call.videoEnabled
      ? t('callVideoOff') : t('callVideoOn');
    dom.callSwitchLabel.textContent = t('callSwitchCamera');
    dom.callHangupLabel.textContent = t('callHangup');
    dom.callRejectLabel.textContent = t('callReject');
    dom.callAcceptLabel.textContent = t('callAccept');
  } catch (e) {}
}

/* 音量检测：AnalyserNode 每 100ms 采样 RMS，阈值触发音量环 */
function setupVolumeDetection(stream, isLocal) {
  if (!stream) return;
  var c = state.call;
  var AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) return;
  try {
    var ctx = new AC();
    var src = ctx.createMediaStreamSource(stream);
    var analyser = ctx.createAnalyser();
    analyser.fftSize = 512;
    analyser.smoothingTimeConstant = 0.5;
    src.connect(analyser);

    var buf = new Uint8Array(analyser.frequencyBinCount);
    var lastActiveTs = 0;
    var speakingNow = false;

    if (isLocal) {
      c.localAudioCtx = ctx;
      c.localAnalyser = analyser;
      if (c.localVolTimer) { clearInterval(c.localVolTimer); c.localVolTimer = null; }
      c.localVolTimer = setInterval(function () {
        if (!c.active || state.call !== c) {
          if (c.localVolTimer) { clearInterval(c.localVolTimer); c.localVolTimer = null; }
          return;
        }
        try { analyser.getByteFrequencyData(buf); } catch (e) { return; }
        var sum = 0;
        for (var i = 0; i < buf.length; i++) sum += buf[i];
        var avg = sum / buf.length;
        var active = avg > 20;
        if (active) lastActiveTs = Date.now();
        var speaking = (Date.now() - lastActiveTs) < 260;
        if (speaking !== speakingNow) {
          speakingNow = speaking;
          c.localSpeaking = speaking;
          var ring = dom.callVolumeRing;
          if (ring) {
            ring.classList.add('self');
            ring.classList.toggle('active', speaking);
          }
          if (c.active && c.peerId) syncCallMediaState();
        }
      }, 100);
    } else {
      c.remoteAudioCtx = ctx;
      c.remoteAnalyser = analyser;
      if (c.remoteVolTimer) { clearInterval(c.remoteVolTimer); c.remoteVolTimer = null; }
      c.remoteVolTimer = setInterval(function () {
        if (!c.active || state.call !== c) {
          if (c.remoteVolTimer) { clearInterval(c.remoteVolTimer); c.remoteVolTimer = null; }
          return;
        }
        try { analyser.getByteFrequencyData(buf); } catch (e) { return; }
        var sum = 0;
        for (var i = 0; i < buf.length; i++) sum += buf[i];
        var avg = sum / buf.length;
        var active = avg > 20;
        if (active) lastActiveTs = Date.now();
        var speaking = (Date.now() - lastActiveTs) < 260;
        if (speaking !== speakingNow) {
          speakingNow = speaking;
          c.peerSpeaking = speaking;
          var ring2 = dom.callVolumeRing;
          if (ring2) {
            if (speaking) ring2.classList.remove('self');
            ring2.classList.toggle('active', speaking);
          }
        }
      }, 100);
    }
  } catch (e) {
    console.warn('音量检测初始化失败:', e.message);
  }
}

function teardownVolumeDetection() {
  var c = state.call;
  if (c.localVolTimer) { clearInterval(c.localVolTimer); c.localVolTimer = null; }
  if (c.remoteVolTimer) { clearInterval(c.remoteVolTimer); c.remoteVolTimer = null; }
  try {
    if (c.localAudioCtx) {
      var p1 = c.localAudioCtx.close();
      if (p1 && p1.catch) p1.catch(function () {});
    }
  } catch (e) {}
  try {
    if (c.remoteAudioCtx) {
      var p2 = c.remoteAudioCtx.close();
      if (p2 && p2.catch) p2.catch(function () {});
    }
  } catch (e) {}
  c.localAudioCtx = null;
  c.localAnalyser = null;
  c.remoteAudioCtx = null;
  c.remoteAnalyser = null;
  try {
    if (dom.callVolumeRing) dom.callVolumeRing.classList.remove('active', 'self');
  } catch (e) {}
}

function setupQualityMonitor() {
  var c = state.call;
  if (c.qualityTimer) { clearInterval(c.qualityTimer); c.qualityTimer = null; }
  c.qualityTimer = setInterval(function () {
    if (!c.active || state.call !== c || !c.pc) {
      if (c.qualityTimer) { clearInterval(c.qualityTimer); c.qualityTimer = null; }
      return;
    }
    if (typeof c.pc.getStats !== 'function') return;
    c.pc.getStats(null).then(function (report) {
      var rtt = null;
      var packetsLost = 0;
      var packetsRecv = 0;
      report.forEach(function (s) {
        if (s.type === 'candidate-pair' && s.state === 'succeeded' &&
            typeof s.currentRoundTripTime === 'number') {
          rtt = s.currentRoundTripTime * 1000;
        }
        if (s.type === 'inbound-rtp') {
          if (typeof s.packetsLost === 'number') packetsLost += s.packetsLost;
          if (typeof s.packetsReceived === 'number') packetsRecv += s.packetsReceived;
        }
      });
      var lossRate = 0;
      if (packetsRecv + packetsLost > 0) {
        lossRate = packetsLost / (packetsRecv + packetsLost);
      }
      var cls = 'good', txt = '—';
      if (rtt == null) { cls = 'fair'; txt = '—'; }
      else if (rtt < 80 && lossRate < 0.01) { cls = 'good'; txt = Math.round(rtt) + 'ms'; }
      else if (rtt < 200 && lossRate < 0.03) { cls = 'fair'; txt = Math.round(rtt) + 'ms'; }
      else if (rtt < 400 && lossRate < 0.08) { cls = 'poor'; txt = Math.round(rtt) + 'ms'; }
      else { cls = 'bad'; txt = Math.round(rtt) + 'ms'; }

      var el = dom.callQuality;
      if (el) {
        el.classList.add('show');
        el.classList.remove('good', 'fair', 'poor', 'bad');
        el.classList.add(cls);
        var txtEl = $id('callQualityText');
        if (txtEl && c._callQualityText !== txt) {
          txtEl.textContent = txt;
          c._callQualityText = txt;
        }
      }
      c.lastQualityClass = cls;

      if (cls === 'bad' && c.pc && c.status === 'active') {
        tryRestartIce('quality-degraded');
      }
    }).catch(function () {});
  }, CALL_QUALITY_INTERVAL);
}

function teardownQualityMonitor() {
  var c = state.call;
  if (c.qualityTimer) { clearInterval(c.qualityTimer); c.qualityTimer = null; }
  try {
    if (dom.callQuality) {
      dom.callQuality.classList.remove('show', 'good', 'fair', 'poor', 'bad');
    }
  } catch (e) {}
  c._callQualityText = '';
}

/* ICE 重启：质量变差 / 网络恢复时触发，30 秒内最多一次 */
function tryRestartIce(reason) {
  var c = state.call;
  if (!c.active || !c.pc) return;
  if (c.status !== 'active') return;
  var now = Date.now();
  if (now - (c.lastIceRestartAt || 0) < 30000) return;
  c.lastIceRestartAt = now;
  console.log('[Call] ICE restart:', reason);
  /* 复用统一入口：makeCallOffer 会带上 iceRestart:true 选项 */
  makeCallOffer(true);
}

/* 网络恢复 → 尝试 ICE 重启 */
window.addEventListener('online', function () {
  if (state.call.active && state.call.status === 'active') {
    tryRestartIce('network-online');
  }
});

/* ---------- 按钮绑定 ---------- */
(function initCallUI() {
  if (dom.voiceCallBtn) {
    dom.voiceCallBtn.addEventListener('click', function () {
      try { startCall('voice'); } catch (e) { console.error('[Call] startCall 出错:', e); }
    });
  }
  if (dom.videoCallBtn) {
    dom.videoCallBtn.addEventListener('click', function () {
      try { startCall('video'); } catch (e) { console.error('[Call] startCall 出错:', e); }
    });
  }
  if (dom.callAcceptBtn) {
    dom.callAcceptBtn.addEventListener('click', function () {
      try { acceptCall(); } catch (e) { console.error('[Call] acceptCall 出错:', e); }
    });
  }
  if (dom.callRejectBtn) {
    dom.callRejectBtn.addEventListener('click', function () {
      try { rejectCall('rejected'); } catch (e) { console.error('[Call] rejectCall 出错:', e); }
    });
  }
  if (dom.callHangupBtn) {
    dom.callHangupBtn.addEventListener('click', function () {
      try { hangupCall(); } catch (e) { console.error('[Call] hangupCall 出错:', e); }
    });
  }
  if (dom.callMuteBtn) dom.callMuteBtn.addEventListener('click', toggleCallMute);
  if (dom.callVideoToggleBtn) dom.callVideoToggleBtn.addEventListener('click', toggleCallVideo);
  if (dom.callSwitchCameraBtn) dom.callSwitchCameraBtn.addEventListener('click', switchCallCamera);

  if (dom.callLocalVideo) {
    dom.callLocalVideo.addEventListener('click', function () {
      if (state.call.type === 'video' && state.call.status === 'active') {
        switchCallCamera();
      }
    });
  }

  /* ESC 挂断 */
  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape' || !state.call.active) return;
    if (state.call.status === 'ringing') {
      rejectCall('rejected');
    } else {
      hangupCall();
    }
  });

  /* 页面关闭前挂断 */
  window.addEventListener('beforeunload', function () {
    if (state.call.active && state.socket && state.socket.connected) {
      try { state.socket.emit('call-end', { to: state.call.peerId }); } catch (e) {}
    }
  });

  /* 页面切后台：视频通话时暂停摄像头轨，节省电量；
     恢复前台：重新启用。不触发重协商。 */
  document.addEventListener('visibilitychange', function () {
    var c = state.call;
    if (!c.active || c.type !== 'video' || !c.localStream) return;
    if (document.hidden) {
      c.localStream.getVideoTracks().forEach(function (tk) {
        try { tk.enabled = false; } catch (e) {}
      });
    } else {
      c.localStream.getVideoTracks().forEach(function (tk) {
        try { tk.enabled = c.videoEnabled; } catch (e) {}
      });
    }
  });
})();

/* ============================================================
   群通话（mesh 全连接，最多 6 人）
   ============================================================ */
function groupCallSupported() {
  return !!(window.RTCPeerConnection && navigator.mediaDevices &&
            navigator.mediaDevices.getUserMedia);
}

function gcSnapshotMembers() {
  var list = [];
  for (var pid in state.gcall.peers) {
    if (!state.gcall.peers.hasOwnProperty(pid)) continue;
    var p = state.gcall.peers[pid];
    list.push({ id: pid, name: p.name, avatar: p.avatar, verified: p.verified, isSelf: false });
  }
  list.unshift({
    id: state.myId,
    name: state.myName,
    avatar: (state.myProfile && state.myProfile.avatar) || '',
    verified: state.myVerified || '',
    isSelf: true
  });
  return list;
}

function gcRenderGrid() {
  var grid = dom.gcGrid;
  if (!grid) return;
  var members = gcSnapshotMembers();
  var n = members.length;
  grid.className = 'gc-grid count-' + Math.min(Math.max(n, 1), 6);
  /* 差异更新：保留已有 cell */
  var existing = {};
  var cells = grid.querySelectorAll('.gc-cell');
  for (var i = 0; i < cells.length; i++) {
    existing[cells[i].dataset.peerid] = cells[i];
  }
  /* 按 members 顺序重建 */
  for (var j = 0; j < members.length; j++) {
    var m = members[j];
    var cell = existing[m.id];
    if (!cell) {
      cell = document.createElement('div');
      cell.className = 'gc-cell';
      cell.dataset.peerid = m.id;
      cell.innerHTML =
        '<div class="gc-avatar"></div>' +
        '<video autoplay playsinline></video>' +
        '<div class="gc-info">' +
          '<span class="gc-name"></span>' +
          '<span class="gc-badges"></span>' +
        '</div>';
      var avEl = cell.querySelector('.gc-avatar');
      if (m.avatar) avEl.innerHTML = '<img src="' + m.avatar + '" alt="">';
      else avEl.textContent = (m.name || '?').charAt(0).toUpperCase();
      avEl.classList.toggle('verified', !!m.verified);
      cell.querySelector('.gc-name').textContent = m.name + (m.isSelf ? ' (我)' : '');
    }
    /* 更新徽章 */
    var badges = [];
    if (m.isSelf) {
      if (state.gcall.isMuted) badges.push('<span class="muted">🔇</span>');
      if (state.gcall.isHost) badges.push('<span class="host">👑</span>');
    } else {
      var p = state.gcall.peers[m.id];
      if (p && p.muted) badges.push('<span class="muted">🔇</span>');
    }
    cell.querySelector('.gc-badges').innerHTML = badges.join('');
    /* 视频开关 */
    if (m.isSelf) {
      cell.classList.toggle('has-video', state.gcall.videoEnabled);
      if (state.gcall.videoEnabled && state.gcall.localStream) {
        var lv = cell.querySelector('video');
        if (lv && lv.srcObject !== state.gcall.localStream) lv.srcObject = state.gcall.localStream;
        lv.muted = true;
      }
    } else {
      var p2 = state.gcall.peers[m.id];
      var hasVideo = !!(p2 && p2.stream && p2.stream.getVideoTracks().length > 0 &&
                        p2.stream.getVideoTracks()[0].enabled !== false);
      cell.classList.toggle('has-video', hasVideo);
      if (hasVideo && p2 && p2.stream) {
        var rv = cell.querySelector('video');
        if (rv && rv.srcObject !== p2.stream) rv.srcObject = p2.stream;
      }
    }
    /* 重新挂载到 grid 尾部以保持顺序 */
    grid.appendChild(cell);
  }
  /* 删除多余 cell */
  for (var pid in existing) {
    if (!existing.hasOwnProperty(pid)) continue;
    var found = false;
    for (var k = 0; k < members.length; k++) {
      if (members[k].id === pid) { found = true; break; }
    }
    if (!found) {
      try { existing[pid].parentNode.removeChild(existing[pid]); } catch (e) {}
      var pp = state.gcall.peers[pid];
      if (pp) { try { if (pp.pc) pp.pc.close(); } catch (e) {} }
    }
  }
}

function gcStartTimer() {
  var g = state.gcall;
  if (g.timerId) clearInterval(g.timerId);
  g.startedAt = Date.now();
  var render = function () {
    var sec = Math.floor((Date.now() - g.startedAt) / 1000);
    var mm = Math.floor(sec / 60), ss = sec % 60;
    dom.gcStatus.textContent = pad2(mm) + ':' + pad2(ss) +
      ' · ' + t('gcUserCount').split('{n}').join(gcSnapshotMembers().length);
  };
  render();
  g.timerId = setInterval(render, 1000);
}

function gcStopTimer() {
  if (state.gcall.timerId) {
    clearInterval(state.gcall.timerId);
    state.gcall.timerId = null;
  }
}

function gcResetUI() {
  dom.groupCallModal.classList.remove('open');
  dom.groupCallModal.style.display = 'none';
  dom.gcGrid.innerHTML = '';
  dom.gcStatus.textContent = '';
  dom.gcMuteBtn.classList.remove('muted');
  dom.gcMuteIcon.textContent = '🎙️';
  dom.gcMuteLabel.textContent = t('callMute');
  dom.gcVideoToggleIcon.textContent = '📹';
  dom.gcVideoToggleLabel.textContent = t('callVideoOn');
  dom.gcEndBtn.style.display = 'none';
  dom.gcVideoToggleBtn.style.display = 'none';
}

/* 发起群通话：立即显示"连接中"，8 秒内无 group-call-started 回执则兜底退出 */
function gcStart(callType) {
  callType = (callType === 'video') ? 'video' : 'voice';

  if (!groupCallSupported()) {
    showToast(t('callUnsupported'));
    return;
  }
  if (state.currentType !== 'group' || !state.currentTarget) {
    showToast(t('gcOnlyGroup'));
    return;
  }

  var g = state.gcall;
  /* 已在群通话中 → 直接把界面唤到前台，不重复发起 */
  if (g.active) {
    dom.groupCallModal.style.display = 'flex';
    dom.groupCallModal.classList.add('open');
    return;
  }
  if (state.call.active) {
    showToast(t('callSelfBusy'));
    return;
  }
  if (!state.socket || state.socket.connected === false) {
    showConnectionStatus('error', t('connServerLost'));
    return;
  }

  var groupId = state.currentTarget;
  var group = state.groups[groupId];
  var groupName = group ? (group.name || '') : '';

  /* ---- 立即展示"正在连接"界面（用户体验优化） ---- */
  g.active = true;
  g.groupId = groupId;
  g.groupName = groupName;
  g.type = callType;
  g.isHost = true;
  g.isMuted = false;
  g.videoEnabled = false;
  g.peers = {};
  g.localStream = null;
  g.startedAt = 0;

  gcResetUI();
  dom.groupCallModal.style.display = 'flex';
  dom.groupCallModal.classList.add('open');
  dom.gcTitle.textContent = t('gcTitle') + ' · ' + groupName;
  dom.gcStatus.textContent = t('gcConnecting');
  dom.gcVideoToggleBtn.style.display = (callType === 'video') ? 'flex' : 'none';
  dom.gcEndBtn.style.display = 'flex';
  dom.gcEndLabel.textContent = t('gcEnd');
  dom.gcLeaveLabel.textContent = t('gcLeave');
  dom.gcMuteLabel.textContent = t('callMute');

  /* ---- 向服务端发起请求 ---- */
  state.socket.emit('group-call-start', {
    groupId: groupId,
    type: callType
  });

  /* ---- 8 秒兜底：未收到 group-call-started → 视为失败 ---- */
  g._startTimeout = setTimeout(function () {
    if (!g.active || g.startedAt) return;
    if (g.groupId !== groupId) return;
    showToast(t('callFailed'));
    gcLeave(true);
  }, 8000);
}

/* 主持人收到回执：清兜底计时器，复用或获取本地流，建立 P2P mesh */
function gcBecomeParticipant(snapshot, isHost) {
  var g = state.gcall;

  /* ---- 清掉"发起中"的兜底计时器 ---- */
  if (g._startTimeout) {
    clearTimeout(g._startTimeout);
    g._startTimeout = null;
  }

  g.active = true;
  g.groupId = snapshot.groupId;
  g.groupName = (state.groups[snapshot.groupId] &&
                 state.groups[snapshot.groupId].name) || '';
  g.type = snapshot.type || 'voice';
  g.isHost = !!isHost;
  g.startedAt = Date.now();

  /* 复用 gcStart() 里已初始化的字段（没有就补默认值） */
  if (typeof g.isMuted !== 'boolean') g.isMuted = false;
  if (typeof g.videoEnabled !== 'boolean') g.videoEnabled = false;
  if (!g.peers || typeof g.peers !== 'object') g.peers = {};

  dom.groupCallModal.style.display = 'flex';
  dom.groupCallModal.classList.add('open');
  dom.gcTitle.textContent = t('gcTitle') + ' · ' + g.groupName;
  dom.gcStatus.textContent = t('gcConnecting');
  dom.gcVideoToggleBtn.style.display = (g.type === 'video') ? 'flex' : 'none';
  dom.gcEndBtn.style.display = isHost ? 'flex' : 'none';
  dom.gcEndLabel.textContent = t('gcEnd');
  dom.gcLeaveLabel.textContent = t('gcLeave');
  dom.gcMuteLabel.textContent = t('callMute');

  /* ---- 建立 P2P 连接（在拿到本地流之后执行） ---- */
  function _buildMesh() {
    gcRenderGrid();
    if (snapshot.participants && snapshot.participants.length) {
      for (var i = 0; i < snapshot.participants.length; i++) {
        var m = snapshot.participants[i];
        if (m.id === state.myId) continue;
        gcCreatePeer(m.id, m.name, m.avatar, m.verified, true);
      }
    }
    gcStartTimer();
    if (gcSnapshotMembers().length <= 1) {
      dom.gcStatus.textContent = t('gcWaiting');
    }
  }

  /* ---- 已经有本地流（gcStart 预热）→ 跳过获取 ---- */
  if (g.localStream) {
    _buildMesh();
    return;
  }

  /* ---- 获取本地音频流 ---- */
  navigator.mediaDevices.getUserMedia({
    audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
    video: false
  }).then(function (stream) {
    if (!g.active) {
      try { stream.getTracks().forEach(function (tk) { tk.stop(); }); } catch (e) {}
      return;
    }
    g.localStream = stream;
    _buildMesh();
  }).catch(function () {
    showToast(t('callMicDenied'));
    gcLeave(true);
  });
}

/* ---- 加入现有通话（被叫） ---- */
function gcJoinIncoming() {
  if (!state.gcall.incoming) return;
  var inc = state.gcall.incoming;
  state.gcall.incoming = null;
  dom.gcIncomingBanner.style.display = 'none';
  state.socket.emit('group-call-join', { groupId: inc.groupId });
}

/* ---- 忽略来电 ---- */
function gcIgnoreIncoming() {
  state.gcall.incoming = null;
  dom.gcIncomingBanner.style.display = 'none';
}

/* ---- 收到服务端回执：已加入（含现有成员列表） ---- */
function gcHandleJoined(data) {
  var g = state.gcall;
  g.active = true;
  g.groupId = data.groupId;
  g.groupName = (state.groups[data.groupId] &&
                 state.groups[data.groupId].name) || '';
  g.type = data.type || 'voice';
  g.isHost = (data.hostId === state.myId);
  g.isMuted = false;
  g.videoEnabled = false;
  g.peers = {};
  g.localStream = null;

  dom.groupCallModal.style.display = 'flex';
  dom.groupCallModal.classList.add('open');
  dom.gcTitle.textContent = t('gcTitle') + ' · ' + g.groupName;
  dom.gcStatus.textContent = t('gcConnecting');
  dom.gcVideoToggleBtn.style.display = (g.type === 'video') ? 'flex' : 'none';
  dom.gcEndBtn.style.display = g.isHost ? 'flex' : 'none';
  dom.gcEndLabel.textContent = t('gcEnd');
  dom.gcLeaveLabel.textContent = t('gcLeave');
  dom.gcMuteLabel.textContent = t('callMute');

  navigator.mediaDevices.getUserMedia({
    audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
    video: false
  }).then(function (stream) {
    if (!g.active) {
      try { stream.getTracks().forEach(function (tk) { tk.stop(); }); } catch (e) {}
      return;
    }
    g.localStream = stream;
    /* 对每个现有成员建立 P2P（作为发起方） */
    var list = data.members || [];
    for (var i = 0; i < list.length; i++) {
      var m = list[i];
      if (m.id === state.myId) continue;
      gcCreatePeer(m.id, m.name, m.avatar, m.verified, true);
    }
    gcRenderGrid();
    gcStartTimer();
    if (gcSnapshotMembers().length <= 1) dom.gcStatus.textContent = t('gcWaiting');
  }).catch(function () {
    showToast(t('callMicDenied'));
    gcLeave(true);
  });
}

/* ---- 创建 / 获取与某成员的 P2P 连接 ---- */
function gcCreatePeer(peerId, name, avatar, verified, isInitiator) {
  var g = state.gcall;
  if (!g.active) return null;
  if (g.peers[peerId]) return g.peers[peerId];
  if (!g.localStream) return null;

  var pc = new RTCPeerConnection({ iceServers: CALL_ICE_SERVERS });
  var rec = {
    pc: pc, stream: null, name: name || peerId,
    avatar: avatar || '', verified: verified || '',
    audioEl: null, videoEl: null, muted: false
  };
  g.peers[peerId] = rec;

  /* 本地音轨全部推入 */
  g.localStream.getTracks().forEach(function (track) {
    try { pc.addTrack(track, g.localStream); } catch (e) {}
  });

  pc.onicecandidate = function (e) {
    if (e.candidate && state.socket && state.socket.connected) {
      state.socket.emit('group-call-signal', {
        groupId: g.groupId,
        to: peerId,
        signal: { type: 'ice', candidate: e.candidate }
      });
    }
  };

  pc.ontrack = function (e) {
    if (!e.streams || !e.streams[0]) return;
    rec.stream = e.streams[0];
    /* 如果只有音频，用隐藏 audio 播放 */
    if (!rec.audioEl) {
      var a = document.createElement('audio');
      a.autoplay = true;
      a.style.display = 'none';
      document.body.appendChild(a);
      rec.audioEl = a;
    }
    try { rec.audioEl.srcObject = e.streams[0]; } catch (er) {}
    gcRenderGrid();
  };

  pc.onconnectionstatechange = function () {
    if (pc.connectionState === 'failed' || pc.connectionState === 'closed') {
      gcRemovePeer(peerId);
    }
  };

  if (isInitiator) {
    pc.createOffer({ offerToReceiveAudio: true, offerToReceiveVideo: false })
      .then(function (offer) { return pc.setLocalDescription(offer); })
      .then(function () {
        state.socket.emit('group-call-signal', {
          groupId: g.groupId,
          to: peerId,
          signal: { type: 'offer', sdp: pc.localDescription }
        });
      })
      .catch(function () { gcRemovePeer(peerId); });
  }
  gcRenderGrid();
  return rec;
}

function gcRemovePeer(peerId) {
  var g = state.gcall;
  var rec = g.peers[peerId];
  if (!rec) return;
  try { if (rec.pc) rec.pc.close(); } catch (e) {}
  try { if (rec.audioEl && rec.audioEl.parentNode) rec.audioEl.parentNode.removeChild(rec.audioEl); } catch (e) {}
  delete g.peers[peerId];
  gcRenderGrid();
}

/* ---- 收到信令 ---- */
function gcHandleSignal(data) {
  var g = state.gcall;
  if (!g.active || !data || data.groupId !== g.groupId) return;
  var fromId = data.from;
  var sig = data.signal;
  if (!sig) return;

  if (sig.type === 'offer') {
    /* 新的对端主动连接我 */
    var rec = g.peers[fromId];
    if (!rec) rec = gcCreatePeer(fromId, data.fromName || fromId, '', '', false);
    if (!rec) return;
    rec.pc.setRemoteDescription(new RTCSessionDescription(sig.sdp))
      .then(function () { return rec.pc.createAnswer(); })
      .then(function (answer) { return rec.pc.setLocalDescription(answer); })
      .then(function () {
        state.socket.emit('group-call-signal', {
          groupId: g.groupId,
          to: fromId,
          signal: { type: 'answer', sdp: rec.pc.localDescription }
        });
      })
      .catch(function () { gcRemovePeer(fromId); });
  } else if (sig.type === 'answer') {
    var rec2 = g.peers[fromId];
    if (rec2 && rec2.pc) {
      rec2.pc.setRemoteDescription(new RTCSessionDescription(sig.sdp)).catch(function () {});
    }
  } else if (sig.type === 'ice') {
    var rec3 = g.peers[fromId];
    if (rec3 && rec3.pc) {
      try { rec3.pc.addIceCandidate(new RTCIceCandidate(sig.candidate)).catch(function () {}); } catch (e) {}
    }
  }
}

/* ---- 离开 ---- */
function gcLeave(silent) {
  var g = state.gcall;

  /* ★ 清理 gcStart() 里的兜底计时器，避免泄漏 */
  if (g._startTimeout) {
    clearTimeout(g._startTimeout);
    g._startTimeout = null;
  }

  if (!g.active) { gcResetUI(); return; }
  if (state.socket && state.socket.connected && g.groupId) {
    state.socket.emit('group-call-leave', { groupId: g.groupId });
  }
  gcStopTimer();
  /* 关闭所有 pc 与流 */
  for (var pid in g.peers) {
    if (!g.peers.hasOwnProperty(pid)) continue;
    var rec = g.peers[pid];
    try { if (rec.pc) rec.pc.close(); } catch (e) {}
    try { if (rec.audioEl && rec.audioEl.parentNode) rec.audioEl.parentNode.removeChild(rec.audioEl); } catch (e) {}
  }
  g.peers = {};
  if (g.localStream) {
    try { g.localStream.getTracks().forEach(function (tk) { tk.stop(); }); } catch (e) {}
    g.localStream = null;
  }
  g.active = false;
  g.groupId = null;
  g.groupName = '';
  g.isHost = false;
  g.isMuted = false;
  g.videoEnabled = false;
  gcResetUI();
  if (!silent) showToast(t('gcLeave'));
}

/* ---- 主持人结束整个通话 ---- */
function gcEndAll() {
  var g = state.gcall;
  if (!g.active) return;
  if (state.socket && state.socket.connected && g.groupId) {
    state.socket.emit('group-call-end', { groupId: g.groupId });
  }
  gcLeave(true);
  showToast(t('callEnded'));
}

function gcToggleMute() {
  var g = state.gcall;
  if (!g.localStream) return;
  g.isMuted = !g.isMuted;
  g.localStream.getAudioTracks().forEach(function (tk) { tk.enabled = !g.isMuted; });
  dom.gcMuteBtn.classList.toggle('muted', g.isMuted);
  dom.gcMuteIcon.textContent = g.isMuted ? '🔇' : '🎙️';
  dom.gcMuteLabel.textContent = g.isMuted ? t('callUnmute') : t('callMute');
  gcRenderGrid();
}

function gcToggleVideo() {
  var g = state.gcall;
  if (!g.localStream) return;
  if (!g.videoEnabled) {
    /* 开启视频：向本地流增加视频轨，并 replaceTrack 到所有 pc */
    navigator.mediaDevices.getUserMedia({
      video: { width: { ideal: 640 }, height: { ideal: 480 }, facingMode: 'user' }
    }).then(function (vs) {
      var vt = vs.getVideoTracks()[0];
      if (!vt) return;
      g.localStream.addTrack(vt);
      g.videoEnabled = true;
      for (var pid in g.peers) {
        if (!g.peers.hasOwnProperty(pid)) continue;
        var rec = g.peers[pid];
        try {
          var sender = rec.pc.getSenders().filter(function (s) { return s.track && s.track.kind === 'video'; })[0];
          if (sender) sender.replaceTrack(vt);
          else rec.pc.addTrack(vt, g.localStream);
          /* 由于轨道数变化，需要重新协商（由本端发起新 offer） */
          rec.pc.createOffer().then(function (o) { return rec.pc.setLocalDescription(o); })
            .then(function () {
              state.socket.emit('group-call-signal', {
                groupId: g.groupId,
                to: pid,
                signal: { type: 'offer', sdp: rec.pc.localDescription }
              });
            }).catch(function () {});
        } catch (e) {}
      }
      dom.gcVideoToggleIcon.textContent = '🚫';
      dom.gcVideoToggleLabel.textContent = t('callVideoOff');
      gcRenderGrid();
    }).catch(function () { showToast(t('callCameraDenied')); });
  } else {
    /* 关闭视频 */
    var tracks = g.localStream.getVideoTracks();
    tracks.forEach(function (tk) { tk.stop(); try { g.localStream.removeTrack(tk); } catch (e) {} });
    g.videoEnabled = false;
    for (var pid2 in g.peers) {
      if (!g.peers.hasOwnProperty(pid2)) continue;
      var rec2 = g.peers[pid2];
      try {
        var sender2 = rec2.pc.getSenders().filter(function (s) { return s.track && s.track.kind === 'video'; })[0];
        if (sender2) sender2.replaceTrack(null);
      } catch (e) {}
    }
    dom.gcVideoToggleIcon.textContent = '📹';
    dom.gcVideoToggleLabel.textContent = t('callVideoOn');
    gcRenderGrid();
  }
}

function gcShowIncomingBanner(inc) {
  state.gcall.incoming = inc;
  var g = state.groups[inc.groupId];
  var title = inc.groupName || (g ? g.name : '') || t('gcTitle');
  dom.gcibTitle.textContent = t('gcIncoming');
  dom.gcibSub.textContent = title + ' · ' + (inc.hostName || '');
  dom.gcibJoinBtn.textContent = t('gcJoin');
  dom.gcibIgnoreBtn.textContent = t('gcIgnore');
  var initial = (inc.hostName || '?').charAt(0).toUpperCase();
  dom.gcibAvatar.innerHTML = inc.hostAvatar
    ? '<img src="' + inc.hostAvatar + '" alt="">'
    : escapeHtml(initial);
  dom.gcIncomingBanner.style.display = 'flex';
  /* 30 秒自动消失 */
  if (state.gcall._incomingTimer) clearTimeout(state.gcall._incomingTimer);
  state.gcall._incomingTimer = setTimeout(function () {
    if (state.gcall.incoming &&
        state.gcall.incoming.groupId === inc.groupId) {
      gcIgnoreIncoming();
    }
  }, 30000);
}

/* ---- 按钮绑定 ---- */
(function initGroupCallUI() {
  if (dom.groupCallBtn) {
    dom.groupCallBtn.addEventListener('click', function () {
      if (state.currentType !== 'group') { showToast(t('gcOnlyGroup')); return; }
      if (state.gcall.active) {
        /* 已在群通话 → 打开界面 */
        dom.groupCallModal.style.display = 'flex';
        dom.groupCallModal.classList.add('open');
      } else {
        gcStart();
      }
    });
  }
  if (dom.gcMuteBtn) dom.gcMuteBtn.addEventListener('click', gcToggleMute);
  if (dom.gcLeaveBtn) dom.gcLeaveBtn.addEventListener('click', function () { gcLeave(false); });
  if (dom.gcVideoToggleBtn) dom.gcVideoToggleBtn.addEventListener('click', gcToggleVideo);
  if (dom.gcEndBtn) dom.gcEndBtn.addEventListener('click', gcEndAll);
  if (dom.gcibJoinBtn) dom.gcibJoinBtn.addEventListener('click', gcJoinIncoming);
  if (dom.gcibIgnoreBtn) dom.gcibIgnoreBtn.addEventListener('click', gcIgnoreIncoming);
  window.addEventListener('beforeunload', function () {
    if (state.gcall.active && state.socket && state.socket.connected) {
      try { state.socket.emit('group-call-leave', { groupId: state.gcall.groupId }); } catch (e) {}
    }
  });
})();

/* 输入区「更多」菜单：移动端收纳通话类按钮，不添加与聊天栏重复的入口 */
(function initInputMoreMenu() {
  var btn  = $id('inputMoreBtn');
  var menu = $id('inputMoreMenu');
  if (!btn || !menu) return;

  var tools = document.querySelector('.input-area .tools');
  if (!tools) return;

  /* 完整的原始顺序（桌面端恢复时按这个顺序排回去）
     —— 与 HTML 里 .tools 内按钮的实际顺序保持一致 */
  var TOOLS_ORDER = [
    'voiceCallBtn',   /* 📞 语音通话 */
    'videoCallBtn',   /* 📹 视频通话 */
    'groupCallBtn',   /* 👥 群通话 */
    'mentionBtn',     /* @  提及 */
    'quickReplyBtn',  /* ⚡ 快捷回复 */
    'emojiBtn',       /* 😊 表情 */
    'redpacketBtn',   /* 🧧 发红包 */
    'fileBtn',        /* 📎 发送文件 */
    'voiceBtn',       /* 🎤 录音 */
    'voiceCancelBtn', /* ✖ 取消录音（录音时才显示） */
    'inputMoreBtn'    /* ⋯ 更多（永远在最后） */
  ];

  /* 仅移动端收纳的按钮列表：
     只包含「输入区专有」的按钮。
     凡是顶部聊天栏（含顶部「⋯」下拉菜单）里已经存在的按钮
     —— 搜索 / 收藏 / 刷新 / 自动滚动 / 设置 / 清空 / 退出会话 /
        群成员 / 群文件 / 群相册 / 群投票 —— 一律不再重复收纳。
     保留在 tools 里的：😊 表情、🎤 录音、✖ 取消录音、⋯ */
  var INPUT_MOVE = [
    'voiceCallBtn',
    'videoCallBtn',
    'groupCallBtn',
    'mentionBtn',
    'quickReplyBtn',
    'redpacketBtn',
    'fileBtn',
    /* ★ 优化：阅后即焚在移动端也搬进「更多」菜单，
       腾出输入区空间 */
    'burnBtn'
  ];

  /* ---------- 移动端：把 INPUT_MOVE 里的按钮搬进菜单 ---------- */
  function moveToMenu() {
    for (var i = 0; i < INPUT_MOVE.length; i++) {
      var el = document.getElementById(INPUT_MOVE[i]);
      if (!el) continue;
      if (el.parentNode === menu) continue; /* 已在菜单里 */
      menu.appendChild(el);
    }
  }

  /* ---------- 桌面端：把按钮按原始顺序还原回 tools ---------- */
  function restoreToTools() {
    /* 按 TOOLS_ORDER 顺序把按钮逐一 appendChild 回 tools。
       由于 appendChild 会自动"搬运"节点，此时不需要手工判断
       元素当前在哪个父节点下。 */
    for (var i = 0; i < TOOLS_ORDER.length; i++) {
      var el = document.getElementById(TOOLS_ORDER[i]);
      if (!el) continue;
      tools.appendChild(el);
    }
  }

  /* ---------- 按屏宽同步：桌面还原、移动收纳 ---------- */
  var moved = false; /* 当前是否处于"已收纳"状态 */
  function sync() {
    var isMobile = window.innerWidth <= 768;
    if (isMobile && !moved) { moveToMenu(); moved = true; }
    else if (!isMobile && moved) { restoreToTools(); moved = false; }
  }

  function closeMenu() {
    menu.classList.remove('open');
    btn.classList.remove('open');
  }
  window.__closeInputMoreMenu = closeMenu;

  /* 首次进入：按当前宽度决定收纳或展开 */
  sync();

  /* 点「⋯」：展开 / 收起 */
  btn.addEventListener('click', function (e) {
    e.stopPropagation();
    if (!menu.children.length) return;
    var open = menu.classList.toggle('open');
    btn.classList.toggle('open', open);
  });

  /* 点击菜单里的任意按钮 → 延迟收起（让按钮自身的 click 先执行） */
  menu.addEventListener('click', function (e) {
    e.stopPropagation();
    var t0 = e.target;
    while (t0 && t0 !== menu) {
      if (t0.tagName === 'BUTTON') {
        setTimeout(closeMenu, 150);
        return;
      }
      t0 = t0.parentNode;
    }
  });

  /* 点击页面其它位置关闭 */
  document.addEventListener('click', function () { closeMenu(); });

  /* 窗口尺寸变化 → 重新同步收纳 / 展开状态 */
  var _rt = null;
  window.addEventListener('resize', function () {
    if (_rt) clearTimeout(_rt);
    _rt = setTimeout(function () { _rt = null; sync(); }, 150);
  });
})();

/* ============================================================
   智能手表检测（Apple Watch / Wear OS / Tizen / watchOS）
   ------------------------------------------------------------
   命中后给 <html> 加 .is-watch（可选 .is-watch-round），
   由上方 CSS 处理布局；同时：
     · 强制深色主题（OLED 省电 + 高对比）
     · 关闭磨砂玻璃（性能 / 耗电）
     · 收紧字体与行距，提高一屏信息量
   判定逻辑（任意命中即为手表）：
     A) URL 带 ?watch=1 / ?watch=true    —— 调试 / 强制模式
     B) UA 匹配 watch / wear / tizen     —— 最可靠
     C) 短边 ≤ 240px 且支持触摸          —— Apple Watch 全系
     D) 短边 ≤ 320px 且宽高比 ≥ 1.4
        且支持触摸                       —— Wear OS 圆屏
   ============================================================ */
(function initWatchMode() {
  function checkWatch() {
    try {
      /* A. URL 显式指定 */
      if (/[?&]watch=(1|true|yes)\b/i.test(location.search)) return true;

      /* B. UA 特征 */
      var ua = (navigator.userAgent || '').toLowerCase();
      if (/watch|wear|tizen|watchos|wearos/.test(ua)) return true;

      /* C / D. 几何 + 触摸 */
      var w = window.innerWidth || 0;
      var h = window.innerHeight || 0;
      if (!w || !h) return false;
      var minSide = Math.min(w, h);
      var maxSide = Math.max(w, h);
      var ratio = maxSide / Math.max(1, minSide);
      var isTouch = ('ontouchstart' in window) ||
                    (navigator.maxTouchPoints > 0);

      /* ★ v0.27.5：放宽判定范围 —— 覆盖华为 / 小米 / 三星 Wear OS
         方形与圆形表盘（部分表盘短边 280~340px）。 */
      if (isTouch && minSide <= 260) return true;              /* C */
      if (isTouch && minSide <= 340 && ratio >= 1.3) return true; /* D */
      /* ★ v0.27.5：显式匹配 Wear OS / Tizen 的 UA 特征 */
      var uaLow = (navigator.userAgent || '').toLowerCase();
      if (/wear\s?os|watch|samsungbrowser.*watch|tizen/.test(uaLow) &&
          isTouch) return true;
      return false;
    } catch (e) {
      return false;
    }
  }

  function checkRound() {
    try {
      if (window.matchMedia && window.matchMedia('(environment: round)').matches) return true;
      /* 部分 Wear OS 浏览器 UA 里带 round */
      if (/round/.test((navigator.userAgent || '').toLowerCase())) return true;
    } catch (e) {}
    return false;
  }

  function applyWatch() {
    var root = document.documentElement;
    if (checkWatch()) {
      root.classList.add('is-watch');

      /* 圆屏判定 */
      if (checkRound()) root.classList.add('is-watch-round');
      else root.classList.remove('is-watch-round');

      /* 强制深色（OLED 省电）；用户手动切回浅色会被 setTheme 覆盖，
         这是有意的：手表上深色可读性 / 续航都更好。 */
      try {
        root.setAttribute('data-theme', 'dark');
        var tt = document.getElementById('themeToggle');
        if (tt) tt.textContent = '☀️';
      } catch (e) {}

      /* 收紧字体 / 行距 / 气泡宽度 */
      try {
        root.style.setProperty('--msg-font-size', '14px');
        root.style.setProperty('--msg-line-height', '1.45');
        root.style.setProperty('--msg-max-width', '92%');
      } catch (e) {}

      /* 记录到 state，便于其它逻辑判断 */
      try { if (typeof state === 'object' && state) state.isWatch = true; } catch (e) {}
    } else {
      root.classList.remove('is-watch');
      root.classList.remove('is-watch-round');
      try { if (typeof state === 'object' && state) state.isWatch = false; } catch (e) {}
    }
  }

  applyWatch();

  /* 旋转 / 窗口变化后重新判定（防抖 200ms） */
  var _wt = null;
  function recheck() {
    if (_wt) clearTimeout(_wt);
    _wt = setTimeout(function () { _wt = null; applyWatch(); }, 200);
  }
  window.addEventListener('resize', recheck);
  window.addEventListener('orientationchange', function () {
    setTimeout(applyWatch, 300);
  });
})();

/* 音乐库：音频在 files/music/，客户端只维护元数据 + 一个 <audio> */

/* ---- 秒 → m:ss ---- */
function fmtDuration(sec) {
  sec = Math.max(0, Math.floor(Number(sec) || 0));
  var m = Math.floor(sec / 60);
  var s = sec % 60;
  return m + ':' + (s < 10 ? '0' : '') + s;
}

/* ---- 当前曲目 ---- */
function musicCurrent() {
  var id = state.music.currentId;
  if (!id) return null;
  for (var i = 0; i < state.music.list.length; i++) {
    if (state.music.list[i].id === id) return state.music.list[i];
  }
  return null;
}

/* ---- 过滤后的列表（受搜索影响） ---- */
function musicFiltered() {
  var q = (dom.musicSearchInput && dom.musicSearchInput.value || '')
    .trim().toLowerCase();
  if (!q) return state.music.list;
  var out = [];
  for (var i = 0; i < state.music.list.length; i++) {
    var m = state.music.list[i];
    var hay = ((m.name || '') + ' ' + (m.artist || '') + ' ' +
               (m.album || '') + ' ' + (m.uploaderName || '')).toLowerCase();
    if (hay.indexOf(q) !== -1) out.push(m);
  }
  return out;
}

function renderMusicCount() {
  if (dom.musicCount) dom.musicCount.textContent = String(state.music.list.length);
}

function renderMusicList() {
  if (!dom.musicList) return;
  renderMusicCount();
  var arr = musicFiltered();
  if (!state.music.list.length) {
    dom.musicList.innerHTML = '<div class="music-empty">' +
      escapeHtml(t('musicEmpty')) + '</div>';
    return;
  }
  if (!arr.length) {
    dom.musicList.innerHTML = '<div class="music-empty">' +
      escapeHtml(t('musicNoMatch')) + '</div>';
    return;
  }
  var html = '';
  for (var i = 0; i < arr.length; i++) {
    var m = arr[i];
    var isPlaying = (m.id === state.music.currentId);
    var liked = (m.likes || []).indexOf(state.myId) !== -1;
    var meta = [];
    if (m.artist) meta.push(m.artist);
    if (m.album) meta.push(m.album);
    meta.push(formatFileSize(m.fileSize));
    if (m.duration) meta.push(fmtDuration(m.duration));
    meta.push(t('musicPlays').split('{n}').join(m.plays || 0));
    html += '<div class="music-item' + (isPlaying ? ' playing' : '') +
      '" data-mid="' + escapeHtml(m.id) + '">' +
      '<div class="music-item-idx">' + (isPlaying ? '♪' : (i + 1)) + '</div>' +
      '<div class="music-item-body">' +
        '<div class="music-item-name">' + escapeHtml(m.name) + '</div>' +
        '<div class="music-item-meta">' + escapeHtml(meta.join(' · ')) + '</div>' +
      '</div>' +
      '<div class="music-item-actions">' +
        '<button class="music-item-btn music-like-btn' + (liked ? ' liked' : '') +
          '" data-action="like" title="' + escapeHtml(t('musicLike')) + '">' +
          (liked ? '❤️' : '🤍') + '</button>' +
        ((m.uploader === state.myId || state.isAdmin)
          ? '<button class="music-item-btn" data-action="delete" title="' +
            escapeHtml(t('btnDelete')) + '">🗑️</button>'
          : '') +
      '</div>' +
    '</div>';
  }
  dom.musicList.innerHTML = html;
}

/* ---- 播放控制 ---- */
function musicSetNowPlaying(m) {
  /* ---- 音乐库内的「正在播放」区 ---- */
  if (dom.musicNowName) {
    if (!m) {
      dom.musicNowName.textContent = t('musicNoSong');
      if (dom.musicNowArtist) dom.musicNowArtist.textContent = '';
    } else {
      dom.musicNowName.textContent = m.name;
      var parts = [];
      if (m.artist) parts.push(m.artist);
      if (m.album) parts.push(m.album);
      if (m.uploaderName) {
        parts.push(t('musicUploadedBy').split('{name}').join(m.uploaderName));
      }
      if (dom.musicNowArtist) dom.musicNowArtist.textContent = parts.join(' · ');
    }
  }
  /* ---- 全局迷你播放条 ---- */
  musicMiniRefresh();
}

function musicPlayById(id, autoplay) {
  var m = null;
  for (var i = 0; i < state.music.list.length; i++) {
    if (state.music.list[i].id === id) { m = state.music.list[i]; break; }
  }
  if (!m) return;

  /* 切歌 → 重新允许迷你条显示（即使用户此前点过 ✕）
     · miniHidden    ：完全隐藏 → 重置（让用户重新看到播放提示）
     · miniCollapsed ：靠边收起 → 保留（用户意图就是保持靠边，
                        不应被切歌打断而自动展开完整播放条）
     唯一例外：完全隐藏后再切歌，此时连靠边状态一起重置，
     让用户重新看到完整播放条。 */
  if (state.music.miniHidden) {
    state.music.miniHidden = false;
    state.music.miniCollapsed = false;
  }

  state.music.currentId = id;
  musicSetNowPlaying(m);
  renderMusicList();

  if (!dom.musicAudio) return;
  if (dom.musicAudio.getAttribute('data-mid') !== id) {
    dom.musicAudio.src = m.url;
    dom.musicAudio.setAttribute('data-mid', id);
  }

  if (autoplay !== false) {
    var p = dom.musicAudio.play();
    if (p && p.catch) p.catch(function () {});
    if (state.socket && state.socket.connected) {
      state.socket.emit('music-play', { id: id });
    }
    /* ★ 播放提示：等待 play() 真正兑现后再弹，
       避免自动播放被浏览器拦截时给出「正在播放」的误导提示。 */
    var _display = m.name || '';
    if (m.artist) _display += ' — ' + m.artist;
    var _toastTxt = t('musicPlayingToast').split('{name}').join(_display);
    if (p && p.then) {
      p.then(function () { showToast(_toastTxt); })
       .catch(function () {});
    } else {
      showToast(_toastTxt);
    }
  } else {
    musicMiniRefresh();
  }
}

function musicTogglePlay() {
  if (!dom.musicAudio) return;
  if (!state.music.currentId) {
    var arr = musicFiltered();
    if (arr.length) musicPlayById(arr[0].id, true);
    return;
  }
  if (dom.musicAudio.paused) {
    var p = dom.musicAudio.play();
    if (p && p.catch) p.catch(function () {});
    if (state.socket && state.socket.connected) {
      state.socket.emit('music-play', { id: state.music.currentId });
    }
  } else {
    dom.musicAudio.pause();
  }
}

function musicStep(delta) {
  var arr = musicFiltered();
  if (!arr.length) return;
  var idx = -1;
  for (var i = 0; i < arr.length; i++) {
    if (arr[i].id === state.music.currentId) { idx = i; break; }
  }
  var next;
  if (state.music.shuffle && arr.length > 1) {
    do { next = Math.floor(Math.random() * arr.length); }
    while (next === idx);
  } else {
    next = (idx === -1) ? 0 : (idx + delta + arr.length) % arr.length;
  }
  musicPlayById(arr[next].id, true);
}

function musicUpdatePlayBtn() {
  if (!dom.musicAudio) return;
  var playing = !dom.musicAudio.paused && !!state.music.currentId;
  if (dom.musicPlayBtn) {
    dom.musicPlayBtn.textContent = playing ? '⏸' : '▶';
    dom.musicPlayBtn.title = playing ? t('musicPause') : t('musicPlay');
  }
  /* ★ 同步迷你播放条（播放态 / 图标 / 歌名） */
  musicMiniRefresh();
}

function musicUpdateLoopBtn() {
  if (!dom.musicLoopBtn) return;
  var mode = state.music.loopMode;
  dom.musicLoopBtn.classList.toggle('active', mode !== 'off');
  dom.musicLoopBtn.textContent = (mode === 'one') ? '🔂' : '🔁';
  dom.musicLoopBtn.title = (mode === 'one') ? t('musicLoopOne')
    : (mode === 'off' ? t('musicLoopOff') : t('musicLoopList'));
}

/* 迷你播放条：有曲目 + 未手动隐藏 + 音乐库未打开时显示 */
function musicMiniShow() {
  if (!dom.musicMini) return;

  /* ---- 统一收起辅助：把迷你条与展开按钮都隐藏 ---- */
  function hideAll() {
    dom.musicMini.classList.remove('show');
    if (dom.musicMiniExpand) dom.musicMiniExpand.classList.remove('show');
  }

  /* 手动隐藏（点 ✕）→ 两者都不显示 */
  if (state.music.miniHidden) { hideAll(); return; }

  /* 没有当前曲目 → 两者都不显示 */
  if (!state.music.currentId) { hideAll(); return; }

  /* 音乐库已经打开 → 两者都不显示 */
  if (dom.musicModal && dom.musicModal.classList.contains('open')) {
    hideAll();
    return;
  }

  /* ---- 靠边模式：只显示圆形展开按钮 ---- */
  if (state.music.miniCollapsed) {
    dom.musicMini.classList.remove('show');
    if (dom.musicMiniExpand) dom.musicMiniExpand.classList.add('show');
    return;
  }

  /* ---- 正常模式：显示完整迷你条 ---- */
  dom.musicMini.classList.add('show');
  if (dom.musicMiniExpand) dom.musicMiniExpand.classList.remove('show');
}

function musicMiniRefresh() {
  if (!dom.musicMini) return;

  var m = musicCurrent();
  if (!m) {
    dom.musicMini.classList.remove('show');
    if (dom.musicMiniFill) dom.musicMiniFill.style.width = '0%';
    return;
  }

  /* ---- 文本 ---- */
  if (dom.musicMiniName) dom.musicMiniName.textContent = m.name || '—';
  if (dom.musicMiniArtist) {
    var parts = [];
    if (m.artist) parts.push(m.artist);
    if (m.uploaderName) {
      parts.push(t('musicUploadedBy').split('{name}').join(m.uploaderName));
    }
    dom.musicMiniArtist.textContent = parts.join(' · ');
  }

  /* ---- 播放态 ---- */
  var playing = !!(dom.musicAudio && !dom.musicAudio.paused && !dom.musicAudio.ended);
  dom.musicMini.classList.toggle('playing', playing);
  if (dom.musicMiniPlay) {
    dom.musicMiniPlay.textContent = playing ? '⏸' : '▶';
    dom.musicMiniPlay.title = playing ? t('musicPause') : t('musicPlay');
  }
  /* ★ 同步展开按钮的播放态（播放中 → 🎵 旋转；暂停 → 呼吸动画） */
  if (dom.musicMiniExpand) {
    dom.musicMiniExpand.classList.toggle('playing', playing);
  }

  /* ---- 进度 ---- */
  musicMiniRefreshProgress();

  /* ---- 显隐 ---- */
  musicMiniShow();
}

/* 只刷新进度条（timeupdate 高频调用，避免多余 DOM 操作） */
function musicMiniRefreshProgress() {
  if (!dom.musicMiniFill || !dom.musicAudio) return;
  var audio = dom.musicAudio;
  if (!audio.duration || !isFinite(audio.duration) || audio.duration <= 0) {
    dom.musicMiniFill.style.width = '0%';
    return;
  }
  var pct = audio.currentTime / audio.duration * 100;
  if (!isFinite(pct) || pct < 0) pct = 0;
  if (pct > 100) pct = 100;
  dom.musicMiniFill.style.width = pct.toFixed(2) + '%';
}

/* 迷你条上的按钮事件（一次性绑定） */
(function initMusicMiniUI() {
  if (!dom.musicMini) return;

  /* ---- 点击主体 → 打开音乐库 ---- */
  dom.musicMini.addEventListener('click', function (e) {
    var btn = e.target && e.target.closest
      ? e.target.closest('.music-mini-btn') : null;
    if (btn) return;   /* 按钮各自处理，避免重复触发 */
    if (!state.isLoggedIn) return;
    dom.musicModal.classList.add('open');
    renderMusicList();
    if (state.socket && state.socket.connected) {
      state.socket.emit('music-list');
    }
    musicMiniRefresh();   /* 音乐库已打开 → 自动隐藏迷你条 */
  });

  function bindMiniBtn(el, fn) {
    if (!el) return;
    el.addEventListener('click', function (e) {
      e.stopPropagation();
      fn();
    });
  }
  bindMiniBtn(dom.musicMiniPrev, function () { musicStep(-1); });
  bindMiniBtn(dom.musicMiniPlay, function () { musicTogglePlay(); });
  bindMiniBtn(dom.musicMiniNext, function () { musicStep(1); });

  /* ---- 靠边收起：迷你条 → 圆形展开按钮 ---- */
  bindMiniBtn(dom.musicMiniCollapse, function () {
    state.music.miniCollapsed = true;
    musicMiniShow();
  });

  /* ---- 完全隐藏：两者都不显示 ---- */
  bindMiniBtn(dom.musicMiniClose, function () {
    state.music.miniHidden = true;
    state.music.miniCollapsed = false;  /* 重置靠边状态，切歌后重新展开 */
    musicMiniShow();
  });

  /* ---- 圆形展开按钮：恢复到完整迷你条 ---- */
  if (dom.musicMiniExpand) {
    dom.musicMiniExpand.addEventListener('click', function (e) {
      e.stopPropagation();
      state.music.miniCollapsed = false;
      musicMiniRefresh();   /* 内部会调用 musicMiniShow() */
    });
  }
})();

/* ---- 上传 ---- */
function musicUploadFiles(files) {
  if (!files || !files.length) return;
  if (!state.socket || !state.socket.connected) {
    showConnectionStatus('error', t('connServerLost'));
    return;
  }
  for (var i = 0; i < files.length; i++) {
    (function (f) {
      if (!f.type || f.type.indexOf('audio/') !== 0) {
        showToast(t('musicOnlyAudio'));
        return;
      }
      if (f.size > state.music.maxSize) {
        showToast(t('musicTooLarge').split('{n}')
          .join(Math.round(state.music.maxSize / 1048576)));
        return;
      }
      /* 从文件名推 歌曲名 / 歌手（"歌手 - 歌名.mp3" 常见命名） */
      var base = String(f.name || '').replace(/\.[^.]+$/, '');
      var songName = base, artist = '';
      var dash = base.indexOf(' - ');
      if (dash > 0) {
        artist = base.substring(0, dash).trim();
        songName = base.substring(dash + 3).trim();
      }
      if (!songName) songName = base || '未命名';
      if (dom.musicList) {
        dom.musicList.insertAdjacentHTML('afterbegin',
          '<div class="music-uploading" id="musicUploadingTip">' +
          escapeHtml(t('musicUploading')) + ' ' + escapeHtml(f.name) + '</div>');
      }
      var rd = new FileReader();
      rd.onload = function (ev) {
        state.socket.emit('music-upload', {
          name: songName,
          artist: artist,
          album: '',
          fileData: ev.target.result,
          origName: f.name,
          duration: 0
        });
      };
      rd.onerror = function () {
        var tip = document.getElementById('musicUploadingTip');
        if (tip && tip.parentNode) tip.parentNode.removeChild(tip);
        showToast(t('musicUploadFail'));
      };
      rd.readAsDataURL(f);
    })(files[i]);
  }
}

/* 反馈中心入口：带 token 打开 /kf，token 缺失时跳登录页 */
(function initFeedbackEntry() {
  var btn = $id('feedbackBtn');
  if (!btn) return;

  function _openKf(token) {
    var url = (location.origin || '') + '/kf';
    if (token) url += '?t=' + encodeURIComponent(token);
    try {
      window.open(url, '_blank', 'noopener,noreferrer');
    } catch (e) {
      showToast(state.lang === 'en'
        ? 'Please allow pop-ups to open the feedback center'
        : '请允许弹出窗口以打开反馈中心');
    }
  }

  btn.addEventListener('click', function () {
    if (!state.isLoggedIn) { showToast(t('toastLoginFirst')); return; }

    function _fallbackToken() {
      var tk = state.feedbackToken;
      if (!tk) {
        try { tk = localStorage.getItem('feedback_token') || ''; } catch (e) {}
      }
      return tk;
    }

    /* ★ v0.24.47：优先向服务端请求最新 token ——
       服务端重启后内存 session 会清空，旧 token 会失效。
       新 token 一定与当前在线会话同步。旧 token 作降级兜底。 */
    if (state.socket && state.socket.connected) {
      var _handled = false;
      var _timer = setTimeout(function () {
        if (_handled) return;
        _handled = true;
        _openKf(_fallbackToken());
      }, 1500);
      try {
        state.socket.emit('request-feedback-token', function (res) {
          if (_handled) return;
          _handled = true;
          clearTimeout(_timer);
          _openKf((res && res.ok && res.token) ? res.token : _fallbackToken());
        });
      } catch (e) {
        clearTimeout(_timer);
        if (!_handled) { _handled = true; _openKf(_fallbackToken()); }
      }
      return;
    }
    _openKf(_fallbackToken());
  });
})();

/* ============================================================
   ★ B站全屏视频面板
   ------------------------------------------------------------
   · window.__openBiliPanel()   从任意位置打开
   · 三个 Tab：推荐（WBI 推荐）/ 热门 / 排行榜
   · 支持关键词搜索（WBI 签名）
   · 全屏双栏：左视频列表 + 右播放器 + 详情 + 相关推荐
   · 本地记录播放历史（localStorage.bili_history）
   ============================================================ */
(function initBiliPanel() {
  var modal       = document.getElementById('biliModal');
  if (!modal) return;

  var grid        = document.getElementById('biliGrid');
  var stage       = document.getElementById('biliStage');
  var playerWrap  = document.getElementById('biliPlayerWrap');
  var playerEmpty = document.getElementById('biliPlayerEmpty');
  var frame       = document.getElementById('biliFrame');
  var loadingMask = document.getElementById('biliLoadingMask');
  var detail      = document.getElementById('biliDetail');
  var sourceTag   = document.getElementById('biliSourceTag');
  var searchInput = document.getElementById('biliSearchInput');
  var searchBtn   = document.getElementById('biliSearchBtn');
  var refreshBtn  = document.getElementById('biliRefreshBtn');
  var closeBtn    = document.getElementById('biliCloseBtn');
  var tabBtns     = modal.querySelectorAll('[data-bili-tab]');

  var currentTab      = 'recommend';
  var currentFreshIdx = 1;
  var currentList     = [];
  var currentBvid     = '';
  var currentItem     = null;
  var searchKeyword   = '';
  var isLoading       = false;
  var escHandler      = null;

  /* ---- 播放历史 ---- */
  var HISTORY_KEY = 'bili_history';
  var HISTORY_MAX = 30;

  function getHistory() {
    try {
      var raw = localStorage.getItem(HISTORY_KEY);
      var arr = raw ? JSON.parse(raw) : [];
      return Array.isArray(arr) ? arr : [];
    } catch (e) { return []; }
  }
  function pushHistory(item) {
    if (!item || !item.bvid) return;
    try {
      var h = getHistory().filter(function (x) { return x.bvid !== item.bvid; });
      h.unshift({
        bvid: item.bvid,
        cid: item.cid || 0,
        title: item.title || '',
        cover: item.cover || '',
        owner: item.owner || { name: '' },
        stat: item.stat || { view: 0 },
        ts: Date.now()
      });
      if (h.length > HISTORY_MAX) h.length = HISTORY_MAX;
      localStorage.setItem(HISTORY_KEY, JSON.stringify(h));
    } catch (e) {}
  }

  /* ---- 打开 / 关闭 ---- */
  function open() {
    modal.classList.add('open');
    document.body.style.overflow = 'hidden';

    /* ★ 仅在首次打开时加载；未打开面板前不发任何 B 站请求 */
    if (!currentList.length) loadTab('recommend', true);

    /* ★ Esc 监听只在打开时挂载，关闭即解绑 */
    if (!escHandler) {
      escHandler = function (e) {
        if (e.key === 'Escape' && modal.classList.contains('open')) {
          e.preventDefault();
          close();
        }
      };
      document.addEventListener('keydown', escHandler);
    }
  }
  function close() {
    modal.classList.remove('open');
    document.body.style.overflow = '';

    /* ★ 双重停止：removeAttribute + 设置 about:blank
       —— 部分浏览器在 removeAttribute 后仍保留已加载的播放器，
          设置 about:blank 会真正卸载 iframe 内容、停止音频 */
    try { frame.removeAttribute('src'); } catch (e) {}
    try { frame.src = 'about:blank'; } catch (e) {}
    playerWrap.classList.remove('has-video');
    playerWrap.classList.remove('loading');

    currentBvid = '';
    currentItem = null;

    /* ★ 关闭时解绑 Esc 监听 */
    if (escHandler) {
      document.removeEventListener('keydown', escHandler);
      escHandler = null;
    }
  }
  window.__openBiliPanel = open;

  /* ---- Tab 切换 ---- */
  function setTab(tab) {
    currentTab = tab;
    currentFreshIdx = 1;
    for (var i = 0; i < tabBtns.length; i++) {
      tabBtns[i].classList.toggle('active',
        tabBtns[i].getAttribute('data-bili-tab') === tab);
    }
    sourceTag.textContent = ({
      recommend: '推荐视频',
      popular:   '热门视频',
      rank:      '排行榜',
      search:    '搜索结果：' + (searchKeyword || '')
    })[tab] || '视频';
    loadTab(tab, true);
  }

  /* ---- 加载列表 ---- */
  function loadTab(tab, resetScroll) {
    if (isLoading) return;
    isLoading = true;
    if (resetScroll) grid.scrollTop = 0;
    grid.innerHTML = '<div class="bili-loading">加载中…</div>';

    var url;
    if (tab === 'popular') {
      url = '/api/bili/popular?ps=20&pn=1';
    } else if (tab === 'rank') {
      url = '/api/bili/rank?rid=0';
    } else if (tab === 'search') {
      url = '/api/bili/search?keyword=' +
        encodeURIComponent(searchKeyword) + '&page=1';
    } else {
      url = '/api/bili/recommend?ps=20&fresh_idx=' + currentFreshIdx;
    }

    fetch(url)
      .then(function (r) { return r.json(); })
      .then(function (d) {
        isLoading = false;
        if (d && d.ok && d.list && d.list.length) {
          currentList = d.list;
          renderGrid(d.list);
          return;
        }
        /* 推荐降级热门 */
        if (tab === 'recommend') {
          sourceTag.textContent = '热门视频（推荐不可用）';
          return fetch('/api/bili/popular?ps=20&pn=1')
            .then(function (r) { return r.json(); })
            .then(function (d2) {
              if (d2 && d2.ok && d2.list && d2.list.length) {
                currentList = d2.list;
                renderGrid(d2.list);
              } else {
                grid.innerHTML =
                  '<div class="bili-loading">⚠️ 推荐与热门均不可用</div>';
              }
            });
        }
        grid.innerHTML = '<div class="bili-loading">⚠️ ' +
          escapeHtml((d && d.error) || '加载失败') + '</div>';
      })
      .catch(function () {
        isLoading = false;
        grid.innerHTML = '<div class="bili-loading">⚠️ 网络错误</div>';
      });
  }

  /* ---- 渲染左侧列表 ---- */
  function renderGrid(list) {
    grid.innerHTML = '';
    for (var i = 0; i < list.length; i++) {
      (function (item) {
        var card = document.createElement('div');
        card.className = 'bili-card';
        if (currentBvid === item.bvid) card.classList.add('active');

        var coverHtml = item.cover
          ? '<img class="bili-card-cover" src="' + escapeHtml(item.cover) +
            '" alt="" loading="lazy">'
          : '<div class="bili-card-cover"></div>';

        card.innerHTML = coverHtml +
          '<div class="bili-card-body">' +
            '<div class="bili-card-title">' + escapeHtml(item.title) + '</div>' +
            '<div class="bili-card-meta">' +
              '<span>👤 ' +
                escapeHtml((item.owner && item.owner.name) || '') + '</span>' +
              (item.stat && item.stat.view
                ? '<span>▶ ' + fmtView(item.stat.view) + '</span>'
                : '') +
            '</div>' +
          '</div>';

        card.addEventListener('click', function () { playVideo(item); });
        grid.appendChild(card);
      })(list[i]);
    }
  }

  /* ---- 播放视频（缺 cid 时自动拉详情） ---- */
  function playVideo(item) {
    if (!item || !item.bvid) return;

    /* ★ 点击同一个视频且正在播放 → 不重复加载 */
    if (currentBvid === item.bvid &&
        frame.getAttribute('src') &&
        frame.getAttribute('src') !== 'about:blank') {
      return;
    }

    currentItem = item;
    currentBvid = item.bvid;
    pushHistory(item);

    /* 更新左侧高亮 */
    renderGrid(currentList);

    /* ★ 显示 loading 遮罩（B 站播放器初始化期间覆盖黑屏） */
    playerWrap.classList.add('loading');
    playerWrap.classList.add('has-video');

    var doPlay = function (cid) {
      /* ★ v0.28.0：从设置中读取默认清晰度 / 弹幕 / 自动播放 */
      var _q  = state.biliQuality != null ? String(state.biliQuality) : '0';
      var _dm = state.biliDanmaku !== false ? 1 : 0;
      var _ap = state.biliAutoplay === true ? 1 : 0;
      var url = '//player.bilibili.com/player.html'
        + '?bvid=' + encodeURIComponent(item.bvid)
        + '&cid=' + encodeURIComponent(cid || 0)
        + '&page=1'
        + '&isOutside=true'
        + '&high_quality=' + _q
        + '&danmaku=' + _dm
        + '&autoplay=' + _ap;
      /* ★ 直接赋值新 src，不先设 about:blank（少一次导航） */
      try { frame.src = url; } catch (e) {}
      loadDetail(item.bvid);
    };

    if (item.cid) { doPlay(item.cid); return; }

    fetch('/api/bili/video?bvid=' + encodeURIComponent(item.bvid))
      .then(function (r) { return r.json(); })
      .then(function (d) {
        if (d && d.ok) {
          var cid = (d.pages && d.pages.length) ? d.pages[0].cid : 0;
          doPlay(cid);
        } else {
          doPlay(0);
        }
      })
      .catch(function () { doPlay(0); });
  }

  /* ---- 右侧详情 + 相关推荐 ---- */
  function loadDetail(bvid) {
    detail.innerHTML = '<div class="bili-detail-empty">加载详情…</div>';
    fetch('/api/bili/video?bvid=' + encodeURIComponent(bvid))
      .then(function (r) { return r.json(); })
      .then(function (d) {
        if (!d || !d.ok) {
          detail.innerHTML =
            '<div class="bili-detail-empty">⚠️ 无法获取详情</div>';
          return;
        }
        var html = '';
        html += '<div class="bili-detail-title">' +
          escapeHtml(d.title) + '</div>';
        html += '<div class="bili-detail-meta">';
        if (d.owner && d.owner.name) {
          html += '<span>👤 ' + escapeHtml(d.owner.name) + '</span>';
        }
        if (d.stat && d.stat.view) {
          html += '<span>▶ ' + fmtView(d.stat.view) + ' 播放</span>';
        }
        if (d.stat && d.stat.like) {
          html += '<span>👍 ' + fmtView(d.stat.like) + '</span>';
        }
        /* ★ v0.28.0：投币 / 收藏 / 分享 */
        if (d.stat && d.stat.coin) {
          html += '<span>🪙 ' + fmtView(d.stat.coin) + ' 投币</span>';
        }
        if (d.stat && d.stat.favorite) {
          html += '<span>⭐ ' + fmtView(d.stat.favorite) + ' 收藏</span>';
        }
        if (d.duration) {
          html += '<span>⏱ ' + fmtDur(d.duration) + '</span>';
        }
        /* ★ v0.28.0：发布时间（YYYY-MM-DD HH:mm） */
        if (d.pubdate) {
          html += '<span>📅 ' +
            escapeHtml(fmtPubDate(d.pubdate)) + ' 发布</span>';
        }
        html += '</div>';
        if (d.desc) {
          html += '<div class="bili-detail-desc">' +
            escapeHtml(d.desc) + '</div>';
        }
        html += '<div class="bili-related-title">相关推荐</div>';
        html += '<div class="bili-related-grid" id="biliRelatedGrid">' +
          '<div class="bili-loading">加载中…</div></div>';
        detail.innerHTML = html;
        loadRelated(bvid);
      })
      .catch(function () {
        detail.innerHTML =
          '<div class="bili-detail-empty">⚠️ 网络错误</div>';
      });
  }

  function loadRelated(bvid) {
    var box = document.getElementById('biliRelatedGrid');
    if (!box) return;
    fetch('/api/bili/related?bvid=' + encodeURIComponent(bvid))
      .then(function (r) { return r.json(); })
      .then(function (d) {
        if (!d || !d.ok || !d.list || !d.list.length) {
          box.innerHTML = '<div class="bili-loading">暂无相关推荐</div>';
          return;
        }
        box.innerHTML = '';
        for (var i = 0; i < d.list.length && i < 12; i++) {
          (function (item) {
            var card = document.createElement('div');
            card.className = 'bili-related-card';
            card.innerHTML =
              (item.cover
                ? '<img src="' + escapeHtml(item.cover) +
                  '" alt="" loading="lazy">'
                : '<div style="aspect-ratio:16/10;background:#111"></div>') +
              '<div class="bili-rc-body">' +
                '<div class="bili-rc-title">' +
                  escapeHtml(item.title) + '</div>' +
                '<div class="bili-rc-meta">' +
                  escapeHtml((item.owner && item.owner.name) || '') +
                  (item.stat && item.stat.view
                    ? ' · ▶ ' + fmtView(item.stat.view)
                    : '') +
                '</div>' +
              '</div>';
            card.addEventListener('click', function () {
              playVideo(item);
              if (stage) stage.scrollTop = 0;
            });
            box.appendChild(card);
          })(d.list[i]);
        }
      })
      .catch(function () {
        box.innerHTML = '<div class="bili-loading">⚠️ 加载失败</div>';
      });
  }

  /* ---- 工具 ---- */
  function escapeHtml(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function fmtView(n) {
    n = Number(n) || 0;
    if (n >= 1e8) return (n / 1e8).toFixed(1) + '亿';
    if (n >= 1e4) return (n / 1e4).toFixed(1) + '万';
    return String(n);
  }
  function fmtDur(sec) {
    sec = Math.max(0, Math.floor(Number(sec) || 0));
    var m = Math.floor(sec / 60);
    var s = sec % 60;
    return m + ':' + (s < 10 ? '0' : '') + s;
  }
  /* ★ v0.28.0：秒级时间戳 → YYYY-MM-DD HH:mm（本地时区） */
  function fmtPubDate(ts) {
    var n = Number(ts) || 0;
    if (!n) return '';
    try {
      var d = new Date(n * 1000);
      var yy = d.getFullYear();
      var mm = String(d.getMonth() + 1).padStart(2, '0');
      var dd = String(d.getDate()).padStart(2, '0');
      var hh = String(d.getHours()).padStart(2, '0');
      var mi = String(d.getMinutes()).padStart(2, '0');
      return yy + '-' + mm + '-' + dd + ' ' + hh + ':' + mi;
    } catch (e) { return ''; }
  }

  /* ---- 搜索 ---- */
  function doSearch() {
    var kw = String(searchInput.value || '').trim();
    if (!kw) { showToast('请输入搜索关键词'); return; }
    searchKeyword = kw;
    setTab('search');
  }

  /* ---- 事件绑定 ---- */
  for (var i = 0; i < tabBtns.length; i++) {
    (function (btn) {
      btn.addEventListener('click', function () {
        setTab(btn.getAttribute('data-bili-tab'));
      });
    })(tabBtns[i]);
  }

  searchBtn.addEventListener('click', doSearch);
  searchInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') { e.preventDefault(); doSearch(); }
  });

  refreshBtn.addEventListener('click', function () {
    if (currentTab === 'recommend') {
      currentFreshIdx++;
      loadTab('recommend', true);
    } else if (currentTab === 'search') {
      loadTab('search', true);
    } else {
      loadTab(currentTab, true);
    }
  });

  /* ★ iframe load → 隐藏 loading 遮罩
     —— 只在真正加载新视频时移除遮罩，about:blank 或空 src 不触发 */
  frame.addEventListener('load', function () {
    var src = frame.getAttribute('src') || '';
    if (src && src !== 'about:blank') {
      playerWrap.classList.remove('loading');
    }
  });

  closeBtn.addEventListener('click', close);
})();

/* 音乐库事件绑定（一次性） */
(function initMusicUI() {
  if (dom.musicBtn) {
    dom.musicBtn.addEventListener('click', function () {
      if (!state.isLoggedIn) { showToast(t('toastLoginFirst')); return; }
      dom.musicModal.classList.add('open');
      renderMusicList();
      if (state.socket && state.socket.connected) {
        state.socket.emit('music-list');
      }
      if (dom.musicAudio) {
        dom.musicAudio.volume = state.music.muted ? 0 : state.music.volume;
      }
      if (dom.musicVolume) {
        dom.musicVolume.value = String(Math.round(state.music.volume * 100));
      }
      musicUpdateLoopBtn();
      musicUpdatePlayBtn();
      /* ★ 音乐库已打开 → 迷你条自动隐藏 */
      musicMiniShow();
    });
  }
  /* 关闭音乐库 → 若仍在播放则显示迷你条 */
  function closeMusicModal() {
    dom.musicModal.classList.remove('open');
    musicMiniRefresh();
  }
  if (dom.musicCloseBtn) {
    dom.musicCloseBtn.addEventListener('click', closeMusicModal);
  }
  if (dom.closeMusicModal) {
    dom.closeMusicModal.addEventListener('click', closeMusicModal);
  }
  if (dom.musicModal) {
    dom.musicModal.addEventListener('click', function (e) {
      var ov = dom.musicModal;
      if (typeof isEventOnOverlayBackground === 'function'
          ? isEventOnOverlayBackground(e, ov)
          : e.target === ov) {
        closeMusicModal();
      }
    });
  }

  /* 上传 */
  if (dom.musicFileInput) {
    dom.musicFileInput.addEventListener('change', function () {
      musicUploadFiles(dom.musicFileInput.files);
      dom.musicFileInput.value = '';
    });
  }

  /* 搜索 */
  if (dom.musicSearchInput) {
    dom.musicSearchInput.addEventListener('input', debounce(function () {
      renderMusicList();
    }, 160));
  }

  /* 列表点击：播放 / 点赞 / 删除（事件委托） */
  if (dom.musicList) {
    dom.musicList.addEventListener('click', function (e) {
      var btn = e.target.closest ? e.target.closest('[data-action]') : null;
      var item = e.target.closest ? e.target.closest('.music-item') : null;
      if (!item) return;
      var mid = item.getAttribute('data-mid');
      if (!mid) return;
      if (btn) {
        var act = btn.getAttribute('data-action');
        if (act === 'like') {
          if (state.socket && state.socket.connected) {
            state.socket.emit('music-like', { id: mid });
          }
          return;
        }
        if (act === 'delete') {
          showConfirm(t('musicDeleteConfirm'), {
            icon: '🗑️', danger: true, confirmText: t('msgDelete')
          }).then(function (ok) {
            if (!ok) return;
            if (state.socket && state.socket.connected) {
              state.socket.emit('music-delete', { id: mid });
            }
          });
          return;
        }
      }
      /* 点整行 → 播放 */
      if (mid === state.music.currentId) musicTogglePlay();
      else musicPlayById(mid, true);
    });
  }

  /* 播放器控件 */
  if (dom.musicPlayBtn) {
    dom.musicPlayBtn.addEventListener('click', musicTogglePlay);
  }
  if (dom.musicPrevBtn) {
    dom.musicPrevBtn.addEventListener('click', function () { musicStep(-1); });
  }
  if (dom.musicNextBtn) {
    dom.musicNextBtn.addEventListener('click', function () { musicStep(1); });
  }
  if (dom.musicShuffleBtn) {
    dom.musicShuffleBtn.addEventListener('click', function () {
      state.music.shuffle = !state.music.shuffle;
      dom.musicShuffleBtn.classList.toggle('active', state.music.shuffle);
    });
  }
  if (dom.musicLoopBtn) {
    dom.musicLoopBtn.addEventListener('click', function () {
      var order = ['list', 'one', 'off'];
      var i = order.indexOf(state.music.loopMode);
      state.music.loopMode = order[(i + 1) % order.length];
      musicUpdateLoopBtn();
      if (dom.musicAudio) {
        dom.musicAudio.loop = (state.music.loopMode === 'one');
      }
    });
  }

  /* 进度条 */
  if (dom.musicProgress && dom.musicAudio) {
    dom.musicProgress.addEventListener('input', function () {
      state.music.seeking = true;
    });
    dom.musicProgress.addEventListener('change', function () {
      var audio = dom.musicAudio;
      if (audio.duration && isFinite(audio.duration)) {
        audio.currentTime = (parseInt(dom.musicProgress.value, 10) / 1000) *
          audio.duration;
      }
      state.music.seeking = false;
    });
  }

  /* 音量 */
  if (dom.musicVolume && dom.musicAudio) {
    dom.musicVolume.addEventListener('input', function () {
      var v = parseInt(dom.musicVolume.value, 10) / 100;
      state.music.volume = v;
      state.music.muted = (v === 0);
      dom.musicAudio.volume = v;
      if (dom.musicVolIcon) {
        dom.musicVolIcon.textContent = (v === 0) ? '🔇' : (v < 0.5 ? '🔉' : '🔊');
      }
    });
  }
  if (dom.musicVolIcon && dom.musicAudio) {
    dom.musicVolIcon.addEventListener('click', function () {
      state.music.muted = !state.music.muted;
      dom.musicAudio.volume = state.music.muted ? 0 : state.music.volume;
      dom.musicVolIcon.textContent =
        state.music.muted ? '🔇' : (state.music.volume < 0.5 ? '🔉' : '🔊');
    });
  }

  /* <audio> 事件 */
  if (dom.musicAudio) {
    var audio = dom.musicAudio;
    audio.addEventListener('play', musicUpdatePlayBtn);
    audio.addEventListener('pause', musicUpdatePlayBtn);
    audio.addEventListener('loadedmetadata', function () {
      if (dom.musicTotalTime) {
        dom.musicTotalTime.textContent = fmtDuration(audio.duration || 0);
      }
    });
    audio.addEventListener('timeupdate', function () {
      if (!audio.duration || !isFinite(audio.duration)) return;
      var pct = audio.currentTime / audio.duration;
      /* 拖动中不覆盖进度条位置 */
      if (!state.music.seeking) {
        if (dom.musicProgress) {
          dom.musicProgress.value = String(Math.round(pct * 1000));
        }
        if (dom.musicCurTime) {
          dom.musicCurTime.textContent = fmtDuration(audio.currentTime);
        }
      }
      /* ★ 迷你播放条进度（高频，只改一个 width） */
      musicMiniRefreshProgress();
    });
    audio.addEventListener('ended', function () {
      if (state.music.loopMode === 'one') {
        try { audio.currentTime = 0; audio.play(); } catch (e) {}
        return;
      }
      musicStep(1);
    });
    audio.addEventListener('error', function () {
      musicUpdatePlayBtn();
    });
    audio.volume = state.music.volume;
  }
})();

/* 存储空间：calcStorageStats 扫描统计，renderStorageStats 渲染，各清理按钮带二次确认 */

/* 统计字符串字节数（UTF-16 近似为实际占用） */
function _strSize(s) {
  if (!s) return 0;
  return String(s).length;
}

/* 估算 JSON 对象占用（近似值） */
function _jsonSize(obj) {
  try { return JSON.stringify(obj).length; }
  catch (e) { return 0; }
}

function calcStorageStats() {
  var stats = {
    msgCount: 0, msgSize: 0,
    imageCount: 0, imageSize: 0,
    videoCount: 0, videoSize: 0,
    voiceCount: 0, voiceSize: 0,
    fileCount: 0, fileSize: 0,
    stickerCount: 0, stickerSize: 0,
    starredCount: 0, starredSize: 0,
    draftCount: 0, draftSize: 0,
    totalSize: 0
  };

  /* 逐条扫描消息数组 */
  function scan(arr) {
    if (!arr || !arr.length) return;
    for (var i = 0; i < arr.length; i++) {
      var m = arr[i];
      if (!m) continue;
      stats.msgCount++;
      stats.msgSize += _jsonSize(m);

      if (m.type === 'file' || m.type === 'voice') {
        var ft = m.fileType || '';
        var dSize = _strSize(m.fileData);
        if (m.type === 'voice' || ft.indexOf('audio/') === 0) {
          stats.voiceCount++; stats.voiceSize += dSize;
        } else if (ft.indexOf('image/') === 0) {
          stats.imageCount++; stats.imageSize += dSize;
        } else if (ft.indexOf('video/') === 0) {
          stats.videoCount++; stats.videoSize += dSize;
        } else {
          stats.fileCount++; stats.fileSize += dSize;
        }
      } else if (m.type === 'sticker') {
        stats.stickerCount++; stats.stickerSize += _strSize(m.fileData);
      }
    }
  }

  var k;
  for (k in state.messages) {
    if (state.messages.hasOwnProperty(k)) scan(state.messages[k]);
  }
  for (k in state.groups) {
    if (state.groups.hasOwnProperty(k) && state.groups[k] && state.groups[k].messages) {
      scan(state.groups[k].messages);
    }
  }

  /* 表情包 */
  if (Array.isArray(state.stickers)) {
    for (var si = 0; si < state.stickers.length; si++) {
      stats.stickerCount++;
      stats.stickerSize += _strSize(state.stickers[si]);
    }
  }

  /* 收藏 */
  for (var mk in state.starredMsgs) {
    if (state.starredMsgs.hasOwnProperty(mk)) {
      stats.starredCount++;
      stats.starredSize += _jsonSize(state.starredMsgs[mk]);
    }
  }

  /* 草稿 */
  for (var dk in state.drafts) {
    if (state.drafts.hasOwnProperty(dk)) {
      stats.draftCount++;
      stats.draftSize += _strSize(state.drafts[dk]);
    }
  }

  stats.totalSize = stats.msgSize + stats.stickerSize +
                    stats.starredSize + stats.draftSize;
  return stats;
}

function renderStorageStats() {
  if (!dom.storageStats) return;
  var s = calcStorageStats();

  /* 无数据 */
  if (!s.totalSize && !s.msgCount) {
    dom.storageStats.innerHTML =
      '<div style="text-align:center;color:var(--text-muted);padding:36px 0;font-size:14px;">' +
      escapeHtml(t('storageEmpty')) + '</div>';
    if (dom.storageActions) dom.storageActions.style.display = 'none';
    return;
  }
  if (dom.storageActions) dom.storageActions.style.display = '';

  /* ---- 顶部总计卡片 ---- */
  var totalHtml =
    '<div style="background:linear-gradient(135deg,rgba(var(--accent-rgb),.14),rgba(var(--accent-rgb),.06));' +
    'border:1px solid rgba(var(--accent-rgb),.25);border-radius:14px;' +
    'padding:14px 18px;text-align:center;margin-bottom:14px;">' +
      '<div style="font-size:12px;color:var(--text-secondary);letter-spacing:.5px;margin-bottom:4px;">' +
        escapeHtml(t('storageTotal')) + '</div>' +
      '<div style="font-size:28px;font-weight:700;color:var(--accent);' +
        'font-variant-numeric:tabular-nums;letter-spacing:-.5px;">' +
        formatFileSize(s.totalSize) + '</div>' +
    '</div>';

  /* ---- 分类列表 ---- */
  function row(icon, label, size, count, countTpl) {
    return '<div style="display:flex;align-items:center;gap:12px;' +
      'padding:9px 4px;border-bottom:1px solid var(--border-modal);">' +
      '<span style="font-size:18px;width:24px;text-align:center;flex-shrink:0;">' + icon + '</span>' +
      '<span style="flex:1;font-size:14px;color:var(--text-primary);">' +
        escapeHtml(label) + '</span>' +
      (count > 0
        ? '<span style="font-size:12px;color:var(--text-muted);font-variant-numeric:tabular-nums;">' +
            escapeHtml(countTpl.split('{n}').join(count)) + '</span>'
        : '') +
      '<span style="font-size:13px;color:var(--text-secondary);min-width:70px;text-align:right;' +
        'font-variant-numeric:tabular-nums;">' + formatFileSize(size) + '</span>' +
    '</div>';
  }

  var listHtml = '';
  listHtml += row('📨', t('storageMessages'), s.msgSize, s.msgCount, t('storageCountMsg'));
  if (s.imageCount) listHtml += row('🖼️', t('storageImages'), s.imageSize, s.imageCount, t('storageCountImg'));
  if (s.videoCount) listHtml += row('🎬', t('storageVideos'), s.videoSize, s.videoCount, t('storageCountVid'));
  if (s.voiceCount) listHtml += row('🎤', t('storageVoices'), s.voiceSize, s.voiceCount, t('storageCountVoi'));
  if (s.fileCount)  listHtml += row('📎', t('storageFiles'),    s.fileSize,  s.fileCount,  t('storageCountFil'));
  if (s.stickerCount) listHtml += row('😊', t('storageStickers'), s.stickerSize, s.stickerCount, t('storageCountMsg'));
  if (s.starredCount) listHtml += row('⭐', t('storageStarred'), s.starredSize, s.starredCount, t('storageCountMsg'));
  if (s.draftCount)   listHtml += row('📝', t('storageDrafts'),  s.draftSize,  s.draftCount,  t('storageCountMsg'));

  dom.storageStats.innerHTML = totalHtml + listHtml;
}

/* ---- 清理：全部聊天记录 ---- */
function cleanAllChats() {
  showConfirm(t('storageCleanConfirm'), {
    icon: '🗑️', danger: true, confirmText: t('storageCleanChats')
  }).then(function (ok) {
    if (!ok) return;
    state.messages = {};
    for (var gid in state.groups) {
      if (state.groups.hasOwnProperty(gid) && state.groups[gid]) {
        state.groups[gid].messages = [];
      }
    }
    if (state.currentTarget) renderMessages();
    renderContacts();
    renderStorageStats();
    showToast(t('storageCleaned'));
  });
}

/* ---- 清理：媒体原始数据（保留文本、元数据） ---- */
function cleanMediaData() {
  showConfirm(t('storageCleanMediaConfirm'), {
    icon: '🧹', danger: true, confirmText: t('storageCleanMedia')
  }).then(function (ok) {
  if (!ok) return;
  var n = 0;
  function scan(arr) {
    if (!arr) return;
    for (var i = 0; i < arr.length; i++) {
      var m = arr[i];
      if (!m) continue;
      if ((m.type === 'file' || m.type === 'voice' || m.type === 'sticker') &&
          m.fileData) {
        m.fileData = '';
        n++;
      }
    }
  }
  var k;
  for (k in state.messages) {
    if (state.messages.hasOwnProperty(k)) scan(state.messages[k]);
  }
  for (k in state.groups) {
    if (state.groups.hasOwnProperty(k) && state.groups[k]) scan(state.groups[k].messages);
  }
  if (state.currentTarget) renderMessages();
  renderStorageStats();
  showToast(t('storageCleaned') + ' (' + n + ')');
  });
}

/* ---- 清理：收藏 ---- */
function cleanStarred() {
  showConfirm(t('storageCleanConfirm'), {
    icon: '⭐', danger: true, confirmText: t('storageCleanStarred')
  }).then(function (ok) {
    if (!ok) return;
    state.starredMsgs = {};
    try { localStorage.setItem('starred_msgs', '{}'); } catch (e) {}
    if (state.currentTarget) renderMessages();
    renderStorageStats();
    showToast(t('storageCleaned'));
  });
}

/* ---- 清理：草稿 ---- */
function cleanDrafts() {
  showConfirm(t('storageCleanConfirm'), {
    icon: '📝', danger: true, confirmText: t('storageCleanDrafts')
  }).then(function (ok) {
    if (!ok) return;
    state.drafts = {};
    try { localStorage.setItem('chat_drafts', '{}'); } catch (e) {}
    renderStorageStats();
    showToast(t('storageCleaned'));
  });
}

/* ---- 清理：表情包 ---- */
function cleanStickers() {
  showConfirm(t('storageCleanConfirm'), {
    icon: '😊', danger: true, confirmText: t('storageCleanStickers')
  }).then(function (ok) {
    if (!ok) return;
    /* 表情包服务端持久化，需逐个删除 */
    if (state.socket && state.socket.connected) {
      for (var i = state.stickers.length - 1; i >= 0; i--) {
        state.socket.emit('sticker-delete', { index: i });
      }
    }
    state.stickers = [];
    renderEmojiPicker();
    renderStorageStats();
    showToast(t('storageCleaned'));
  });
}

/* ---- 渲染操作按钮 ---- */
function renderStorageActions() {
  if (!dom.storageActions) return;
  var btns = [
    { id: 'scChats',   label: t('storageCleanChats'),   cls: 'btn-confirm', fn: cleanAllChats },
    { id: 'scMedia',   label: t('storageCleanMedia'),   cls: 'btn-cancel',  fn: cleanMediaData },
    { id: 'scStarred', label: t('storageCleanStarred'), cls: 'btn-cancel',  fn: cleanStarred },
    { id: 'scDrafts',  label: t('storageCleanDrafts'),  cls: 'btn-cancel',  fn: cleanDrafts },
    { id: 'scStickers',label: t('storageCleanStickers'),cls: 'btn-cancel',  fn: cleanStickers }
  ];
  var html = '';
  for (var i = 0; i < btns.length; i++) {
    html += '<button id="' + btns[i].id + '" class="' + btns[i].cls + '" ' +
      'style="padding:6px 16px;border-radius:20px;font-size:13px;cursor:pointer;border:none;' +
      (btns[i].cls === 'btn-confirm'
        ? 'background:var(--bg-btn-danger);color:#fff;font-weight:500;'
        : 'background:var(--border-input);color:var(--text-primary);') +
      '">' + escapeHtml(btns[i].label) + '</button>';
  }
  dom.storageActions.innerHTML = html;
  for (var j = 0; j < btns.length; j++) {
    (function (b) {
      var el = document.getElementById(b.id);
      if (el) el.addEventListener('click', b.fn);
    })(btns[j]);
  }
}

/* ---- 打开存储空间弹窗 ---- */
function openStorageModal() {
  if (!dom.storageModal) return;
  renderStorageActions();
  renderStorageStats();
  dom.storageModal.classList.add('open');
}

/* ---- 绑定 ---- */
(function initStorageUI() {
  if (dom.openStorageBtn) {
    dom.openStorageBtn.addEventListener('click', function () {
      dom.settingsModal.classList.remove('open');
      openStorageModal();
    });
  }
  if (dom.closeStorageModal) {
    dom.closeStorageModal.addEventListener('click', function () {
      dom.storageModal.classList.remove('open');
    });
  }
  if (dom.storageModal) {
    dom.storageModal.addEventListener('click', function (e) {
      var ov = dom.storageModal;
      if (typeof isEventOnOverlayBackground === 'function'
          ? isEventOnOverlayBackground(e, ov)
          : e.target === ov) {
        ov.classList.remove('open');
      }
    });
  }
})();

/* 群聊右侧信息栏：默认收起，☰ 切换，切换会话时重置 */

state._gspOpen = false;

function _isLandscape() {
  try {
    /* ★ 统一用「宽 ≥ 769 或 宽 > 高」判定：
       桌面端自然满足第一条，移动端横屏满足第二条。
       不再读 matchMedia('(orientation: landscape)')，
       避免分屏 / resize / 特定比例下与 CSS 判定不一致。 */
    var w = window.innerWidth || 0;
    var h = window.innerHeight || 0;
    if (w >= 769) return true;
    return w > h;
  } catch (e) { return false; }
}

function renderGroupSidePanel() {
  var panel = document.getElementById('groupSidePanel');
  var toggle = document.getElementById('groupSideToggle');
  if (!panel) return;

  /* ---- 非群聊 / 未选中 → 隐藏面板和按钮 ---- */
  if (state.currentType !== 'group' || !state.currentTarget) {
    panel.classList.remove('show');
    if (toggle) toggle.style.display = 'none';
    return;
  }
  var g = state.groups[state.currentTarget];
  if (!g) {
    panel.classList.remove('show');
    if (toggle) toggle.style.display = 'none';
    return;
  }

  /* ---- 头部 ☰ 按钮：显隐完全交给 CSS（按设备 + 朝向）控制，
         这里不再写内联 style.display，避免 !important 覆盖冲突 ---- */
  if (toggle) {
    /* 清掉可能残留的内联样式 */
    toggle.style.display = '';
    /* 展开时高亮 */
    toggle.classList.toggle('active', state._gspOpen);
  }

  /* ---- 面板可见性：只由 state._gspOpen 决定；
         移动端竖屏下由 CSS 强制隐藏 ---- */
  if (!state._gspOpen) {
    panel.classList.remove('show');
    return;
  }
  panel.classList.add('show');

  /* ==================== 渲染内容 ==================== */

  /* 头部：群名 + 人数 + 群主标识 + 在线聚合 */
  var memberCount = (g.members || []).length;
  var isOwner = (g.owner === state.myId);
  /* ★ 新增：在线 / 离线人数聚合 */
  var _onlineCnt = 0;
  for (var _mi = 0; _mi < (g.members || []).length; _mi++) {
    var _mu = state.users[g.members[_mi]];
    if (_mu && _mu.online) _onlineCnt++;
  }
  var _offlineCnt = memberCount - _onlineCnt;

  /* ★ v0.27.0：统计在线 / 离线人数 */
  var _onlineN = 0, _offlineN = 0;
  for (var _mi = 0; _mi < (g.members || []).length; _mi++) {
    var _mu = state.users[g.members[_mi]];
    if (_mu && _mu.online) _onlineN++;
    else _offlineN++;
  }

  var headerHtml =
    '<div class="gsp-header">' +
      '<button class="gsp-collapse-btn" id="gspCollapseBtn" ' +
        'title="' + escapeHtml(t('gspCollapse')) + '" ' +
        'aria-label="' + escapeHtml(t('gspCollapse')) + '">»</button>' +
      '<div class="gsp-group-name" title="' + escapeHtml(g.name) + '">' +
        escapeHtml(g.name) +
      '</div>' +
      '<div class="gsp-group-meta">' +
        '<span>' + escapeHtml(t('gspMemberCount').split('{n}').join(memberCount)) + '</span>' +
        (isOwner ? '<span class="gsp-owner-badge">' + escapeHtml(t('gspOwner')) + '</span>' : '') +
        '<span class="gsp-online-count" title="在线 / 离线">' +
          '<span class="gsp-online-dot"></span>' +
          _onlineN + ' / ' + _offlineN +
        '</span>' +
      '</div>' +
    '</div>';

  /* 快捷操作：群文件 / 群相册 / 群投票 / 群管理 */
  var quickHtml =
    '<div class="gsp-quick-actions">' +
      '<button class="gsp-qa-btn" data-action="files">' +
        '<span class="gsp-qa-icon">📁</span>' +
        '<span>' + escapeHtml(t('gspFiles')) + '</span>' +
      '</button>' +
      '<button class="gsp-qa-btn" data-action="album">' +
        '<span class="gsp-qa-icon">🖼️</span>' +
        '<span>' + escapeHtml(t('gspAlbum')) + '</span>' +
      '</button>' +
      '<button class="gsp-qa-btn" data-action="vote">' +
        '<span class="gsp-qa-icon">🗳️</span>' +
        '<span>' + escapeHtml(t('gspVote')) + '</span>' +
      '</button>' +
      '<button class="gsp-qa-btn" data-action="manage">' +
        '<span class="gsp-qa-icon">⚙️</span>' +
        '<span>' + escapeHtml(t('gspManage')) + '</span>' +
      '</button>' +
    '</div>';

  /* 群公告 */
  var _topAnn = g.announcements ? (g.announcements.find(function(a){return a.pinned;}) || g.announcements[0]) : null;
  var announceHtml =
    '<div class="gsp-announce" onclick="openAnnouncementModal(\'' + g.id + '\')" style="cursor:pointer;">' +
      '<div class="gsp-announce-title">📢 ' + escapeHtml(t('gspAnnounce')) + ' (' + (g.announcements||[]).length + ')</div>' +
      '<div class="gsp-announce-text">' + escapeHtml(_topAnn ? _topAnn.text : t('gspNoAnnounce')) + '</div>' +
    '</div>';

  /* 成员列表排序：群主 → 管理员 → 有头衔 → 在线 → 离线 → 昵称 */
  var mem = (g.members || []).slice();
  mem.sort(function (a, b) {
    var ua = state.users[a], ub = state.users[b];
    var aOwner = (a === g.owner) ? 1 : 0;
    var bOwner = (b === g.owner) ? 1 : 0;
    if (aOwner !== bOwner) return bOwner - aOwner;
    var aAdmin = (ua && ua.isAdmin) ? 1 : 0;
    var bAdmin = (ub && ub.isAdmin) ? 1 : 0;
    if (aAdmin !== bAdmin) return bAdmin - aAdmin;
    var aTitle = (g.titles && g.titles[a]) ? 1 : 0;
    var bTitle = (g.titles && g.titles[b]) ? 1 : 0;
    if (aTitle !== bTitle) return bTitle - aTitle;
    var aOn = (ua && ua.online) ? 1 : 0;
    var bOn = (ub && ub.online) ? 1 : 0;
    if (aOn !== bOn) return bOn - aOn;
    var aName = ua ? ua.name : a;
    var bName = ub ? ub.name : b;
    return String(aName).localeCompare(String(bName), 'zh');
  });

  var membersHtml =
    '<div class="gsp-members-wrap">' +
      '<div class="gsp-members-title">' +
        escapeHtml(t('gspMembers')) + ' (' + memberCount + ')' +
      '</div>' +
      '<div style="padding:0 12px 8px;">' +
        '<input type="text" id="gspSearchInput" placeholder="搜索群成员..." style="width:100%;padding:6px 12px;border:1px solid var(--border-input);border-radius:16px;background:var(--bg-input);color:var(--text-primary);font-size:13px;outline:none;box-sizing:border-box;">' +
      '</div>';

  for (var i = 0; i < mem.length; i++) {
    var uid = mem[i];
    var u = state.users[uid] || {};
    var name = u.name || uid;
    var initial = (name || '?').charAt(0).toUpperCase();
    var avatar = (u.profile && u.profile.avatar) || '';
    var title = (g.titles && g.titles[uid]) || '';
    var isOwnerM = (uid === g.owner);
    var offlineM = !u.online;
    var verifiedM = u.verified || '';
    var presence = u.presence || 'online';

    var avInner = avatar
      ? '<img src="' + avatar + '" alt="">'
      : escapeHtml(initial);
    var avCls = 'gsp-member-avatar' + (verifiedM ? ' verified' : '');

    var dotHtml = u.online
      ? '<span class="gsp-presence-dot ' + presence + '"></span>'
      : '';

    var roleHtml = '';
    if (isOwnerM) {
      roleHtml = '<span class="gsp-role-tag owner">' + escapeHtml(t('gspOwner')) + '</span>';
    } else if (title) {
      roleHtml = '<span class="gsp-role-tag title">' + escapeHtml(title) + '</span>';
    }

    var _isSysM = isSystemUserId(uid);
    var verifyMiniHtml = verifiedM
      ? '<span class="gsp-verified-mini' + (_isSysM ? ' system' : '') +
        '" title="' + escapeHtml(verifiedM) + '">✓</span>'
      : '';

    /* ★ v0.29.0：成员等级 + 群火花 / 龙王，统一显示在等级旁边 */
    var _lvM = u.level || 0;
    var lvHtmlM = _lvM > 0
      ? '<span class="lv-badge' + (u.vip ? ' vip' : '') +
        '" style="font-size:10px;line-height:14px;padding:0 5px;">' +
        (u.vip ? '👑' : '') + 'LV' + _lvM + '</span>'
      : '';

    var _gFireBadgeM = '';
    var _dragonBadge = '';
    try {
      var _gI = (state.showInteraction !== false &&
        state.interactions && state.interactions.group)
        ? state.interactions.group[g.id] : null;
      if (_gI) {
        /* ★ 修复：只有今天真正发过言的成员（counts > 0）才显示火花 */
        var _countsM = (_gI.dailyTop && _gI.dailyTop.date === todayStr() && _gI.dailyTop.counts)
          ? _gI.dailyTop.counts : {};
        var _hasSpokenM = _countsM[uid] > 0;
        if (_hasSpokenM && _gI.lastDate === todayStr() && _gI.days > 1) {
          _gFireBadgeM = '<span class="contact-fire-badge" title="群聊连续 ' +
            _gI.days + ' 天">🔥' + _gI.days + '</span>';
        }
        if (_gI.dailyTop && _gI.dailyTop.date === todayStr() &&
            _gI.dailyTop.uid === uid) {
          _dragonBadge = '<span class="gsp-dragon-badge" title="今日龙王（' +
            _gI.dailyTop.count + ' 条消息）">🐲</span>';
        }
      }
    } catch (eDB) { }

    membersHtml +=
      '<div class="gsp-member' + (offlineM ? ' gsp-offline' : '') +
        '" data-uid="' + escapeHtml(uid) + '">' +
        '<div class="' + avCls + '">' + avInner + dotHtml + '</div>' +
        '<div class="gsp-member-info">' +
          '<div class="gsp-member-name">' +
            escapeHtml(name) +
            verifyMiniHtml +
            lvHtmlM +
            _dragonBadge +
            roleHtml +
          '</div>' +
        '</div>' +
      '</div>';
  }
  membersHtml += '</div>';

  panel.innerHTML = headerHtml + quickHtml + announceHtml + membersHtml;

  /* ---- 面板内 » 按钮 → 收起 ---- */
  var collapseBtn = document.getElementById('gspCollapseBtn');
  if (collapseBtn) {
    collapseBtn.addEventListener('click', function (e) {
      e.stopPropagation();
      state._gspOpen = false;
      renderGroupSidePanel();
    });
  }

  /* ---- 快捷操作按钮 ---- */
  var qaBtns = panel.querySelectorAll('.gsp-qa-btn');
  for (var qi = 0; qi < qaBtns.length; qi++) {
    (function (btn) {
      btn.addEventListener('click', function (e) {
        e.stopPropagation();
        var act = btn.dataset.action;
        if (act === 'files') {
          if (dom.qqFileModal) {
            dom.qqFileModal.classList.add('open');
            renderQQFiles();
          }
        } else if (act === 'album') {
          if (dom.qqAlbumModal) {
            dom.qqAlbumModal.classList.add('open');
            renderQQAlbum();
          }
        } else if (act === 'vote') {
          if (dom.qqVoteModal) {
            dom.qqVoteModal.classList.add('open');
            renderQQVotes();
          }
        } else if (act === 'manage') {
          if (state.currentTarget) openGroupManage(state.currentTarget);
        }
      });
    })(qaBtns[qi]);
  }

  /* ---- 成员：单击看名片，双击 @提及 ---- */
  var items = panel.querySelectorAll('.gsp-member');
  for (var j = 0; j < items.length; j++) {
    (function (el) {
      el.addEventListener('click', function (e) {
        e.stopPropagation();
        var uid = el.dataset.uid;
        if (uid && state.users[uid]) openProfile(uid);
      });
      el.addEventListener('dblclick', function (e) {
        e.preventDefault();
        e.stopPropagation();
        var uid = el.dataset.uid;
        var u2 = state.users[uid];
        if (!u2) return;
        insertMention('@' + u2.name);
        showToast(t('toastMentioned') + u2.name);
      });
    })(items[j]);
  }

  // ★ v0.29.0：群侧栏成员搜索
  var gspSearch = document.getElementById('gspSearchInput');
  if (gspSearch) {
    gspSearch.addEventListener('input', function() {
      var q = this.value.trim().toLowerCase();
      var memItems = panel.querySelectorAll('.gsp-member');
      for (var k = 0; k < memItems.length; k++) {
        var nEl = memItems[k].querySelector('.gsp-member-name');
        var nameText = nEl ? nEl.textContent.toLowerCase() : '';
        memItems[k].style.display = nameText.indexOf(q) !== -1 ? '' : 'none';
      }
    });
  }
}

