/* ---- 屏幕旋转时重新判定 ---- */
(function initGspResizeObserver() {
  var _t = null;
  function recheck() {
    if (_t) clearTimeout(_t);
    _t = setTimeout(function () {
      _t = null;
      /* ★ v0.24.17：不再区分横屏/竖屏，直接重渲染 ——
         renderGroupSidePanel 内部会调用 _isLandscape() 自行
         决定是否显示按钮和面板。 */
      renderGroupSidePanel();
    }, 180);
  }
  window.addEventListener('resize', recheck);
  window.addEventListener('orientationchange', function () {
    setTimeout(recheck, 300);
  });
})();

