/* HTML 分段流式传输：按 head/header/main/modals/float/scripts/tail 切分，chunked 逐段下发 */
var HTML_CHUNKS = null;

function buildHtmlChunks(src) {
  var SEPS = [
    { name: 'head',    find: '</head>',                                     after: true  },
    { name: 'header',  find: '<div class="header">',                        after: false },
    { name: 'main',    find: '<div class="main">',                          after: false },
    { name: 'modals',  find: '<div class="modal-overlay" id="adminModal">', after: false },
    { name: 'float',   find: '<div class="browser-modal" id="browserModal">', after: false },
    { name: 'scripts', find: '<script src="https://cdn.socket.io/',         after: false },
    { name: 'tail',    find: '</body>',                                     after: false }
  ];
  var chunks = [];
  var pos = 0;
  for (var i = 0; i < SEPS.length; i++) {
    var sep = SEPS[i];
    var idx = src.indexOf(sep.find, pos);
    if (idx === -1) continue;
    var cut = sep.after ? (idx + sep.find.length) : idx;
    if (cut > pos) {
      chunks.push({ name: sep.name, content: src.slice(pos, cut) });
      pos = cut;
    }
  }
  if (pos < src.length) {
    chunks.push({ name: 'end', content: src.slice(pos) });
  }
  return chunks;
}

/* 流式下发：每段之间 setImmediate，让事件循环有机会处理其它请求 */
function sendHtmlStream(req, res) {
  if (!HTML_CHUNKS || !HTML_CHUNKS.length) {
    /* 兜底：分段失败直接走预压缩路径 */
    sendHtml(req, res);
    return;
  }

  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  /* ★ v0.27.7：HEAD 探测请求只返回头部 */
  if (req.method === 'HEAD') {
    res.setHeader('X-Streaming', '1');
    res.end();
    return;
  }
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('X-Streaming', '1');
  /* 明确不使用 Content-Length —— 由 chunked 传输 */
  res.removeHeader('Content-Length');

  var idx = 0;
  function next() {
    if (idx >= HTML_CHUNKS.length) {
      res.end();
      return;
    }
    var chunk = HTML_CHUNKS[idx++];
    try {
      res.write(chunk.content);
    } catch (e) {
      try { res.end(); } catch (e2) {}
      return;
    }
    /* 关键：让出事件循环 —— 让 Node 处理其它请求 + 让 TCP 尽快把已写的
       数据发出去。setImmediate 在 I/O 阶段之后执行，比 setTimeout(0)
       更快，也不阻塞其他 I/O。 */
    setImmediate(next);
  }
  next();
}

/* 骨架压缩：script/style 已替换为哨兵，只需保护 pre/textarea */
function minifyHtmlSkeleton(src) {
  var src2 = String(src || '');

  /* 保护 pre / textarea */
  var blocks = [];
  src2 = src2.replace(/<(pre|textarea)\b[^>]*>[\s\S]*?<\/\1>/gi,
    function (m) {
      blocks.push(m);
      return '\x00BLK' + (blocks.length - 1) + '\x00';
    });

  /* 去 HTML 注释（保留条件注释） */
  src2 = src2.replace(/<!--(?!\[if)[\s\S]*?-->/g, '');
  /* 标签间空白：> ... < → >< */
  src2 = src2.replace(/>\s+</g, '><');
  /* 标签内属性空白折叠 */
  src2 = src2.replace(
    /<([a-zA-Z][\w-]*)((?:\s+[^\s<>"']+(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s<>"']+))?)*)\s*>/g,
    function (_, tag, attrs) {
      return '<' + tag + attrs.replace(/\s+/g, ' ') + '>';
    }
  );
  src2 = src2.replace(/^\s+|\s+$/g, '');

  /* 还原 */
  src2 = src2.replace(/\x00BLK(\d+)\x00/g, function (_, i) { return blocks[+i]; });
  return src2;
}

/* ==================== 异步构建 HTML（terser + clean-css） ==================== */
var HTML_TO_SERVE = null;         /* 未压缩字符串（兜底，等价于 full） */
var HTML_BR = null;         /* Brotli Buffer（full 版本，向后兼容） */
var HTML_GZ = null;         /* Gzip Buffer（full 版本） */
var HTML_ETAG = null;         /* ETag 字符串 */
var HTML_BUILD_STATS = null;

/* 设备分流：按 desktop/mobile/watch 生成 3 份 HTML，UA 匹配失败回退 full */

/* 自动标记 CSS：扫描 @media / html.is-* 规则 */
function _autoTagDeviceBlocks(src) {
  if (!src) return src;
  var s = String(src);

  /* ---- 1a. @media (max-width: N) —— 判定为 mobile 或 watch ---- */
  /* 用平衡括号扫描器处理嵌套 */
  var mediaRe = /@media[^{]*\(\s*(?:max|min)-width\s*:\s*(\d+)px\s*\)[^{]*\{/g;
  var result = '';
  var lastIdx = 0;
  var m;
  while ((m = mediaRe.exec(s)) !== null) {
    var startIdx = m.index;
    var braceIdx = startIdx + m[0].length - 1;    /* 指向 '{' */
    /* 从 braceIdx 找配对的 '}' */
    var depth = 1;
    var j = braceIdx + 1;
    while (j < s.length && depth > 0) {
      var ch = s.charAt(j);
      if (ch === '{') depth++;
      else if (ch === '}') depth--;
      j++;
    }
    if (depth !== 0) continue;
    var endIdx = j;    /* 指向 '}' 之后 */
    var full = s.substring(startIdx, endIdx);
    var width = parseInt(m[1], 10);
    var isMax = /max-width/.test(m[0]);

    /* 判定设备类型 */
    var dev = 'mobile';
    if (isMax) {
      if (width <= 340) dev = 'watch';
      else if (width <= 768) dev = 'mobile';
      else dev = 'mobile';   /* 更宽的最大宽度断点仍属移动端 */
    } else {
      /* min-width 断点 → desktop */
      dev = 'desktop';
    }

    /* 输出：前面原样，然后标记块 */
    result += s.substring(lastIdx, startIdx);
    result += '/* @device:' + dev + '-start */' + full +
      '/* @device:' + dev + '-end */';
    lastIdx = endIdx;
    mediaRe.lastIndex = endIdx;
  }
  result += s.substring(lastIdx);
  s = result;

  /* ---- 1b. html.is-mobile / html.is-pc / html.is-watch 前缀选择器 ---- */
  /* 只标记「整条规则都以 html.is-X 开头」的；混合选择器的规则不动 */
  var prefixRe = /(^|\})\s*(html\.is-(mobile|pc|watch)(?:\s*[^{,]*?)?)\s*\{/g;
  /* 这个太复杂，简化为：只找独立规则 */
  /* 因为平衡括号扫描器已经处理了所有 @media 块，这里只需处理顶层的
     html.is-* 选择器规则。做法：按 } 分块，检查每块是否以 html.is-* 开头。 */
  var re2 = /(^|[}\n;])(\s*html\.is-(mobile|pc|watch)\b[^{]*)\{/g;
  var out = '';
  var lastPos = 0;
  var m2;
  while ((m2 = re2.exec(s)) !== null) {
    var lead = m2[1];
    var sel = m2[2];
    var devType = (m2[3] === 'mobile') ? 'mobile'
      : (m2[3] === 'watch') ? 'watch' : 'desktop';
    /* 位置计算 */
    var ruleStart = m2.index + lead.length;
    var braceStart = s.indexOf('{', ruleStart);
    if (braceStart === -1) continue;
    var depth2 = 1;
    var k = braceStart + 1;
    while (k < s.length && depth2 > 0) {
      var c2 = s.charAt(k);
      if (c2 === '{') depth2++;
      else if (c2 === '}') depth2--;
      k++;
    }
    if (depth2 !== 0) continue;
    var ruleEnd = k;
    var ruleFull = s.substring(ruleStart, ruleEnd);

    out += s.substring(lastPos, ruleStart);
    /* 检测是否已经有标记（避免二次标记） */
    if (s.lastIndexOf('@device:' + devType + '-start', ruleStart - 20) ===
        ruleStart - 20 - ('/* @device:' + devType + '-start */').length) {
      out += ruleFull;
    } else {
      out += '/* @device:' + devType + '-start */' + ruleFull +
        '/* @device:' + devType + '-end */';
    }
    lastPos = ruleEnd;
    re2.lastIndex = ruleEnd;
  }
  out += s.substring(lastPos);
  return out;
}

/* ---- 2. 按设备裁剪 HTML ---- */
var _DEVICE_TYPES = ['desktop', 'mobile', 'watch'];

function _splitByDevice(fullHtml, keepDevice) {
  if (!fullHtml) return fullHtml;
  if (!keepDevice || keepDevice === 'full') return fullHtml;
  if (_DEVICE_TYPES.indexOf(keepDevice) === -1) return fullHtml;

  var html = String(fullHtml);

  /* ---- 2a. 提取要保留的块（保护） ---- */
  var keepBlocks = [];
  var keepRe = new RegExp(
    '@device:' + keepDevice + '-start[\\s\\S]*?@device:' + keepDevice + '-end',
    'g'
  );
  html = html.replace(keepRe, function (block) {
    keepBlocks.push(block);
    return '\x00KEEP' + (keepBlocks.length - 1) + '\x00';
  });

  /* ---- 2b. 移除所有其它设备的块（连同标记） ---- */
  for (var i = 0; i < _DEVICE_TYPES.length; i++) {
    var d = _DEVICE_TYPES[i];
    if (d === keepDevice) continue;
    var delRe = new RegExp(
      '@device:' + d + '-start[\\s\\S]*?@device:' + d + '-end',
      'g'
    );
    html = html.replace(delRe, '');
  }

  /* ---- 2c. 清理残留的空标记（可能有孤立的 start / end） ---- */
  html = html.replace(/@device:[a-z]+-(?:start|end)/g, '');

  /* ---- 2d. 还原 keep 块，并去掉其内部的标记文字 ---- */
  html = html.replace(/\x00KEEP(\d+)\x00/g, function (_, idx) {
    var b = keepBlocks[+idx] || '';
    var startRe = new RegExp('@device:' + keepDevice + '-start', 'g');
    var endRe = new RegExp('@device:' + keepDevice + '-end', 'g');
    return b.replace(startRe, '').replace(endRe, '');
  });

  return html;
}

/* ---- 3. 三份 HTML 缓存 ---- */
var HTML_BY_DEVICE = {
  desktop: { raw: null, br: null, gz: null, etag: null },
  mobile:  { raw: null, br: null, gz: null, etag: null },
  watch:   { raw: null, br: null, gz: null, etag: null },
  full:    { raw: null, br: null, gz: null, etag: null }
};

/* ---- 4. UA 检测 ---- */
function _detectDevice(req) {
  /* 手动指定优先 */
  try {
    var q = String((req.query && req.query.device) || '').toLowerCase();
    if (q === 'desktop' || q === 'pc') return 'desktop';
    if (q === 'mobile' || q === 'phone') return 'mobile';
    if (q === 'watch' || q === 'wear') return 'watch';
    if (q === 'full') return 'full';
  } catch (e) {}

  var ua = String((req.headers && req.headers['user-agent']) || '');
  if (!ua) return 'full';
  var low = ua.toLowerCase();

  /* 手表优先 */
  if (/watch|wear|tizen|watchos|wearos|applewatch/.test(low)) return 'watch';
  /* iPad 用 desktop 布局（屏幕够宽） */
  if (/ipad|tablet|playbook|silk/.test(low) && !/mobile/.test(low)) return 'desktop';
  /* 移动端 */
  if (/android|iphone|ipod|mobile|windows phone|blackberry|opera mini|iemobile/.test(low)) {
    return 'mobile';
  }
  /* 其它（PC / 爬虫）→ 完整版兜底 */
  return 'full';
}

/* ---- 5. 生成并缓存单个设备版本的 HTML ---- */
function _buildDeviceVersion(device, sourceHtml) {
  try {
    var deviceHtml = _splitByDevice(sourceHtml, device);
    var buf = Buffer.from(deviceHtml, 'utf8');

    var br = null;
    try {
      br = zlib.brotliCompressSync(buf, {
        params: {
          [zlib.constants.BROTLI_PARAM_QUALITY]: 10,
          [zlib.constants.BROTLI_PARAM_SIZE_HINT]: buf.length
        }
      });
    } catch (e) { br = null; }

    var gz = null;
    try {
      gz = zlib.gzipSync(buf, { level: 9 });
    } catch (e) { gz = null; }

    var h = 5381;
    for (var i = 0; i < deviceHtml.length; i += 97) {
      h = ((h << 5) + h + deviceHtml.charCodeAt(i)) >>> 0;
    }
    var etag = '"' + device + '-' + buf.length.toString(36) + '-' +
      h.toString(36) + '"';

    HTML_BY_DEVICE[device] = {
      raw: deviceHtml,
      br: br,
      gz: gz,
      etag: etag
    };
    return {
      raw: buf.length,
      br: br ? br.length : 0,
      gz: gz ? gz.length : 0
    };
  } catch (e) {
    console.error('⚠️ 构建 ' + device + ' 版 HTML 失败:', e.message);
    return null;
  }
}

async function buildHtml() {
  var raw = String(html);

  /* ---- Step 0: 注入版本号 ----
     把 HTML 中的 __CHANGELOG_VERSION__ 占位符替换为
     CHANGELOG_DATA[0].v 对应的字符串。因为 CHANGELOG_DATA
     已迁移到服务端，客户端不需要在启动时获取版本号。 */
  var _ver = (Array.isArray(CHANGELOG_DATA) && CHANGELOG_DATA.length)
    ? String(CHANGELOG_DATA[0].v) : '0.0.0';
  raw = raw.replace(/__CHANGELOG_VERSION__/g, 'v' + _ver);

  /* ---- Step 1: 抽出所有 <script> ---- */
  var scripts = [];               /* { attrs, js, isInline, min } */
  raw = raw.replace(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi,
    function (full, attrs, js) {
      var isInline = !/\bsrc\s*=/i.test(attrs) && js.trim().length > 0;
      scripts.push({ attrs: attrs, js: js, isInline: isInline, min: full });
      return '\x00SCRIPT' + (scripts.length - 1) + '\x00';
    });

  /* ---- Step 2: 抽出所有 <style> ---- */
  var styles = [];                /* { attrs, css, min } */
  raw = raw.replace(/<style\b([^>]*)>([\s\S]*?)<\/style>/gi,
    function (full, attrs, css) {
      styles.push({ attrs: attrs, css: css, min: css });
      return '\x00STYLE' + (styles.length - 1) + '\x00';
    });

  /* ---- Step 3: clean-css 压缩（level 2 = 高级优化） ---- */
  var cssIn = 0, cssOut = 0;
  try {
    var CleanCSS = require('clean-css');
    for (var ci = 0; ci < styles.length; ci++) {
      var s = styles[ci];
      cssIn += s.css.length;
      try {
        var out = new CleanCSS({
          level: {
            1: {
              /* 一级优化：安全 */
              specialComments: 0,
              removeWhitespace: true,
              semicolonAfterLastProperty: true
            },
            2: {
              /* 二级优化：更激进但可控 */
              mergeAdjacentRules: true,
              mergeIntoShorthands: true,
              mergeMedia: true,
              mergeNonAdjacentRules: false,     /* 关掉，避免顺序依赖 */
              mergeSemantically: false,         /* 关掉，避免改变语义 */
              removeEmpty: true,
              reduceNonAdjacentRules: false,    /* 关掉 */
              removeDuplicateFontRules: true,
              removeDuplicateMediaBlocks: true,
              removeDuplicateRules: true,
              removeUnusedAtRules: false,
              restructureRules: false,          /* 关掉，避免顺序错乱 */
              skipProperties: []
            }
          },
          compatibility: '*',
          rebase: false
        }).minify(s.css);
        if (out && out.styles && out.styles.length > 200) s.min = out.styles;
      } catch (e) {
        /* 单块失败 → 保留原 CSS，不影响其它块 */
        console.error('⚠️ clean-css 压缩失败，使用原 CSS:', e.message);
      }
      cssOut += s.min.length;
    }
  } catch (e) {
    console.error('⚠️ clean-css 未安装，跳过 CSS 压缩:', e.message);
    for (var cj = 0; cj < styles.length; cj++) { cssIn += styles[cj].css.length; cssOut += styles[cj].min.length; }
  }

  /* ---- Step 4: terser 压缩内联 JS ---- */
  var jsIn = 0, jsOut = 0;
  var terser = null;
  try { terser = require('terser'); }
  catch (e) { console.error('⚠️ terser 未安装，跳过 JS 压缩:', e.message); }

  /* ★ 语法自检工具：new Function 只解析不执行，能捕获 SyntaxError。
     成功返回 null，失败返回带块号的错误描述。 */
  function checkJsSyntax(code, label) {
    try {
      new Function(code);
      return null;
    } catch (err) {
      var loc = '';
      if (err.stack) {
        var m = err.stack.match(/<anonymous>:(\d+):(\d+)/);
        if (m) {
          var lineNo = parseInt(m[1], 10);
          var colNo = parseInt(m[2], 10);
          loc = ' (第 ' + lineNo + ' 行, 第 ' + colNo + ' 列)';
          var lines = code.split('\n');
          var start = Math.max(0, lineNo - 4);
          var end = Math.min(lines.length, lineNo + 3);
          var ctx = '\n  ── 代码上下文 ──\n';
          for (var i = start; i < end; i++) {
            var mark = (i + 1 === lineNo) ? ' >>> ' : '     ';
            ctx += mark + (i + 1) + ' | ' + lines[i] + '\n';
          }
          return '[' + label + '] ' + err.message + loc + ctx;
        }
      }
      return '[' + label + '] ' + err.message + loc;
    }
  }

  for (var si = 0; si < scripts.length; si++) {
    var sc = scripts[si];
    if (!sc.isInline) continue;
    jsIn += sc.js.length;

    /* ★ 压缩前自检原始 JS —— 语法错误应在这里就被发现，
       避免其一路走到浏览器端造成整块 <script> 拒绝执行 */
    var rawErr = checkJsSyntax(sc.js, '原始第 ' + si + ' 块');
    if (rawErr) {
      console.error('❌ 内联 JS 语法错误（压缩前）:', rawErr);
      console.error('   → 该块将保持原样输出，请修复语法后重新构建');
      sc.min = '<script' + sc.attrs + '>' + sc.js + '</script>';
      jsOut += sc.js.length;
      continue;
    }

    if (!terser) { jsOut += sc.js.length; continue; }
    try {
      var res = await terser.minify(sc.js, {
        compress: {
          defaults: true,
          drop_console: false,
          /* ★ v0.25.1：源码保护开启时保留 debugger 语句，
             因为反调试模块依赖 debugger 检测。
             注意：这会让普通用户的调试器每次断下 —— 正是预期效果。 */
          drop_debugger: false,
          passes: 3,
          hoist_funs: false,
          hoist_vars: false,
          pure_getters: false,
          keep_fargs: true,
          keep_fnames: false,
          /* 移除 console 以外的副作用丢弃，更激进地压缩 */
          unused: true,
          dead_code: true,
          conditionals: true,
          evaluate: true,
          booleans: true,
          loops: true,
          if_return: true,
          join_vars: true,
          collapse_vars: true,
          reduce_vars: true,
          sequences: true
        },
        mangle: {
          toplevel: false,
          eval: false,
          keep_classnames: false,
          keep_fnames: false,
          reserved: [
            't', 's2t', 'i18n', 'I18N', 'state', 'dom',
            'window', 'document', 'console', 'socket', 'io',
            'localStorage', 'sessionStorage', 'JSON', 'Date',
            'Array', 'Object', 'String', 'Number', 'Math',
            'setTimeout', 'setInterval', 'clearTimeout', 'clearInterval',
            'requestAnimationFrame', 'cancelAnimationFrame',
            'callIf', 'openProfile', 'openWallet', 'openSpace',
            'openSpaceFeed', 'openRedpacketDetail', 'openGroupManage',
            'openSearch', 'openBrowser', 'openProfileEdit',
            'selectContact', 'clearSelection', 'renderMessages',
            'renderContacts', 'renderPlaceholder', 'renderTypingIndicator',
            'renderGroupSidePanel', 'renderPinnedBanner',
            'renderWalletBalance', 'renderWalletRecords',
            'renderWalletTransferTargets', 'renderMusicList',
            'renderOnlineUsers', 'renderDeviceList', 'renderSigninCalendar',
            'showToast', 'showConfirm', 'showPrompt', 'showModal',
            'showMessagePopup', 'showMsgMenu', 'showGroupMenu',
            'showContactMenu', 'showReactionPicker',
            'closeModalWithFade', 'closeProfile', 'closeSpace', 'closeBrowser',
            'jumpToMessage', 'jumpToNextUnread',
            'startCall', 'acceptCall', 'rejectCall', 'hangupCall',
            'gcStart', 'gcLeave', 'gcEndAll',
            'musicPlayById', 'musicTogglePlay', 'musicStep',
            'playFaceIdAnimation', 'tryLoginWithFaceId',
            'applyLang', 'applyAccentColor', 'applyAppleV3Style',
            'applyBackground', 'applyCustomShortcuts', 'applyTimeBasedTheme',
            'playBeep', 'playChatSound', 'stopFlashTitle', 'flashTitle',
            'debugLog', 'debugEnable', 'debugDisable', 'debugTogglePanel',
            'uiGuardOnViolation', 'uiGuardEnable', 'uiGuardDisable',
            'uiGuardCheckAllOnce', 'uiGuardSnapshotParents',
            'tuiEnter', 'tuiExit', 'tuiDraw', 'tuiOnKey', 'tuiPushLog',
            'handleCommand', 'restartServer', 'doPauseServer', 'doResumeServer',
            'loadJSON', 'saveJSON', 'buildHtml', 'precompressHtml', 'sendHtml',
            'crashLog', 'log', 'emitToUser', 'broadcastUserList',
            'broadcastGroupList', 'addMessage', 'saveMessage', 'getHistory',
            'getUserById', 'getUserBySocketId', 'getUserByName', 'getGroupById',
            'getHistoryKey', 'getUserHistory', 'saveHistoryNow',
            'scheduleSaveHistory', 'deleteUserAccount',
            'recordDevice', 'removeDevice', 'saveDevices',
            'genFeedbackId', 'saveFeedback', 'kfRenderPageV2',
            'gwRenderLoginPage', 'gwGetSession', 'gwCreateSession',
            'gwDestroySession', 'gwReadBody', 'gwParseCookies',
            'parseBanDuration', 'formatBanDuration',
            'minifyHtmlSkeleton', 'cleanupSystemSessionResidue'
          ]
        },
        format: {
          comments: false,
          beautify: false,
          preserve_annotations: false
        },
        ie8: false
      });
      if (res && res.code) {
        /* ★ 压缩后再自检一次 —— 防止 terser 在极端情况下产出非法代码 */
        var minErr = checkJsSyntax(res.code, '压缩后第 ' + si + ' 块');
        if (minErr) {
          console.error('❌ terser 产出语法错误，回退原始 JS:', minErr);
          sc.min = '<script' + sc.attrs + '>' + sc.js + '</script>';
          jsOut += sc.js.length;
        } else {
          sc.min = '<script' + sc.attrs + '>' + res.code + '</script>';
          jsOut += res.code.length;
        }
      } else {
        jsOut += sc.js.length;
      }
    } catch (e) {
      console.error('⚠️ terser 压缩失败（第 ' + si + ' 块），使用原代码:', e.message);
      jsOut += sc.js.length;
    }
  }

  /* ---- Step 5: 骨架压缩 ---- */
  var skeleton = minifyHtmlSkeleton(raw);

  /* ---- Step 6: 回填 ---- */
  skeleton = skeleton.replace(/\x00SCRIPT(\d+)\x00/g, function (_, i) {
    return scripts[+i].min;
  });
  skeleton = skeleton.replace(/\x00STYLE(\d+)\x00/g, function (_, i) {
    var s = styles[+i];
    return '<style' + s.attrs + '>' + s.min + '</style>';
  });

  /* ---- Step 6.5：自动标记设备代码块 ---- */
  /* 在回填 SCRIPT / STYLE 之前，先对骨架（含 CSS）自动标记。
     然后把同一逻辑应用于内联的 JS 与 CSS 段。 */
  try {
    skeleton = _autoTagDeviceBlocks(skeleton);
    for (var _si2 = 0; _si2 < scripts.length; _si2++) {
      if (scripts[_si2].isInline && scripts[_si2].min) {
        /* 只标记 JS 里的字符串模板或注释中的 @device 标记，
           不改动实际逻辑 —— JS 里我们不做自动分块 */
      }
    }
    /* 对已压缩的 CSS 块同样自动标记 */
    for (var _cj2 = 0; _cj2 < styles.length; _cj2++) {
      if (styles[_cj2].min) {
        styles[_cj2].min = _autoTagDeviceBlocks(styles[_cj2].min);
      }
    }
    console.log('🏷️ 设备代码块自动标记完成');
  } catch (e) {
    console.warn('⚠️ 设备标记失败，将使用完整版:', e.message);
  }

  /* ---- Step 7: 统计 ---- */
  var rawLen = String(html).length;
  var minLen = skeleton.length;
  HTML_BUILD_STATS = {
    raw: rawLen, min: minLen,
    cssIn: cssIn, cssOut: cssOut,
    jsIn: jsIn, jsOut: jsOut
  };
  console.log('📦 前端构建完成');
  console.log('   HTML 骨架 : ' + (rawLen / 1024).toFixed(1) + 'KB → ' + (minLen / 1024).toFixed(1) + 'KB' +
    ' (' + (100 - minLen / rawLen * 100).toFixed(1) + '% ↓)');
  if (cssIn) console.log('   CSS       : ' + (cssIn / 1024).toFixed(1) + 'KB → ' + (cssOut / 1024).toFixed(1) + 'KB' +
    ' (' + (100 - cssOut / cssIn * 100).toFixed(1) + '% ↓)');
  if (jsIn) console.log('   JS        : ' + (jsIn / 1024).toFixed(1) + 'KB → ' + (jsOut / 1024).toFixed(1) + 'KB' +
    ' (' + (100 - jsOut / jsIn * 100).toFixed(1) + '% ↓)');

  return skeleton;
}

/* 路由：构建完成前挂起请求，构建完统一响应 */
var HTML_PENDING = [];            /* 等待中的 { req, res } */
var HTML_BUILD_DONE = false;

/* 预压缩：Brotli q10 + Gzip 9，ETag 用「长度 + djb2 抽样 hash」 */
function precompressHtml(htmlStr) {
  /* ★ 修复：必须保留原始字符串引用，否则 serveHtml 会一直判定为未准备好而等待 30 秒 */
  HTML_TO_SERVE = htmlStr;

  /* ============================================================
     ★ v0.27.10：生成 4 份设备专用 HTML（full / desktop / mobile / watch）
     ============================================================ */
  try {
    var _devList = ['full', 'desktop', 'mobile', 'watch'];
    var _report = [];
    for (var _di = 0; _di < _devList.length; _di++) {
      var _dev = _devList[_di];
      var _stat = _buildDeviceVersion(_dev, htmlStr);
      if (_stat) {
        var _brKB = (_stat.br / 1024).toFixed(1);
        var _gzKB = (_stat.gz / 1024).toFixed(1);
        _report.push(_dev + ': ' + _brKB + 'KB/br');
      }
    }
    if (_report.length) {
      console.log('🎯 设备分流构建完成 · ' + _report.join(' · '));
    }
  } catch (eDev) {
    console.error('⚠️ 设备分流构建失败，回退到 full 版本:', eDev.message);
  }

  /* ★ v0.27.7：生成流式分段（失败不影响主流程） */
  try {
    HTML_CHUNKS = buildHtmlChunks(htmlStr);
    if (HTML_CHUNKS && HTML_CHUNKS.length > 1) {
      var _names = [];
      var _total = 0;
      for (var _ci = 0; _ci < HTML_CHUNKS.length; _ci++) {
        _names.push(HTML_CHUNKS[_ci].name + '(' +
          (HTML_CHUNKS[_ci].content.length / 1024).toFixed(0) + 'KB)');
        _total += HTML_CHUNKS[_ci].content.length;
      }
      console.log('🌊 流式分段：' + HTML_CHUNKS.length + ' 段 · ' +
        _names.join(' → '));
    } else {
      HTML_CHUNKS = null;
    }
  } catch (e) {
    console.warn('⚠️ 流式分段生成失败，将使用整段下发:', e.message);
    HTML_CHUNKS = null;
  }

  var buf = Buffer.from(htmlStr, 'utf8');

  try {
    HTML_BR = zlib.brotliCompressSync(buf, {
      params: {
        [zlib.constants.BROTLI_PARAM_QUALITY]: 10,
        [zlib.constants.BROTLI_PARAM_SIZE_HINT]: buf.length
      }
    });
  } catch (e) {
    console.error('⚠️ Brotli 压缩失败:', e.message);
    HTML_BR = null;
  }

  try {
    HTML_GZ = zlib.gzipSync(buf, { level: 9 });
  } catch (e) {
    console.error('⚠️ Gzip 压缩失败:', e.message);
    HTML_GZ = null;
  }

  var h = 5381;
  for (var i = 0; i < htmlStr.length; i += 97) {
    h = ((h << 5) + h + htmlStr.charCodeAt(i)) >>> 0;
  }
  HTML_ETAG = '"' + buf.length.toString(36) + '-' + h.toString(36) + '"';

  var brLen = HTML_BR ? HTML_BR.length : 0;
  var gzLen = HTML_GZ ? HTML_GZ.length : 0;
  console.log('🗜️  预压缩: 原始 ' + (buf.length / 1024).toFixed(1) + 'KB' +
    ' → br ' + (brLen / 1024).toFixed(1) + 'KB (' +
    (100 - brLen / buf.length * 100).toFixed(1) + '% ↓)' +
    ' · gz ' + (gzLen / 1024).toFixed(1) + 'KB (' +
    (100 - gzLen / buf.length * 100).toFixed(1) + '% ↓)');
}

/* 设备专用 HTML 下发 */
function sendDeviceHtml(req, res, ver, device) {
  res.setHeader('Vary', 'Accept-Encoding, User-Agent');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('ETag', ver.etag);
  res.setHeader('X-Device', device);

  /* HEAD 探测 */
  if (req.method === 'HEAD') {
    res.end();
    return;
  }
  /* 命中 ETag → 304 */
  if (req.headers['if-none-match'] === ver.etag) {
    res.status(304).end();
    return;
  }

  res.setHeader('Content-Type', 'text/html; charset=utf-8');

  var ae = String(req.headers['accept-encoding'] || '');
  if (ver.br && /\bbr\b/.test(ae)) {
    res.setHeader('Content-Encoding', 'br');
    res.setHeader('Content-Length', ver.br.length);
    res.end(ver.br);
  } else if (ver.gz && /\bgzip\b/.test(ae)) {
    res.setHeader('Content-Encoding', 'gzip');
    res.setHeader('Content-Length', ver.gz.length);
    res.end(ver.gz);
  } else {
    res.setHeader('Content-Length', Buffer.byteLength(ver.raw, 'utf8'));
    res.end(ver.raw);
  }
}

/* 按 Accept-Encoding 下发对应版本；命中 ETag → 304 空响应 */
function sendHtml(req, res) {
  res.setHeader('Vary', 'Accept-Encoding');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('ETag', HTML_ETAG);
  /* ★ v0.27.7：告知客户端支持流式传输（用于探测） */
  if (HTML_CHUNKS && HTML_CHUNKS.length > 1) {
    res.setHeader('X-Streaming', '1');
  }

  /* HEAD 请求：只返回头部，不发送内容 */
  if (req.method === 'HEAD') {
    res.end();
    return;
  }

  /* 二次访问：浏览器发 If-None-Match → 只回 304 */
  if (req.headers['if-none-match'] === HTML_ETAG) {
    res.status(304).end();
    return;
  }

  res.setHeader('Content-Type', 'text/html; charset=utf-8');

  /* compression 中间件检测到已有 Content-Encoding 会自动跳过，
     不会二次压缩。 */
  var ae = String(req.headers['accept-encoding'] || '');
  if (HTML_BR && /\bbr\b/.test(ae)) {
    res.setHeader('Content-Encoding', 'br');
    res.setHeader('Content-Length', HTML_BR.length);
    res.end(HTML_BR);
  } else if (HTML_GZ && /\bgzip\b/.test(ae)) {
    res.setHeader('Content-Encoding', 'gzip');
    res.setHeader('Content-Length', HTML_GZ.length);
    res.end(HTML_GZ);
  } else {
    res.setHeader('Content-Length', Buffer.byteLength(HTML_TO_SERVE, 'utf8'));
    res.end(HTML_TO_SERVE);
  }
}

function serveHtml(req, res) {
  /* ★ v0.27.7：?stream=1 或 Sec-Fetch-Mode:navigate 时启用流式传输 */
  var _wantStream = false;
  try {
    var _q = String(req.query && req.query.stream || '');
    if (_q === '1' || _q === 'true') _wantStream = true;
  } catch (e) {}

  /* ★ 优化：改用检查 HTML_BY_DEVICE 是否就绪，真正释放 HTML_TO_SERVE 内存 */
  if (HTML_BUILD_DONE && HTML_BY_DEVICE && HTML_BY_DEVICE.full && HTML_BY_DEVICE.full.raw) {
    /* ★ v0.27.10：按设备分流 */
    var _dev = _detectDevice(req);
    var _ver = HTML_BY_DEVICE[_dev];
    if (!_ver || !_ver.raw) _ver = HTML_BY_DEVICE.full;
    if (_ver && _ver.raw) {
      /* 流式传输只在 full 版本支持（分段缓存来自完整版） */
      if (_wantStream && _dev === 'full' &&
          HTML_CHUNKS && HTML_CHUNKS.length > 1) {
        sendHtmlStream(req, res);
        return;
      }
      sendDeviceHtml(req, res, _ver, _dev);
      return;
    }
    /* 兜底：走完整版 */
    if (_wantStream && HTML_CHUNKS && HTML_CHUNKS.length > 1) {
      sendHtmlStream(req, res);
    } else {
      sendHtml(req, res);
    }
    return;
  }
  /* 构建尚未完成 → 排队 */
  HTML_PENDING.push({ req: req, res: res });
  /* 兜底：30 秒超时直接回退到原始 html（不压缩），
     保证服务永不因压缩失败而不可用 */
  setTimeout(function () {
    var idx = HTML_PENDING.findIndex(function (p) { return p.res === res; });
    if (idx === -1) return;
    HTML_PENDING.splice(idx, 1);
    res.type('html').send(html);
  }, 30000);
}


/* ============================================================
   ★ v0.31.0：只读模式 HTTP 中间件
   ------------------------------------------------------------
   白名单（仅以下可访问）：
     · 登录：/、/index*、/login、/download/login、/download/logout
     · 聊天记录：/（HTML 中包含客户端拉取逻辑，socket 侧另有白名单）
     · 官网：/gw、/log、/gy、/privacy
     · 下载中心：/download、/dl/*
     · 音乐流：/music/*
     · 公开状态：/api/ip-status、/api/changelog
     · Socket.IO 握手：/socket.io/*
   其余全部返回 403（纯 HTML，无 JS，兼容旧浏览器）
   ============================================================ */
var READONLY_HTTP_OK = {
  '/': 1, '/index': 1, '/index/': 1, '/index.html': 1,
  '/gw': 1, '/log': 1, '/gy': 1, '/privacy': 1,
  '/login': 1, '/download': 1, '/download/login': 1, '/download/logout': 1,
  /* ★ v0.31.3：所有 /api/* 已从白名单移除 —— 只读模式下全部 403。
     /readonly-check 是唯一放行的「非 api 状态查询接口」，
     供客户端 / 公开页面探测只读状态与 IP 封禁状态使用。 */
  '/readonly-check': 1,
  '/favicon.ico': 1
};
function _readonlyHttpAllowed(req) {
  var p = String(req.path || '');
  /* Socket.IO 握手必须放行，否则客户端无法连接 */
  if (p.indexOf('/socket.io') === 0) return true;
  /* ★ v0.31.2：只读模式下 /dl/* 与 /music/* 一律拒绝
     —— 无法下载文件、无法播放音乐。
     /download 页面本身仍可访问（能查看文件列表），
     但点击「下载」按钮 / 播放音乐时会得到 403。 */
  /* 精确白名单（只读状态查询接口也必须放行） */
  if (READONLY_HTTP_OK[p] === 1) return true;
  return false;
}
app.use(function (req, res, next) {
  if (config.readonlyMode !== true) return next();
  /* CORS 预检放行，避免旧浏览器 fetch 预检失败 */
  if (req.method === 'OPTIONS') return next();
  /* ★ v0.31.3：/readonly-check 是唯一放行的非 api 状态查询接口，
     该接口内部自带 IP 封禁判定，不需要在这里拦截。 */
  var _rp = String(req.path || '');
  if (_rp === '/readonly-check') return next();
  if (_readonlyHttpAllowed(req)) return next();

  /* ★ v0.31.3：所有 /api/* 返回 JSON 403 —— 便于客户端
     用 try/catch 处理，避免解析 HTML 失败。 */
  if (_rp.indexOf('/api/') === 0) {
    res.status(403);
    res.setHeader('Content-Type', 'application/json; charset=utf-8');
    res.setHeader('Cache-Control', 'no-store');
    res.setHeader('X-Readonly-Mode', '1');
    res.end(JSON.stringify({
      ok: false,
      error: 'readonly-mode',
      message: '服务器处于只读模式，API 已被禁用'
    }));
    return;
  }

  /* 其它路径（/dl/*、/music/*、/kf、/root 等）返回 HTML 403 */
  res.status(403);
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.setHeader('Cache-Control', 'no-store');
  res.end('<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>只读模式</title></head><body style="font-family:-apple-system,&#39;PingFang SC&#39;,&#39;Microsoft YaHei&#39;,sans-serif;background:#f6fef9;color:#333;margin:0;padding:40px 20px;text-align:center;"><div style="max-width:480px;margin:40px auto;background:#fff;border-radius:16px;padding:40px 28px;box-shadow:0 8px 30px rgba(7,193,96,.12);"><div style="font-size:56px;line-height:1;">🔒</div><h1 style="font-size:22px;color:#c62828;margin:16px 0 12px;">只读模式已启用</h1><p style="color:#666;font-size:14px;line-height:1.7;margin:0 0 20px;">服务器当前处于只读模式。<br>仅允许登录、查看聊天记录与浏览官网。<br>如需写入数据，请联系管理员关闭只读模式。</p><a href="/" style="display:inline-block;padding:10px 24px;background:#07c160;color:#fff;text-decoration:none;border-radius:22px;font-size:14px;">返回主界面</a></div></body></html>');
});

app.get('/', serveHtml);
app.get('/index.html', serveHtml);
/* ★ 支持 /index 与 /index/ 也能打开主页面 */
app.get('/index', serveHtml);
app.get('/index/', serveHtml);

/* 公开页面 UI Guard：无 socket，仅遮罩 + 2 秒后刷新。ID 列表由 window.__UI_GUARD_IDS 提供 */
/* 公开页面 IP 检查：每 10 秒轮询 /api/ip-status，403 则遮罩 + 刷新 */
var PUBLIC_IP_GUARD_JS = [
  '/* ===== 公开页面 IP 封禁实时检查 ===== */',
  '(function(){',
  '  try {',
  '    var POLL_MS = 10000;',
  '    var _banned = false;',
  '    function _showBanOverlay(remainSec){',
  '      if (document.getElementById("__ipBanOverlay")) return;',
  '      var ov = document.createElement("div");',
  '      ov.id = "__ipBanOverlay";',
  '      ov.style.cssText =',
  '        "position:fixed;top:0;right:0;bottom:0;left:0;" +',
  '        "z-index:2147483647;" +',
  '        "background:rgba(15,15,15,.96);" +',
  '        "-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);" +',
  '        "color:#fff;display:flex;align-items:center;justify-content:center;" +',
  '        "flex-direction:column;gap:14px;text-align:center;padding:28px;" +',
  '        "font-family:-apple-system,BlinkMacSystemFont,\\"PingFang SC\\"," +',
  '        "\\"Microsoft YaHei\\",sans-serif;";',
  '      var _remainTxt = "";',
  '      if (typeof remainSec === "number" && remainSec > 0) {',
  '        if (remainSec > 86400) _remainTxt = "约 " + Math.round(remainSec / 86400) + " 天";',
  '        else if (remainSec > 3600) _remainTxt = "约 " + Math.round(remainSec / 3600) + " 小时";',
  '        else if (remainSec > 60) _remainTxt = "约 " + Math.round(remainSec / 60) + " 分钟";',
  '        else _remainTxt = remainSec + " 秒";',
  '      }',
  '      ov.innerHTML =',
  '        \'<div style="font-size:60px;line-height:1">🚫</div>\' +',
  '        \'<div style="font-weight:700;font-size:20px">访问被拒绝</div>\' +',
  '        \'<div style="opacity:.85;font-size:14.5px;line-height:1.7;max-width:440px">\' +',
  '          \'你的 IP 已被管理员封禁，页面即将刷新…\' +',
  '        \'</div>\' +',
  '        (_remainTxt',
  '          ? (\'<div style="margin-top:6px;font-size:13px;opacity:.7">剩余时间：\' + _remainTxt + \'</div>\')',
  '          : "");',
  '      try { document.body.appendChild(ov); } catch (e) {}',
  '    }',
  '    function _check(){',
  '      /* ★ v0.31.3：改用 /readonly-check —— 只读模式下 /api/* 全部 403，',
  '         该非 api 路径能同时返回 IP 封禁状态与只读状态。 */',
  '      fetch("/readonly-check", {',
  '        method: "GET",',
  '        credentials: "same-origin",',
  '        cache: "no-store"',
  '      }).then(function(r){',
  '        if (r.status === 403) {',
  '          if (_banned) return;',
  '          _banned = true;',
  '          var _remain = 0;',
  '          r.json().then(function(d){',
  '            _remain = d && d.remainSec || 0;',
  '            _showBanOverlay(_remain);',
  '          }).catch(function(){',
  '            _showBanOverlay(0);',
  '          });',
  '          setTimeout(function(){',
  '            try { location.reload(); }',
  '            catch(e){ try { location.href = location.href; } catch(e2){} }',
  '          }, 900);',
  '          return;',
  '        }',
  '      }).catch(function(){});',
  '    }',
  '    setTimeout(_check, 3000);',
  '    setInterval(_check, POLL_MS);',
  '    console.log("[IP Guard] 已启用实时检查（每 " + (POLL_MS / 1000) + " 秒）");',
  '  } catch (e) {',
  '    console.warn("[IP Guard] 初始化失败:", e && e.message);',
  '  }',
  '})();'
].join('\n');

var PUBLIC_UI_GUARD_JS = [
  '/* ===== 公开页面界面保护（v0.24.1） ===== */',
  '(function(){',
  '  try {',
  '    if (typeof MutationObserver !== "function") return;',
  '    var IDS = (window.__UI_GUARD_IDS || []).slice();',
  '    if (!IDS.length) {',
  '      console.log("[Public UI Guard] 未配置白名单，已跳过");',
  '      return;',
  '    }',
  '',
  '    /* ---- 用哈希表替换数组查找，复杂度 O(1) ---- */',
  '    var ID_MAP = Object.create(null);',
  '    for (var i = 0; i < IDS.length; i++) ID_MAP[IDS[i]] = true;',
  '',
  '    var ALLOWED_ATTRS = [',
  '      "class", "style", "value", "disabled", "checked", "selected",',
  '      "readonly", "hidden", "placeholder", "title", "aria-label",',
  '      "aria-hidden", "aria-disabled", "aria-expanded",',
  '      "lang", "dir", "open", "href", "src"',
  '    ];',
  '    function isAllowedAttr(n){',
  '      if (!n) return true;',
  '      if (n.indexOf("data-") === 0) return true;',
  '      return ALLOWED_ATTRS.indexOf(n) !== -1;',
  '    }',
  '    function isCritical(id){ return !!(id && ID_MAP[id]); }',
  '',
  '    var triggered = false;',
  '    function onViolation(id, action){',
  '      if (triggered) return;',
  '      triggered = true;',
  '      try { if (obs) obs.disconnect(); } catch(e){}',
  '      var actTxt = action || "删除";',
  '      var actMsg =',
  '        actTxt === "移动" ? "检测到关键界面元素被移动到其它位置。" :',
  '        actTxt === "粘贴" ? "检测到粘贴了重复的关键界面元素。" :',
  '        actTxt === "添加" ? "检测到向关键位置添加了非法元素。" :',
  '        actTxt.indexOf("属性:") === 0',
  '          ? ("检测到关键元素属性 " + actTxt.substring(3) + " 被修改。")',
  '          : "检测到关键界面元素被删除。";',
  '      /* ★ v0.24.6：上报服务端（用于统计 + 封禁） */',
  '      try {',
  '        fetch("/api/ui-guard-violation", {',
  '          method: "POST",',
  '          headers: { "Content-Type": "application/json" },',
  '          body: JSON.stringify({',
  '            element: String(id||"").slice(0, 64),',
  '            action: actTxt.slice(0, 64),',
  '            ts: Date.now()',
  '          })',
  '        }).catch(function(){});',
  '      } catch(e){}',
  '',
  '      var ov = document.createElement("div");',
  '      ov.id = "__pubUiGuardBlock";',
  '      ov.style.cssText =',
  '        "position:fixed;top:0;right:0;bottom:0;left:0;" +',
  '        "z-index:2147483647;" +',
  '        "background:rgba(15,15,15,.92);" +',
  '        "-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);" +',
  '        "color:#fff;display:flex;align-items:center;justify-content:center;" +',
  '        "flex-direction:column;gap:14px;text-align:center;padding:28px;" +',
  '        "font-family:-apple-system,BlinkMacSystemFont,\\"Segoe UI\\",\\"PingFang SC\\",\\"Microsoft YaHei\\",sans-serif;";',
  '      ov.innerHTML =',
  '        \'<div style="font-size:60px;line-height:1">🛡️</div>\' +',
  '        \'<div style="font-weight:700;font-size:20px;letter-spacing:.5px">\' +',
  '          \'界面保护已触发\' +',
  '        \'</div>\' +',
  '        \'<div style="opacity:.82;font-size:14.5px;line-height:1.75;max-width:440px">\' +',
  '          actMsg + \'<br>页面将在 <b id="__pubUiGuardSec">2</b> 秒后自动刷新…\' +',
  '        \'</div>\' +',
  '        \'<div style="margin-top:6px;font-size:12px;opacity:.5;font-family:Consolas,Monaco,monospace">\' +',
  '          "Element: #" + String(id||"").replace(/[<>&"]/g,"") +',
  '          "   ·   Action: " + actTxt +',
  '        \'</div>\';',
  '      try { (document.body||document.documentElement).appendChild(ov); } catch(e){}',
  '      var sec = 2;',
  '      var secEl = document.getElementById("__pubUiGuardSec");',
  '      var t = setInterval(function(){',
  '        sec--;',
  '        if (sec <= 0) {',
  '          clearInterval(t);',
  '          try { location.reload(); }',
  '          catch(e){ try { location.href = location.href; } catch(e2){} }',
  '          return;',
  '        }',
  '        if (secEl) secEl.textContent = String(sec);',
  '      }, 1000);',
  '      setTimeout(function(){ try { location.reload(); } catch(e){} }, 2500);',
  '    }',
  '',
  '    /* ---- 记录每个关键元素的「初始父节点」快照 ---- */',
  '    var initParents = Object.create(null);',
  '    for (var pi = 0; pi < IDS.length; pi++) {',
  '      var pel = document.getElementById(IDS[pi]);',
  '      if (pel && pel.parentNode) initParents[IDS[pi]] = pel.parentNode;',
  '    }',
  '',
  '    /* ---- 300ms 延迟二次确认：业务"清空→重建"不会误触发 ---- */',
  '    var pending = {};',
  '    function schedule(id, kind) {',
  '      var qk = id + ":" + kind;',
  '      if (pending[qk]) return;',
  '      pending[qk] = setTimeout(function(){',
  '        delete pending[qk];',
  '        if (triggered) return;',
  '        var el = document.getElementById(id);',
  '        var inDoc = !!(el && document.body && document.body.contains(el));',
  '        var expP = initParents[id];',
  '        if (kind === "remove") {',
  '          if (!inDoc) { onViolation(id, "删除"); return; }',
  '          if (expP && el.parentNode !== expP) { onViolation(id, "移动"); return; }',
  '          return;',
  '        }',
  '        /* add 分支：判断是否出现重复 id */',
  '        var all = document.querySelectorAll(',
  '          \'[id="\' + String(id).replace(/"/g, \'\\\\"\') + \'"]\'',
  '        );',
  '        if (all.length > 1) { onViolation(id, "粘贴"); return; }',
  '        if (el && expP && el.parentNode !== expP) { onViolation(id, "移动"); return; }',
  '      }, 300);',
  '    }',
  '',
  '    var obs = new MutationObserver(function(muts){',
  '      if (triggered) return;',
  '      for (var i = 0; i < muts.length; i++) {',
  '        var m = muts[i];',
  '        if (m.type === "childList") {',
  '          if (m.removedNodes && m.removedNodes.length) {',
  '            for (var r = 0; r < m.removedNodes.length; r++) {',
  '              var rn = m.removedNodes[r];',
  '              if (rn.nodeType !== 1) continue;',
  '              if (!isCritical(rn.id)) continue;',
  '              schedule(rn.id, "remove");',
  '            }',
  '          }',
  '          if (m.addedNodes && m.addedNodes.length) {',
  '            for (var a = 0; a < m.addedNodes.length; a++) {',
  '              var an = m.addedNodes[a];',
  '              if (an.nodeType !== 1) continue;',
  '              if (!isCritical(an.id)) continue;',
  '              schedule(an.id, "add");',
  '            }',
  '          }',
  '          continue;',
  '        }',
  '        if (m.type === "attributes") {',
  '          var tgt = m.target;',
  '          if (!tgt || tgt.nodeType !== 1) continue;',
  '          if (!isCritical(tgt.id)) continue;',
  '          var an2 = m.attributeName;',
  '          if (isAllowedAttr(an2)) continue;',
  '          onViolation(tgt.id, "属性:" + an2);',
  '          return;',
  '        }',
  '      }',
  '    });',
  '',
  '    obs.observe(document.body, {',
  '      childList: true,',
  '      subtree: true,',
  '      attributes: true,',
  '      attributeOldValue: false',
  '    });',
  '    console.log("[Public UI Guard] 已启用，监控 " + IDS.length +',
  '      " 个关键元素");',
  '  } catch(e){',
  '    console.warn("[Public UI Guard] 启用失败:", e && e.message);',
  '  }',
  '})();',
  '',
  PUBLIC_IP_GUARD_JS
].join('\n');

