/* 下载中心会话：内存表，cookie gw_session HttpOnly 7 天，系统账号禁止登录 */
var gwSessions = {};
var GW_SESSION_TTL = 7 * 24 * 3600 * 1000;  /* 7 天 */
/* 登录尝试限速表：{ ip: { window: 起始时间, count: 次数 } } */
var gwLoginAttempts = {};

function gwParseCookies(req) {
  var out = {};
  try {
    var raw = req.headers.cookie || '';
    var parts = raw.split(';');
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i].trim();
      if (!p) continue;
      var eq = p.indexOf('=');
      if (eq === -1) continue;
      var k = p.substring(0, eq).trim();
      var v = p.substring(eq + 1).trim();
      try { out[k] = decodeURIComponent(v); }
      catch (e) { out[k] = v; }
    }
  } catch (e) { }
  return out;
}

function gwCreateSession(userId, userName) {
  var token = crypto.randomBytes(24).toString('hex');
  gwSessions[token] = {
    userId: userId,
    userName: userName,
    expires: Date.now() + GW_SESSION_TTL
  };
  /* 顺手清理过期会话 */
  var now = Date.now();
  for (var k in gwSessions) {
    if (gwSessions[k] && gwSessions[k].expires < now) delete gwSessions[k];
  }
  return token;
}

function gwGetSession(req) {
  var token = '';
  /* 1. 优先读 cookie */
  try {
    var cookies = gwParseCookies(req);
    token = cookies.gw_session || '';
  } catch (e) {}
  /* ★ v0.24.47：cookie 缺失时回退到 URL 参数 ?t=
     —— 兼容无 cookie 环境（隐私模式 / 严格拦截）。 */
  if (!token && req && req.query && req.query.t) {
    token = String(req.query.t);
  }
  if (!token) return null;
  var s = gwSessions[token];
  if (!s) return null;
  if (s.expires < Date.now()) { delete gwSessions[token]; return null; }
  return s;
}

function gwDestroySession(req) {
  var cookies = gwParseCookies(req);
  var token = cookies.gw_session;
  if (token) delete gwSessions[token];
}

/* 读取 POST body（application/x-www-form-urlencoded 或 JSON） */
function gwReadBody(req, cb, maxSize) {
  var chunks = [];
  var total = 0;
  var MAX = (typeof maxSize === 'number' && maxSize > 0)
    ? maxSize
    : (1024 * 64);   /* 默认 64KB */
  req.on('data', function (c) {
    total += c.length;
    if (total > MAX) { req.destroy(); return; }
    chunks.push(c);
  });
  req.on('end', function () {
    var raw = Buffer.concat(chunks).toString('utf8');
    var ct = String(req.headers['content-type'] || '');
    if (ct.indexOf('application/json') !== -1) {
      try { cb(null, JSON.parse(raw)); }
      catch (e) { cb(e); }
      return;
    }
    /* 默认按 urlencoded 解析 */
    var obj = {};
    var parts = raw.split('&');
    for (var i = 0; i < parts.length; i++) {
      if (!parts[i]) continue;
      var eq = parts[i].indexOf('=');
      var k = (eq === -1) ? parts[i] : parts[i].substring(0, eq);
      var v = (eq === -1) ? '' : parts[i].substring(eq + 1);
      try { k = decodeURIComponent(k.replace(/\+/g, ' ')); } catch (e) { }
      try { v = decodeURIComponent(v.replace(/\+/g, ' ')); } catch (e) { }
      obj[k] = v;
    }
    cb(null, obj);
  });
  req.on('error', function (e) { cb(e); });
}

