/* 反馈页专用 HTML 转义（独立函数，避免污染下载页的 esc） */
function kfEscape(s) {
  try {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  } catch (e) { return ''; }
}

