  /* ---- 页面 JS ---- */
  html += '<script>';
  html += 'window.__UI_GUARD_IDS = ["btForm","btList","btToast"];';
  html += '(function(){';
  html += 'var KF_QS = ' + JSON.stringify(sessToken ? ('?t=' + sessToken) : '') + ';';

  /* ---- 多语言：客户端 applyKfLang ---- */
  html += 'var _kfLang = (function(){';
  html += '  try { var v = localStorage.getItem("gwLang"); if (v) return v; } catch(e){}';
  html += '  return window.__KF_CUR_LANG || "zh";';
  html += '})();';
  html += 'function _tk(key){';
  html += '  var pack = (window.__KF_LANG && window.__KF_LANG[_kfLang]) || {};';
  html += '  var v = pack[key];';
  html += '  if (v == null && window.__KF_LANG && window.__KF_LANG.zh) v = window.__KF_LANG.zh[key];';
  html += '  return v == null ? key : v;';
  html += '}';
  html += 'function applyKfLang(){';
  html += '  var nodes = document.querySelectorAll("[data-kf]");';
  html += '  for (var i = 0; i < nodes.length; i++){';
  html += '    var k = nodes[i].getAttribute("data-kf");';
  html += '    var v = _tk(k);';
  html += '    if (typeof v === "string") nodes[i].textContent = v;';
  html += '    if (nodes[i].hasAttribute("data-kf-title")) {';
  html += '      var tk2 = nodes[i].getAttribute("data-kf-title");';
  html += '      nodes[i].setAttribute("title", _tk(tk2));';
  html += '    }';
  html += '  }';
  html += '  var phs = document.querySelectorAll("[data-kf-ph]");';
  html += '  for (var j = 0; j < phs.length; j++){';
  html += '    var pk = phs[j].getAttribute("data-kf-ph");';
  html += '    phs[j].setAttribute("placeholder", _tk(pk));';
  html += '  }';
  html += '  document.documentElement.lang = (_kfLang === "en") ? "en" :';
  html += '    (_kfLang === "zh-TW" ? "zh-Hant" : (_kfLang === "zh-wenyan" ? "lzh" : "zh-CN"));';
  html += '}';
  html += 'applyKfLang();';
  html += 'function $(id){return document.getElementById(id);}';
  html += 'function toast(m,err){var el=$("btToast");if(!el)return;el.textContent=m;el.className="bt-toast show"+(err?" err":"");clearTimeout(el._t);el._t=setTimeout(function(){el.className="bt-toast"+(err?" err":"");},2400);}';

/* ============ 自绘对话框 ============ */
html += 'var _kfDlgEl=null,_kfDlgResolve=null;';
html += 'function _kfEnsureDlg(){';
html += '  if(_kfDlgEl)return _kfDlgEl;';
html += '  var ov=document.createElement("div");';
html += '  ov.className="kf-dlg-overlay";';
html += '  ov.innerHTML=\'<div class="kf-dlg">\' +';
html += '    \'<div class="kf-dlg-icon" id="kfDlgIcon"></div>\' +';
html += '    \'<div class="kf-dlg-title" id="kfDlgTitle"></div>\' +';
html += '    \'<div class="kf-dlg-msg" id="kfDlgMsg"></div>\' +';
html += '    \'<div class="kf-dlg-actions">\' +';
html += '      \'<button type="button" class="kf-dlg-btn cancel" id="kfDlgCancel">取消</button>\' +';
html += '      \'<button type="button" class="kf-dlg-btn confirm" id="kfDlgConfirm">确定</button>\' +';
html += '    \'</div></div>\';';
html += '  document.body.appendChild(ov);';
html += '  _kfDlgEl=ov;';
html += '  function _finish(v){';
html += '    if(!_kfDlgResolve)return;';
html += '    var r=_kfDlgResolve;_kfDlgResolve=null;';
html += '    ov.classList.remove("open");';
html += '    setTimeout(function(){r(v);},180);';
html += '  }';
html += '  ov.querySelector("#kfDlgConfirm").addEventListener("click",function(){_finish(true);});';
html += '  ov.querySelector("#kfDlgCancel").addEventListener("click",function(){_finish(false);});';
html += '  ov.addEventListener("click",function(e){if(e.target===ov)_finish(false);});';
html += '  document.addEventListener("keydown",function(e){';
html += '    if(!ov.classList.contains("open"))return;';
html += '    if(e.key==="Escape"){e.preventDefault();_finish(false);}';
html += '    else if(e.key==="Enter"){e.preventDefault();_finish(true);}';
html += '  });';
html += '  return ov;';
html += '}';
html += 'function kfConfirm(opts){';
html += '  opts=opts||{};';
html += '  var ov=_kfEnsureDlg();';
html += '  var iconEl=ov.querySelector("#kfDlgIcon");';
html += '  var titleEl=ov.querySelector("#kfDlgTitle");';
html += '  var msgEl=ov.querySelector("#kfDlgMsg");';
html += '  var cancelBtn=ov.querySelector("#kfDlgCancel");';
html += '  var confirmBtn=ov.querySelector("#kfDlgConfirm");';
html += '  iconEl.textContent=opts.icon||"❓";';
html += '  titleEl.textContent=opts.title||"请确认";';
html += '  msgEl.textContent=opts.message||"";';
html += '  cancelBtn.textContent=opts.cancelText||"取消";';
html += '  confirmBtn.textContent=opts.confirmText||"确定";';
html += '  confirmBtn.classList.toggle("danger",!!opts.danger);';
