  html += '      (function(f){';
  html += '        if(!/^image\\//.test(f.type))return;';
  html += '        if(f.size>8*1024*1024){kfAlert("单张图片不能超过 8MB","图片过大","🖼️");return;}';
  html += '        var rd=new FileReader();';
  html += '        rd.onload=function(ev){';
  html += '          var img=new Image();';
  html += '          img.onload=function(){';
  html += '            try{';
  html += '              var w=img.width,h=img.height;';
  html += '              var MAX=1280;';
  html += '              if(w>MAX||h>MAX){';
  html += '                var r=Math.min(MAX/w,MAX/h);w=Math.round(w*r);h=Math.round(h*r);';
  html += '              }';
  html += '              var cv=document.createElement("canvas");';
  html += '              cv.width=w;cv.height=h;';
  html += '              var cx=cv.getContext("2d");';
  html += '              cx.drawImage(img,0,0,w,h);';
