/* ---- API：导出反馈（管理员，JSON / CSV） ---- */
app.get('/kf/api/export', function (req, res) {
  var sess = gwGetSession(req);
  if (!sess) { res.status(401).json({ ok: false, error: '未登录' }); return; }
  var userRec = persistentUsers[sess.userName] || {};
  if (!userRec.isAdmin) {
    res.status(403).json({ ok: false, error: '仅管理员可操作' });
    return;
  }

  var fmt = String((req.query && req.query.fmt) || 'json').toLowerCase();
  var stamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);

  /* ---- CSV 分支 ---- */
  if (fmt === 'csv') {
    function _csv(s) {
      s = String(s == null ? '' : s).replace(/"/g, '""').replace(/\r?\n/g, ' ');
      return '"' + s + '"';
    }
    var lines = [];
    lines.push(['编号', '用户', '分类', '优先级', '状态',
      '内容', '联系方式', '管理员备注', '回复数',
      '创建时间', '更新时间'].join(','));
    for (var i = 0; i < feedbackList.length; i++) {
      var f = feedbackList[i];
      lines.push([
        _csv(f.id),
        _csv(f.userName),
        _csv((FEEDBACK_CATEGORY[f.category || 'other'] || {}).zh || ''),
        _csv((FEEDBACK_PRIORITY[f.priority || 'normal'] || {}).zh || ''),
        _csv((FEEDBACK_STATUS[f.status || 'unconfirmed'] || {}).zh || ''),
        _csv(f.content),
        _csv(f.contact || ''),
        _csv(f.adminNote || ''),
        _csv((f.replies || []).length),
        _csv(new Date(f.createdAt || 0).toLocaleString('zh-CN', { hour12: false })),
        _csv(new Date(f.updatedAt || 0).toLocaleString('zh-CN', { hour12: false }))
      ].join(','));
    }
    /* UTF-8 BOM，让 Excel 正确识别中文 */
    var csv = '\uFEFF' + lines.join('\r\n');
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader('Content-Disposition',
      'attachment; filename="feedback_' + stamp + '.csv"');
    res.end(csv);
    return;
  }

  /* ---- JSON 分支 ---- */
  var json = JSON.stringify({
    exportedAt: new Date().toISOString(),
    total: feedbackList.length,
    category: FEEDBACK_CATEGORY,
    priority: FEEDBACK_PRIORITY,
    status: FEEDBACK_STATUS,
    list: feedbackList
  }, null, 2);
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('Content-Disposition',
    'attachment; filename="feedback_' + stamp + '.json"');
  res.end(json);
});

