/* HTTP 限流：单 IP 每 10 秒 ≤ 120 次，已封禁 IP 一律 429 */
function attackGuardMiddleware(req, res, next) {
  /* ★ 走 _getRealIp：反向代理场景自动读取 X-Forwarded-For */
  var ip = _getRealIp(req);
  if (!ip) return next();

  /* 已封禁 IP → 直接 429 */
  if (_agIsBanned(ip)) {
    res.status(429).json({ ok: false, error: 'too many requests' });
    return;
  }

  /* 滑动窗口限流 */
  if (!_agRateCheck(agState.ipHttpHist, ip, AG.HTTP_WINDOW_MS, AG.MAX_HTTP_PER_IP)) {
    _agViolation(ip, 'http-flood');
    res.status(429).json({ ok: false, error: 'too many requests' });
    return;
  }

  next();
}
