  socket.on('device-remove', function (data) {
    var uid = socket.data && socket.data.userId;
    if (!uid || !data || !data.token) return;

    var list = devices[uid] || [];
    var target = null;
    for (var i = 0; i < list.length; i++) {
      if (list[i].token === data.token) { target = list[i]; break; }
    }
    if (!target) {
      socket.emit('device-removed', {
        ok: false, token: data.token, error: '设备不存在'
      });
      return;
    }
    /* 不允许移出当前设备（防止误操作把自己踢下线） */
    if (target.socketId && target.socketId === socket.id) {
      socket.emit('device-removed', {
        ok: false, token: data.token, error: '不能移除当前设备'
      });
      return;
    }

    var removed = removeDevice(uid, data.token);

    /* 若该设备仍在线 → 强制断开 */
    if (target.socketId) {
      var ts = io.sockets.sockets.get(target.socketId);
      if (ts) {
        try {
          ts.emit('force-logout', '该设备已被移出登录设备列表');
        } catch (e) { }
        setTimeout(function (sk) {
          return function () {
            try { sk.disconnect(true); } catch (e) { }
          };
        }(ts), 200);
      }
    }

    socket.emit('device-removed', {
      ok: removed, token: data.token, name: target.name || ''
    });
  });

