  socket.on('announcement-history-get', function (data) {
    var uid = socket.data && socket.data.userId;
    if (!uid || !data || !data.groupId) return;
    var gid = data.groupId;
    var group = getGroupById(gid);
    if (!group) return;
    if (!group.members.has(uid) && !getUserById(uid).isAdmin) return;
    socket.emit('announcement-history-data', {
      groupId: gid,
      history: (announcementHistory[gid] || []).slice().reverse()
    });
  });

  /* ==================== 关键词规则事件 ==================== */
  socket.on('keyword-rules-save', function (data) {
    var uid = socket.data && socket.data.userId;
    if (!uid || !data || !data.rules) return;
    keywordRules[uid] = data.rules;
    saveKeywordRules();
    socket.emit('keyword-rules-saved', { ok: true });
  });

  socket.on('keyword-rules-get', function () {
    var uid = socket.data && socket.data.userId;
    if (!uid) return;
    socket.emit('keyword-rules-data', {
      rules: keywordRules[uid] || { alerts: [], highlight: [] }
    });
  });

  /* ==================== 自定义快捷键事件 ==================== */
  socket.on('shortcuts-save', function (data) {
    var uid = socket.data && socket.data.userId;
    if (!uid || !data || !data.shortcuts) return;
    customShortcuts[uid] = data.shortcuts;
    saveShortcuts();
    socket.emit('shortcuts-saved', { ok: true });
  });

  socket.on('shortcuts-get', function () {
    var uid = socket.data && socket.data.userId;
    if (!uid) return;
    socket.emit('shortcuts-data', { shortcuts: customShortcuts[uid] || {} });
  });

  /* ==================== 时间段主题事件 ==================== */
  socket.on('time-theme-save', function (data) {
    var uid = socket.data && socket.data.userId;
    if (!uid || !data || !data.timeTheme) return;
    timeTheme[uid] = data.timeTheme;
    saveTimeTheme();
    socket.emit('time-theme-saved', { ok: true });
  });

  socket.on('time-theme-get', function () {
    var uid = socket.data && socket.data.userId;
    if (!uid) return;
    socket.emit('time-theme-data', {
      timeTheme: timeTheme[uid] || { enabled: false, dayStart: '08:00', dayEnd: '20:00' }
    });
  });

  /* ==================== 群公告变更时记录历史 + 清空已读 ==================== */
  var _origGroupAnnouncementHandler = null;
  socket.on('set-announcement', function (data) {
    var uid = socket.data && socket.data.userId;
    if (!uid || !data || !data.groupId) return;
    var group = getGroupById(data.groupId);
    if (!group) return;
    /* 记录到公告历史 */
    var user = getUserById(uid);
    addAnnouncementHistory(data.groupId, data.text || '', user ? user.name : '');
    /* 清空旧公告的已读记录 */
    if (announcementReads[data.groupId]) {
      delete announcementReads[data.groupId];
      saveAnnouncementReads();
    }
    /* 记录群动态 */
    addGroupActivity(data.groupId, 'announce', uid, user ? user.name : '', '', data.text || '');
  });

  /* ==================== 群成员变更时记录动态 ==================== */
  socket.on('group-member-action', function (data) {
    var uid = socket.data && socket.data.userId;
    if (!uid || !data || !data.groupId || !data.action) return;
    var user = getUserById(uid);
    if (!user) return;
    if (data.action === 'join' || data.action === 'add') {
      addGroupActivity(data.groupId, 'join', uid, user.name, data.target || '', '');
    } else if (data.action === 'leave' || data.action === 'kick') {
      addGroupActivity(data.groupId, 'leave', uid, user.name, data.target || '', '');
    } else if (data.action === 'rename') {
      addGroupActivity(data.groupId, 'rename', uid, user.name, '', data.extra || '');
    } else if (data.action === 'title') {
      addGroupActivity(data.groupId, 'title', uid, user.name, data.target || '', data.extra || '');
    } else if (data.action === 'mute-all') {
      addGroupActivity(data.groupId, 'mute-all', uid, user.name, '', data.extra || '');
    }
  });

  /* ==================== 自动回复：在收到私聊消息时触发 ==================== */
  function tryAutoReply(fromId, toId, text) {
    if (!toId || !fromId) return;
    var toUser = getUserById(toId);
    if (!toUser || toUser.online) return; /* 只处理离线用户的消息 */
    var rules = autoReplies[toId];
    if (!Array.isArray(rules)) return;
    var reply = matchAutoReply(toId, text);
    if (!reply) return;
    /* 延迟 1 秒后发送自动回复 */
    setTimeout(function () {
      var fromUser = getUserById(fromId);
      if (!fromUser || !fromUser.online) return;
      var autoMsg = {
        from: toId,
        fromName: toUser.name,
        to: fromId,
        content: reply,
        time: new Date().toLocaleString('zh-CN', { hour12: false }),
        msgId: generateId(),
        type: 'text',
        recalled: false,
        recalledBy: null,
        readUsers: [],
        fromLevel: toUser.level || 0,
        fromVip: !!toUser.vip,
        fromAdmin: !!toUser.isAdmin,
        isAutoReply: true
      };
      var pkey = getHistoryKey('private', toId, fromId);
      saveMessage('private', pkey, autoMsg);
      if (fromUser.online) emitToUser(fromId, 'private-message', autoMsg);
      /* 通知发送者消息已自动回复 */
      emitToUser(fromId, 'auto-reply-sent', { to: toId, reply: reply });
    }, 1000);
  }

  /* UI Guard 违规上报：先 ack 再断连；10 分钟内累计 3 次 → 封禁账号 10 分钟 */
  socket.on('ui-guard-violation', function (data, callback) {
    /* ★ v0.24.7：先 ack —— 保证客户端明确知道服务端已收到，
       客户端收到 ack 后才执行断连，避免「emit 后立即断连丢事件」。 */
    try {
      if (typeof callback === 'function') {
        callback({ received: true, ts: Date.now() });
      }
    } catch (eAck) { }

    var user = getUserBySocketId(socket.id);
    /* 未登录用户不参与账号封禁（没有可封的目标），
       但仍按 IP 记录，供后续审计。 */
    if (!user || !user.id) {
      var _ipAnon = String(socket.handshake.address || '');
      if (_ipAnon) {
        var _nowAnon = Date.now();
        var _recAnon = uiGuardViolations['ip:' + _ipAnon];
        if (!_recAnon || (_nowAnon - _recAnon.firstAt) > UI_GUARD_BAN_WINDOW_MS) {
          _recAnon = { count: 0, firstAt: _nowAnon, lastAt: _nowAnon };
          uiGuardViolations['ip:' + _ipAnon] = _recAnon;
        }
        _recAnon.count++;
        _recAnon.lastAt = _nowAnon;
        console.log('🛡️ [UI Guard] 未登录 IP ' + _ipAnon + ' 触发 ' +
          _recAnon.count + '/' + UI_GUARD_BAN_THRESHOLD);
      }
      return;
    }
    /* 管理员不参与统计 —— 管理员需要频繁调试界面，误伤代价高 */
    if (user.isAdmin) {
      console.log('🛡️ [UI Guard] 管理员 ' + user.name +
        ' 触发界面保护（已豁免统计）');
      return;
    }

    var now = Date.now();
    var rec = uiGuardViolations[user.id];

    /* ---- 窗口判定与计数 ---- */
    if (!rec || (now - rec.firstAt) > UI_GUARD_BAN_WINDOW_MS) {
      rec = { count: 0, firstAt: now, lastAt: now };
      uiGuardViolations[user.id] = rec;
    }
    rec.count++;
    rec.lastAt = now;

    var elem = data && data.element ? String(data.element).slice(0, 64) : '?';
    var act = data && data.action ? String(data.action).slice(0, 64) : '?';
    console.log('🛡️ [UI Guard] ' + user.name + ' 触发界面保护 ' +
      rec.count + '/' + UI_GUARD_BAN_THRESHOLD +
      '（元素 #' + elem + '，动作 ' + act + '）');

    /* ---- 未达阈值 → 仅记录 ---- */
    if (rec.count < UI_GUARD_BAN_THRESHOLD) return;

    /* ---- 达到阈值 → 封禁 10 分钟 ---- */
    var recUser = persistentUsers[user.name];
    if (!recUser) {
      /* 账号在持久化表中不存在（极少见）→ 仅清理计数 */
      delete uiGuardViolations[user.id];
      return;
    }

    recUser.banned = true;
    recUser.bannedAt = now;
    recUser.bannedBy = '系统（界面保护）';
    recUser.banReason = '多次触发界面保护';
    recUser.bannedUntil = now + UI_GUARD_BAN_DURATION_MS;
    saveUsers();

    /* 清空违规计数，避免解封后立即被再次封禁 */
    delete uiGuardViolations[user.id];

    console.log('');
    console.log('╔═══════════════════════════════════════════╗');
    console.log('║  🚫  自动封禁                              ║');
    console.log('╠═══════════════════════════════════════════╣');
    console.log('║  用户  : ' + user.name);
    console.log('║  原因  : 多次触发界面保护（10 分钟内 ' +
      UI_GUARD_BAN_THRESHOLD + ' 次）');
    console.log('║  时长  : 10 分钟');
    console.log('╚═══════════════════════════════════════════╝');
    console.log('');

    /* ============================================================
       ★ v0.24.7：断开该用户的【所有】连接（多设备同时踢出）
       ------------------------------------------------------------
       原先只断开 user.socketId 指向的那一个 socket，若同一账号
       在手机 + 电脑同时登录，只有触发违规的那一端被踢，另一端
       仍能收发消息 —— 表现就是「部分未封禁」。
       现在遍历全部 socket，凡是 socket.data.userId 或
       socket.rooms 命中该 uid 的全部断开。
       ============================================================ */
    var _bannedSockets = [];
    var _banTargetRoom = 'user:' + user.id;
    try {
      io.sockets.sockets.forEach(function (sk) {
        if (!sk) return;
        var hit = false;
        if (sk.data && sk.data.userId === user.id) hit = true;
        if (!hit && sk.rooms) {
          var _rooms = sk.rooms;
          var _check = function (rn) {
            if (rn && rn === _banTargetRoom) hit = true;
          };
          if (typeof _rooms.forEach === 'function') _rooms.forEach(_check);
          else if (_rooms.length) {
            for (var _ri = 0; _ri < _rooms.length; _ri++) _check(_rooms[_ri]);
          }
        }
        if (hit) _bannedSockets.push(sk);
      });
    } catch (eScan) {
      console.error('⚠️ 封禁扫描 socket 出错:', eScan.message);
    }

    /* 兜底：若扫描没找到任何 socket，至少断开 user.socketId 那个 */
    if (!_bannedSockets.length) {
      var _fallback = io.sockets.sockets.get(user.socketId);
      if (_fallback) _bannedSockets.push(_fallback);
    }

    for (var _bsi = 0; _bsi < _bannedSockets.length; _bsi++) {
      (function (sk) {
        try {
          sk.emit('account-banned', {
            reason: recUser.banReason,
            bannedBy: recUser.bannedBy,
            bannedUntil: recUser.bannedUntil
          });
        } catch (e) { }
        setTimeout(function () {
          try { sk.disconnect(true); } catch (e) { }
        }, 500);
      })(_bannedSockets[_bsi]);
    }
    console.log('🚫 已断开 ' + _bannedSockets.length + ' 个连接（用户 ' +
      user.name + '）');

    userMap.delete(user.id);
    io.emit('user-left', { id: user.id, name: user.name });
    broadcastUserList();
    io.emit('user-updated', {
      id: recUser.id, name: recUser.name, banned: true
    });

    log('BAN_USER', {
      target: user.name,
      by: '系统（界面保护）',
      reason: recUser.banReason,
      duration: '10 分钟'
    });
  });

  /* 管理员调试验证：遍历管理员账号比对密码哈希，成功签发 24h token */
  socket.on('verify-admin-dev', function (data, ack) {
    function _fail(msg) {
      if (typeof ack === 'function') ack({ ok: false, error: msg });
    }
    try {
      var _pwd = String((data && data.password) || '');
      if (!_pwd) { _fail('密码不能为空'); return; }
      var _input = looksLikeSha256Hex(_pwd) ? _pwd : hashSecret(_pwd);

      var _matched = null;
      for (var _name in persistentUsers) {
        if (!persistentUsers.hasOwnProperty(_name)) continue;
        var _rec = persistentUsers[_name];
        if (!_rec || !_rec.isAdmin) continue;
        if (!_rec.passwordHash) continue;
        if (_input === _rec.passwordHash) { _matched = _rec; break; }
      }

      if (!_matched) {
        console.warn('🛡️ [DevToken] 管理员调试验证失败（IP: ' +
          (socket.handshake.address || '?') + '）');
        _fail('密码错误或该账号不是管理员');
        return;
      }

      var _token = crypto.randomBytes(24).toString('hex');
      var _expires = Date.now() + ADMIN_DEV_TTL;
      adminDevTokens[_token] = {
        userId: _matched.id,
        name: _matched.name,
        expires: _expires
      };

      /* 清理过期 token */
      var _now = Date.now();
      for (var _tk in adminDevTokens) {
        if (adminDevTokens[_tk].expires < _now) delete adminDevTokens[_tk];
      }

      console.log('🔓 [DevToken] 管理员 "' + _matched.name +
        '" 已获得调试豁免（24 小时有效）');
      if (typeof ack === 'function') {
        ack({ ok: true, token: _token, name: _matched.name, expires: _expires });
      }
    } catch (e) {
      _fail('验证失败：' + (e && e.message ? e.message : '未知错误'));
    }
  });

  /* 客户端启动时校验已保存的 token 是否仍有效 */
  socket.on('check-admin-dev', function (data, ack) {
    var token = String((data && data.token) || '');
    var rec = adminDevTokens[token];
    if (!rec || rec.expires < Date.now()) {
      if (typeof ack === 'function') ack({ ok: false });
      return;
    }
    if (typeof ack === 'function') ack({ ok: true, name: rec.name });
  });

  /* ★ v0.24.47：主应用请求反馈中心免密令牌 ——
     服务器重启后内存 gwSessions 会清空，通过 socket 即时
     签发新 token 保证反馈页面总是可用。 */
  socket.on('request-feedback-token', function (ack) {
    var user = getUserBySocketId(socket.id);
    if (!user) {
      if (typeof ack === 'function') ack({ ok: false, error: '未登录' });
      return;
    }
    try {
      var token = gwCreateSession(user.id, user.name);
      if (typeof ack === 'function') ack({ ok: true, token: token });
      else socket.emit('feedback-token-issued', { ok: true, token: token });
    } catch (e) {
      if (typeof ack === 'function') ack({ ok: false, error: e && e.message });
    }
  });

  socket.on('disconnect', function () {
    /* ---- 攻击防护：释放连接计数 ---- */
    try {
      var _agIpD = socket.data && socket.data._agIp;
      if (_agIpD && agState.ipConn[_agIpD] > 0) {
        agState.ipConn[_agIpD]--;
        if (agState.ipConn[_agIpD] <= 0) delete agState.ipConn[_agIpD];
      }
      if (agState.totalConnections > 0) agState.totalConnections--;
    } catch (e) {}

    var user = getUserBySocketId(socket.id);
    if (user) {
      user.online = false;

      /* ★ v0.28.0：判断该用户是否还有其它 socket 在线（多设备）
         —— 只要有任一端还连着，就不能把整账号标离线。 */
      var _stillOnline = false;
      try {
        io.sockets.sockets.forEach(function (sk) {
          if (!sk || sk.id === socket.id) return;
          if (sk.connected === false) return;
          if (sk.data && sk.data.userId === user.id) _stillOnline = true;
        });
      } catch (eChk) { }

      if (!_stillOnline) {
        /* ---- 该用户真的完全离线 ---- */
        try { removeUserFromAllGroupCalls(user.id, user.name); } catch (e) { }

        /* ★ v0.28.0：离线时刷新最后活跃时间并持久化 */
        var _now = Date.now();
        var _rec = persistentUsers[user.name];
        if (_rec) {
          _rec.lastActive = _now;
          saveUsers();
        }

        io.emit('user-left', { id: user.id, name: user.name });
        /* ★ 广播 lastActive，让所有在线客户端的名片 / 全部用户弹窗
           实时看到「最后活跃」已更新 */
        io.emit('user-updated', {
          id: user.id, name: user.name, lastActive: _now
        });
        broadcastUserList();
        log('DISCONNECT', { userId: user.id, name: user.name });
      } else {
        log('DISCONNECT', {
          userId: user.id, name: user.name, stillOnline: true
        });
      }
    }
    /* 防御性清理：某些旧客户端重连过程里可能残留 room 关联，
       这里主动把当前 socket 从 user:* 房间退出，
       避免后续 io.to('user:'+id) 命中旧 socket（旧 socket 已死，
       命中也不会真正发出去，但清掉更干净）。 */
    try {
      if (socket.rooms) {
        var _rooms = socket.rooms;
        var _leave = function (rn) {
          if (rn && rn.indexOf('user:') === 0) {
            try { socket.leave(rn); } catch (e) { }
          }
        };
        if (typeof _rooms.forEach === 'function') _rooms.forEach(_leave);
        else if (_rooms.length) {
          for (var _i = 0; _i < _rooms.length; _i++) _leave(_rooms[_i]);
        }
      }
    } catch (e) { }
  });

  /* 注册 / 找回密码：登录前可用，放在 login 之外 */

  /* ---- 注册第一步：请求验证码 ---- */
  socket.on('register-request-code', function (data) {
    /* ★ 已登录用户不能注册新账号 */
    if (getUserBySocketId(socket.id)) {
      socket.emit('register-error', '已登录，无法注册新账号');
      return;
    }
    var name = String((data && data.name) || '').trim();
    if (!name) { socket.emit('register-error', '请输入昵称'); return; }
    if (name.length > 12) { socket.emit('register-error', '昵称过长（最多12字符）'); return; }
    if (persistentUsers[name]) { socket.emit('register-error', '该昵称已被注册'); return; }

    var code = genVerifyCode();
    pendingRegistrations[name] = {
      code: code,
      expires: Date.now() + REGISTER_CODE_TTL,
      createdAt: Date.now()
    };

    /* ★ 关键：在命令行打印验证码，供管理员转告用户 */
    console.log('');
    console.log('╔═══════════════════════════════════════════╗');
    console.log('║  📝  新用户注册验证码                     ║');
    console.log('╠═══════════════════════════════════════════╣');
    console.log('║  昵称  : ' + name);
    console.log('║  验证码: ' + code);
    console.log('║  有效期: 5 分钟');
    console.log('╚═══════════════════════════════════════════╝');
    console.log('');

    socket.emit('register-code-sent', { name: name, ttl: REGISTER_CODE_TTL });
    log('REGISTER_CODE', { name: name, code: code });
  });

  /* ---- 注册第二步：提交验证码 / 密码（可选）/ 密保（必填） ---- */
  socket.on('register-submit', function (data) {
    /* ★ 已登录用户不能注册新账号 */
    if (getUserBySocketId(socket.id)) {
      socket.emit('register-error', '已登录，无法注册新账号');
      return;
    }
    var name = String((data && data.name) || '').trim();
    var code = String((data && data.code) || '').trim();
    var password = String((data && data.password) || '');
    var secQ = String((data && data.securityQuestion) || '').trim();
    var secA = String((data && data.securityAnswer) || '').trim();

    if (!name) { socket.emit('register-error', '请输入昵称'); return; }
    if (name.length > 12) { socket.emit('register-error', '昵称过长（最多12字符）'); return; }
    /* ★ v0.25.0 安全：昵称白名单 */
    if (!isValidNickname(name)) {
      socket.emit('register-error', '昵称包含非法字符'); return;
    }
    if (!/^\d{6}$/.test(code)) { socket.emit('register-error', '验证码为 6 位数字'); return; }
    if (persistentUsers[name]) { socket.emit('register-error', '该昵称已被注册'); return; }

    var pending = pendingRegistrations[name];
    if (!pending) { socket.emit('register-error', '请先点击「获取」生成验证码'); return; }
    if (Date.now() > pending.expires) {
      delete pendingRegistrations[name];
      socket.emit('register-error', '验证码已过期，请重新获取');
      return;
    }
    if (pending.code !== code) { socket.emit('register-error', '验证码错误'); return; }

    /* ★ 密码必填：客户端传上来的是 SHA256 哈希（64 位十六进制）。
       兼容旧客户端：若收到明文，则此处自行哈希。 */
    if (!password) {
      socket.emit('register-error', '请设置密码（至少 6 位）');
      return;
    }
    if (looksLikeSha256Hex(password)) {
      /* 已经是哈希，直接采用 */
    } else if (String(password).length >= 6) {
      /* 兼容：明文密码 → 服务端哈希 */
      password = hashSecret(String(password));
    } else {
      socket.emit('register-error', '请设置密码（至少 6 位）');
      return;
    }
    /* 密保必填，用于日后找回密码 */
    if (!secQ) { socket.emit('register-error', '请设置密保问题'); return; }
    if (!secA) { socket.emit('register-error', '请设置密保答案'); return; }

    /* ---- 创建账号 ---- */
    var id = generateId();
    var hasAdmin = false;
    for (var k in persistentUsers) {
      if (persistentUsers[k] && persistentUsers[k].isAdmin) { hasAdmin = true; break; }
    }
    var isAdmin = !hasAdmin;
    var level = isAdmin ? MAX_LEVEL : (Math.floor(Math.random() * 10) + 1);
    var userExp = expForLevel(level);

    persistentUsers[name] = {
      id: id, name: name, level: level, vip: !!isAdmin,
      isAdmin: isAdmin, muted: false, verified: '',
      presence: 'online', exp: userExp, lastSignin: '',
      /* ★ 新增：注册时间与最后活跃时间 */
      createdAt: Date.now(),
      lastActive: Date.now(),
      /* ★ 认证字段：密码与密保均为必填（上面已校验）。
         password 此时已确定是哈希值（客户端预哈希 or 服务端兜底）。 */
      passwordHash: password,
      securityQuestion: secQ.slice(0, 60),
      securityAnswerHash: hashSecret(secA.toLowerCase()),
      /* 设备令牌列表：首次登录成功时签发 */
      deviceTokens: []
    };
    saveUsers();
    delete pendingRegistrations[name];

    console.log('✅ 新用户注册成功: ' + name + ' (ID: ' + id + ')' +
      (isAdmin ? ' [首位用户·管理员]' : '') +
      (password ? ' [已设密码]' : ' [无密码]'));
    socket.emit('register-success', { name: name, hasPassword: !!password });
    log('REGISTER_SUCCESS', { name: name, id: id, isAdmin: isAdmin });
  });

  /* ---- 找回密码第一步：查询密保问题 ---- */
  socket.on('forgot-request', function (data) {
    /* ★ 已登录用户不能发起找回密码 */
    if (getUserBySocketId(socket.id)) {
      socket.emit('forgot-error', '已登录，无法发起找回密码');
      return;
    }
    var name = String((data && data.name) || '').trim();
    if (!name) { socket.emit('forgot-error', '请输入昵称'); return; }
    var rec = persistentUsers[name];
    if (!rec) { socket.emit('forgot-error', '该昵称未注册'); return; }
    if (!rec.securityQuestion) {
      socket.emit('forgot-error', '该账号未设置密保，无法找回密码，请联系管理员');
      return;
    }
    socket.emit('forgot-question', { name: name, question: rec.securityQuestion });
  });

  /* ---- 找回密码第二步：校验密保答案并重置密码 ---- */
  socket.on('forgot-verify', function (data) {
    /* ★ 已登录用户不能通过此接口重置密码 */
    if (getUserBySocketId(socket.id)) {
      socket.emit('forgot-error', '已登录，无法通过此接口重置密码');
      return;
    }
    var name = String((data && data.name) || '').trim();
    var answer = String((data && data.answer) || '').trim();
    var newPassword = String((data && data.newPassword) || '');

    if (!name || !answer) { socket.emit('forgot-error', '请填写完整'); return; }
    /* ★ 新密码：客户端预哈希（64 位 hex）或旧客户端明文 */
    var _newPwdHash = '';
    if (newPassword && looksLikeSha256Hex(newPassword)) {
      _newPwdHash = newPassword;
    } else if (newPassword && String(newPassword).length >= 6) {
      _newPwdHash = hashSecret(String(newPassword));
    } else {
      socket.emit('forgot-error', '新密码至少 6 位');
      return;
    }

    var rec = persistentUsers[name];
    if (!rec || !rec.securityQuestion) {
      socket.emit('forgot-error', '账号异常，无法找回'); return;
    }
    if (hashSecret(answer.toLowerCase()) !== rec.securityAnswerHash) {
      socket.emit('forgot-error', '密保答案错误');
      log('FORGOT_FAIL', { name: name });
      return;
    }
    rec.passwordHash = _newPwdHash;
    saveUsers();
    console.log('🔑 用户 "' + name + '" 通过密保重置了密码');
    socket.emit('forgot-success', { name: name });
    log('FORGOT_SUCCESS', { name: name });
  });

  /* ---- 老用户补设密码与密保（首次登录时强制） ---- */
  socket.on('setup-account', function (data) {
    /* ★ 已登录用户不能再走老用户补设流程 */
    if (getUserBySocketId(socket.id)) {
      socket.emit('setup-error', '已登录，无需重复设置');
      return;
    }
    var name = String((data && data.name) || '').trim();
    var password = String((data && data.password) || '');
    var secQ = String((data && data.securityQuestion) || '').trim();
    var secA = String((data && data.securityAnswer) || '').trim();

    if (!name) { socket.emit('setup-error', '昵称不能为空'); return; }
    var rec = persistentUsers[name];
    if (!rec) { socket.emit('setup-error', '账号不存在'); return; }
    /* 已设密码 → 说明上一次已经保存成功（可能是网络抖动重试），
       直接返回 setup-success，让客户端继续走登录流程，避免用户困惑。 */
    if (rec.passwordHash) {
      console.log('ℹ️ 老用户 "' + name + '" 的密码已存在，跳过一次重复设置');
      socket.emit('setup-success', {
        name: name,
        hasPassword: true,
        hasSecurity: !!rec.securityAnswerHash,
        already: true
      });
      return;
    }
    /* ★ 密码：客户端预哈希（64 位 hex）或旧客户端明文，两种都接受 */
    var _setupPwdHash = '';
    if (password && looksLikeSha256Hex(password)) {
      _setupPwdHash = password;
    } else if (password && String(password).length >= 6) {
      _setupPwdHash = hashSecret(String(password));
    } else {
      socket.emit('setup-error', '密码至少 6 位');
      return;
    }
    if (!secQ) { socket.emit('setup-error', '请填写密保问题'); return; }
    if (!secA) { socket.emit('setup-error', '请填写密保答案'); return; }

    rec.passwordHash = _setupPwdHash;
    rec.securityQuestion = secQ.slice(0, 60);
    rec.securityAnswerHash = hashSecret(secA.toLowerCase());
    saveUsers();

    console.log('🔐 老用户 "' + name + '" 已完成密码与密保设置');
    console.log('   密码哈希前缀: ' + rec.passwordHash.slice(0, 12) + '…');
    console.log('   密保问题: ' + rec.securityQuestion);
    /* ★ 回执里附带关键字段，客户端可据此确认保存成功 */
    socket.emit('setup-success', {
      name: name,
      hasPassword: !!rec.passwordHash,
      hasSecurity: !!rec.securityAnswerHash
    });
    log('SETUP_ACCOUNT', { name: name, saved: !!rec.passwordHash });
  });

  /* ==================== Web 终端 ==================== */
  socket.on('terminal-auth', function (data) {
    var code = String((data && data.code) || '').trim();

    /* ★ 先检查是否过期 */
    if (Date.now() > _termCodeExpires) {
      socket.emit('terminal-auth-result', {
        ok: false,
        error: '验证码已过期（有效期 5 分钟），请重新获取',
        expired: true
      });
      console.log('⚠️  Web 终端验证：验证码已过期（IP: ' +
        (socket.handshake.address || 'unknown') + '）');
      return;
    }

    if (code === _termCode) {
      socket.data.termAuthorized = true;
      socket.emit('terminal-auth-result', { ok: true });
      console.log('🖥️  Web 终端已授权（IP: ' +
        (socket.handshake.address || 'unknown') + '）');
    } else {
      socket.emit('terminal-auth-result', { ok: false, error: '验证码错误' });
      console.log('⚠️  Web 终端验证失败（IP: ' +
        (socket.handshake.address || 'unknown') + '）');
    }
  });

  /* ★ Web 终端「获取验证码」：
     浏览器点按钮 → 服务端重新生成一个 6 位验证码，
     打印到服务器命令行，并回执浏览器。
     同一 socket 30 秒内只能请求一次，防止刷屏。 */
  socket.on('terminal-request-code', function () {
    var now = Date.now();
    var COOLDOWN = 30000;
    if (socket.data._lastCodeReq && now - socket.data._lastCodeReq < COOLDOWN) {
      var wait = Math.ceil((COOLDOWN - (now - socket.data._lastCodeReq)) / 1000);
      socket.emit('terminal-code-sent', {
        ok: false,
        error: '请 ' + wait + ' 秒后再试',
        remain: wait
      });
      return;
    }
    socket.data._lastCodeReq = now;

    /* 生成新验证码 */
    _termCode = String(Math.floor(100000 + Math.random() * 900000));
    _termCodeExpires = Date.now() + TERM_CODE_TTL;

    var ip = socket.handshake.address || 'unknown';
    var timeStr = new Date().toLocaleString('zh-CN', { hour12: false });
    console.log('');
    console.log('╔═══════════════════════════════════════════╗');
    console.log('║  🖥️  Web 终端访问码（重新获取）           ║');
    console.log('╠═══════════════════════════════════════════╣');
    console.log('║  访问码  : ' + _termCode);
    console.log('║  请求者  : ' + ip);
    console.log('║  时间    : ' + timeStr);
    console.log('║  有效期  : 5 分钟');
    console.log('╚═══════════════════════════════════════════╝');
    console.log('');

    socket.emit('terminal-code-sent', { ok: true });
  });

  socket.on('terminal-exec', function (data) {
    /* 未授权 → 直接拒绝 */
    if (!socket.data || !socket.data.termAuthorized) {
      socket.emit('terminal-output', { text: '❌ 未授权，请先输入访问码' });
      return;
    }
    var cmd = String((data && data.cmd) || '').trim();
    if (!cmd) return;

    /* 拦截可能影响进程本身的命令 */
    var cmdMain = cmd.split(/\s+/)[0].toLowerCase();
    if (cmdMain === 'exit') {
      socket.emit('terminal-output', {
        text: '❌ Web 终端不支持 exit（避免误关服务器）\n' +
          '   如需关闭请到服务器本地命令行执行'
      });
      return;
    }

    /* ★ v0.30.0：只读模式下的命令白名单 */
    if (config.readOnly) {
      var _RO_TERM_ALLOW = {
        'help': 1, 'h': 1, '?': 1,
        'help+': 1, 'help-extra': 1,
        'status': 1, 'info': 1,
        'online': 1, 'sessions': 1, 'mem': 1, 'gc': 1, 'uptime': 1,
        'readonly': 1, 'ro': 1,
        'kflist': 1, 'kfshow': 1, 'kfstats': 1, 'kfhelp': 1,
        'whois': 1, 'wallet': 1, 'wallets': 1
      };
      if (!_RO_TERM_ALLOW[cmdMain]) {
        socket.emit('terminal-output', {
          text: '🔒 服务器处于只读模式，仅允许查看类命令\n' +
            '\n' +
            '允许：help   online   sessions   mem   gc   uptime   status\n' +
            '      kflist   kfshow   kfstats   kfhelp   whois   wallet   wallets\n' +
            '      readonly off   （关闭只读模式）\n' +
            '\n' +
            '当前命令 "' + cmdMain + '" 已被拒绝。'
        });
        console.warn('🔒 [只读模式] Web 终端拦截命令：' + cmdMain);
        return;
      }
    }

    /* ============================================================
       ★ 反馈中心快捷指令（kf 系列）
       ============================================================ */
    try {
      var _kfArgs = cmd.split(/\s+/).slice(1);
      var _kfOut = null;

      if (cmdMain === 'kflist' || cmdMain === 'feedback-list') {
        var _kfN = Math.min(50, parseInt(_kfArgs[0], 10) || 10);
        var _kfSorted = feedbackList.slice().sort(function (a, b) {
          return (b.createdAt || 0) - (a.createdAt || 0);
        });
        var _kfLines = ['📮 最近 ' + _kfN + ' 条反馈（共 ' + feedbackList.length + ' 条）'];
        for (var _ki = 0; _ki < Math.min(_kfN, _kfSorted.length); _ki++) {
          var _kf = _kfSorted[_ki];
          var _kfSt = FEEDBACK_STATUS[_kf.status || 'unconfirmed'] || { zh: '?' };
          var _kfP = FEEDBACK_PRIORITY[_kf.priority || 'normal'] || { zh: '?' };
          _kfLines.push('  ' + _kf.id + ' [' + _kfSt.zh + '/' + _kfP.zh + '] ' +
            String(_kf.userName || '').padEnd(10, ' ') + ' ' +
            String(_kf.content || '').slice(0, 40).replace(/\n/g, ' '));
        }
        _kfOut = _kfLines.join('\n');
      } else if (cmdMain === 'kfshow' || cmdMain === 'feedback-show') {
        var _kfId = String(_kfArgs[0] || '').trim();
        if (!_kfId) { _kfOut = '用法：kfshow <反馈编号>，例如：kfshow WL-000001'; }
        else {
          var _kfF = null;
          for (var _kj = 0; _kj < feedbackList.length; _kj++) {
            if (feedbackList[_kj].id === _kfId) { _kfF = feedbackList[_kj]; break; }
          }
          if (!_kfF) { _kfOut = '❌ 反馈不存在：' + _kfId; }
          else {
            var _kfSt2 = FEEDBACK_STATUS[_kfF.status || 'unconfirmed'] || { zh: '?' };
            var _kfC2 = FEEDBACK_CATEGORY[_kfF.category || 'other'] || { zh: '?' };
            var _kfP2 = FEEDBACK_PRIORITY[_kfF.priority || 'normal'] || { zh: '?' };
            var _kfL = [
              '━━━ 反馈 ' + _kfF.id + ' ━━━',
              '用户  : ' + _kfF.userName,
              '状态  : ' + _kfSt2.zh,
              '类型  : ' + _kfC2.zh,
              '优先级: ' + _kfP2.zh,
              '时间  : ' + new Date(_kfF.createdAt || 0).toLocaleString('zh-CN', { hour12: false }),
              '内容  :',
              '  ' + String(_kfF.content || '').replace(/\n/g, '\n  ')
            ];
            if (_kfF.adminNote) _kfL.push('备注  : ' + _kfF.adminNote);
            if (Array.isArray(_kfF.replies) && _kfF.replies.length) {
              _kfL.push('回复历史 (' + _kfF.replies.length + '):');
              for (var _kr = 0; _kr < _kfF.replies.length; _kr++) {
                var _krr = _kfF.replies[_kr];
                _kfL.push('  [' + new Date(_krr.at || 0).toLocaleString('zh-CN', { hour12: false }) + '] ' +
                  _krr.by + ': ' + String(_krr.text || '').slice(0, 60));
              }
            }
            _kfOut = _kfL.join('\n');
          }
        }
      } else if (cmdMain === 'kfstats' || cmdMain === 'feedback-stats') {
        var _kfs = { open: 0, in_progress: 0, resolved: 0, fixed: 0, cannot_reproduce: 0, duplicate: 0, invalid: 0, wont_fix: 0 };
        var _kfUrgent = 0;
        for (var _ks = 0; _ks < feedbackList.length; _ks++) {
          var _fk = feedbackList[_ks];
          var _fs = _fk.status || 'unconfirmed';
          if (_fs === 'unconfirmed') _fs = 'open';
          if (_kfs[_fs] != null) _kfs[_fs]++;
          if ((_fk.priority === 'urgent' || _fk.priority === 'high') &&
              _fs === 'open') _kfUrgent++;
        }
        _kfOut = [
          '📊 反馈统计（共 ' + feedbackList.length + ' 条）',
          '  待处理    : ' + _kfs.open,
          '  处理中    : ' + _kfs.in_progress,
          '  已解决    : ' + _kfs.resolved,
          '  已修复    : ' + _kfs.fixed,
          '  无法复现  : ' + _kfs.cannot_reproduce,
          '  重复      : ' + _kfs.duplicate,
          '  无效      : ' + _kfs.invalid,
          '  不予处理  : ' + _kfs.wont_fix,
          '  ⚠️  高优/紧急待处理 : ' + _kfUrgent
        ].join('\n');
      } else if (cmdMain === 'kfreply') {
        var _kfRid = String(_kfArgs[0] || '').trim();
        var _kfRtext = _kfArgs.slice(1).join(' ').trim();
        if (!_kfRid || !_kfRtext) {
          _kfOut = '用法：kfreply <反馈编号> <回复内容>';
        } else {
          var _kfRF = null;
          for (var _kx = 0; _kx < feedbackList.length; _kx++) {
            if (feedbackList[_kx].id === _kfRid) { _kfRF = feedbackList[_kx]; break; }
          }
          if (!_kfRF) { _kfOut = '❌ 反馈不存在：' + _kfRid; }
          else {
            if (!Array.isArray(_kfRF.replies)) _kfRF.replies = [];
            var _kfNow = Date.now();
            _kfRF.replies.push({
              id: 'r' + _kfNow.toString(36) + Math.random().toString(36).slice(2, 6),
              by: '服务器控制台',
              role: 'admin',
              text: _kfRtext.slice(0, 1000),
              at: _kfNow
            });
            _kfRF.updatedAt = _kfNow;
            saveFeedback();
            _kfOut = '✅ 已回复 ' + _kfRid + '：' + _kfRtext.slice(0, 60);
            try {
              var _kfOwner = getUserById(_kfRF.userId);
              if (_kfOwner && _kfOwner.online) {
                emitToUser(_kfOwner.id, 'feedback-replied', {
                  id: _kfRF.id, text: _kfRtext,
                  by: '服务器控制台', time: _kfNow
                });
              }
            } catch (e) {}
          }
        }
      } else if (cmdMain === 'kfdel') {
        var _kfDid = String(_kfArgs[0] || '').trim();
        if (!_kfDid) { _kfOut = '用法：kfdel <反馈编号>'; }
        else {
          var _kfIdx = -1;
          for (var _kz = 0; _kz < feedbackList.length; _kz++) {
            if (feedbackList[_kz].id === _kfDid) { _kfIdx = _kz; break; }
          }
          if (_kfIdx === -1) { _kfOut = '❌ 反馈不存在：' + _kfDid; }
          else {
            feedbackList.splice(_kfIdx, 1);
            saveFeedback();
            _kfOut = '🗑️ 已删除反馈：' + _kfDid;
          }
        }
      } else if (cmdMain === 'kfopen' || cmdMain === 'feedback-open') {
        var _kfHost = String((socket.handshake.headers && socket.handshake.headers.host) || 'localhost:3000');
        var _kfProto = 'https';
        try {
          var _xhp = socket.handshake.headers && socket.handshake.headers['x-forwarded-proto'];
          if (_xhp) _kfProto = String(_xhp).split(',')[0].trim();
        } catch (e) {}
        _kfOut = '📮 反馈中心地址：\n  ' + _kfProto + '://' + _kfHost + '/kf\n' +
          '  管理员可直接访问，普通用户需登录。';
      } else if (cmdMain === 'kfhelp' || cmdMain === 'feedback-help') {
        _kfOut = [
          '📮 反馈中心快捷指令',
          '  kflist [n]        列出最近 n 条反馈（默认 10）',
          '  kfshow <id>       查看指定反馈详情',
          '  kfstats           查看反馈统计',
          '  kfreply <id> <文> 以管理员身份回复反馈',
          '  kfdel <id>        删除指定反馈（不可撤销）',
          '  kfopen            显示反馈中心地址',
          '  kfhelp            显示本帮助'
        ].join('\n');
      }

      if (_kfOut !== null) {
        socket.emit('terminal-output', { text: _kfOut });
        console.log('[Web终端] ' + (socket.handshake.address || '?') + ' > ' + cmd);
        return;
      }
    } catch (_kfErr) {
      socket.emit('terminal-output', {
        text: '❌ kf 指令执行出错: ' + (_kfErr && _kfErr.message ? _kfErr.message : String(_kfErr))
      });
      return;
    }

    /* 捕获 console.log 输出 */
    var outputs = [];
    var _origLog = console.log;
    console.log = function () {
      try {
        var args = Array.prototype.slice.call(arguments);
        outputs.push(args.map(function (x) {
          if (typeof x === 'string') return x;
          if (x === null || x === undefined) return String(x);
          if (typeof x === 'object') {
            try { return JSON.stringify(x); }
            catch (e) { return '[object]'; }
          }
          return String(x);
        }).join(' '));
      } catch (e) { }
    };

    try {
      handleCommand(cmd);
    } catch (e) {
      outputs.push('❌ 命令执行出错: ' + (e && e.message ? e.message : String(e)));
    } finally {
      console.log = _origLog;
    }

    socket.emit('terminal-output', {
      text: outputs.length ? outputs.join('\n') : '(无输出)'
    });

    /* 记录到终端日志 */
    console.log('[Web终端] ' + (socket.handshake.address || '?') + ' > ' + cmd);
  });

  /* ==================== 网络状态：延迟测量 ====================
     客户端定期发送 net-ping 带时间戳；服务端原样回发 net-pong。
     客户端据此计算往返延迟 RTT。
     只允许已登录连接使用，避免未认证连接刷流量。 */
  socket.on('net-ping', function (data) {
    if (!getUserBySocketId(socket.id)) return;
    socket.emit('net-pong', {
      t: (data && typeof data.t === 'number') ? data.t : Date.now()
    });
  });

  socket.on('get-history', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    /* ★ 群聊 key 是 group_<群ID>，不能传 user.id 当第一个参数 */
    var key = (data.type === 'group')
      ? getHistoryKey('group', data.targetId)
      : getHistoryKey('private', user.id, data.targetId);
    var arr = messageHistory[key] || [];
    socket.emit('history', {
      targetId: data.targetId,
      type: data.type,
      /* 只下发最近 HISTORY_PAGE_SIZE 条 */
      messages: arr.slice(-HISTORY_PAGE_SIZE),
      hasMore: arr.length > HISTORY_PAGE_SIZE
    });
  });

  /* ============================================================
     按需加载更早的消息
     ------------------------------------------------------------
     客户端滚动到顶部时发送：
       { type, targetId, beforeMsgId, limit }
     服务端返回该消息之前的 HISTORY_PAGE_SIZE 条。
     ============================================================ */
  socket.on('history-load-more', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data || !data.targetId) return;
    var type = (data.type === 'group') ? 'group' : 'private';
    /* ★ 同上：群聊必须用 group_<群ID> */
    var key = (type === 'group')
      ? getHistoryKey('group', data.targetId)
      : getHistoryKey('private', user.id, data.targetId);
    var arr = messageHistory[key] || [];
    if (!arr.length) {
      socket.emit('history-more', {
        targetId: data.targetId, type: type,
        messages: [], hasMore: false
      });
      return;
    }
    /* 定位 beforeMsgId 在数组中的位置 */
    var endIdx = arr.length;
    if (data.beforeMsgId) {
      for (var i = arr.length - 1; i >= 0; i--) {
        if (arr[i].msgId === data.beforeMsgId) { endIdx = i; break; }
      }
    }
    var limit = Math.max(1, Math.min(200,
      parseInt(data.limit, 10) || HISTORY_PAGE_SIZE));
    var startIdx = Math.max(0, endIdx - limit);
    socket.emit('history-more', {
      targetId: data.targetId,
      type: type,
      messages: arr.slice(startIdx, endIdx),
      hasMore: startIdx > 0
    });
  });

  socket.on('get-my-history', function () {
    var user = getUserBySocketId(socket.id);
    if (!user) return;
    var _uh2 = getUserHistory(user.id) || { private: {}, group: {}, peers: {} };
    if (!_uh2.private || typeof _uh2.private !== 'object') _uh2.private = {};
    if (!_uh2.group || typeof _uh2.group !== 'object') _uh2.group = {};
    if (!_uh2.peers || typeof _uh2.peers !== 'object') _uh2.peers = {};
    socket.emit('history-bulk', { data: _uh2 });
  });

  /* ==================== 个人名片 ==================== */
  socket.on('profile-update', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var prof = user.profile || {};
    if (typeof data.signature === 'string') prof.signature = data.signature.slice(0, 200);
    if (typeof data.gender === 'string') prof.gender = data.gender.slice(0, 10);
    if (typeof data.mood === 'string') prof.mood = data.mood.slice(0, 20);
    /* ★ v0.32.0：MBTI 性格（4 位英文大写字母） */
    if (typeof data.personality === 'string') {
      var _persCode = String(data.personality).toUpperCase().replace(/[^A-Z]/g, '').slice(0, 4);
      prof.personality = _persCode;
    }
    if (typeof data.birthday === 'string') prof.birthday = data.birthday.slice(0, 20);
    if (typeof data.location === 'string') prof.location = data.location.slice(0, 30);
    if (typeof data.website === 'string') prof.website = data.website.slice(0, 100);
    if (typeof data.avatar === 'string') {
      /* 头像大小限制 ~500KB base64 */
      if (data.avatar.length <= 700000) prof.avatar = data.avatar;
    }
    /* ★ v0.27.13：拍一拍三段式模板 */
    if (data.patTemplate && typeof data.patTemplate === 'object') {
      prof.patTemplate = {
        pre: String(data.patTemplate.pre == null
          ? '拍' : data.patTemplate.pre).slice(0, 4),
        mid: String(data.patTemplate.mid == null
          ? '拍' : data.patTemplate.mid).slice(0, 4),
        suf: String(data.patTemplate.suf == null
          ? '' : data.patTemplate.suf).slice(0, 12)
      };
    }
    user.profile = prof;
    if (persistentProfiles[user.name] === undefined) persistentProfiles[user.name] = {};
    persistentProfiles[user.name] = prof;
    saveProfiles();

    /* 广播给所有人 */
    io.emit('user-updated', { id: user.id, name: user.name, profile: prof });
    socket.emit('profile-updated', { profile: prof });
    log('PROFILE_UPDATE', { user: user.name });
  });

  /* ==================== 用户在线状态 ====================
     客户端在设置面板切换后 emit 此事件。
     服务端校验取值 → 写入 userMap 与持久化表 → 广播给所有客户端。 */
  socket.on('user-presence', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    /* 白名单：只允许四种状态，其余一律回落到 online */
    var pres = String(data.presence || 'online');
    if (['online', 'away', 'busy', 'dnd',
         'listening', 'gaming', 'working',
         'studying', 'eating', 'sleeping'].indexOf(pres) === -1) pres = 'online';
    user.presence = pres;
    if (persistentUsers[user.name]) persistentUsers[user.name].presence = pres;
    saveUsers();
    /* user-updated 让所有人即时更新该用户的圆点 / 状态行 */
    io.emit('user-updated', { id: user.id, name: user.name, presence: pres });
    broadcastUserList();
    log('PRESENCE_UPDATE', { user: user.name, presence: pres });
  });

  socket.on('profile-get', function (data) {
    var target = null;
    if (data && data.userId) target = getUserById(data.userId);
    else if (data && data.name) target = getUserByName(data.name);
    
    if (!target) { 
      /* ★ 防枚举扫描：频繁查询不存在的用户，增加违规分 */
      _agViolation(socket.data._agIp, 'id-enumeration');
      socket.emit('profile-data', { found: false }); 
      return; 
    }
    socket.emit('profile-data', {
      found: true,
      userId: target.id,
      name: target.name,
      profile: target.profile || {},
      online: target.online,
      level: target.level || 0,
      vip: !!target.vip,
      verified: target.verified || '',
      isAdmin: !!target.isAdmin,
      /* ★ 封禁状态：客户端据此在名片中显示封禁横幅 */
      banned: !!target.banned,
      /* ★ 下发注册时间和最后活跃时间 */
      createdAt: persistentUsers[target.name] ? (persistentUsers[target.name].createdAt || 0) : 0,
      lastActive: persistentUsers[target.name] ? (persistentUsers[target.name].lastActive || 0) : 0
    });
  });

  /* ==================== 修改昵称 ====================
     昵称是 persistentUsers / persistentStickers / persistentProfiles
     三个持久化表的 key，改名时需要一并迁移；
     blocks / wallets / redPackets / moments 都以 userId 索引，
     不受影响，无需迁移。 */
  socket.on('rename-user', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;

    var newName = String(data.newName || '').trim();
    if (!newName) { socket.emit('rename-error', '昵称不能为空'); return; }
    if (newName.length > 12) { socket.emit('rename-error', '昵称过长（最多12字符）'); return; }
    /* ★ v0.25.0 安全：昵称白名单 */
    if (!isValidNickname(newName)) {
      socket.emit('rename-error', '昵称包含非法字符'); return;
    }
    if (newName === user.name) { socket.emit('rename-error', '新昵称与当前昵称相同'); return; }

    /* ★ v0.25.1：风控 —— 改名频率 */
    riskCheckRename(user.id);
    /* 冲突检测：持久化表 + 内存表各查一遍 */
    var _conflict = false;
    if (persistentUsers[newName] && persistentUsers[newName].id !== user.id) _conflict = true;
    if (!_conflict) {
      userMap.forEach(function (u) {
        if (u.id !== user.id && u.name === newName) _conflict = true;
      });
    }
    if (_conflict) { socket.emit('rename-error', '该昵称已被使用'); return; }

    var oldName = user.name;

    /* ---- 迁移三张按昵称索引的持久化表 ---- */
    if (persistentUsers[oldName]) {
      persistentUsers[newName] = persistentUsers[oldName];
      persistentUsers[newName].name = newName;
      delete persistentUsers[oldName];
    }
    if (persistentStickers[oldName]) {
      persistentStickers[newName] = persistentStickers[oldName];
      delete persistentStickers[oldName];
    }
    if (persistentProfiles[oldName]) {
      persistentProfiles[newName] = persistentProfiles[oldName];
      delete persistentProfiles[oldName];
    }
    saveUsers();
    saveStickers();
    saveProfiles();

    /* ---- 更新内存中的用户对象 ---- */
    user.name = newName;
    socket.data.userName = newName;

    /* ---- 记录改名历史（存入 profile，随 user-updated 全站可见） ---- */
    var _prof = user.profile || {};
    if (!Array.isArray(_prof.renameHistory)) _prof.renameHistory = [];
    _prof.renameHistory.unshift({
      oldName: oldName,
      newName: newName,
      time: Date.now(),
      by: user.id
    });
    /* 只保留最近 50 条，避免数据无限膨胀 */
    if (_prof.renameHistory.length > 50) _prof.renameHistory.length = 50;
    user.profile = _prof;
    /* 同步到持久化表（此时 key 已迁移到 newName） */
    if (persistentProfiles[newName] === undefined) persistentProfiles[newName] = {};
    persistentProfiles[newName] = _prof;
    saveProfiles();

    /* ---- 广播给所有人（包括自己） ----
       带上完整 profile（含 renameHistory），
       这样别人正在查看我的名片时也能实时看到改名记录。 */
    io.emit('user-updated', {
      id: user.id,
      name: newName,
      profile: _prof
    });
    socket.emit('rename-success', {
      id: user.id,
      name: newName,
      renameHistory: _prof.renameHistory
    });
    broadcastUserList();

    log('RENAME_USER', { id: user.id, oldName: oldName, newName: newName });
  });

  socket.on('sticker-upload', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user) return;
    if (!data || !data.dataUrl) return;
    if (String(data.dataUrl).length > 800000) {
      socket.emit('sticker-error', '表情包太大（请小于 500KB）');
      return;
    }
    var list = persistentStickers[user.name] || [];
    if (list.length >= 60) {
      socket.emit('sticker-error', '表情包已达上限（60个）');
      return;
    }
    list.push(data.dataUrl);
    persistentStickers[user.name] = list;
    saveStickers();
    socket.emit('sticker-updated', { stickers: list });
    log('STICKER_UPLOAD', { user: user.name, count: list.length });
  });

  socket.on('sticker-delete', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user) return;
    var list = persistentStickers[user.name] || [];
    var idx = parseInt(data && data.index, 10);
    if (isNaN(idx) || idx < 0 || idx >= list.length) return;
    list.splice(idx, 1);
    persistentStickers[user.name] = list;
    saveStickers();
    socket.emit('sticker-updated', { stickers: list });
  });

  socket.on('private-message', function (data) {
    var fromUser = getUserBySocketId(socket.id);
    if (!fromUser || !data) return;

    /* ---- 攻击防护：payload 结构校验 ---- */
    var _agV = validateMessagePayload(data, false);
    if (!_agV.ok) {
      _agViolation(socket.data._agIp, 'bad-payload: ' + _agV.reason);
      console.warn('🛡️ [Attack Guard] 非法 payload（来自 ' +
        socket.data._agIp + '）：' + _agV.reason);
      socket.emit('message-rejected', {
        msgId: data.msgId, from: fromUser.id, to: data.to,
        reason: 'invalid-payload',
        time: new Date().toLocaleString('zh-CN', { hour12: false })
      });
      return;
    }
    /* ---- 消息洪水硬限流 ---- */
    var _agF = _agCheckMsgFlood(socket);
    if (!_agF.ok) {
      _agViolation(socket.data._agIp, _agF.reason);
      console.warn('🛡️ [Attack Guard] 消息洪水（' +
        socket.data._agIp + '）：' + _agF.reason);
      try { socket.emit('force-logout', '消息发送过于频繁，请稍后再试'); } catch (e) {}
      setTimeout(function () {
        try { socket.disconnect(true); } catch (e) {}
      }, 200);
      return;
    }

    /* ★ v0.25.0 安全：文本长度硬上限（防 DoS / OOM）
       任何类型的消息内容都不允许超过 MAX_TEXT_LEN 字符。 */
    if (typeof data.content === 'string' && data.content.length > MAX_TEXT_LEN) {
      socket.emit('message-rejected', {
        msgId: data.msgId, from: fromUser.id, to: data.to,
        reason: 'too-long',
        time: new Date().toLocaleString('zh-CN', { hour12: false })
      });
      return;
    }
    /* ★ v0.25.0 安全：fileData 上限校验（防 base64 内存炸弹）
       socket.io maxHttpBufferSize 是 160MB，即便 fileSize 检查通过，
       fileData 本身仍可能极大 —— 这里强制二次校验。 */
    if (typeof data.fileData === 'string' && data.fileData.length > MAX_FILE_DATA_LEN) {
      socket.emit('private-message', {
        from: 'SYSTEM', fromName: '系统',
        content: '⚠️ 文件数据过大，已被服务端拒绝',
        time: new Date().toLocaleString('zh-CN', { hour12: false }),
        msgId: generateId(), type: 'text',
        peerId: data.to, to: data.to
      });
      return;
    }
    /* ★ 系统账号（微信团队 / 微信支付）不接受用户发来的消息 */
    if (data.to === 'wx_team' || data.to === 'wx_pay' || data.to === 'SYSTEM') {
      socket.emit('message-rejected', {
        msgId: data.msgId,
        from: fromUser.id,
        to: data.to,
        reason: 'system-account',
        time: new Date().toLocaleString('zh-CN', { hour12: false })
      });
      return;
    }
    var toUser = getUserById(data.to);
    if (!toUser) {
      socket.emit('private-message', {
        from: 'SYSTEM', fromName: '系统',
        content: '⚠️ 对方不存在',
        time: new Date().toLocaleString('zh-CN', { hour12: false }),
        msgId: generateId(), type: 'text',
        peerId: data.to, to: data.to
      });
      return;
    }
    /* ---- 拉黑拦截：双向 ---- */
    var _blockedByTarget = isBlockedBy(toUser.id, fromUser.id);
    var _selfBlocked = isBlockedBy(fromUser.id, toUser.id);
    if (_blockedByTarget || _selfBlocked) {
      socket.emit('message-rejected', {
        msgId: data.msgId,
        from: fromUser.id,
        to: toUser.id,
        reason: _blockedByTarget ? 'blocked' : 'self-blocked',
        time: new Date().toLocaleString('zh-CN', { hour12: false })
      });
      log('PM_BLOCKED', { from: fromUser.name, to: toUser.name, blockedByTarget: _blockedByTarget });
      return;
    }
    /* 对方离线：只标记，不 return —— 保证消息落盘，对方上线后可见 */
    var _peerOffline = !toUser.online;
    if (_peerOffline) {
      log('PM_OFFLINE', { from: fromUser.id, to: toUser.id });
    }
    var msgData = {
      from: fromUser.id,
      fromName: fromUser.name,
      to: toUser.id,
      content: data.content || '',
      time: new Date().toLocaleString('zh-CN', { hour12: false }),
      msgId: data.msgId || generateId(),
      type: data.type || 'text',
      fileName: data.fileName || null,
      fileSize: data.fileSize || null,
      fileType: data.fileType || null,
      fileData: data.fileData || null,
      duration: data.duration || null,
      reply: data.reply || null,
      recalled: false, recalledBy: null,
      fromLevel: fromUser.level || 0,
      fromVip: !!fromUser.vip,
      fromAdmin: !!fromUser.isAdmin,
      fromVerified: fromUser.verified || '',
      fromAvatar: (fromUser.profile && fromUser.profile.avatar) || '',
      /* ★ 通话记录结构化字段：原样透传，供双方按视角本地化渲染 */
      isCallRecord: !!data.isCallRecord,
      callKind: data.callKind || null,
      callResult: data.callResult || null,
      callDuration: (typeof data.callDuration === 'number') ? data.callDuration : 0,
      callInitiator: data.callInitiator || null,
      /* ★ 转发消息字段透传（此前完全丢失，接收方看不到转发标识） */
      forwardFrom: data.forwardFrom || null,
      forwardFromName: data.forwardFromName || null,
      /* ★ 拍一拍字段透传 */
      isPat: !!data.isPat,
      patTargetId: data.patTargetId || null,
      patTargetName: data.patTargetName || null
    };
    /* ★ v0.25.1：风控 —— 消息速率与超长检查 */
    riskCheckMessage(fromUser.id);
    riskCheckLongMessage(fromUser.id, data.content);
    /* ★ v0.25.0：消息审核 */
    if (typeof data.content === 'string' && data.content && moderation.enabled) {
      var _hits = checkModeration(data.content);
      if (_hits.length) {
        pushModerationQueue({
          from: fromUser.id, fromName: fromUser.name,
          to: toUser.id,
          content: data.content, msgId: msgData.msgId
        }, _hits);
        if (moderation.action === 'block') {
          socket.emit('message-rejected', {
            msgId: msgData.msgId, from: fromUser.id, to: toUser.id,
            reason: 'moderation',
            time: new Date().toLocaleString('zh-CN', { hour12: false })
          });
          return;
        }
      }
    }
    /* ★ v0.25.0：风控检查（频率 / 重复 / 群发） */
    fromUser._targetUser = toUser.id;
    fromUser._targetGroup = null;
    fromUser._lastContent = String(data.content || '');
    var _rb = checkMsgRate(fromUser, false);
    if (_rb) {
      var _rbTxt = _rb.kind === 'ban'
        ? ('账号因风控被临时封禁 ' + Math.ceil(_rb.remain / 1000) + ' 秒')
        : _rb.kind === 'mute'
          ? ('你已被临时禁言 ' + Math.ceil(_rb.remain / 1000) + ' 秒')
          : ('发送过于频繁，请 ' + Math.ceil(_rb.remain / 1000) + ' 秒后再试');
      socket.emit('message-rejected', {
        msgId: msgData.msgId, from: fromUser.id, to: toUser.id,
        reason: 'risk-' + _rb.kind,
        detail: _rbTxt,
        time: new Date().toLocaleString('zh-CN', { hour12: false })
      });
      return;
    }
    /* ★ v0.25.6：阅后即焚 —— 校验并附加 burn 字段 */
    if (data.burnAfterRead && data.burnAfterRead.enabled && burnConfig.enabled) {
      var _bd = Number(data.burnAfterRead.duration) || 30000;
      _bd = Math.max(1000, Math.min(BURN_MAX_MS, _bd));
      msgData.burnAfterRead = {
        enabled: true,
        duration: _bd,
        viewedAt: 0,
        expiresAt: 0
      };
    }
    var key = getHistoryKey('private', fromUser.id, toUser.id);
    saveMessage('private', key, msgData);

    /* ★ v0.28.0：更新连续聊天火花，并分别推给双方 */
    try {
      var _pStreak = updatePrivateStreak(key);
      saveInteractions();
      var _pBase = { kind: 'private', days: _pStreak.days, lastDate: _pStreak.lastDate };
      emitToUser(fromUser.id, 'interaction-update',
        Object.assign({ peerId: toUser.id }, _pBase));
      emitToUser(toUser.id, 'interaction-update',
        Object.assign({ peerId: fromUser.id }, _pBase));
    } catch (eI) { }

    /* 在线才推送；离线跳过，上线后由 history 拉取 */
    if (!_peerOffline) {
      emitToUser(toUser.id, 'private-message', msgData);
    }
    socket.emit('message-sent', msgData);
    /* 离线时给发送方一条系统提示 */
    if (_peerOffline) {
      socket.emit('private-message', {
        from: 'SYSTEM', fromName: '系统',
        content: '⚠️ 对方不在线，消息已保存但暂未送达',
        time: new Date().toLocaleString('zh-CN', { hour12: false }),
        msgId: generateId(), type: 'text',
        peerId: toUser.id, to: toUser.id
      });
    }
    /* ★ 发消息 +5 经验 */
    pushExpResult(socket, addExpToUser(fromUser.id, 5), 'message');
    /* ★ 自动回复：如果接收方离线且配置了自动回复规则，尝试触发 */
    tryAutoReply(fromUser.id, toUser.id, data.content || '');
  });

  /* ==================== 消息表情回应 ====================
     客户端在 handleReaction 里已把「全量快照」放到 data.reactions，
     服务端只需：写回历史 + 广播。私聊 → 对方 + 回执给自己；
     群聊 → 广播给所有在线群成员。 */
  socket.on('message-react', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data || !data.msgId || !data.emoji) return;
    var emoji = String(data.emoji).slice(0, 8);   /* 防注入：限制 emoji 长度 */
    var reactions = data.reactions || {};

    if (data.to) {
      /* ---- 私聊 ---- */
      var pkey = getHistoryKey('private', user.id, data.to);
      var hist = messageHistory[pkey] || [];
      for (var i = 0; i < hist.length; i++) {
        if (hist[i].msgId === data.msgId) {
          hist[i].reactions = reactions;
          break;
        }
      }
      scheduleSaveHistory();
      emitToUser(data.to, 'message-reacted', {
        msgId: data.msgId, reactions: reactions, from: user.id
      });
      socket.emit('message-reacted', {
        msgId: data.msgId, reactions: reactions, from: user.id
      });
    } else if (data.groupId) {
      /* ---- 群聊 ---- */
      var gkey = getHistoryKey('group', data.groupId);
      var ghist = messageHistory[gkey] || [];
      for (var j = 0; j < ghist.length; j++) {
        if (ghist[j].msgId === data.msgId) {
          ghist[j].reactions = reactions;
          break;
        }
      }
      scheduleSaveHistory();
      var group = getGroupById(data.groupId);
      if (group) {
        group.members.forEach(function (uid) {
          var u = getUserById(uid);
          if (u && u.online) {
            emitToUser(uid, 'message-reacted', {
              msgId: data.msgId, reactions: reactions, from: user.id
            });
          }
        });
      }
    }
    log('MESSAGE_REACT', { user: user.name, msgId: data.msgId, emoji: emoji });
  });

  socket.on('private-read', function (data) {
    var fromUser = getUserBySocketId(socket.id);
    if (!fromUser || !data) return;
    var toUser = getUserById(data.to);
    if (toUser && toUser.online) {
      emitToUser(toUser.id, 'private-read', { from: fromUser.id, msgIds: data.msgIds || [] });
    }
  });

  /* ============================================================
     ★ v0.27.0：拍一拍
     ============================================================ */
  socket.on('pat-pat', function (data) {
    var fromUser = getUserBySocketId(socket.id);
    if (!fromUser || !data || !data.to) return;
    var toUser = getUserById(data.to);
    if (!toUser) return;

    /* ★ v0.27.20：支持私聊与群聊
       · 私聊：to 必填，groupId 空
       · 群聊：to + groupId 都必填，双方必须是群成员 */
    var groupId = data.groupId ? String(data.groupId) : '';
    var group = null;
    if (groupId) {
      group = getGroupById(groupId);
      if (!group) return;
      if (!group.members.has(fromUser.id) || !group.members.has(toUser.id)) return;
      if (group.disbanded) return;
    } else {
      if (isBlockedBy(toUser.id, fromUser.id) ||
          isBlockedBy(fromUser.id, toUser.id)) return;
    }

    var now = Date.now();
    if (!fromUser._lastPatTs) fromUser._lastPatTs = 0;
    if (now - fromUser._lastPatTs < 800) return;
    fromUser._lastPatTs = now;

    var msgId = data.msgId || ('pat_' + now.toString(36) + Math.random().toString(36).slice(2, 6));
    /* 三段式模板由被拍者 profile.patTemplate 提供 */
    var _patTemplate = { pre: '拍', mid: '拍', suf: '' };
    try {
      var _toRec = persistentProfiles[toUser.name];
      if (_toRec && _toRec.patTemplate &&
          typeof _toRec.patTemplate === 'object') {
        var _pt = _toRec.patTemplate;
        _patTemplate = {
          pre: String(_pt.pre == null ? '拍' : _pt.pre).slice(0, 4),
          mid: String(_pt.mid == null ? '拍' : _pt.mid).slice(0, 4),
          suf: String(_pt.suf == null ? '' : _pt.suf).slice(0, 12)
        };
      }
    } catch (e) {
      console.warn('读取拍一拍模板失败，使用默认:', e.message);
    }

    /* ★ v0.27.20：字段名对齐客户端
       （原 isPatPat / patToId / patToName 客户端识别不了，
         导致拍一拍气泡不渲染、退回成普通空文本消息） */
    var msgData = {
      from: fromUser.id,
      fromName: fromUser.name,
      to: toUser.id,
      content: '',
      time: new Date().toLocaleString('zh-CN', { hour12: false }),
      msgId: msgId,
      type: 'text',
      recalled: false, recalledBy: null,
      fromLevel: fromUser.level || 0,
      fromVip: !!fromUser.vip,
      fromAdmin: !!fromUser.isAdmin,
      fromVerified: fromUser.verified || '',
      fromAvatar: (fromUser.profile && fromUser.profile.avatar) || '',
      isPat: true,
      patFromId: fromUser.id,
      patFromName: fromUser.name,
      patTargetId: toUser.id,
      patTargetName: toUser.name,
      patTemplate: _patTemplate
    };

    if (group) {
      /* 群聊：写入群历史并广播给全体成员 */
      msgData.groupId = group.id;
      var gkey = getHistoryKey('group', group.id);
      saveMessage('group', gkey, msgData);
      group.members.forEach(function (uid) {
        var u = getUserById(uid);
        if (u && u.online) emitToUser(uid, 'group-message', msgData);
      });
    } else {
      /* 私聊 */
      var key = getHistoryKey('private', fromUser.id, toUser.id);
      saveMessage('private', key, msgData);
      emitToUser(toUser.id, 'private-message', msgData);
      socket.emit('message-sent', msgData);
      if (fromUser.id !== toUser.id) {
        var _selfMsg = {};
        for (var k in msgData) if (msgData.hasOwnProperty(k)) _selfMsg[k] = msgData[k];
        _selfMsg.peerId = toUser.id;
        _selfMsg.to = toUser.id;
        emitToUser(fromUser.id, 'private-message', _selfMsg);
      }
    }
    log('PAT_PAT', { from: fromUser.name, to: toUser.name,
      group: group ? group.id : '' });
  });

  /* ★ 输入中提示：服务端纯转发，不持久化
     - 私聊：只发给对方（在线 + 未被双向拉黑）
     - 群聊：广播给所有在线成员（除发送者自己） */
  socket.on('typing', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var typing = !!data.typing;

    /* 每个用户最多 200ms 一次 typing 转发，防止高频刷屏导致
       客户端 state.typingUsers 累积、网络拥塞 */
    var _now = Date.now();
    if (!user._lastTypingAt) user._lastTypingAt = 0;
    if (_now - user._lastTypingAt < 200 && typing) return;
    user._lastTypingAt = _now;

    if (data.to) {
      /* ---- 私聊 ---- */
      var toUser = getUserById(data.to);
      if (!toUser || !toUser.online) return;
      /* 双向拉黑拦截：与消息一致 */
      if (isBlockedBy(toUser.id, user.id) ||
        isBlockedBy(user.id, toUser.id)) return;
      emitToUser(toUser.id, 'typing', {
        from: user.id,
        fromName: user.name,
        typing: typing,
        isGroup: false
      });
    } else if (data.groupId) {
      /* ---- 群聊 ---- */
      var group = getGroupById(data.groupId);
      if (!group || !group.members.has(user.id)) return;
      group.members.forEach(function (uid) {
        if (uid === user.id) return;
        var u = getUserById(uid);
        if (u && u.online) {
          emitToUser(uid, 'typing', {
            from: user.id,
            fromName: user.name,
            typing: typing,
            isGroup: true,
            groupId: group.id
          });
        }
      });
    }
  });

  socket.on('recall-message', function (data) {
    var fromUser = getUserBySocketId(socket.id);
    if (!fromUser || !data) return;
    var key = getHistoryKey('private', fromUser.id, data.to);
    var history = messageHistory[key] || [];
    var origFromName = '';
    var origFrom = '';
    for (var i = 0; i < history.length; i++) {
      if (history[i].msgId === data.msgId) {
        if (history[i].from !== fromUser.id) return;
        history[i].recalled = true;
        history[i].recalledBy = fromUser.id;
        history[i].recalledByName = fromUser.name;
        history[i].originalFrom = history[i].from;
        history[i].originalFromName = history[i].fromName || history[i].from;
        origFrom = history[i].from;
        origFromName = history[i].originalFromName;
        break;
      }
    }
    scheduleSaveHistory();
    var payload = {
      msgId: data.msgId,
      recalledBy: fromUser.id,
      recalledByName: fromUser.name,
      originalFrom: origFrom,
      originalFromName: origFromName
    };
    var toUser = getUserById(data.to);
    if (toUser && toUser.online) {
      emitToUser(toUser.id, 'message-recalled', payload);
    }
    socket.emit('message-recalled', payload);
    log('RECALL_MSG', { from: fromUser.id, msgId: data.msgId });
  });

  socket.on('file-chunk', function (data) {
    var fromUser = getUserBySocketId(socket.id);
    if (!fromUser || !data) return;
    data.from = fromUser.id;
    data.fromName = fromUser.name;
    data.fromLevel = fromUser.level || 0;
    data.fromVip = !!fromUser.vip;
    if (data.type === 'private') {
      var toUser = getUserById(data.to);
      if (toUser && toUser.online) io.to(toUser.socketId).emit('file-chunk', data);
    } else if (data.type === 'group') {
      var group = getGroupById(data.to);
      if (group) {
        group.members.forEach(function (uid) {
          if (uid === fromUser.id) return;
          var u = getUserById(uid);
          if (u && u.online) io.to(u.socketId).emit('file-chunk', data);
        });
      }
    }
  });

  socket.on('get-groups', function () {
    var user = getUserBySocketId(socket.id);
    if (user) broadcastGroupList(user.id);
  });

  socket.on('create-group', function (data) {
    var fromUser = getUserBySocketId(socket.id);
    if (!fromUser || !data) return;
    var name = (data.name || '').trim();
    if (!name) { socket.emit('group-error', '群名称不能为空'); return; }
    /* ★ v0.25.1：风控 —— 建群频率 */
    riskCheckGroupCreate(fromUser.id);
    var gid = generateGroupId();
    var memberSet = new Set([fromUser.id]);
    /* ★ v0.29.0：过滤掉不允许被拉入群聊的用户 */
    (data.members || []).forEach(function (m) { 
      var store = userDataStore[m];
      if (!store || store.set_allowInvite !== 'false') {
        memberSet.add(m); 
      }
    });
    var group = {
      id: gid, name: name, owner: fromUser.id,
      members: memberSet, titles: {}, announcement: '',
      muted: {}, allMuted: false, files: [], albums: [], votes: []
    };
    groupMap.set(gid, group);
    saveGroups();
    memberSet.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) {
        io.to(u.socketId).emit('group-created', {
          id: gid, name: name, owner: fromUser.id, members: Array.from(memberSet)
        });
        broadcastGroupList(uid);
      }
    });
    log('CREATE_GROUP', { groupId: gid, name: name, owner: fromUser.id });
  });

  socket.on('join-group', function (data) {
    var targetUser = data && data.userId ? getUserById(data.userId) : getUserBySocketId(socket.id);
    if (!targetUser || !data) return;
    var group = getGroupById(data.groupId);
    if (!group) { socket.emit('group-error', '群不存在'); return; }
    if (group.members.has(targetUser.id)) return;
    
    /* ★ v0.29.0：拦截禁止被拉入群聊的设置 */
    var _store = userDataStore[targetUser.id];
    if (_store && _store.set_allowInvite === 'false') {
      socket.emit('group-error', targetUser.name + ' 拒绝被拉入群聊');
      return;
    }
    
    group.members.add(targetUser.id);
    saveGroups();
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) {
        io.to(u.socketId).emit('group-joined', {
          groupId: group.id, memberId: targetUser.id, memberName: targetUser.name
        });
        broadcastGroupList(uid);
      }
    });
    log('JOIN_GROUP', { userId: targetUser.id, groupId: group.id });
  });

  socket.on('leave-group', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var group = getGroupById(data.groupId);
    if (!group || !group.members.has(user.id)) return;
    group.members.delete(user.id);

    /* ── 1. 通知「剩余成员」：有人离开了 ── */
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) {
        io.to(u.socketId).emit('group-left', {
          groupId: group.id, memberId: user.id, memberName: user.name
        });
        broadcastGroupList(uid);
      }
    });

    /* ── 2. ★ 关键修复：单独通知「离开者本人」 ──
       此前 group.members 已不含自己，导致离开者收不到任何广播，
       客户端 state.groups 仍保留该群 —— 界面毫无变化。 */
    emitToUser(user.id, 'group-left', {
      groupId: group.id,
      memberId: user.id,
      memberName: user.name,
      groupName: group.name
    });
    broadcastGroupList(user.id);

    /* ★ 只有当所有成员都退出后，群才真正从 groupMap 删除。
       已解散的群同样遵循此规则 —— 所有成员退出后自动清理。 */
    if (group.members.size === 0) {
      groupMap.delete(group.id);
      if (groupReadMap[group.id]) delete groupReadMap[group.id];
      console.log('🧹 群组已清空并删除：' + group.name + ' (' + group.id + ')');
    }
    saveGroups();
    log('LEAVE_GROUP', { userId: user.id, groupId: group.id });
  });

  /* ============================================================
     ★ 解散群聊（仅群主 / 管理员）—— 微信模式
     ------------------------------------------------------------
     与「退出群聊」的区别：
       · 群本身【不删除】，只标记 disbanded = true
       · 所有成员仍然能看到该群，能翻看历史消息
       · 所有发送入口被禁用，提示"无法在已解散的群聊中发送消息"
       · 成员需自行点「退出群聊」才真正从列表中移除
       · 当最后一个成员退出时，群才会被真正从 groupMap 删除
     ============================================================ */
  socket.on('disband-group', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data || !data.groupId) return;
    var group = getGroupById(data.groupId);
    if (!group) {
      socket.emit('group-error', '群不存在');
      return;
    }
    if (group.owner !== user.id && !user.isAdmin) {
      socket.emit('group-error', '只有群主或管理员可以解散群聊');
      return;
    }
    if (group.disbanded) {
      socket.emit('group-error', '该群聊已经解散');
      return;
    }

    /* ── 1. 标记为已解散（不删除） ── */
    group.disbanded = true;
    group.disbandedAt = Date.now();
    group.disbandedBy = user.id;
    group.disbandedByName = user.name;
    saveGroups();

    /* ── 2. 通知所有成员（含群主自己）：群已解散 ── */
    var memberList = [];
    group.members.forEach(function (uid) { memberList.push(uid); });
    for (var i = 0; i < memberList.length; i++) {
      var uid = memberList[i];
      var u = getUserById(uid);
      if (u && u.online) {
        emitToUser(uid, 'group-disbanded', {
          groupId: group.id,
          groupName: group.name,
          by: user.id,
          byName: user.name
        });
        broadcastGroupList(uid);
      }
    }

    log('DISBAND_GROUP', { groupId: group.id, name: group.name, by: user.name });
    console.log('🗑️ 群聊已解散（成员可自行退出）：' + group.name +
      ' (' + group.id + ') by ' + user.name);
  });

  /* ============================================================
     ★ 转让群主
     ============================================================ */
  socket.on('transfer-group-owner', function (data) {
    var fromUser = getUserBySocketId(socket.id);
    if (!fromUser || !data || !data.groupId || !data.targetId) return;
    var group = getGroupById(data.groupId);
    if (!group) return;
    
    // 只有当前群主可以转让
    if (group.owner !== fromUser.id) {
      socket.emit('group-error', '只有群主可以转让群主');
      return;
    }
    if (!group.members.has(data.targetId)) {
      socket.emit('group-error', '该用户不在群内');
      return;
    }
    if (data.targetId === fromUser.id) return;
    
    var targetUser = getUserById(data.targetId);
    var targetName = targetUser ? targetUser.name : data.targetId;
    
    group.owner = data.targetId;
    saveGroups();
    
    // 广播给所有成员刷新群列表
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) {
        emitToUser(uid, 'group-owner-changed', {
          groupId: group.id,
          owner: data.targetId,
          ownerName: targetName,
          byName: fromUser.name
        });
        broadcastGroupList(uid);
      }
    });
    
    // 写入系统消息记录
    var msgData = {
      groupId: group.id,
      from: 'SYSTEM',
      fromName: '系统',
      content: '👑 "' + fromUser.name + '" 将群主转让给了 "' + targetName + '"',
      time: new Date().toLocaleString('zh-CN', { hour12: false }),
      msgId: generateId(),
      type: 'text',
      recalled: false, recalledBy: null, readUsers: [],
      fromLevel: 100, fromVip: true, fromAdmin: false,
      fromVerified: '系统通知 官方账号'
    };
    var gkey = getHistoryKey('group', group.id);
    saveMessage('group', gkey, msgData);
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) emitToUser(uid, 'group-message', msgData);
    });
    
    log('TRANSFER_OWNER', { groupId: group.id, from: fromUser.name, to: targetName });
  });

  socket.on('remove-group-member', function (data) {
    var fromUser = getUserBySocketId(socket.id);
    if (!fromUser || !data) return;
    var group = getGroupById(data.groupId);
    if (!group) return;
    if (group.owner !== fromUser.id) { socket.emit('group-error', '只有群主可以移除成员'); return; }
    if (!group.members.has(data.memberId)) return;
    group.members.delete(data.memberId);
    var member = getUserById(data.memberId);
    var mname = member ? member.name : data.memberId;
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) {
        io.to(u.socketId).emit('group-left', { groupId: group.id, memberId: data.memberId, memberName: mname });
        broadcastGroupList(uid);
      }
    });
    if (member && member.online) {
      io.to(member.socketId).emit('group-left', { groupId: group.id, memberId: data.memberId, memberName: mname });
      broadcastGroupList(member.id);
    }
    if (group.members.size === 0) groupMap.delete(group.id);
    saveGroups();
    log('REMOVE_MEMBER', { groupId: group.id, memberId: data.memberId });
  });

  socket.on('rename-group', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var group = getGroupById(data.groupId);
    if (!group) return;
    if (group.owner !== user.id) { socket.emit('group-error', '只有群主可以修改群名称'); return; }
    var newName = (data.newName || '').trim();
    if (!newName) { socket.emit('group-error', '群名称不能为空'); return; }
    group.name = newName;
    saveGroups();
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) {
        io.to(u.socketId).emit('group-renamed', { groupId: group.id, newName: newName });
        broadcastGroupList(uid);
      }
    });
    log('RENAME_GROUP', { groupId: group.id, newName: newName });
  });

  socket.on('set-group-title', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var group = getGroupById(data.groupId);
    if (!group) return;
    if (group.owner !== user.id) { socket.emit('group-error', '只有群主可以设置头衔'); return; }
    if (!group.members.has(data.memberId)) return;
    if (!group.titles) group.titles = {};
    if (data.title && data.title.trim()) group.titles[data.memberId] = data.title.trim();
    else delete group.titles[data.memberId];
    saveGroups();
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) {
        io.to(u.socketId).emit('group-title-updated', {
          groupId: group.id, memberId: data.memberId, title: group.titles[data.memberId] || ''
        });
      }
    });
  });

  socket.on('group-announce', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var group = getGroupById(data.groupId);
    if (!group) return;
    if (group.owner !== user.id && !user.isAdmin) {
      socket.emit('group-error', '只有群主或管理员可以设置群公告');
      return;
    }
    var text = (data.announcement || '').trim();
    if (!text) return;
    
    if (!group.announcements) group.announcements = [];
    var ann = {
      id: 'ann_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 6),
      text: text,
      time: Date.now(),
      author: user.name,
      pinned: false
    };
    group.announcements.unshift(ann);
    group.announcement = text; // 兼容旧字段
    saveGroups();
    
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) {
        io.to(u.socketId).emit('group-announce-updated', {
          groupId: group.id, announcements: group.announcements, latest: ann
        });
      }
    });

    // ★ v0.29.0：在群里发一条系统消息（类似 QQ）
    var msgData = {
      groupId: group.id,
      from: 'SYSTEM',
      fromName: '系统',
      content: '群公告：' + text,
      time: new Date().toLocaleString('zh-CN', { hour12: false }),
      msgId: generateId(),
      type: 'text',
      isAnnouncement: true,
      announcementId: ann.id,
      recalled: false, recalledBy: null, readUsers: [],
      fromLevel: 100, fromVip: true, fromAdmin: false,
      fromVerified: '系统通知 官方账号'
    };
    var key = getHistoryKey('group', group.id);
    saveMessage('group', key, msgData);
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) emitToUser(uid, 'group-message', msgData);
    });
    log('GROUP_ANNOUNCE', { groupId: group.id, text: text });
  });

  // ★ v0.29.0：公告置顶
  socket.on('group-announce-pin', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var group = getGroupById(data.groupId);
    if (!group || (group.owner !== user.id && !user.isAdmin)) return;
    var ann = (group.announcements || []).find(function(a) { return a.id === data.annId; });
    if (ann) {
      ann.pinned = !!data.pinned;
      saveGroups();
      group.members.forEach(function (uid) {
        var u = getUserById(uid);
        if (u && u.online) io.to(u.socketId).emit('group-announce-updated', { groupId: group.id, announcements: group.announcements });
      });
    }
  });

  // ★ v0.29.0：公告删除
  socket.on('group-announce-delete', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var group = getGroupById(data.groupId);
    if (!group || (group.owner !== user.id && !user.isAdmin)) return;
    group.announcements = (group.announcements || []).filter(function(a) { return a.id !== data.annId; });
    if (group.announcements.length > 0) {
      group.announcement = group.announcements[0].text;
    } else {
      group.announcement = '';
    }
    saveGroups();
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) io.to(u.socketId).emit('group-announce-updated', { groupId: group.id, announcements: group.announcements });
    });
  });

  socket.on('group-toggle-all-mute', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var group = getGroupById(data.groupId);
    if (!group) return;
    if (group.owner !== user.id && !user.isAdmin) {
      socket.emit('group-error', '只有群主或管理员可以设置全员禁言');
      return;
    }
    group.allMuted = !!data.mute;
    saveGroups();
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) {
        io.to(u.socketId).emit('group-all-mute-updated', { groupId: group.id, allMuted: group.allMuted });
        broadcastGroupList(uid);
      }
    });
  });

  socket.on('group-message', function (data) {
    var fromUser = getUserBySocketId(socket.id);
    if (!fromUser || !data) return;

    /* ---- 攻击防护：payload 结构校验 ---- */
    var _agVg = validateMessagePayload(data, true);
    if (!_agVg.ok) {
      _agViolation(socket.data._agIp, 'bad-payload: ' + _agVg.reason);
      console.warn('🛡️ [Attack Guard] 非法 payload（来自 ' +
        socket.data._agIp + '）：' + _agVg.reason);
      socket.emit('group-error', '无效的消息格式');
      return;
    }
    /* ---- 消息洪水硬限流 ---- */
    var _agFg = _agCheckMsgFlood(socket);
    if (!_agFg.ok) {
      _agViolation(socket.data._agIp, _agFg.reason);
      console.warn('🛡️ [Attack Guard] 消息洪水（' +
        socket.data._agIp + '）：' + _agFg.reason);
      try { socket.emit('force-logout', '消息发送过于频繁，请稍后再试'); } catch (e) {}
      setTimeout(function () {
        try { socket.disconnect(true); } catch (e) {}
      }, 200);
      return;
    }

    /* ★ v0.25.0 安全：文本长度 / fileData 双重上限 */
    if (typeof data.content === 'string' && data.content.length > MAX_TEXT_LEN) {
      socket.emit('group-error', '消息过长（上限 ' + MAX_TEXT_LEN + ' 字符）');
      return;
    }
    if (typeof data.fileData === 'string' && data.fileData.length > MAX_FILE_DATA_LEN) {
      socket.emit('group-error', '文件数据过大，已被服务端拒绝');
      return;
    }
    var group = getGroupById(data.groupId);
    if (!group) { socket.emit('group-error', '群不存在'); return; }
    if (!group.members.has(fromUser.id)) { socket.emit('group-error', '您不是群成员'); return; }
    /* ★ 已解散的群聊：拒绝发送，返回微信同款提示 */
    if (group.disbanded) {
      socket.emit('group-error', '无法在已解散的群聊中发送消息');
      return;
    }
    if (group.allMuted && group.owner !== fromUser.id) {
      socket.emit('group-error', '全员禁言中'); return;
    }
    if (group.muted && group.muted[fromUser.id]) {
      socket.emit('group-error', '您已被禁言'); return;
    }
    var finalMsgId = data.msgId || generateId();
    if (!groupReadMap[group.id]) groupReadMap[group.id] = {};
    groupReadMap[group.id][finalMsgId] = new Set();
    /* 群消息已读回执上限：超出后丢弃最早的一半，避免长期累积 */
    var _grIds = Object.keys(groupReadMap[group.id]);
    if (_grIds.length > 1000) {
      var _grDrop = _grIds.length - 500;
      for (var _grI = 0; _grI < _grDrop; _grI++) {
        delete groupReadMap[group.id][_grIds[_grI]];
      }
    }

    var msgData = {
      groupId: group.id,
      from: fromUser.id,
      fromName: fromUser.name,
      content: data.content || '',
      time: new Date().toLocaleString('zh-CN', { hour12: false }),
      msgId: finalMsgId,
      type: data.type || 'text',
      fileName: data.fileName || null,
      fileSize: data.fileSize || null,
      fileType: data.fileType || null,
      fileData: data.fileData || null,
      duration: data.duration || null,
      reply: data.reply || null,
      recalled: false, recalledBy: null,
      readUsers: [],
      fromLevel: fromUser.level || 0,
      fromVip: !!fromUser.vip,
      fromAdmin: !!fromUser.isAdmin,
      fromVerified: fromUser.verified || '',
      fromAvatar: (fromUser.profile && fromUser.profile.avatar) || '',
      /* ★ 拍一拍字段透传 */
      isPat: !!data.isPat,
      patTargetId: data.patTargetId || null,
      patTargetName: data.patTargetName || null
    };
    /* ★ v0.25.1：风控 —— 消息速率与超长检查 */
    riskCheckMessage(fromUser.id);
    riskCheckLongMessage(fromUser.id, data.content);
    /* ★ v0.25.0：群消息审核 */
    if (typeof data.content === 'string' && data.content && moderation.enabled) {
      var _ghits = checkModeration(data.content);
      if (_ghits.length) {
        pushModerationQueue({
          from: fromUser.id, fromName: fromUser.name,
          groupId: group.id,
          content: data.content, msgId: msgData.msgId
        }, _ghits);
        if (moderation.action === 'block') {
          socket.emit('group-error', '消息包含敏感词，已被拦截');
          return;
        }
      }
    }
    /* ★ v0.25.0：群消息风控 */
    fromUser._targetGroup = group.id;
    fromUser._targetUser = null;
    fromUser._lastContent = String(data.content || '');
    var _grb = checkMsgRate(fromUser, true);
    if (_grb) {
      var _grbTxt = _grb.kind === 'ban'
        ? ('账号因风控被临时封禁 ' + Math.ceil(_grb.remain / 1000) + ' 秒')
        : _grb.kind === 'mute'
          ? ('你已被临时禁言 ' + Math.ceil(_grb.remain / 1000) + ' 秒')
          : ('发送过于频繁，请 ' + Math.ceil(_grb.remain / 1000) + ' 秒后再试');
      socket.emit('group-error', _grbTxt);
      return;
    }
    /* ★ v0.25.6：群聊阅后即焚 */
    if (data.burnAfterRead && data.burnAfterRead.enabled && burnConfig.enabled) {
      var _gbd = Number(data.burnAfterRead.duration) || 30000;
      _gbd = Math.max(1000, Math.min(BURN_MAX_MS, _gbd));
      msgData.burnAfterRead = {
        enabled: true,
        duration: _gbd,
        viewedAt: 0,
        expiresAt: 0
      };
    }
    var key = getHistoryKey('group', group.id);
    saveMessage('group', key, msgData);

    /* ★ v0.28.0：更新群聊火花与当日龙王，并广播给全体成员 */
    try {
      var _gRec = updateGroupInteraction(group.id, fromUser.id);
      saveInteractions();
      var _gPayload = {
        kind: 'group',
        groupId: group.id,
        days: _gRec.days,
        lastDate: _gRec.lastDate,
        dailyTop: _gRec.dailyTop
          ? { uid: _gRec.dailyTop.uid, count: _gRec.dailyTop.count }
          : null
      };
      group.members.forEach(function (uid) {
        var u = getUserById(uid);
        if (u && u.online) emitToUser(uid, 'interaction-update', _gPayload);
      });
    } catch (eI) { }

    /* 通过房间广播 → 不再受 userMap 里陈旧 socketId 影响，
       彻底修复「非发送者群成员必须重新登录才可领取红包」 */
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) emitToUser(uid, 'group-message', msgData);
    });
    /* ★ 发消息 +5 经验 */
    pushExpResult(socket, addExpToUser(fromUser.id, 5), 'message');
  });

  socket.on('recall-group-message', function (data) {
    var fromUser = getUserBySocketId(socket.id);
    if (!fromUser || !data) return;
    var group = getGroupById(data.groupId);
    if (!group || !group.members.has(fromUser.id)) return;
    var key = getHistoryKey('group', group.id);
    var history = messageHistory[key] || [];
    var target = null;
    for (var i = 0; i < history.length; i++) {
      if (history[i].msgId === data.msgId) { target = history[i]; break; }
    }
    if (!target) return;
    var isSender = target.from === fromUser.id;
    var isOwner = group.owner === fromUser.id;
    if (!isSender && !isOwner && !fromUser.isAdmin) {
      socket.emit('group-error', '无权撤回他人消息');
      return;
    }
    var _origFrom = target.from;
    var _origFromName = target.fromName || target.from;
    var _ou = getUserById(_origFrom);
    if (_ou) _origFromName = _ou.name;
    target.recalled = true;
    target.recalledBy = fromUser.id;
    target.recalledByName = fromUser.name;
    target.originalFrom = _origFrom;
    target.originalFromName = _origFromName;
    scheduleSaveHistory();
    var _rPayload = {
      msgId: data.msgId,
      groupId: group.id,
      recalledBy: fromUser.id,
      recalledByName: fromUser.name,
      originalFrom: _origFrom,
      originalFromName: _origFromName
    };
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) {
        emitToUser(uid, 'group-message-recalled', _rPayload);
      }
    });
    log('RECALL_GROUP_MSG', { groupId: group.id, msgId: data.msgId, by: fromUser.id });
  });

  /* ============================================================
     ★ v0.25.6：阅后即焚 —— 接收方首次查看时触发
     ------------------------------------------------------------
     接收方进入会话、消息渲染完毕后，客户端 emit 此事件，
     携带该会话中所有「未读 burn 消息」的 msgId 列表。
     服务端为每条消息启动销毁定时器，并广播 burn-viewed 给双方。
     ============================================================ */
  socket.on('burn-viewed', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data || !Array.isArray(data.msgIds)) return;
    if (!burnConfig.enabled) return;
    var scopeType = data.scope === 'group' ? 'group' : 'private';
    var targetId = String(data.targetId || '');
    if (!targetId) return;

    var sessionKey = '';
    var scope = null;
    if (scopeType === 'group') {
      var g = getGroupById(targetId);
      if (!g || !g.members.has(user.id)) return;
      sessionKey = getHistoryKey('group', targetId);
      scope = { type: 'group', id: targetId };
    } else {
      var peer = getUserById(targetId);
      if (!peer) return;
      sessionKey = getHistoryKey('private', user.id, targetId);
      scope = { type: 'private', ids: [user.id, targetId] };
    }
    var arr = messageHistory[sessionKey] || [];
    var now = Date.now();
    var started = [];
    for (var i = 0; i < data.msgIds.length; i++) {
      var mid = data.msgIds[i];
      if (!mid) continue;
      /* ★ 竞态保护：2 秒内的同 ID 上报直接忽略 */
      if (burnViewLocks[mid] && now - burnViewLocks[mid] < 2000) continue;
      burnViewLocks[mid] = now;

      for (var j = 0; j < arr.length; j++) {
        var m = arr[j];
        if (!m || m.msgId !== mid) continue;
        if (!m.burnAfterRead || !m.burnAfterRead.enabled) break;
        if (m.burnAfterRead.viewedAt) break;
        if (m.from === user.id) break;
        m.burnAfterRead.viewedAt = now;
        m.burnAfterRead.expiresAt = now + m.burnAfterRead.duration;
        _burnIndexAdd(mid, sessionKey, scope);
        scheduleBurn(mid, sessionKey, m.burnAfterRead.duration, scope);
        started.push({
          msgId: mid,
          viewedAt: now,
          expiresAt: m.burnAfterRead.expiresAt,
          viewedBy: user.id,
          viewedByName: user.name,
          /* ★ 附带服务端时间，客户端据此校准 */
          serverNow: now
        });
        break;
      }
    }
    if (!started.length) return;
    scheduleSaveHistory();
    /* 广播 */
    if (scope.type === 'group') {
      var g2 = getGroupById(targetId);
      if (g2) {
        g2.members.forEach(function (uid) {
          var u = getUserById(uid);
          if (u && u.online) {
            emitToUser(uid, 'burn-viewed', {
              scope: 'group', targetId: targetId, items: started
            });
          }
        });
      }
    } else {
      var ids = scope.ids || [];
      for (var k = 0; k < ids.length; k++) {
        var u2 = getUserById(ids[k]);
        if (u2 && u2.online) {
          emitToUser(u2.id, 'burn-viewed', {
            scope: 'private', targetId: targetId, items: started
          });
        }
      }
    }
    log('BURN_VIEWED', { by: user.name, count: started.length });
  });

  /* ============================================================
     ★ v0.26.1：客户端上报"我已本地标记 burned"（双保险）
     ------------------------------------------------------------
     客户端定时器到 0 后主动上报，服务端立即标记并广播。
     即使服务端自己的 setTimeout 丢失（进程崩溃 / 节流），
     只要有一个客户端在线，消息就一定会被标记。
     ============================================================ */
  socket.on('burn-mark-burned', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data || !Array.isArray(data.msgIds)) return;
    var info = null;
    var _now = Date.now();
    var _changed = false;
    for (var i = 0; i < data.msgIds.length; i++) {
      var mid = data.msgIds[i];
      if (!mid) continue;
      info = burnIndex[mid];
      if (!info || !info.sessionKey) continue;
      var arr = messageHistory[info.sessionKey];
      if (!Array.isArray(arr)) continue;
      for (var j = 0; j < arr.length; j++) {
        var m = arr[j];
        if (m && m.msgId === mid && !m.burned) {
          m.burned = true;
          m.content = '';
          m.fileData = null; m.fileName = null;
          m.fileSize = 0; m.fileType = null;
          m.duration = null; m.reply = null;
          _changed = true;
          if (burnTimers[mid]) { clearTimeout(burnTimers[mid]); delete burnTimers[mid]; }
          break;
        }
      }
      _burnIndexDel(mid);
    }
    if (_changed) {
      scheduleSaveHistory();
      /* 广播给会话双方 */
      for (var k in messageHistory) {
        if (!messageHistory.hasOwnProperty(k)) continue;
        /* 仅对涉及该用户的会话广播 —— 简化处理：全局广播 */
      }
    }
  });

  socket.on('group-read', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var group = getGroupById(data.groupId);
    if (!group || !group.members.has(user.id)) return;
    if (!groupReadMap[group.id]) groupReadMap[group.id] = {};
    if (!groupReadMap[group.id][data.msgId]) groupReadMap[group.id][data.msgId] = new Set();
    groupReadMap[group.id][data.msgId].add(user.id);
    var readUsers = Array.from(groupReadMap[group.id][data.msgId]);
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) {
        emitToUser(uid, 'group-read-update', {
          groupId: group.id, msgId: data.msgId, userId: user.id, readUsers: readUsers
        });
      }
    });
  });

  socket.on('qq-file-upload', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var group = getGroupById(data.groupId);
    if (!group || !group.members.has(user.id)) return;
    if (typeof data.fileSize === 'number' && data.fileSize > config.maxFileSize) {
      socket.emit('group-error', '文件太大（上限 ' + (config.maxFileSize / 1048576).toFixed(0) + 'MB）');
      return;
    }
    if (!group.files) group.files = [];
    group.files.push({
      fileName: data.fileName, fileSize: data.fileSize, fileType: data.fileType,
      fileData: data.fileData, uploader: user.id, uploadTime: new Date().toISOString()
    });
    saveGroups();
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) io.to(u.socketId).emit('qq-file-updated', { groupId: group.id, files: group.files });
    });
    log('QQ_FILE_UPLOAD', { groupId: group.id, fileName: data.fileName });
  });

  socket.on('qq-album-upload', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var group = getGroupById(data.groupId);
    if (!group || !group.members.has(user.id)) return;
    if (!group.albums) group.albums = [];
    group.albums.push({
      fileName: data.fileName, fileData: data.fileData,
      uploader: user.id, uploadTime: new Date().toISOString()
    });
    saveGroups();
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) io.to(u.socketId).emit('qq-album-updated', { groupId: group.id, albums: group.albums });
    });
  });

  socket.on('qq-vote-create', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var group = getGroupById(data.groupId);
    if (!group || !group.members.has(user.id)) return;
    if (!group.votes) group.votes = [];
    var voteId = generateVoteId();
    var results = {};
    (data.options || []).forEach(function (o) { results[o] = 0; });
    group.votes.push({
      voteId: voteId, question: data.question, options: data.options,
      results: results, voters: [], creator: user.id, active: true
    });
    saveGroups();
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) io.to(u.socketId).emit('qq-vote-updated', { groupId: group.id, votes: group.votes });
    });
  });

  socket.on('qq-vote-submit', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var group = getGroupById(data.groupId);
    if (!group || !group.members.has(user.id)) return;
    var votes = group.votes || [];
    var vote = null;
    for (var i = 0; i < votes.length; i++) {
      if (votes[i].voteId === data.voteId) { vote = votes[i]; break; }
    }
    if (!vote || !vote.active) { socket.emit('vote-error', '投票已结束'); return; }
    if (vote.voters.indexOf(user.id) !== -1) { socket.emit('vote-error', '您已投票'); return; }
    if (vote.options.indexOf(data.option) === -1) { socket.emit('vote-error', '无效选项'); return; }
    vote.results[data.option] = (vote.results[data.option] || 0) + 1;
    vote.voters.push(user.id);
    saveGroups();
    group.members.forEach(function (uid) {
      var u = getUserById(uid);
      if (u && u.online) io.to(u.socketId).emit('qq-vote-updated', { groupId: group.id, votes: group.votes });
    });
  });

  function requireAdmin(socket, cb) {
    var u = getUserBySocketId(socket.id);
    if (!u || !u.isAdmin) { socket.emit('admin-error', '权限不足'); return null; }
    return cb(u);
  }

  socket.on('admin-set-level', function (data) {
    requireAdmin(socket, function () {
      var target = getUserByName(data.targetName);
      if (!target) { socket.emit('admin-error', '用户不在线'); return; }
      var newLv = Math.min(MAX_LEVEL, Math.max(1, parseInt(data.level, 10) || 1));
      target.level = newLv;
      /* ★ 等级与经验同步：等级对应的最低经验补齐 */
      target.exp = expForLevel(newLv);
      if (persistentUsers[target.name]) {
        persistentUsers[target.name].level = newLv;
        persistentUsers[target.name].exp = target.exp;
      }
      saveUsers();
      io.emit('user-updated', {
        id: target.id, name: target.name,
        level: newLv, exp: target.exp
      });
    });
  });

  /* ============================================================
     ★ 管理员：修改用户注册时间
     ============================================================ */
  socket.on('admin-set-createdat', function (data) {
    requireAdmin(socket, function (admin) {
      var targetName = String(data && data.targetName || '').trim();
      var ts = parseInt(data && data.timestamp, 10);
      
      if (!targetName) { socket.emit('admin-error', '参数缺失'); return; }
      if (isNaN(ts) || ts <= 0) { socket.emit('admin-error', '无效的时间戳'); return; }
      
      var rec = persistentUsers[targetName];
      if (!rec) { socket.emit('admin-error', '用户不存在'); return; }
      
      rec.createdAt = ts;
      saveUsers();
      
      /* 广播用户更新，客户端侧边栏 / 名片会实时刷新 */
      io.emit('user-updated', {
        id: rec.id,
        name: rec.name,
        createdAt: ts
      });
      
      socket.emit('admin-error', '✅ 已修改 ' + targetName + ' 的注册时间为 ' + 
        new Date(ts).toLocaleString('zh-CN', { hour12: false }));
      log('ADMIN_SET_TIME', { target: targetName, by: admin.name, ts: ts });
    });
  });

  socket.on('admin-set-svip', function (data) {
    requireAdmin(socket, function () {
      var target = getUserByName(data.targetName);
      if (!target) { socket.emit('admin-error', '用户不在线'); return; }
      target.vip = !!data.svip;
      if (persistentUsers[target.name]) persistentUsers[target.name].vip = target.vip;
      saveUsers();
      io.emit('user-updated', { id: target.id, name: target.name, vip: target.vip });
    });
  });

  socket.on('admin-set-admin', function (data) {
    requireAdmin(socket, function () {
      var target = getUserByName(data.targetName);
      if (!target) { socket.emit('admin-error', '用户不在线'); return; }
      target.isAdmin = !!data.isAdmin;
      if (persistentUsers[target.name]) persistentUsers[target.name].isAdmin = target.isAdmin;
      saveUsers();
      io.emit('user-updated', { id: target.id, name: target.name, isAdmin: target.isAdmin });
    });
  });

  socket.on('admin-kick', function (data) {
    requireAdmin(socket, function () {
      var target = getUserByName(data.targetName);
      if (!target) { socket.emit('admin-error', '用户不在线'); return; }
      var ts = io.sockets.sockets.get(target.socketId);
      if (ts) { try { ts.emit('force-logout', '您已被管理员踢出'); ts.disconnect(true); } catch (e) { } }
      userMap.delete(target.id);
      broadcastUserList();
      io.emit('user-left', { id: target.id, name: target.name });
    });
  });

  /* ============================================================
     ★ 封禁 / 解封
     ------------------------------------------------------------
     封禁是账号级操作，写入 users.json，重启后依然有效：
       · 被封禁账号无法登录（login 事件最前面拦截）
       · 若账号当前在线，立即断开并通知客户端
       · 内置账号（wx_team / wx_pay）与系统管理员自己不可被封禁
     ============================================================ */
  socket.on('admin-ban', function (data) {
    requireAdmin(socket, function (admin) {
      var targetName = String(data && data.targetName || '').trim();
      var reason = String(data && data.reason || '').slice(0, 60);
      /* ★ 支持时长：data.durationMs 或 data.duration 字符串
         0 / 空 → 永久 */
      var durationMs = 0;
      if (data && typeof data.durationMs === 'number' && data.durationMs > 0) {
        durationMs = data.durationMs;
      } else if (data && data.duration) {
        var _parsed = parseBanDuration(data.duration);
        if (_parsed !== null) durationMs = _parsed;
      }
      if (!targetName) { socket.emit('admin-error', '参数缺失'); return; }
      if (targetName === '微信团队' || targetName === '微信支付') {
        socket.emit('admin-error', '系统内置账号不可封禁');
        return;
      }
      var rec = persistentUsers[targetName];
      if (!rec) { socket.emit('admin-error', '用户不存在'); return; }
      if (rec.id === admin.id) {
        socket.emit('admin-error', '不能封禁自己');
        return;
      }
      if (rec.banned) { socket.emit('admin-error', '该账号已被封禁'); return; }

      rec.banned = true;
      rec.bannedAt = Date.now();
      rec.bannedBy = admin.name;
      rec.banReason = reason;
      /* ★ 到期时间戳；0 = 永久 */
      rec.bannedUntil = durationMs > 0 ? Date.now() + durationMs : 0;
      saveUsers();

      var live = getUserById(rec.id);
      if (live && live.online) {
        var ts = io.sockets.sockets.get(live.socketId);
        if (ts) {
          try {
            ts.emit('account-banned', {
              reason: reason,
              bannedBy: admin.name,
              bannedUntil: rec.bannedUntil
            });
          } catch (e) { }
          setTimeout(function () {
            try { ts.disconnect(true); } catch (e) { }
          }, 300);
        }
        userMap.delete(live.id);
        io.emit('user-left', { id: live.id, name: live.name });
      }
      broadcastUserList();
      io.emit('user-updated', { id: rec.id, name: rec.name, banned: true });
      var _durTxt = durationMs > 0
        ? formatBanDuration(durationMs)
        : '永久';
      socket.emit('admin-error', '✅ 已封禁 ' + targetName + '（' + _durTxt + '）');
      log('BAN_USER', {
        target: targetName, by: admin.name,
        reason: reason, duration: _durTxt
      });
    });
  });

  socket.on('admin-unban', function (data) {
    requireAdmin(socket, function (admin) {
      var targetName = String(data && data.targetName || '').trim();
      if (!targetName) { socket.emit('admin-error', '参数缺失'); return; }
      var rec = persistentUsers[targetName];
      if (!rec) { socket.emit('admin-error', '用户不存在'); return; }
      if (!rec.banned) { socket.emit('admin-error', '该账号未被封禁'); return; }

      rec.banned = false;
      rec.bannedAt = 0;
      rec.bannedBy = '';
      rec.banReason = '';
      rec.bannedUntil = 0;
      saveUsers();

      /* ★ v0.24.6：管理员手动解封时同样清空界面保护违规计数 */
      if (uiGuardViolations[rec.id]) {
        delete uiGuardViolations[rec.id];
      }

      /* 若账号在线（不太可能，但以防万一）同步更新 */
      var live = getUserById(rec.id);
      if (live) {
        live.banned = false;
      }
      /* ★ 广播封禁解除：
         · user-updated  → 已登录客户端刷新侧边栏 / 名片 / 全部用户弹窗
         · user-unbanned → 未登录客户端（停留在登录页）刷新登录按钮 */
      io.emit('user-updated', { id: rec.id, name: rec.name, banned: false });
      io.emit('user-unbanned', { id: rec.id, name: rec.name });
      broadcastUserList();
      socket.emit('admin-error', '✅ 已解除封禁 ' + targetName);
      log('UNBAN_USER', { target: targetName, by: admin.name });
    });
  });

  /* ============================================================
     ★ 管理员删除用户
     ============================================================ */
