/* 空间 / 动态 */
  socket.on('moment-post', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data) return;
    var content = String(data.content || '').trim().slice(0, 2000);
    var rawImgs = Array.isArray(data.images) ? data.images.slice(0, MAX_MOMENT_IMAGES) : [];
    var images = [];
    for (var i = 0; i < rawImgs.length; i++) {
      var im = rawImgs[i];
      if (typeof im !== 'string') continue;
      if (im.indexOf('data:image/') !== 0) continue;
      if (im.length > MAX_MOMENT_IMAGE_LEN) continue;
      images.push(im);
    }
    if (!content && !images.length) { socket.emit('moment-error', '内容不能为空'); return; }
    /* ★ v0.27.11：可见范围 */
    var visibility = 'public';
    var visibleTo = [];
    var vRaw = data.visibility;
    if (vRaw === 'private') {
      visibility = 'private';
    } else if (vRaw === 'friends') {
      visibility = 'friends';
    } else if (Array.isArray(data.visibleTo) && data.visibleTo.length) {
      visibility = 'custom';
      /* 限制最多 100 人，且必须是已注册用户 ID */
      for (var vi = 0; vi < data.visibleTo.length && visibleTo.length < 100; vi++) {
        var vid = String(data.visibleTo[vi] || '').slice(0, 64);
        if (_agIsValidId(vid)) visibleTo.push(vid);
      }
      if (!visibleTo.length) visibility = 'private';
    }
    var m = {
      id: 'm' + Date.now().toString(36) + Math.random().toString(36).substring(2, 6),
      author: user.id, authorName: user.name,
      authorAvatar: (user.profile && user.profile.avatar) || '',
      authorVerified: user.verified || '',
      content: content, images: images, time: Date.now(),
      likes: [], comments: [],
      visibility: visibility,
      visibleTo: visibleTo
    };
    moments.unshift(m);
    if (moments.length > MAX_MOMENTS) moments.length = MAX_MOMENTS;
    saveMoments();
    io.emit('moment-new', momentToClient(m));
    /* ★ 发动态 +20 经验 */
    pushExpResult(socket, addExpToUser(user.id, 20), 'moment');
    log('MOMENT_POST', { user: user.name, imgs: images.length });
  });

  socket.on('moment-get', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user) return;
    var targetId = (data && data.targetId) || user.id;
    var offset = parseInt(data && data.offset, 10) || 0;
    var limit = Math.min(60, parseInt(data && data.limit, 10) || 30);
    var list = moments.filter(function (m) { return m.author === targetId; });
    list.sort(function (a, b) { return (b.time || 0) - (a.time || 0); });
    var totalLikes = 0;
    for (var i = 0; i < list.length; i++) totalLikes += (list[i].likes || []).length;
    socket.emit('moment-list', {
      targetId: targetId, offset: offset,
      total: list.length, totalLikes: totalLikes,
      visitorCount: (visitors[targetId] || []).length,
      hasMore: offset + limit < list.length,
      moments: list.slice(offset, offset + limit).map(momentToClient)
    });
  });

  socket.on('moment-delete', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data || !data.momentId) return;
    var idx = findMomentIndex(data.momentId);
    if (idx === -1) return;
    var m = moments[idx];
    if (m.author !== user.id && !user.isAdmin) {
      socket.emit('moment-error', '只能删除自己的动态'); return;
    }
    moments.splice(idx, 1);
    saveMoments();
    io.emit('moment-deleted', { momentId: data.momentId });
    log('MOMENT_DELETE', { by: user.name, id: data.momentId });
  });

  socket.on('moment-like', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data || !data.momentId) return;
    var idx = findMomentIndex(data.momentId);
    if (idx === -1) return;
    var m = moments[idx];
    if (!m.likes) m.likes = [];
    var li = m.likes.indexOf(user.id);
    if (li === -1) m.likes.push(user.id);
    else m.likes.splice(li, 1);
    saveMoments();
    io.emit('moment-liked', { momentId: m.id, likes: m.likes.slice() });
  });

  socket.on('moment-comment', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data || !data.momentId) return;
    var content = String(data.content || '').trim().slice(0, 500);
    if (!content) return;
    var idx = findMomentIndex(data.momentId);
    if (idx === -1) return;
    var m = moments[idx];
    if (!m.comments) m.comments = [];
    var c = {
      id: 'c' + Date.now().toString(36) + Math.random().toString(36).substring(2, 6),
      from: user.id, fromName: user.name,
      fromAvatar: (user.profile && user.profile.avatar) || '',
      content: content, time: Date.now()
    };
    m.comments.push(c);
    if (m.comments.length > 200) m.comments = m.comments.slice(-200);
    saveMoments();
    io.emit('moment-commented', { momentId: m.id, comment: c, comments: m.comments });

    /* ★ v0.27.11：动态 @我 提醒 —— 扫描评论中的 @昵称 */
    var mentions = content.match(/@([A-Za-z0-9_\u4e00-\u9fa5]{1,24})/g) || [];
    if (mentions.length) {
      var sent = {};
      for (var mi = 0; mi < mentions.length && mi < 20; mi++) {
        var name = mentions[mi].substring(1);
        if (!name || name === user.name || sent[name]) continue;
        sent[name] = 1;
        /* 从 persistentUsers 查找 */
        var targetRec = persistentUsers[name];
        if (!targetRec || !targetRec.id || targetRec.id === user.id) continue;
        /* 通知该用户 */
        emitToUser(targetRec.id, 'moment-mention', {
          momentId: m.id,
          commentId: c.id,
          fromId: user.id,
          fromName: user.name,
          fromAvatar: c.fromAvatar,
          text: content.length > 60 ? content.slice(0, 60) + '…' : content,
          time: Date.now()
        });
      }
    }
  });

  socket.on('moment-comment-delete', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data || !data.momentId || !data.commentId) return;
    var idx = findMomentIndex(data.momentId);
    if (idx === -1) return;
    var m = moments[idx];
    if (!m.comments) return;
    var newArr = []; var changed = false;
    for (var i = 0; i < m.comments.length; i++) {
      var c = m.comments[i];
      if (c.id === data.commentId &&
        (c.from === user.id || m.author === user.id || user.isAdmin)) {
        changed = true; continue;
      }
      newArr.push(c);
    }
    if (!changed) return;
    m.comments = newArr;
    saveMoments();
    io.emit('moment-commented', { momentId: m.id, comment: null, comments: m.comments });
  });

  socket.on('moment-visit', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data || !data.targetId) return;
    if (data.targetId === user.id) return;
    if (!getUserById(data.targetId)) return;
    if (!visitors[data.targetId]) visitors[data.targetId] = [];
    var arr = visitors[data.targetId].filter(function (v) { return v.visitorId !== user.id; });
    arr.unshift({
      visitorId: user.id, visitorName: user.name,
      visitorAvatar: (user.profile && user.profile.avatar) || '',
      time: Date.now()
    });
    if (arr.length > MAX_VISITORS_PER_USER) arr.length = MAX_VISITORS_PER_USER;
    visitors[data.targetId] = arr;
    saveVisitors();
  });

  socket.on('moment-get-visitors', function () {
    var user = getUserBySocketId(socket.id);
    if (!user) return;
    socket.emit('moment-visitors', { visitors: visitors[user.id] || [] });
  });

  /* ==================== 每日签到 ==================== */
  socket.on('daily-signin', function () {
    var user = getUserBySocketId(socket.id);
    if (!user) return;
    var today = todayStr();
    if (user.lastSignin === today) {
      socket.emit('signin-result', {
        ok: false, reason: 'already', lastSignin: today
      });
      return;
    }
    user.lastSignin = today;
    /* ★ 记录签到历史（日历展示用，只保留最近 90 天） */
    var _sh = [];
    if (persistentUsers[user.name]) {
      persistentUsers[user.name].lastSignin = today;
      if (!Array.isArray(persistentUsers[user.name].signinHistory)) {
        persistentUsers[user.name].signinHistory = [];
      }
      _sh = persistentUsers[user.name].signinHistory;
      if (_sh.indexOf(today) === -1) _sh.push(today);
      _sh.sort();
      if (_sh.length > 90) {
        _sh = _sh.slice(-90);
        persistentUsers[user.name].signinHistory = _sh;
      }
    }
    user.signinHistory = _sh.slice();
    /* ★ 每日签到 +10 经验 */
    var res = addExpToUser(user.id, 10);
    saveUsers();
    socket.emit('signin-result', {
      ok: true,
      exp: res ? res.exp : (user.exp || 0),
      level: res ? res.level : user.level,
      oldLevel: res ? res.oldLevel : user.level,
      leveledUp: res ? res.leveledUp : false,
      lastSignin: today,
      /* ★ 回传最新签到历史，客户端据此刷新日历 */
      signinHistory: _sh.slice()
    });
    if (res && res.leveledUp) {
      io.emit('user-updated', {
        id: user.id, name: user.name,
        level: res.level, exp: res.exp
      });
    }
    log('DAILY_SIGNIN', { user: user.name, exp: user.exp, level: user.level });
  });

/* 拉黑管理 */
  socket.on('block-user', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data || !data.userId) return;
    if (data.userId === user.id) return;
    if (!getUserById(data.userId)) { socket.emit('moment-error', '用户不存在'); return; }
    if (!blocks[user.id]) blocks[user.id] = [];
    if (blocks[user.id].indexOf(data.userId) === -1) {
      blocks[user.id].push(data.userId);
    }
    saveBlocks();
    socket.emit('block-updated', { userId: data.userId, blocked: true });
    log('BLOCK_USER', { by: user.name, target: data.userId });
  });

  socket.on('unblock-user', function (data) {
    var user = getUserBySocketId(socket.id);
    if (!user || !data || !data.userId) return;
    if (!blocks[user.id]) return;
    var idx = blocks[user.id].indexOf(data.userId);
    if (idx !== -1) blocks[user.id].splice(idx, 1);
    saveBlocks();
    socket.emit('block-updated', { userId: data.userId, blocked: false });
    log('UNBLOCK_USER', { by: user.name, target: data.userId });
  });

