  RENAME_GROUP: '修改群名', ADMIN_GLOBAL_ANNOUNCE: '全局公告',
  GROUP_ANNOUNCE: '群公告', STICKER_UPLOAD: '表情包上传',
  CALL_REQUEST: '发起通话', CALL_ACCEPT: '接听通话', CALL_REJECT: '拒接通话',
  CALL_END: '结束通话', MESSAGE_REACT: '表情回应',
  BAN_USER: '封禁用户', UNBAN_USER: '解除封禁', LOGIN_BANNED: '登录被拒（已封禁）',
  REDPACKET_SEND: '发出红包', REDPACKET_GRAB: '领取红包',
  MOMENT_POST: '发布动态', MOMENT_DELETE: '删除动态',
