  PROFILE_UPDATE: '更新名片', RENAME_USER: '修改昵称',
  PRESENCE_UPDATE: '切换状态', GROUP_CALL_START: '发起群通话',
  GROUP_CALL_JOIN: '加入群通话', GROUP_CALL_LEAVE: '离开群通话',
  GROUP_CALL_END: '结束群通话', DELETE_USER: '删除用户',
  ADMIN_SET_MONEY: '调整余额', ADMIN_BATCH_SET_MONEY: '批量调整余额',
  ADMIN_SET_MAX_FILE: '调整文件上限', ADMIN_SET_VERIFIED: '设置认证',
  REGISTER_SUCCESS: '新用户注册', REGISTER_CODE: '注册验证码',
  FORGOT_SUCCESS: '重置密码', SETUP_ACCOUNT: '首次安全设置',
